-- Domain 11: Finance: Ledger, Close & Consolidation | functions
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 73
CREATE FUNCTION public.acct__account_amounts(p_tenant_id uuid, p_from date, p_to date, p_entity_id uuid DEFAULT NULL::uuid) RETURNS TABLE(account_id uuid, code text, name text, account_type text, subtype text, activity numeric, ending_balance numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT a.id, a.code, a.name, a.account_type, a.subtype,
         coalesce(sum(CASE WHEN l.entry_date BETWEEN p_from AND p_to AND NOT l.is_closing THEN l.debit - l.credit END), 0)
           * CASE WHEN a.account_type IN ('asset','contra_asset','expense') THEN 1 ELSE -1 END,
         coalesce(sum(l.debit - l.credit), 0)
           * CASE WHEN a.account_type IN ('asset','contra_asset','expense') THEN 1 ELSE -1 END
    FROM acct_chart_of_accounts a
    LEFT JOIN (SELECT l.account_id, l.debit, l.credit, je.entry_date, je.is_closing
                 FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id
                WHERE je.tenant_id = p_tenant_id AND je.status IN ('posted','reversed') AND je.entry_date <= p_to
                  AND (p_entity_id IS NULL OR je.entity_id = p_entity_id)) l ON l.account_id = a.id
   WHERE a.tenant_id = p_tenant_id AND (p_entity_id IS NULL OR a.entity_id = p_entity_id)
   GROUP BY a.id;
$$;

-- @seq 74
CREATE FUNCTION public.acct__apply_security() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  DECLARE
    r record; p record;
    v_readonly text[] := ARRAY['acct_journal_entries','acct_journal_lines','acct_account_balances','acct_tax_transactions',
                               'acct_number_sequences','acct_audit_log','acct_debt_schedule','acct_bank_rule_matches',
                               -- parts 8-9: written only by posting functions
                               'acct_inventory_moves','acct_inventory_layers','acct_inventory_layer_draws',
                               'acct_order_postings','acct_order_payments','acct_recognition_lines',
                               'acct_asset_depreciation_runs','acct_asset_depreciation_lines',
                               'acct_review_runs','acct_review_findings','acct_report_snapshots','acct_coding_history'];
    v_service_only text[] := ARRAY['acct_processor_events'];
    v_global text[] := ARRAY['acct_1099_thresholds'];
  BEGIN
    FOR r IN
      SELECT c.relname,
             EXISTS (SELECT 1 FROM information_schema.columns ic WHERE ic.table_schema='public' AND ic.table_name=c.relname AND ic.column_name='tenant_id') AS has_tenant,
             coalesce((SELECT ic.is_nullable='YES' FROM information_schema.columns ic WHERE ic.table_schema='public' AND ic.table_name=c.relname AND ic.column_name='tenant_id'), false) AS tenant_nullable
        FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
       WHERE n.nspname = 'public' AND c.relkind IN ('r','p') AND c.relname LIKE 'acct\_%'
    LOOP
      EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', r.relname);
      EXECUTE format('REVOKE ALL ON public.%I FROM anon', r.relname);

      IF r.has_tenant OR r.relname = ANY (v_global) THEN
        FOR p IN SELECT policyname FROM pg_policies WHERE schemaname='public' AND tablename = r.relname LOOP
          EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, r.relname);
        END LOOP;

        IF r.relname = ANY (v_service_only) THEN
          EXECUTE format('REVOKE ALL ON public.%I FROM authenticated', r.relname);       -- service_role bypasses RLS
        ELSIF r.relname = ANY (v_global) THEN
          EXECUTE format('REVOKE INSERT, UPDATE, DELETE ON public.%I FROM authenticated', r.relname);
          EXECUTE format('CREATE POLICY acct_global_read ON public.%I FOR SELECT TO authenticated USING (true)', r.relname);
        ELSIF r.relname = ANY (v_readonly) THEN
          EXECUTE format('REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON public.%I FROM authenticated', r.relname);
          EXECUTE format('CREATE POLICY acct_member_read ON public.%I FOR SELECT TO authenticated USING (acct_is_tenant_member(tenant_id))', r.relname);
        ELSE
          IF r.tenant_nullable THEN   -- global seed rows (tenant_id NULL) are readable, never writable
            EXECUTE format('CREATE POLICY acct_member_read ON public.%I FOR SELECT TO authenticated USING (tenant_id IS NULL OR acct_is_tenant_member(tenant_id))', r.relname);
          ELSE
            EXECUTE format('CREATE POLICY acct_member_read ON public.%I FOR SELECT TO authenticated USING (acct_is_tenant_member(tenant_id))', r.relname);
          END IF;
          EXECUTE format('CREATE POLICY acct_member_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (acct_is_tenant_member(tenant_id))', r.relname);
          EXECUTE format('CREATE POLICY acct_member_update ON public.%I FOR UPDATE TO authenticated USING (acct_is_tenant_member(tenant_id)) WITH CHECK (acct_is_tenant_member(tenant_id))', r.relname);
          EXECUTE format('CREATE POLICY acct_member_delete ON public.%I FOR DELETE TO authenticated USING (acct_is_tenant_member(tenant_id))', r.relname);
        END IF;
      ELSE
        -- child tables without tenant_id keep their parent-EXISTS policies; only the
        -- "allow everything when the setting is unset" policies are removed
        FOR p IN SELECT policyname FROM pg_policies
                  WHERE schemaname='public' AND tablename = r.relname
                    AND (coalesce(qual,'') || coalesce(with_check,'')) ILIKE '%current_setting%IS NULL%' LOOP
          EXECUTE format('DROP POLICY %I ON public.%I', p.policyname, r.relname);
        END LOOP;
      END IF;
    END LOOP;
  END;

  -- views: authenticated may read (RLS of the base tables applies), anon may not
  DECLARE r record;
  BEGIN
    FOR r IN SELECT viewname FROM pg_views WHERE schemaname='public' AND viewname LIKE 'acct\_v\_%' LOOP
      EXECUTE format('REVOKE ALL ON public.%I FROM anon', r.viewname);
      EXECUTE format('GRANT SELECT ON public.%I TO authenticated', r.viewname);
    END LOOP;
  END;

  -- =====================================================================================
  -- Function EXECUTE allowlist
  --   granted to authenticated: security-invoker functions (RLS applies) and security-
  --   definer functions that check tenant access or the service role themselves.
  --   Everything else (internal helpers, the Stripe processor, schedulers) is service-only.
  -- =====================================================================================
  DECLARE f record; v_sig text;
  BEGIN
    FOR f IN
      SELECT p.oid, p.proname, p.prosecdef, p.prosrc, pg_get_function_identity_arguments(p.oid) AS args,
             pg_get_function_result(p.oid) AS res
        FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
       WHERE n.nspname = 'public' AND p.proname LIKE 'acct\_%' AND p.prokind = 'f'
    LOOP
      v_sig := format('public.%I(%s)', f.proname, f.args);
      EXECUTE 'REVOKE ALL ON FUNCTION ' || v_sig || ' FROM PUBLIC, anon';
      EXECUTE 'GRANT EXECUTE ON FUNCTION ' || v_sig || ' TO service_role';
      IF f.res = 'trigger' THEN
        EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || v_sig || ' FROM authenticated';
      ELSIF NOT f.prosecdef
         OR f.prosrc ~ '(acct_assert_access|acct_can_access|acct__assert_migrator|service_role)'
         OR f.proname IN ('acct_is_tenant_member','acct_complete_contractor_profile','acct_valid_routing','acct__pnl_section',
                          -- id-only lookups the app needs to build postings (return uuids, never row data)
                          'acct_default_entity','acct_role_account','acct_primary_book','acct_bank_gl','acct_fiscal_year_start') THEN
        EXECUTE 'GRANT EXECUTE ON FUNCTION ' || v_sig || ' TO authenticated';
      ELSE
        EXECUTE 'REVOKE EXECUTE ON FUNCTION ' || v_sig || ' FROM authenticated';
      END IF;
    END LOOP;
  END;
  -- the RLS policies call this, so app users must be able to execute it
  GRANT EXECUTE ON FUNCTION public.acct_is_tenant_member(uuid) TO authenticated;
  REVOKE ALL ON FUNCTION public.acct__apply_security() FROM PUBLIC, anon, authenticated;
END $$;

-- @seq 75
CREATE FUNCTION public.acct__assert_migrator(p_tenant uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NOT (current_user IN ('postgres','supabase_admin','service_role')
          OR coalesce(auth.role(),'') = 'service_role'
          OR platform_is_admin()
          OR EXISTS (SELECT 1 FROM tenant_memberships m WHERE m.tenant_id = p_tenant AND m.user_id = auth.uid()
                      AND m.role = 'owner' AND m.active AND m.status = 'active')) THEN
    RAISE EXCEPTION 'Only the company owner or the platform service role can run the legacy migration';
  END IF;
END $$;

-- @seq 76
CREATE FUNCTION public.acct__close_check(p_tenant_id uuid, p_code text, p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE n numeric; v_entity uuid := acct_default_entity(p_tenant_id); d jsonb;
BEGIN
  CASE p_code
  WHEN 'bank_feed_clear' THEN
    SELECT count(*) INTO n FROM acct_bank_transactions WHERE tenant_id = p_tenant_id AND review_status IN ('for_review','categorized') AND transaction_date <= p_to;
    RETURN jsonb_build_object('passed', n = 0, 'detail', n || ' bank lines still waiting');
  WHEN 'all_reconciled' THEN
    SELECT count(*) INTO n FROM acct_bank_accounts ba
     WHERE ba.tenant_id = p_tenant_id AND ba.is_active AND coalesce(ba.account_kind,'') NOT IN ('undeposited_funds','payment_processor')
       AND EXISTS (SELECT 1 FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id
                    WHERE l.account_id = ba.gl_account_id AND je.entry_date <= p_to)
       AND NOT EXISTS (SELECT 1 FROM acct_reconciliations r WHERE r.bank_account_id = ba.id AND r.status = 'reconciled' AND r.as_of_date >= p_to);
    RETURN jsonb_build_object('passed', n = 0, 'detail', n || ' accounts not reconciled through ' || p_to);
  WHEN 'inventory_tieout' THEN
    SELECT coalesce(sum(abs(difference)),0) INTO n FROM acct_inventory_tieout(p_tenant_id, p_to);
    RETURN jsonb_build_object('passed', n < 0.005, 'detail', 'Difference ' || n);
  WHEN 'depreciation_current' THEN
    SELECT count(*) INTO n FROM acct_asset_books b JOIN acct_fixed_assets a ON a.id = b.asset_id
     WHERE a.tenant_id = p_tenant_id AND a.status = 'in_service' AND b.depreciation_start_date <= p_to
       AND coalesce(b.last_depreciation_date, b.depreciation_start_date - 1) < p_to;
    RETURN jsonb_build_object('passed', n = 0, 'detail', n || ' assets not depreciated through ' || p_to);
  WHEN 'recognition_current' THEN
    SELECT count(*) INTO n FROM acct_recognition_lines rl WHERE rl.tenant_id = p_tenant_id AND rl.status = 'pending' AND rl.recognize_on <= p_to;
    RETURN jsonb_build_object('passed', n = 0, 'detail', n || ' schedule lines due but not posted');
  WHEN 'payroll_posted' THEN
    SELECT count(*) INTO n FROM acct_payroll_runs pr JOIN acct_pay_periods pp ON pp.id = pr.pay_period_id
     WHERE pr.tenant_id = p_tenant_id AND pp.pay_date BETWEEN p_from AND p_to AND pr.status IN ('submitted','paid') AND pr.gl_journal_entry_id IS NULL;
    RETURN jsonb_build_object('passed', n = 0, 'detail', n || ' paid payroll runs not in the books');
  WHEN 'review_clear' THEN
    SELECT count(*) INTO n FROM acct_review_findings WHERE tenant_id = p_tenant_id AND status IN ('open','in_progress') AND severity = 'error'
       AND (txn_date IS NULL OR txn_date <= p_to);
    RETURN jsonb_build_object('passed', n = 0, 'detail', n || ' open error findings');
  WHEN 'flux_explained' THEN
    SELECT count(*) INTO n FROM acct_flux_analysis(p_tenant_id, p_from, p_to) f WHERE f.flagged AND f.explanation IS NULL;
    RETURN jsonb_build_object('passed', n = 0, 'detail', n || ' flagged accounts without an explanation');
  ELSE
    -- any review check code: passes when there are no open findings of that kind dated in the window
    SELECT count(*) INTO n FROM acct_review_findings WHERE tenant_id = p_tenant_id AND status IN ('open','in_progress') AND check_code = p_code
       AND (txn_date IS NULL OR txn_date <= p_to);
    RETURN jsonb_build_object('passed', n = 0, 'detail', n || ' open ' || p_code || ' findings');
  END CASE;
END $$;

-- @seq 77
CREATE FUNCTION public.acct__csv_header_index(p_hdr text[], p_key text, p_mapping jsonb) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE cands text[]; c text; i int;
BEGIN
  IF p_mapping ? p_key THEN
    FOR i IN 1..coalesce(array_length(p_hdr,1),0) LOOP
      IF lower(btrim(p_hdr[i])) = lower(btrim(p_mapping->>p_key)) THEN RETURN i; END IF;
    END LOOP;
    RAISE EXCEPTION 'Mapped column "%" for % is not in the file header', p_mapping->>p_key, p_key;
  END IF;
  cands := CASE p_key
    WHEN 'date' THEN ARRAY['transaction date','trans. date','trans date','date','posting date','posted date','post date']
    WHEN 'description' THEN ARRAY['description','transaction description','memo','details','name','narrative']
    WHEN 'amount' THEN ARRAY['amount','transaction amount','amount ($)','amount (usd)']
    WHEN 'debit' THEN ARRAY['debit','debits','withdrawal','withdrawals','debit amount','money out','withdrawal amount']
    WHEN 'credit' THEN ARRAY['credit','credits','deposit','deposits','credit amount','money in','deposit amount']
    WHEN 'reference' THEN ARRAY['check number','check or slip #','check #','check no','reference','ref','ref #','reference number']
    WHEN 'id' THEN ARRAY['transaction id','fitid']
    WHEN 'payee' THEN ARRAY['payee','merchant','merchant name','counterparty'] END;
  FOREACH c IN ARRAY cands LOOP           -- preference order of the candidate list
    FOR i IN 1..coalesce(array_length(p_hdr,1),0) LOOP
      IF lower(btrim(p_hdr[i])) = c THEN RETURN i; END IF;
    END LOOP;
  END LOOP;
  RETURN NULL;
END $_$;

-- @seq 78
CREATE FUNCTION public.acct__csv_rows(p_text text, p_delim text DEFAULT ','::text) RETURNS SETOF text[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE i int := 1; n int := length(p_text); ch text; f text := ''; rec text[] := '{}'; q boolean := false; any_char boolean := false;
BEGIN
  WHILE i <= n LOOP
    ch := substr(p_text, i, 1);
    IF q THEN
      IF ch = '"' THEN
        IF substr(p_text, i + 1, 1) = '"' THEN f := f || '"'; i := i + 1; ELSE q := false; END IF;
      ELSE f := f || ch; END IF;
    ELSE
      IF ch = '"' THEN q := true; any_char := true;
      ELSIF ch = p_delim THEN rec := rec || f; f := ''; any_char := true;
      ELSIF ch = E'\n' OR ch = E'\r' THEN
        IF ch = E'\r' AND substr(p_text, i + 1, 1) = E'\n' THEN i := i + 1; END IF;
        IF any_char OR f <> '' THEN rec := rec || f; RETURN NEXT rec; END IF;
        rec := '{}'; f := ''; any_char := false;
      ELSE f := f || ch; any_char := true; END IF;
    END IF;
    i := i + 1;
  END LOOP;
  IF any_char OR f <> '' THEN rec := rec || f; RETURN NEXT rec; END IF;
END $$;

-- @seq 79
CREATE FUNCTION public.acct__default_asset_class(p_tenant_id uuid, p_entity_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid;
BEGIN
  SELECT id INTO v FROM acct_asset_classes WHERE tenant_id = p_tenant_id AND code = 'EQUIP';
  IF v IS NULL THEN
    INSERT INTO acct_asset_classes(tenant_id, code, name, asset_account_id, accumulated_depreciation_account_id, depreciation_expense_account_id,
                                   default_useful_life_months, default_method, residual_percent)
    VALUES (p_tenant_id, 'EQUIP', 'Furniture and Equipment', acct__role(p_tenant_id, p_entity_id, 'fixed_assets'),
            acct__role(p_tenant_id, p_entity_id, 'accumulated_depreciation'), acct__role(p_tenant_id, p_entity_id, 'depreciation_expense'), 84, 'straight_line', 0)
    ON CONFLICT (tenant_id, code) DO NOTHING RETURNING id INTO v;
    IF v IS NULL THEN SELECT id INTO v FROM acct_asset_classes WHERE tenant_id = p_tenant_id AND code = 'EQUIP'; END IF;
  END IF;
  RETURN v;
END $$;

