   (p_tenant_id, v, '1. Cash',        'Clear the bank feed', 'Accept, match or exclude every bank and card line dated in the month.', 10, 3, 'every_close', 'bank_feed_clear', 3),
   (p_tenant_id, v, '1. Cash',        'Reconcile every bank, card and loan account', 'Statement balance must equal the books at month end.', 20, 5, 'every_close', 'all_reconciled', 3),
   (p_tenant_id, v, '1. Cash',        'Deposit undeposited payments', 'Nothing older than 14 days left in Undeposited Funds.', 30, 3, 'every_close', 'stale_undeposited', 1),
   (p_tenant_id, v, '1. Cash',        'Tie Stripe balance to payouts', 'Stripe clearing account should hold only charges not yet paid out.', 40, 5, 'every_close', NULL, 1),
   (p_tenant_id, v, '2. Sales',       'Sync shop orders', 'Every shipped order is in the books; no order posting errors.', 50, 2, 'every_close', 'order_sync_error', 3),
   (p_tenant_id, v, '2. Sales',       'Review open invoices and customer credits', 'Follow up overdue invoices; apply unapplied payments.', 60, 5, 'every_close', 'unapplied_payment', 1),
   (p_tenant_id, v, '2. Sales',       'Sales tax review', 'Every tax line has a jurisdiction; rates are consistent.', 70, 5, 'every_close', 'tax_no_jurisdiction', 2),
   (p_tenant_id, v, '3. Purchases',   'Enter all vendor bills for the month', 'Including bills received after month end for goods/services received in the month.', 80, 5, 'every_close', NULL, 2),
   (p_tenant_id, v, '3. Purchases',   'Attach receipts', 'Every expense over the receipt threshold has a receipt.', 90, 5, 'every_close', 'missing_attachment', 1),
   (p_tenant_id, v, '4. Inventory',   'Count or spot-check inventory', 'Post the count; investigate large shrink.', 100, 5, 'every_close', 'negative_inventory', 2),
   (p_tenant_id, v, '4. Inventory',   'Inventory ties to the general ledger', NULL, 110, 6, 'every_close', 'inventory_tieout', 3),
   (p_tenant_id, v, '5. Adjustments', 'Run depreciation', NULL, 120, 6, 'every_close', 'depreciation_current', 2),
   (p_tenant_id, v, '5. Adjustments', 'Run prepaid / deferred revenue / accrual schedules', NULL, 130, 6, 'every_close', 'recognition_current', 2),
   (p_tenant_id, v, '5. Adjustments', 'Record accruals for unbilled expenses', 'Utilities, contractors, anything used but not billed yet.', 140, 6, 'every_close', NULL, 1),
   (p_tenant_id, v, '5. Adjustments', 'Post payroll for every pay date in the month', NULL, 150, 5, 'every_close', 'payroll_posted', 2),
   (p_tenant_id, v, '6. Review',      'Run the file review and clear errors', 'All error-level findings resolved; warnings explained.', 160, 7, 'every_close', 'review_clear', 3),
   (p_tenant_id, v, '6. Review',      'Sub-ledgers tie out (A/R, A/P, inventory, schedules)', NULL, 170, 7, 'every_close', 'subledger_tieout', 3),
   (p_tenant_id, v, '6. Review',      'Explain significant changes vs prior month', 'Flux analysis: explain every flagged account.', 180, 8, 'every_close', 'flux_explained', 1),
   (p_tenant_id, v, '7. Reporting',   'Publish the monthly report package', NULL, 190, 10, 'every_close', NULL, 1),
   (p_tenant_id, v, '7. Reporting',   'Prepare quarterly sales tax / payroll filings', NULL, 200, 15, 'quarter_end', NULL, 2),
   (p_tenant_id, v, '7. Reporting',   'Year end: 1099s, W-2s, fixed asset review, close the year', NULL, 210, 25, 'year_end', 'w9_complete', 3);
  RETURN v;
END $$;

-- @seq 81
CREATE FUNCTION public.acct__depreciation_month(p_method text, p_convention text, p_cost numeric, p_residual numeric, p_life integer, p_accumulated numeric, p_months_taken integer, p_is_first boolean) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE v_base numeric := p_cost - p_residual; v_left numeric := v_base - p_accumulated; v_amt numeric; v_months_left int; v_rate numeric;
BEGIN
  IF v_left <= 0 THEN RETURN 0; END IF;
  v_months_left := greatest(p_life - p_months_taken, 1);
  IF p_method = 'straight_line' THEN
    v_amt := v_base / p_life;
  ELSE
    v_rate := CASE p_method WHEN 'double_declining' THEN 2.0 ELSE 1.5 END / p_life;
    v_amt := greatest((p_cost - p_accumulated) * v_rate, v_left / v_months_left);   -- switch to straight-line when it is larger
  END IF;
  IF p_is_first AND p_convention = 'mid_month' THEN v_amt := v_amt / 2; END IF;
  IF p_months_taken + 1 >= p_life THEN v_amt := v_left; END IF;   -- last month takes the remainder
  RETURN round(least(v_amt, v_left), 2);
END $$;

-- @seq 82
CREATE FUNCTION public.acct__ensure_account(p_tenant_id uuid, p_entity_id uuid, p_code text, p_name text, p_type text, p_normal text, p_subtype text, p_detail text, p_role text DEFAULT NULL::text, p_cash_flow text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid;
BEGIN
  IF p_role IS NOT NULL THEN
    v := acct_role_account(p_tenant_id, p_entity_id, p_role, false);
    IF v IS NOT NULL THEN RETURN v; END IF;
  END IF;
  SELECT id INTO v FROM acct_chart_of_accounts WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id AND code = p_code AND account_type = p_type;
  -- the tenant used this code for something else: never post into it, open the next free sub-code instead
  WHILE v IS NULL AND EXISTS (SELECT 1 FROM acct_chart_of_accounts WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id AND code = p_code) LOOP
    p_code := p_code || '.1';
    SELECT id INTO v FROM acct_chart_of_accounts WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id AND code = p_code AND account_type = p_type;
  END LOOP;
  IF v IS NULL THEN
    INSERT INTO acct_chart_of_accounts(tenant_id, entity_id, code, name, account_type, normal_balance, subtype, detail_type,
           is_control_account, is_reconcilable, is_system, cash_flow_category, metadata, is_bank_feed)
    VALUES (p_tenant_id, p_entity_id, p_code, p_name, p_type, p_normal, p_subtype, p_detail, false, false, true, p_cash_flow, '{}'::jsonb, false)
    RETURNING id INTO v;
  END IF;
  IF p_role IS NOT NULL THEN
    INSERT INTO acct_account_roles(tenant_id, entity_id, role, account_id) VALUES (p_tenant_id, p_entity_id, p_role, v)
    ON CONFLICT (tenant_id, entity_id, role) DO NOTHING;
  END IF;
  RETURN v;
END $$;

-- @seq 83
CREATE FUNCTION public.acct__ensure_operating_accounts(p_tenant_id uuid, p_entity_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r record; v_id uuid; v_code text; n int := 0;
BEGIN
  FOR r IN SELECT * FROM (VALUES
    ('5100','Inventory Shrinkage and Adjustments','expense','cogs','inventory_adjustments','4','debit','inventory_adjustments'),
    ('2500','Accrued Liabilities','liability','other_current_liability','accrued_liabilities','BS','credit','accrued_liabilities'),
    ('2550','Deferred Revenue','liability','other_current_liability','deferred_revenue','BS','credit','deferred_revenue'),
    ('1400','Prepaid Expenses','asset','other_current_asset','prepaid','BS','debit','prepaid_expenses'),
    ('1500','Furniture and Equipment','asset','fixed_asset','equipment','BS','debit','fixed_assets'),
    ('1590','Accumulated Depreciation','contra_asset','accumulated_depreciation','accumulated_depreciation','BS','credit','accumulated_depreciation'),
    ('6150','Depreciation','expense','expense','depreciation','13','debit','depreciation_expense'),
    ('7900','Gain or Loss on Asset Disposal','expense','other_expense','asset_disposal','BS','debit','asset_disposal_gain_loss'),
    ('6760','Payroll Tax Expense','expense','expense','payroll_taxes','23','debit','payroll_tax_expense'),
    ('7950','Unrealized FX Gain or Loss','expense','other_expense','fx_unrealized','BS','debit','unrealized_fx_gain_loss')
  ) AS t(code,name,typ,sub,detail,line,nb,role) LOOP
    CONTINUE WHEN EXISTS (SELECT 1 FROM acct_account_roles WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id AND role = r.role);
    v_code := r.code;
    SELECT id INTO v_id FROM acct_chart_of_accounts WHERE tenant_id = p_tenant_id AND code = v_code AND account_type = r.typ;
    IF v_id IS NULL AND EXISTS (SELECT 1 FROM acct_chart_of_accounts WHERE tenant_id = p_tenant_id AND code = v_code) THEN
      v_code := r.code || '-1';
      SELECT id INTO v_id FROM acct_chart_of_accounts WHERE tenant_id = p_tenant_id AND code = v_code;
    END IF;
    IF v_id IS NULL THEN
      INSERT INTO acct_chart_of_accounts(tenant_id, entity_id, code, name, account_type, normal_balance, subtype, detail_type,
             is_control_account, is_reconcilable, is_system, tax_line_id, metadata, is_bank_feed)
      VALUES (p_tenant_id, p_entity_id, v_code, r.name, r.typ, r.nb, r.sub, r.detail, false, false, true,
              (SELECT id FROM acct_tax_lines WHERE tenant_id IS NULL AND form = CASE WHEN r.line = 'BS' THEN 'Balance sheet' ELSE 'Schedule C' END AND line = r.line LIMIT 1),
              '{}'::jsonb, false)
      RETURNING id INTO v_id;
      n := n + 1;
    END IF;
    INSERT INTO acct_account_roles(tenant_id, entity_id, role, account_id) VALUES (p_tenant_id, p_entity_id, r.role, v_id)
    ON CONFLICT (tenant_id, entity_id, role) DO NOTHING;
  END LOOP;
  RETURN n;
END $$;

-- @seq 84
CREATE FUNCTION public.acct__eval_kpi(p_formula text, p_tokens jsonb) RETURNS numeric
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_expr text := lower(p_formula); k text; v numeric; v_rest text;
BEGIN
  v_rest := regexp_replace(v_expr, '[a-z_][a-z0-9_]*', '', 'g');
  IF v_rest !~ '^[0-9.+\-*/() ]*$' THEN RAISE EXCEPTION 'KPI formula has invalid characters: %', p_formula; END IF;
  FOR k IN SELECT m[1] FROM regexp_matches(v_expr, '[a-z_][a-z0-9_]*', 'g') m LOOP
    IF NOT p_tokens ? k THEN RAISE EXCEPTION 'Unknown KPI token "%" (allowed: %)', k, (SELECT string_agg(x, ', ') FROM jsonb_object_keys(p_tokens) x); END IF;
  END LOOP;
  FOR k IN SELECT x FROM jsonb_object_keys(p_tokens) x ORDER BY length(x) DESC LOOP
    v_expr := regexp_replace(v_expr, '\m' || k || '\M', '(' || (p_tokens->>k)::numeric::text || '::numeric)', 'g');
  END LOOP;
  BEGIN
    EXECUTE 'SELECT round((' || v_expr || ')::numeric, 2)' INTO v;
  EXCEPTION WHEN division_by_zero THEN v := NULL;
  END;
  RETURN v;
END $_$;

-- @seq 85
CREATE FUNCTION public.acct__inv_components(p_item_id uuid, p_qty numeric) RETURNS TABLE(item_id uuid, quantity numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT i.id, p_qty FROM acct_items i WHERE i.id = p_item_id AND i.item_type = 'inventory'
  UNION ALL
  SELECT c.id, p_qty * coalesce((comp->>'quantity')::numeric, 1)
    FROM acct_items b CROSS JOIN LATERAL jsonb_array_elements(coalesce(b.bundle_components,'[]'::jsonb)) comp
    JOIN acct_items c ON c.id = (comp->>'item_id')::uuid AND c.item_type = 'inventory'
   WHERE b.id = p_item_id AND b.item_type = 'bundle';
$$;

-- @seq 86
CREATE FUNCTION public.acct__inv_invoice_posted(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE iv acct_ar_invoices%ROWTYPE; l record; c record; it acct_items%ROWTYPE; r record; v_lines jsonb := '[]'::jsonb;
        v_moves uuid[] := '{}'; v_mid uuid;
BEGIN
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id;
  IF EXISTS (SELECT 1 FROM acct_inventory_moves WHERE source_type = 'acct_ar_invoices' AND source_id = iv.id) THEN RETURN NULL; END IF;
  FOR l IN SELECT * FROM acct_ar_invoice_lines WHERE invoice_id = iv.id AND item_id IS NOT NULL AND coalesce(quantity,0) <> 0 ORDER BY line_no LOOP
    FOR c IN SELECT * FROM acct__inv_components(l.item_id, l.quantity) LOOP
      SELECT * INTO it FROM acct_items WHERE id = c.item_id;
      IF c.quantity > 0 THEN
        SELECT * INTO r FROM acct__inv_issue(iv.tenant_id, iv.entity_id, c.item_id, c.quantity, iv.invoice_date, 'sale',
                                             'acct_ar_invoices', iv.id, l.id, iv.invoice_number, NULL);
        v_moves := v_moves || r.move_id;
        v_lines := v_lines || jsonb_build_array(
          jsonb_build_object('account_id', it.cogs_account_id, 'debit', r.cost, 'item_id', it.id, 'description', 'COGS ' || it.name, 'customer_id', iv.customer_id::text),
          jsonb_build_object('account_id', it.inventory_asset_account_id, 'credit', r.cost, 'item_id', it.id, 'description', 'COGS ' || it.name));
      ELSE   -- negative quantity on a sales receipt = item returned at the counter
        v_mid := acct__inv_receive(iv.tenant_id, iv.entity_id, c.item_id, -c.quantity, round(-c.quantity * coalesce(it.last_unit_cost, it.purchase_cost, 0), 2),
                                   iv.invoice_date, 'customer_return', 'acct_ar_invoices', iv.id, l.id, iv.invoice_number, 'Returned on sales receipt');
        v_moves := v_moves || v_mid;
        v_lines := v_lines || jsonb_build_array(
          jsonb_build_object('account_id', it.inventory_asset_account_id, 'debit', round(-c.quantity * coalesce(it.last_unit_cost, it.purchase_cost, 0), 2), 'item_id', it.id, 'description', 'Return ' || it.name),
          jsonb_build_object('account_id', it.cogs_account_id, 'credit', round(-c.quantity * coalesce(it.last_unit_cost, it.purchase_cost, 0), 2), 'item_id', it.id, 'description', 'Return ' || it.name, 'customer_id', iv.customer_id::text));
      END IF;
    END LOOP;
  END LOOP;
  IF cardinality(v_moves) = 0 THEN RETURN NULL; END IF;
  RETURN acct__inv_post_je(iv.tenant_id, iv.entity_id, iv.invoice_date, v_lines, iv.invoice_number,
                           'Cost of goods sold ' || iv.invoice_number, 'cogs:inv:' || iv.id, 'acct_ar_invoices', iv.id, v_moves);
END $$;

-- @seq 87
CREATE FUNCTION public.acct__inv_issue(p_tenant_id uuid, p_entity_id uuid, p_item_id uuid, p_qty numeric, p_date date, p_type text, p_source_type text, p_source_id uuid, p_source_line_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS TABLE(move_id uuid, cost numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_move uuid; v_left numeric := p_qty; v_take numeric; v_cost numeric := 0; l record; i acct_items%ROWTYPE; v_fallback numeric;
BEGIN
  IF p_qty <= 0 THEN RAISE EXCEPTION 'Quantity issued must be positive'; END IF;
  SELECT * INTO i FROM acct_items WHERE id = p_item_id FOR UPDATE;
  INSERT INTO acct_inventory_moves(tenant_id, entity_id, item_id, move_date, move_type, quantity, unit_cost, total_cost,
                                   source_type, source_id, source_line_id, reference, reason)
  VALUES (p_tenant_id, p_entity_id, p_item_id, p_date, p_type, -p_qty, 0, 0, p_source_type, p_source_id, p_source_line_id, p_reference, p_reason)
  RETURNING id INTO v_move;
  FOR l IN SELECT * FROM acct_inventory_layers WHERE item_id = p_item_id AND qty_remaining > 0 ORDER BY layer_date, created_at FOR UPDATE LOOP
    EXIT WHEN v_left <= 0;
    v_take := least(v_left, l.qty_remaining);
    UPDATE acct_inventory_layers SET qty_remaining = qty_remaining - v_take WHERE id = l.id;
    INSERT INTO acct_inventory_layer_draws(tenant_id, move_id, layer_id, quantity, unit_cost) VALUES (p_tenant_id, v_move, l.id, v_take, l.unit_cost);
    v_cost := v_cost + round(v_take * l.unit_cost, 2);
    v_left := v_left - v_take;
  END LOOP;
  IF v_left > 0 THEN
    IF NOT (acct__settings(p_tenant_id, p_entity_id)).inventory_allow_negative THEN
      RAISE EXCEPTION 'Not enough % on hand (short %)', i.name, v_left; END IF;
    v_fallback := coalesce(i.last_unit_cost, i.purchase_cost, 0);
    INSERT INTO acct_inventory_layer_draws(tenant_id, move_id, layer_id, quantity, unit_cost) VALUES (p_tenant_id, v_move, NULL, v_left, v_fallback);
    v_cost := v_cost + round(v_left * v_fallback, 2);
  END IF;
  UPDATE acct_inventory_moves SET total_cost = -v_cost, unit_cost = round(v_cost / p_qty, 6) WHERE id = v_move;
  UPDATE acct_items SET quantity_on_hand = quantity_on_hand - p_qty, quantity_as_of = p_date WHERE id = p_item_id;
  PERFORM acct__inv_mirror(v_move);
  move_id := v_move; cost := v_cost; RETURN NEXT;
END $$;

-- @seq 88
CREATE FUNCTION public.acct__inv_mirror(p_move_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE m acct_inventory_moves%ROWTYPE; v_sku uuid; v_id uuid; v_wh uuid; v_loc uuid; v_type erp_inventory_movement_type;
        v_affects boolean := true;
BEGIN
  SELECT * INTO m FROM acct_inventory_moves WHERE id = p_move_id;
  v_sku := erp__sku_for_item(m.item_id);
  IF v_sku IS NULL OR m.quantity = 0 THEN RETURN; END IF;
  v_type := CASE m.move_type
              WHEN 'opening' THEN 'opening' WHEN 'receipt' THEN 'purchase_receipt' WHEN 'receipt_reversal' THEN 'adjustment'
              WHEN 'sale' THEN 'sale' WHEN 'sale_reversal' THEN 'return' WHEN 'customer_return' THEN 'return'
              WHEN 'vendor_return' THEN 'adjustment' WHEN 'revaluation' THEN 'cost_adjustment'
              WHEN 'count' THEN 'count_adjustment' ELSE 'adjustment' END::erp_inventory_movement_type;
  IF m.move_type = 'revaluation' THEN v_affects := false; END IF;
  IF m.source_type = 'acct_ap_bills' AND EXISTS (SELECT 1 FROM acct_ap_bill_lines bl WHERE bl.id = m.source_line_id AND bl.erp_po_line_id IS NOT NULL) THEN
    v_affects := false;     -- physical stock arrived through erp_receive_purchase_order
  END IF;
  IF current_setting('app.erp_stock_recorded', true) = 'on' THEN v_affects := false; END IF;
  -- order stock moves physically through erp_mark_shipped (out) and erp_receive_return (back in);
  -- the order's cost-of-goods moves stay on the books only, so stock is never counted twice
  IF m.source_type = 'erp_orders' THEN v_affects := false; END IF;
  v_wh := erp__default_warehouse(m.tenant_id);
  v_loc := CASE WHEN v_wh IS NOT NULL THEN erp__default_location(m.tenant_id, v_wh) END;
  INSERT INTO erp_inventory_movements(tenant_id, movement_type, sku_id, warehouse_id, from_location_id, to_location_id, quantity,
                                      unit_cost, total_cost, source_type, source_id, reference, reason, metadata, occurred_at, performed_by)
  VALUES (m.tenant_id, v_type, v_sku, v_wh, CASE WHEN m.quantity < 0 THEN v_loc END, CASE WHEN m.quantity > 0 THEN v_loc END, m.quantity,
          coalesce(m.unit_cost,0), coalesce(m.total_cost,0), coalesce(m.source_type, 'acct_inventory_moves'), coalesce(m.source_id, m.id)::text, m.reference, m.reason,
          jsonb_build_object('acct_inventory_move_id', m.id, 'acct_move_type', m.move_type, 'affects_stock', v_affects),
          m.move_date::timestamptz, auth.uid())
  RETURNING id INTO v_id;
  UPDATE acct_inventory_moves SET erp_movement_id = v_id WHERE id = m.id;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'ERP stock mirror skipped for move %: %', p_move_id, SQLERRM;   -- never block a posting
END $$;

-- @seq 89
CREATE FUNCTION public.acct__inv_post_je(p_tenant_id uuid, p_entity_id uuid, p_date date, p_lines jsonb, p_ref text, p_memo text, p_idem text, p_doc_type text, p_doc_id uuid, p_move_ids uuid[]) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_je uuid; v_lines jsonb;
BEGIN
  SELECT coalesce(jsonb_agg(x), '[]'::jsonb) INTO v_lines FROM jsonb_array_elements(p_lines) x
   WHERE coalesce((x->>'debit')::numeric,0) <> 0 OR coalesce((x->>'credit')::numeric,0) <> 0;
  IF jsonb_array_length(v_lines) < 2 THEN RETURN NULL; END IF;
  v_je := acct_post_entry(p_tenant_id, p_entity_id, p_date, v_lines, 'inventory', p_doc_id::text, p_ref, p_memo, p_idem,
                          NULL, NULL, NULL, false, false, p_doc_type, p_doc_id);
  UPDATE acct_inventory_moves SET journal_entry_id = v_je WHERE id = ANY (p_move_ids) AND journal_entry_id IS NULL;
  RETURN v_je;
END $$;

-- @seq 90
CREATE FUNCTION public.acct__inv_receive(p_tenant_id uuid, p_entity_id uuid, p_item_id uuid, p_qty numeric, p_total_cost numeric, p_date date, p_type text, p_source_type text, p_source_id uuid, p_source_line_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_move uuid; v_unit numeric;
BEGIN
  IF p_qty <= 0 THEN RAISE EXCEPTION 'Quantity received must be positive'; END IF;
  IF p_total_cost < 0 THEN RAISE EXCEPTION 'Inventory cost cannot be negative'; END IF;
  v_unit := round(p_total_cost / p_qty, 6);
  INSERT INTO acct_inventory_moves(tenant_id, entity_id, item_id, move_date, move_type, quantity, unit_cost, total_cost,
                                   source_type, source_id, source_line_id, reference, reason)
  VALUES (p_tenant_id, p_entity_id, p_item_id, p_date, p_type, p_qty, v_unit, p_total_cost, p_source_type, p_source_id, p_source_line_id, p_reference, p_reason)
  RETURNING id INTO v_move;
  INSERT INTO acct_inventory_layers(tenant_id, item_id, layer_date, source_move_id, qty_in, qty_remaining, unit_cost)
  VALUES (p_tenant_id, p_item_id, p_date, v_move, p_qty, p_qty, v_unit);
  UPDATE acct_items SET quantity_on_hand = quantity_on_hand + p_qty, last_unit_cost = v_unit, quantity_as_of = p_date WHERE id = p_item_id;
  PERFORM acct__inv_mirror(v_move);
  RETURN v_move;
END $$;

-- @seq 91
CREATE FUNCTION public.acct__inv_restock(p_tenant_id uuid, p_entity_id uuid, p_item_id uuid, p_qty numeric, p_unit_cost numeric, p_date date, p_doc_type text, p_doc_id uuid, p_ref text, p_idem text, p_customer text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE it acct_items%ROWTYPE; v_cost numeric; v_move uuid;
BEGIN
  SELECT * INTO it FROM acct_items WHERE id = p_item_id AND tenant_id = p_tenant_id;
  IF NOT FOUND OR it.item_type <> 'inventory' THEN RAISE EXCEPTION 'Restock item must be a stocked inventory item'; END IF;
  v_cost := round(p_qty * coalesce(p_unit_cost,
              -- cost it left at on the original sale, else last cost
              (SELECT round(sum(d.quantity * d.unit_cost) / nullif(sum(d.quantity),0), 6) FROM acct_inventory_moves m JOIN acct_inventory_layer_draws d ON d.move_id = m.id
                WHERE m.item_id = p_item_id AND m.move_type = 'sale' AND m.source_type = 'acct_ar_invoices'
                  AND m.source_id = (SELECT invoice_id FROM acct_refunds WHERE id = p_doc_id)),
              it.last_unit_cost, it.purchase_cost, 0), 2);
  v_move := acct__inv_receive(p_tenant_id, p_entity_id, p_item_id, p_qty, v_cost, p_date, 'customer_return', p_doc_type, p_doc_id, NULL, p_ref, 'Customer return');
  RETURN acct__inv_post_je(p_tenant_id, p_entity_id, p_date, jsonb_build_array(
           jsonb_build_object('account_id', it.inventory_asset_account_id, 'debit', v_cost, 'item_id', it.id, 'description', 'Restock ' || it.name),
           jsonb_build_object('account_id', it.cogs_account_id, 'credit', v_cost, 'item_id', it.id, 'description', 'Restock ' || it.name, 'customer_id', p_customer)),
         p_ref, 'Restock ' || it.name, p_idem, p_doc_type, p_doc_id, ARRAY[v_move]);
END $$;

-- @seq 92
CREATE FUNCTION public.acct__inv_restore(p_move_id uuid, p_date date, p_type text DEFAULT 'sale_reversal'::text) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE m acct_inventory_moves%ROWTYPE; d record; v_new uuid; v_layer_move uuid;
BEGIN
  SELECT * INTO m FROM acct_inventory_moves WHERE id = p_move_id FOR UPDATE;
  IF m.reversed_by_move_id IS NOT NULL OR m.quantity >= 0 THEN RETURN 0; END IF;
  INSERT INTO acct_inventory_moves(tenant_id, entity_id, item_id, move_date, move_type, quantity, unit_cost, total_cost,
                                   source_type, source_id, source_line_id, reference, reason)
  VALUES (m.tenant_id, m.entity_id, m.item_id, p_date, p_type, -m.quantity, m.unit_cost, -m.total_cost, m.source_type, m.source_id,
          m.source_line_id, m.reference, 'Reversal')
  RETURNING id INTO v_new;
  FOR d IN SELECT * FROM acct_inventory_layer_draws WHERE move_id = m.id LOOP
    IF d.layer_id IS NOT NULL THEN
      UPDATE acct_inventory_layers SET qty_remaining = qty_remaining + d.quantity WHERE id = d.layer_id;
    ELSE
      INSERT INTO acct_inventory_layers(tenant_id, item_id, layer_date, source_move_id, qty_in, qty_remaining, unit_cost)
      VALUES (m.tenant_id, m.item_id, p_date, v_new, d.quantity, d.quantity, d.unit_cost);
    END IF;
  END LOOP;
  UPDATE acct_inventory_moves SET reversed_by_move_id = v_new WHERE id = m.id;
  UPDATE acct_items SET quantity_on_hand = quantity_on_hand - m.quantity WHERE id = m.item_id;
  PERFORM acct__inv_mirror(v_new);
  RETURN -m.total_cost;
END $$;

-- @seq 93
CREATE FUNCTION public.acct__inv_reverse_source(p_source_type text, p_source_id uuid, p_date date, p_memo text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE m record; v_je uuid;
BEGIN
  FOR m IN SELECT * FROM acct_inventory_moves WHERE source_type = p_source_type AND source_id = p_source_id
              AND reversed_by_move_id IS NULL AND move_type IN ('sale','customer_return','receipt','opening') ORDER BY created_at LOOP
    IF m.quantity < 0 THEN PERFORM acct__inv_restore(m.id, p_date);
    ELSE PERFORM acct__inv_unreceive(m.id, p_date); END IF;
  END LOOP;
  FOR v_je IN SELECT DISTINCT journal_entry_id FROM acct_inventory_moves
               WHERE source_type = p_source_type AND source_id = p_source_id AND journal_entry_id IS NOT NULL LOOP
    IF EXISTS (SELECT 1 FROM acct_journal_entries WHERE id = v_je AND status = 'posted' AND reversed_by_id IS NULL AND source = 'inventory') THEN
      PERFORM acct_reverse_journal(v_je, p_date, p_memo);
    END IF;
  END LOOP;
END $$;

-- @seq 94
CREATE FUNCTION public.acct__inv_unreceive(p_move_id uuid, p_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE m acct_inventory_moves%ROWTYPE; l acct_inventory_layers%ROWTYPE; v_new uuid; v_name text;
BEGIN
  SELECT * INTO m FROM acct_inventory_moves WHERE id = p_move_id FOR UPDATE;
  IF m.reversed_by_move_id IS NOT NULL OR m.quantity <= 0 THEN RETURN; END IF;
  SELECT * INTO l FROM acct_inventory_layers WHERE source_move_id = m.id FOR UPDATE;
  IF l.qty_remaining < l.qty_in THEN
    SELECT name INTO v_name FROM acct_items WHERE id = m.item_id;
    RAISE EXCEPTION 'Some of the % from this purchase has already been sold or used (% of %). Enter a vendor credit instead of voiding.',
      v_name, l.qty_in - l.qty_remaining, l.qty_in;
  END IF;
  UPDATE acct_inventory_layers SET qty_remaining = 0 WHERE id = l.id;
  INSERT INTO acct_inventory_moves(tenant_id, entity_id, item_id, move_date, move_type, quantity, unit_cost, total_cost,
                                   source_type, source_id, source_line_id, reference, reason)
  VALUES (m.tenant_id, m.entity_id, m.item_id, p_date, 'receipt_reversal', -m.quantity, m.unit_cost, -m.total_cost, m.source_type, m.source_id,
          m.source_line_id, m.reference, 'Void')
  RETURNING id INTO v_new;
  UPDATE acct_inventory_moves SET reversed_by_move_id = v_new WHERE id = m.id;
  UPDATE acct_items SET quantity_on_hand = quantity_on_hand - m.quantity WHERE id = m.item_id;
  PERFORM acct__inv_mirror(v_new);
END $$;

-- @seq 95
CREATE FUNCTION public.acct__inv_vendor_return(p_tenant_id uuid, p_entity_id uuid, p_item_id uuid, p_qty numeric, p_credit numeric, p_date date, p_doc_type text, p_doc_id uuid, p_line_id uuid, p_ref text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE it acct_items%ROWTYPE; r record; v_diff numeric; v_adj uuid; v_remaining numeric; v_move uuid; y record; v_left numeric; v_cut numeric;
BEGIN
  SELECT * INTO it FROM acct_items WHERE id = p_item_id;
  v_adj := acct__role(p_tenant_id, p_entity_id, 'inventory_adjustments');
  IF coalesce(p_qty,0) > 0 THEN
    SELECT * INTO r FROM acct__inv_issue(p_tenant_id, p_entity_id, p_item_id, p_qty, p_date, 'vendor_return', p_doc_type, p_doc_id, p_line_id, p_ref, 'Returned to vendor');
    -- the credit document already credited inventory by p_credit; layers dropped by r.cost
    v_diff := p_credit - r.cost;
    PERFORM acct__inv_post_je(p_tenant_id, p_entity_id, p_date, jsonb_build_array(
        jsonb_build_object('account_id', it.inventory_asset_account_id, 'debit', greatest(v_diff,0), 'credit', greatest(-v_diff,0), 'item_id', it.id, 'description', 'Vendor return cost true-up'),
        jsonb_build_object('account_id', v_adj, 'credit', greatest(v_diff,0), 'debit', greatest(-v_diff,0), 'item_id', it.id, 'description', 'Vendor return cost true-up')),
      p_ref, 'Vendor return ' || it.name, 'invret:' || p_line_id, p_doc_type, p_doc_id, ARRAY[r.move_id]);
  ELSE
    -- value-only credit (rebate/price adjustment): lower the cost of stock still on hand; the rest (sold stock) goes to adjustments
    SELECT coalesce(sum(qty_remaining * unit_cost),0) INTO v_remaining FROM acct_inventory_layers WHERE item_id = p_item_id AND qty_remaining > 0;
    v_cut := least(p_credit, v_remaining);
    INSERT INTO acct_inventory_moves(tenant_id, entity_id, item_id, move_date, move_type, quantity, unit_cost, total_cost, source_type, source_id, source_line_id, reference, reason)
    VALUES (p_tenant_id, p_entity_id, p_item_id, p_date, 'revaluation', 0, 0, -v_cut, p_doc_type, p_doc_id, p_line_id, p_ref, 'Vendor credit lowers cost')
    RETURNING id INTO v_move;
    IF v_cut > 0 THEN
      v_left := v_cut;
      FOR y IN SELECT * FROM acct_inventory_layers WHERE item_id = p_item_id AND qty_remaining > 0 ORDER BY layer_date, created_at FOR UPDATE LOOP
        UPDATE acct_inventory_layers SET unit_cost = greatest(0, unit_cost - round(v_cut * (y.qty_remaining * y.unit_cost / v_remaining) / y.qty_remaining, 6)) WHERE id = y.id;
      END LOOP;
    END IF;
    IF p_credit - v_cut <> 0 THEN
      PERFORM acct__inv_post_je(p_tenant_id, p_entity_id, p_date, jsonb_build_array(
          jsonb_build_object('account_id', it.inventory_asset_account_id, 'debit', p_credit - v_cut, 'item_id', it.id, 'description', 'Vendor credit on stock already sold'),
          jsonb_build_object('account_id', v_adj, 'credit', p_credit - v_cut, 'item_id', it.id, 'description', 'Vendor credit on stock already sold')),
        p_ref, 'Vendor credit ' || it.name, 'invreval:' || p_line_id, p_doc_type, p_doc_id, ARRAY[v_move]);
    END IF;
  END IF;
END $$;

-- @seq 96
CREATE FUNCTION public.acct__kpi_tokens(p_tenant_id uuid, p_from date, p_to date, p_entity_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r record; v_cash_start numeric; v_months numeric;
BEGIN
  SELECT
    coalesce(sum(activity) FILTER (WHERE account_type = 'revenue' AND subtype IS DISTINCT FROM 'other_income'),0) revenue,
    coalesce(sum(activity) FILTER (WHERE account_type = 'revenue' AND subtype = 'other_income'),0) other_income,
    coalesce(sum(activity) FILTER (WHERE account_type = 'expense' AND subtype = 'cogs'),0) cogs,
    coalesce(sum(activity) FILTER (WHERE account_type = 'expense' AND subtype IS DISTINCT FROM 'cogs' AND subtype IS DISTINCT FROM 'other_expense'),0) opex,
    coalesce(sum(activity) FILTER (WHERE account_type = 'expense' AND subtype = 'other_expense'),0) other_expense,
    coalesce(sum(ending_balance) FILTER (WHERE subtype IN ('bank','cash')),0) cash,
    coalesce(sum(ending_balance) FILTER (WHERE subtype = 'accounts_receivable'),0) ar,
    coalesce(sum(ending_balance) FILTER (WHERE subtype = 'inventory'),0) inventory,
    coalesce(sum(ending_balance) FILTER (WHERE account_type = 'asset' AND subtype IN ('bank','cash','accounts_receivable','inventory','other_current_asset')),0) ca,
    coalesce(sum(ending_balance) FILTER (WHERE account_type IN ('asset','contra_asset')),0) ta,
    coalesce(sum(ending_balance) FILTER (WHERE subtype = 'accounts_payable'),0) ap,
    coalesce(sum(ending_balance) FILTER (WHERE account_type = 'liability' AND subtype IN ('accounts_payable','credit_card','line_of_credit','other_current_liability')),0) cl,
    coalesce(sum(ending_balance) FILTER (WHERE account_type = 'liability'),0) tl
    INTO r FROM acct__account_amounts(p_tenant_id, p_from, p_to, p_entity_id);
  SELECT coalesce(sum(ending_balance),0) INTO v_cash_start FROM acct__account_amounts(p_tenant_id, p_from - 1, p_from - 1, p_entity_id) WHERE subtype IN ('bank','cash');
  v_months := greatest((p_to - p_from + 1) / 30.4375, 0.0001);
  RETURN jsonb_build_object(
    'revenue', r.revenue, 'cogs', r.cogs, 'gross_profit', r.revenue - r.cogs, 'operating_expenses', r.opex,
    'operating_income', r.revenue - r.cogs - r.opex, 'other_income', r.other_income, 'other_expense', r.other_expense,
    'net_income', r.revenue + r.other_income - r.cogs - r.opex - r.other_expense,
    'cash', r.cash, 'cash_start', v_cash_start, 'accounts_receivable', r.ar, 'inventory', r.inventory, 'current_assets', r.ca,
    'total_assets', r.ta, 'accounts_payable', r.ap, 'current_liabilities', r.cl, 'total_liabilities', r.tl, 'equity', r.ta - r.tl,
    'days', p_to - p_from + 1, 'months', round(v_months, 4),
    'monthly_burn', round(greatest(v_cash_start - r.cash, 0) / v_months, 2));
END $$;

-- @seq 97
CREATE FUNCTION public.acct__ledger_sums(p_tenant uuid, p_entity uuid, p_from date, p_to date, p_exclude_closing boolean) RETURNS TABLE(account_id uuid, dr numeric, cr numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT l.account_id, sum(l.debit), sum(l.credit)
    FROM acct_journal_lines l
    JOIN acct_journal_entries e ON e.id = l.journal_entry_id
   WHERE e.tenant_id = p_tenant
     AND e.status IN ('posted','reversed')
     AND (p_entity IS NULL OR e.entity_id = p_entity)
     AND (p_from IS NULL OR e.posting_date >= p_from)
     AND (p_to IS NULL OR e.posting_date <= p_to)
     AND (NOT p_exclude_closing OR NOT coalesce(e.is_closing, false))
   GROUP BY l.account_id;
$$;

-- @seq 98
CREATE FUNCTION public.acct__legacy_customer(p_tenant uuid, p_legacy text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT c.id FROM crm_customers c
   WHERE p_legacy IS NOT NULL AND c.tenant_id = p_tenant
     AND (c.id::text = p_legacy OR c.source_customer_id::text = p_legacy OR c.external_customer_number = p_legacy
          OR lower(c.email) = (SELECT lower(lc.email) FROM customers lc WHERE lc.id = p_legacy))
   ORDER BY (c.id::text = p_legacy) DESC LIMIT 1;
$$;

-- @seq 99
CREATE FUNCTION public.acct__legacy_id(p_tenant uuid, p_table text, p_legacy text) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT new_id FROM acct_legacy_map WHERE tenant_id = p_tenant AND legacy_table = p_table AND legacy_id = p_legacy;
$$;

-- @seq 100
CREATE FUNCTION public.acct__legacy_numeric(p text) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN nullif(regexp_replace(coalesce(p,''), '[^0-9.\-]', '', 'g'), '') IS NULL THEN 0
              ELSE regexp_replace(p, '[^0-9.\-]', '', 'g')::numeric END;
$$;

-- @seq 101
CREATE FUNCTION public.acct__legacy_vendor(p_tenant uuid, p_entity uuid, p_legacy text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_id uuid; l customers%ROWTYPE;
BEGIN
  IF p_legacy IS NULL THEN RETURN NULL; END IF;
  v_id := coalesce(acct__legacy_id(p_tenant, 'vendors', p_legacy), acct__legacy_id(p_tenant, 'customers', p_legacy),
                   (SELECT id FROM acct_vendors WHERE tenant_id = p_tenant AND (id::text = p_legacy OR external_vendor_id = p_legacy) LIMIT 1));
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;
  SELECT * INTO l FROM customers c WHERE c.id = p_legacy;
  IF l.id IS NULL THEN RETURN NULL; END IF;
  SELECT v.id INTO v_id FROM acct_vendors v WHERE v.tenant_id = p_tenant
     AND (v.external_vendor_id = l.id OR (l.email IS NOT NULL AND lower(v.email) = lower(l.email))) LIMIT 1;
  IF v_id IS NULL THEN
    INSERT INTO acct_vendors(tenant_id, entity_id, external_vendor_id, legal_name, display_name, first_name, last_name, email, phone, is_active, metadata)
    VALUES (p_tenant, p_entity, l.id, coalesce(nullif(concat_ws(' ', l."firstName", l."lastName"),''), l.email, 'Vendor ' || l.id),
            coalesce(nullif(concat_ws(' ', l."firstName", l."lastName"),''), l.email, 'Vendor ' || l.id), l."firstName", l."lastName", l.email, l.phone, true,
            jsonb_strip_nulls(jsonb_build_object('legacy_table','customers','address', nullif(concat_ws(', ', l.address, l."addressLine2", l.city, l.state, l."postalCode"),''))))
    RETURNING id INTO v_id;
  END IF;
  INSERT INTO acct_legacy_map VALUES (p_tenant, 'customers', l.id, 'acct_vendors', v_id, 'legacy customer row used as a vendor on bills')
  ON CONFLICT DO NOTHING;
  RETURN v_id;
END $$;

-- @seq 102
CREATE FUNCTION public.acct__ofx_tag(p_block text, p_tag text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  -- works for SGML OFX 1.x (no closing tags) and XML OFX 2.x
  SELECT nullif(btrim(substring(p_block FROM '(?i)<' || p_tag || '>([^<\r\n]*)')), '')
$$;

-- @seq 107
CREATE FUNCTION public.acct__order_for_books(p_order_id uuid) RETURNS public.erp_orders
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE; v_tax numeric;
BEGIN
  SELECT * INTO o FROM erp_orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF coalesce((to_jsonb(o)->>'is_marketplace_facilitated')::boolean, false) AND coalesce(o.tax_total,0) <> 0 THEN
    v_tax := o.tax_total;
    o.total := coalesce(o.total,0) - v_tax;
    o.tax_total := 0;
    o.amount_paid := least(coalesce(o.amount_paid,0), o.total);
    o.amount_refunded := least(coalesce(o.amount_refunded,0), o.total);
    o.metadata := coalesce(o.metadata,'{}'::jsonb) || jsonb_build_object('marketplace_tax_excluded', v_tax);
  END IF;
  RETURN o;
END $$;

-- @seq 108
CREATE FUNCTION public.acct__order_for_charge(p_tenant_id uuid, p_object jsonb) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT o.id FROM erp_orders o
   WHERE o.tenant_id = p_tenant_id AND (
         o.id::text = p_object#>>'{metadata,order_id}' OR o.id::text = p_object#>>'{metadata,erp_order_id}'
      OR o.source_order_id IN (p_object#>>'{metadata,order_id}', p_object->>'payment_intent', p_object->>'id')
      OR o.source_order_id IN (SELECT co.id FROM commerce_orders co WHERE co.tenant_id = p_tenant_id
                                 AND co.stripe_payment_intent_id IN (p_object->>'payment_intent', p_object->>'id')))
   LIMIT 1;
$$;

-- @seq 109
CREATE FUNCTION public.acct__order_is_fulfilled(p_status text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT lower(coalesce(p_status,'')) IN ('shipped','delivered','completed','closed','returned','fulfilled','picked_up');
$$;

-- @seq 110
CREATE FUNCTION public.acct__order_money_in(p_order_id uuid, p_amount numeric, p_fee numeric, p_debit_account uuid, p_date date, p_processor text, p_ref text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p acct_order_postings%ROWTYPE; o erp_orders%ROWTYPE; v_to_ar numeric; v_to_dep numeric; v_lines jsonb; v_je uuid; v_open numeric;
BEGIN
  SELECT * INTO p FROM acct_order_postings WHERE order_id = p_order_id FOR UPDATE;
  SELECT * INTO o FROM acct__order_for_books(p_order_id) x WHERE x.id IS NOT NULL;
  -- open A/R on this order = recognized sale - money already applied to it
  v_open := CASE WHEN p.sale_journal_id IS NOT NULL AND NOT p.sale_reversed
                 THEN greatest(p.sale_amount - (p.payments_posted - p.deposits_held) + p.refunds_posted * 0, 0) ELSE 0 END;
  v_to_ar := least(p_amount, v_open);
  v_to_dep := p_amount - v_to_ar;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', p_debit_account, 'debit', p_amount - p_fee, 'description', 'Order ' || o.order_number || ' payment'));
  IF p_fee <> 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'processor_fees'), 'debit', p_fee, 'description', 'Processing fee');
  END IF;
  IF v_to_ar > 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'accounts_receivable'), 'credit', v_to_ar,
                                             'customer_id', p.party, 'description', 'Order ' || o.order_number);
  END IF;
  IF v_to_dep > 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'customer_deposits'), 'credit', v_to_dep,
                                             'customer_id', p.party, 'description', 'Order ' || o.order_number || ' paid before fulfillment');
  END IF;
  v_je := acct_post_entry(p.tenant_id, p.entity_id, p_date, v_lines, 'customer_receipt', o.id::text, o.order_number, 'Order payment ' || o.order_number,
                          'orderpay:' || o.id || ':' || coalesce(p_ref, (p.payments_posted + p_amount)::text), NULL, NULL, upper(coalesce(nullif(o.currency,''),'USD')),
                          false, false, 'erp_orders', o.id);
  INSERT INTO acct_order_payments(tenant_id, order_id, kind, amount, fee, processor, processor_ref, journal_entry_id)
  VALUES (p.tenant_id, o.id, 'payment', p_amount, p_fee, p_processor, p_ref, v_je);
  UPDATE acct_order_postings SET payments_posted = payments_posted + p_amount, deposits_held = deposits_held + v_to_dep, updated_at = now()
   WHERE order_id = o.id;
  RETURN v_je;
END $$;

-- @seq 111
CREATE FUNCTION public.acct__order_money_out(p_order_id uuid, p_amount numeric, p_credit_account uuid, p_date date, p_processor text, p_ref text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p acct_order_postings%ROWTYPE; o erp_orders%ROWTYPE; v_lines jsonb; v_je uuid; v_tax numeric := 0; v_from_dep numeric; v_rest numeric; v_ratio numeric;
BEGIN
  SELECT * INTO p FROM acct_order_postings WHERE order_id = p_order_id FOR UPDATE;
  SELECT * INTO o FROM acct__order_for_books(p_order_id) x WHERE x.id IS NOT NULL;
  v_from_dep := least(p_amount, p.deposits_held);
  v_rest := p_amount - v_from_dep;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', p_credit_account, 'credit', p_amount, 'description', 'Order ' || o.order_number || ' refund'));
  IF v_from_dep > 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'customer_deposits'), 'debit', v_from_dep,
                                             'customer_id', p.party, 'description', 'Refund of order deposit');
  END IF;
  IF v_rest > 0 THEN
    IF p.sale_journal_id IS NOT NULL AND NOT p.sale_reversed AND p.sale_amount > 0 THEN
      v_tax := round(v_rest * p.sale_tax / p.sale_amount, 2);
      v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'sales_returns'), 'debit', v_rest - v_tax,
                                               'customer_id', p.party, 'description', 'Order ' || o.order_number || ' refund');
      IF v_tax <> 0 THEN
        v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'sales_tax_payable'), 'debit', v_tax,
                                                 'customer_id', p.party, 'description', 'Sales tax refunded');
      END IF;
    ELSE   -- refund of an unpaid/unrecognized balance: comes back out of A/R credit
      v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'accounts_receivable'), 'debit', v_rest,
                                               'customer_id', p.party, 'description', 'Order ' || o.order_number || ' refund');
    END IF;
  END IF;
  v_je := acct_post_entry(p.tenant_id, p.entity_id, p_date, v_lines, 'credit_memo', o.id::text, o.order_number, 'Order refund ' || o.order_number,
                          'orderrefund:' || o.id || ':' || coalesce(p_ref, (p.refunds_posted + p_amount)::text), NULL, NULL, upper(coalesce(nullif(o.currency,''),'USD')),
                          false, false, 'erp_orders', o.id);
  -- tax detail: mirror the sale's jurisdictions in proportion
  IF v_tax <> 0 THEN
    v_ratio := v_tax / nullif(p.sale_tax, 0);
    INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
                                      rule_id, tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason, journal_entry_id)
    SELECT tenant_id, entity_id, p_date, direction, source_doc_type, source_doc_id, 'refund', jurisdiction_id, tax_code_id, rule_id, tax_category,
           -round(gross_amount * v_ratio, 2), -round(taxable_amount * v_ratio, 2), -round(exempt_amount * v_ratio, 2), rate, -round(tax_amount * v_ratio, 2),
           'Order refund', v_je
      FROM acct_tax_transactions WHERE source_doc_type = 'erp_orders' AND source_doc_id = o.id AND journal_entry_id = p.sale_journal_id;
    -- rounding: make the refund rows sum exactly to v_tax
    UPDATE acct_tax_transactions SET tax_amount = tax_amount - ((SELECT sum(tax_amount) FROM acct_tax_transactions WHERE journal_entry_id = v_je) + v_tax)
     WHERE id = (SELECT id FROM acct_tax_transactions WHERE journal_entry_id = v_je ORDER BY abs(tax_amount) DESC LIMIT 1);
  END IF;
  INSERT INTO acct_order_payments(tenant_id, order_id, kind, amount, processor, processor_ref, journal_entry_id)
  VALUES (p.tenant_id, o.id, 'refund', p_amount, p_processor, p_ref, v_je);
  UPDATE acct_order_postings SET refunds_posted = refunds_posted + p_amount, deposits_held = deposits_held - v_from_dep, updated_at = now()
   WHERE order_id = o.id;
  RETURN v_je;
END $$;

-- @seq 112
CREATE FUNCTION public.acct__order_payment_mode(p_tenant_id uuid, p_entity_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE s.order_payment_source WHEN 'auto' THEN
              CASE WHEN (SELECT stripe_connect_account_id FROM tenants WHERE id = p_tenant_id) IS NOT NULL THEN 'processor' ELSE 'order' END
         ELSE s.order_payment_source END
    FROM acct__settings(p_tenant_id, p_entity_id) s;
$$;

-- @seq 113
CREATE FUNCTION public.acct__order_processor_payment(p_order_id uuid, p_amount numeric, p_fee numeric, p_charge text, p_date date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE; v_entity uuid; v_je uuid;
BEGIN
  SELECT * INTO o FROM acct__order_for_books(p_order_id) x WHERE x.id IS NOT NULL;
  v_entity := acct_default_entity(o.tenant_id);
  SELECT journal_entry_id INTO v_je FROM acct_order_payments WHERE tenant_id = o.tenant_id AND processor = 'stripe' AND processor_ref = p_charge AND kind = 'payment';
  IF v_je IS NOT NULL THEN RETURN v_je; END IF;
  INSERT INTO acct_order_postings(order_id, tenant_id, entity_id, party)
  VALUES (o.id, o.tenant_id, v_entity, coalesce(o.crm_customer_id::text, 'order:' || o.id)) ON CONFLICT (order_id) DO NOTHING;
  v_je := acct__order_money_in(o.id, p_amount, p_fee, acct_bank_gl(acct_system_register(o.tenant_id, v_entity, 'stripe')), p_date, 'stripe', p_charge);
  PERFORM acct__sync_erp_order(o.id);   -- may now recognize (revenue point = paid)
  RETURN v_je;
END $$;

-- @seq 114
CREATE FUNCTION public.acct__order_processor_refund(p_order_id uuid, p_amount numeric, p_refund_id text, p_date date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE; v_je uuid;
BEGIN
  SELECT * INTO o FROM acct__order_for_books(p_order_id) x WHERE x.id IS NOT NULL;
  SELECT journal_entry_id INTO v_je FROM acct_order_payments WHERE tenant_id = o.tenant_id AND processor = 'stripe' AND processor_ref = p_refund_id AND kind = 'refund';
  IF v_je IS NOT NULL THEN RETURN v_je; END IF;
  RETURN acct__order_money_out(o.id, p_amount, acct_bank_gl(acct_system_register(o.tenant_id, acct_default_entity(o.tenant_id), 'stripe')), p_date, 'stripe', p_refund_id);
END $$;

-- @seq 115
CREATE FUNCTION public.acct__order_recognize(p_order_id uuid, p_date date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p acct_order_postings%ROWTYPE; o erp_orders%ROWTYPE; s acct_settings%ROWTYPE; v_lines jsonb := '[]'::jsonb; v_je uuid;
        v_gross numeric; v_rev numeric; v_alloc numeric := 0; v_n int; v_i int := 0; l record; v_amt numeric; v_diff numeric;
        v_jur uuid; v_payload jsonb := '[]'::jsonb; v_calc numeric; c record; v_written numeric := 0; v_k int := 0; v_cnt int;
        v_apply numeric; v_cur text; r record; it acct_items%ROWTYPE; v_cogs jsonb := '[]'::jsonb; v_moves uuid[] := '{}'; v_ar uuid;
BEGIN
  SELECT * INTO p FROM acct_order_postings WHERE order_id = p_order_id FOR UPDATE;
  SELECT * INTO o FROM acct__order_for_books(p_order_id) x WHERE x.id IS NOT NULL;
  s := acct__settings(p.tenant_id, p.entity_id);
  v_cur := upper(coalesce(nullif(o.currency,''),'USD'));
  v_ar := acct_role_account(p.tenant_id, p.entity_id, 'accounts_receivable');
  v_rev := coalesce(o.subtotal, 0);
  -- order lines mapped to items: erp_order_lines.sku_id (a product_variants id) -> acct_items.product_variant_id,
  -- or through erp_product_skus (variant_id or id) -> acct_items.sku_id
  CREATE TEMP TABLE IF NOT EXISTS _ord_lines(line_id uuid, item_id uuid, qty numeric, gross numeric, income uuid, tax_category text, descr text) ON COMMIT DROP;
  DELETE FROM _ord_lines;
  INSERT INTO _ord_lines
  SELECT ol.id, i.id, ol.quantity, coalesce(ol.quantity,0) * coalesce(ol.unit_price,0),
         coalesce(i.income_account_id, acct_role_account(p.tenant_id, p.entity_id, 'default_income')), i.tax_category, coalesce(ol.description, i.name)
    FROM erp_order_lines ol
    LEFT JOIN LATERAL (SELECT ai.* FROM acct_items ai
                        WHERE ai.tenant_id = p.tenant_id AND ol.sku_id IS NOT NULL
                          AND (ai.product_variant_id = ol.sku_id
                               OR EXISTS (SELECT 1 FROM erp_product_skus ps WHERE ps.id = ai.sku_id AND (ps.variant_id = ol.sku_id OR ps.id = ol.sku_id)))
                        ORDER BY (ai.product_variant_id = ol.sku_id) DESC NULLS LAST LIMIT 1) i ON true
   WHERE ol.order_id = o.id AND coalesce(ol.status,'') NOT IN ('cancelled','canceled');
  SELECT coalesce(sum(gross),0), count(*) INTO v_gross, v_n FROM _ord_lines;
  IF v_gross > 0 AND v_rev > 0 THEN
    FOR l IN SELECT * FROM _ord_lines ORDER BY gross, line_id LOOP
      v_i := v_i + 1;
      v_amt := CASE WHEN v_i = v_n THEN v_rev - v_alloc ELSE round(v_rev * l.gross / v_gross, 2) END;
      v_alloc := v_alloc + v_amt;
      v_lines := v_lines || jsonb_build_object('account_id', l.income, 'credit', v_amt, 'item_id', l.item_id, 'customer_id', p.party, 'description', l.descr);
      v_payload := v_payload || jsonb_build_object('line_ref', l.line_id, 'amount', v_amt, 'tax_category', l.tax_category);
    END LOOP;
  ELSIF v_rev <> 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'default_income'), 'credit', v_rev,
                                             'customer_id', p.party, 'description', 'Order ' || o.order_number);
    v_payload := jsonb_build_array(jsonb_build_object('line_ref', 'order', 'amount', v_rev));
  END IF;
  IF coalesce(o.discount_total,0) <> 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'discounts_given'), 'debit', o.discount_total,
                                             'customer_id', p.party, 'description', 'Order discount');
  END IF;
  IF coalesce(o.shipping_total,0) <> 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'shipping_income'), 'credit', o.shipping_total,
                                             'customer_id', p.party, 'description', 'Order shipping');
  END IF;
  IF coalesce(o.tax_total,0) <> 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'sales_tax_payable'), 'credit', o.tax_total,
                                             'customer_id', p.party, 'description', 'Order sales tax');
  END IF;
  v_diff := coalesce(o.total,0) - (v_rev - coalesce(o.discount_total,0) + coalesce(o.shipping_total,0) + coalesce(o.tax_total,0));
  IF abs(v_diff) > 1 THEN
    RAISE EXCEPTION 'Order % does not add up: total % vs subtotal - discount + shipping + tax (difference %)', o.order_number, o.total, v_diff; END IF;
  IF v_diff <> 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'rounding'), 'credit', greatest(v_diff,0),
                                             'debit', greatest(-v_diff,0), 'description', 'Order rounding');
  END IF;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', v_ar, 'debit', coalesce(o.total,0), 'customer_id', p.party,
                                                  'description', 'Order ' || o.order_number)) || v_lines;
  -- money received before recognition sits in Customer Deposits; apply it now
  v_apply := least(p.deposits_held, coalesce(o.total,0));
  IF v_apply > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object('account_id', acct_role_account(p.tenant_id, p.entity_id, 'customer_deposits'), 'debit', v_apply, 'customer_id', p.party, 'description', 'Apply order deposit'),
      jsonb_build_object('account_id', v_ar, 'credit', v_apply, 'customer_id', p.party, 'description', 'Apply order deposit'));
  END IF;
  v_je := acct_post_entry(p.tenant_id, p.entity_id, p_date, v_lines, 'invoice', o.id::text, o.order_number, 'Shop order ' || o.order_number,
                          'ordersale:' || o.id, NULL, NULL, v_cur, false, false, 'erp_orders', o.id);

  -- sales tax detail: charged tax spread over the jurisdiction chain the engine would use
  v_jur := coalesce(nullif(o.metadata->>'tax_jurisdiction_id','')::uuid, s.default_tax_jurisdiction_id);
  IF coalesce(o.tax_total,0) <> 0 AND v_jur IS NOT NULL THEN
    CREATE TEMP TABLE IF NOT EXISTS _ord_tax ON COMMIT DROP AS SELECT * FROM acct_calculate_tax(p.tenant_id, p.entity_id, p_date, v_jur, NULL, '[]'::jsonb, 'sale') LIMIT 0;
    DELETE FROM _ord_tax;
    INSERT INTO _ord_tax SELECT * FROM acct_calculate_tax(p.tenant_id, p.entity_id, p_date, v_jur, o.crm_customer_id, v_payload, 'sale');
    SELECT coalesce(sum(tax_amount),0), count(*) FILTER (WHERE tax_amount <> 0) INTO v_calc, v_cnt FROM _ord_tax;
    IF v_calc = 0 THEN
      INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id,
                                        tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason, journal_entry_id)
      VALUES (p.tenant_id, p.entity_id, p_date, 'sale', 'erp_orders', o.id, 'order', v_jur, NULL, v_rev - coalesce(o.discount_total,0),
              v_rev - coalesce(o.discount_total,0), 0, round(o.tax_total / nullif(v_rev - coalesce(o.discount_total,0),0), 6), o.tax_total,
              'Charged by storefront (engine computed no tax - review taxability)', v_je);
    ELSE
      FOR c IN SELECT * FROM _ord_tax WHERE tax_amount <> 0 ORDER BY tax_amount LOOP
        v_k := v_k + 1;
        v_amt := CASE WHEN v_k = v_cnt THEN o.tax_total - v_written ELSE round(c.tax_amount * o.tax_total / v_calc, 2) END;
        v_written := v_written + v_amt;
        INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
                                          rule_id, tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason, journal_entry_id)
        VALUES (p.tenant_id, p.entity_id, p_date, 'sale', 'erp_orders', o.id, c.line_ref, c.jurisdiction_id, c.tax_code_id, c.rule_id, c.tax_category,
                c.gross_amount, c.taxable_amount, c.exempt_amount, c.rate, v_amt,
                CASE WHEN v_calc <> o.tax_total THEN 'Charged ' || o.tax_total || ' vs engine ' || v_calc ELSE c.reason END, v_je);
      END LOOP;
    END IF;
  END IF;

  -- COGS for stocked items
  FOR l IN SELECT * FROM _ord_lines WHERE item_id IS NOT NULL AND coalesce(qty,0) > 0 LOOP
    FOR c IN SELECT * FROM acct__inv_components(l.item_id, l.qty) LOOP
      SELECT * INTO it FROM acct_items WHERE id = c.item_id;
      SELECT * INTO r FROM acct__inv_issue(p.tenant_id, p.entity_id, c.item_id, c.quantity, p_date, 'sale', 'erp_orders', o.id, l.line_id, o.order_number, NULL);
      v_moves := v_moves || r.move_id;
      v_cogs := v_cogs || jsonb_build_array(
        jsonb_build_object('account_id', it.cogs_account_id, 'debit', r.cost, 'item_id', it.id, 'description', 'COGS ' || it.name, 'customer_id', p.party),
        jsonb_build_object('account_id', it.inventory_asset_account_id, 'credit', r.cost, 'item_id', it.id, 'description', 'COGS ' || it.name));
    END LOOP;
  END LOOP;
  IF cardinality(v_moves) > 0 THEN
    PERFORM acct__inv_post_je(p.tenant_id, p.entity_id, p_date, v_cogs, o.order_number, 'Cost of goods sold, order ' || o.order_number,
                              'cogs:order:' || o.id, 'erp_orders', o.id, v_moves);
  END IF;

  UPDATE acct_order_postings SET sale_journal_id = v_je, sale_amount = coalesce(o.total,0), sale_tax = coalesce(o.tax_total,0),
         deposits_held = deposits_held - v_apply, updated_at = now() WHERE order_id = o.id;
  RETURN v_je;
END $$;

-- @seq 116
CREATE FUNCTION public.acct__order_register(p_tenant_id uuid, p_entity_id uuid, p_channel text) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(
    (SELECT c.clearing_register_id FROM acct_channel_accounts c
      WHERE c.tenant_id = p_tenant_id AND c.entity_id = p_entity_id AND c.channel = lower(p_channel) AND c.is_active),
    acct_system_register(p_tenant_id, p_entity_id, 'undeposited_funds'));
$$;

-- @seq 117
CREATE FUNCTION public.acct__parse_amount(p text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE s text := btrim(coalesce(p,'')); neg boolean := false;
BEGIN
  IF s = '' THEN RETURN NULL; END IF;
  IF s ~ '^\(.*\)$' THEN neg := true; s := substr(s, 2, length(s) - 2); END IF;
  IF upper(s) ~ '\s*(CR)$' THEN s := regexp_replace(s, '\s*[Cc][Rr]$', ''); END IF;
  IF upper(s) ~ '\s*(DR)$' THEN neg := NOT neg; s := regexp_replace(s, '\s*[Dd][Rr]$', ''); END IF;
  IF s ~ '-$' THEN neg := NOT neg; s := left(s, length(s) - 1); END IF;
  s := regexp_replace(s, '[$,\s]', '', 'g');
  IF s ~ '^-' THEN neg := NOT neg; s := substr(s, 2); END IF;
  IF s ~ '^\+' THEN s := substr(s, 2); END IF;
  IF s !~ '^\d*\.?\d+$' THEN RAISE EXCEPTION 'Not an amount: %', p; END IF;
  RETURN CASE WHEN neg THEN -s::numeric ELSE s::numeric END;
END $_$;

-- @seq 118
CREATE FUNCTION public.acct__parse_date(p text, p_fmt text DEFAULT NULL::text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE s text := btrim(coalesce(p,''));
BEGIN
  IF s = '' THEN RETURN NULL; END IF;
  IF p_fmt IS NOT NULL THEN RETURN to_date(s, p_fmt); END IF;
  IF s ~ '^\d{4}-\d{1,2}-\d{1,2}' THEN RETURN to_date(left(s, 10), 'YYYY-MM-DD'); END IF;
  IF s ~ '^\d{8}' THEN RETURN to_date(left(s, 8), 'YYYYMMDD'); END IF;
  IF s ~ '^\d{1,2}/\d{1,2}/\d{4}' THEN RETURN to_date(split_part(s,' ',1), 'MM/DD/YYYY'); END IF;   -- US banks
  IF s ~ '^\d{1,2}/\d{1,2}/\d{2}$' THEN RETURN to_date(s, 'MM/DD/YY'); END IF;
  IF s ~ '^\d{1,2}-\d{1,2}-\d{4}$' THEN RETURN to_date(s, 'MM-DD-YYYY'); END IF;
  RAISE EXCEPTION 'Unrecognized date: % (pass date_format in the mapping)', p;
END $_$;

-- @seq 120
CREATE FUNCTION public.acct__pnl_section(a public.acct_chart_of_accounts) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE
    WHEN a.account_type = 'revenue' AND a.subtype = 'other_income'  THEN 'Other Income'
    WHEN a.account_type = 'revenue'                                 THEN 'Income'
    WHEN a.account_type = 'expense' AND a.subtype = 'cogs'          THEN 'Cost of Goods Sold'
    WHEN a.account_type = 'expense' AND a.subtype = 'other_expense' THEN 'Other Expenses'
    WHEN a.account_type = 'expense'                                 THEN 'Expenses'
  END;
$$;

-- @seq 121
CREATE FUNCTION public.acct__prior_window(p_from date, p_to date, OUT prior_from date, OUT prior_to date) RETURNS record
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE n int;
BEGIN
  IF p_from = date_trunc('month', p_from)::date AND p_to = (date_trunc('month', p_to) + interval '1 month - 1 day')::date THEN
    n := (extract(year FROM p_to) * 12 + extract(month FROM p_to) - extract(year FROM p_from) * 12 - extract(month FROM p_from))::int + 1;
    prior_from := (p_from - make_interval(months => n))::date;
    prior_to := p_from - 1;
  ELSE
    prior_to := p_from - 1;
    prior_from := prior_to - (p_to - p_from);
  END IF;
END $$;

-- @seq 122
CREATE FUNCTION public.acct__purchase_line_posted(p_tenant_id uuid, p_entity_id uuid, p_doc_type text, p_doc_id uuid, p_line_id uuid, p_date date, p_ref text, p_item_id uuid, p_account_id uuid, p_qty numeric, p_amount numeric, p_description text, p_vendor_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE it acct_items%ROWTYPE; a acct_chart_of_accounts%ROWTYPE; s acct_settings%ROWTYPE;
BEGIN
  IF p_item_id IS NOT NULL THEN
    SELECT * INTO it FROM acct_items WHERE id = p_item_id;
    IF it.item_type = 'inventory' AND p_account_id = it.inventory_asset_account_id AND coalesce(p_qty,0) > 0 AND p_amount >= 0 THEN
      PERFORM acct__inv_receive(p_tenant_id, p_entity_id, p_item_id, p_qty, p_amount, p_date, 'receipt', p_doc_type, p_doc_id, p_line_id, p_ref, p_vendor_name);
      RETURN;
    END IF;
  END IF;
  -- fixed asset capture: lines coded to a fixed-asset account at or over the capitalization threshold become draft assets
  SELECT * INTO a FROM acct_chart_of_accounts WHERE id = p_account_id;
  s := acct__settings(p_tenant_id, p_entity_id);
  IF a.subtype = 'fixed_asset' AND p_amount >= s.capitalization_threshold THEN
    INSERT INTO acct_fixed_assets(tenant_id, entity_id, asset_number, name, description, acquisition_date, original_cost, residual_value,
                                  accumulated_depreciation, status, source_doc_type, source_doc_id, source_line_id, cost_account_id)
    VALUES (p_tenant_id, p_entity_id, acct_next_number(p_tenant_id, p_entity_id, 'fixed_asset', 'FA-'),
            coalesce(nullif(p_description,''), a.name), 'From ' || p_ref || coalesce(' / ' || p_vendor_name, ''), p_date, p_amount, 0, 0,
            'draft', p_doc_type, p_doc_id, p_line_id, p_account_id)
    ON CONFLICT (source_doc_type, source_line_id) WHERE source_line_id IS NOT NULL DO NOTHING;
  END IF;
END $$;

-- @seq 123
CREATE FUNCTION public.acct__role(p_tenant_id uuid, p_entity_id uuid, p_role text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid;
BEGIN
  v := acct_role_account(p_tenant_id, p_entity_id, p_role, false);
  IF v IS NULL THEN
    PERFORM acct__ensure_operating_accounts(p_tenant_id, p_entity_id);
    v := acct_role_account(p_tenant_id, p_entity_id, p_role, true);
  END IF;
  RETURN v;
END $$;

-- @seq 124
CREATE FUNCTION public.acct__seed_kpis(p_tenant_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  INSERT INTO acct_kpi_definitions(tenant_id, code, name, formula, unit, description, sort_order) VALUES
   (p_tenant_id,'gross_margin','Gross margin','gross_profit / revenue * 100','percent','Share of sales left after cost of goods sold',10),
   (p_tenant_id,'net_margin','Net margin','net_income / revenue * 100','percent','Share of sales kept as profit',20),
   (p_tenant_id,'operating_margin','Operating margin','operating_income / revenue * 100','percent',NULL,25),
   (p_tenant_id,'current_ratio','Current ratio','current_assets / current_liabilities','ratio','Short-term assets per dollar of short-term debt',30),
   (p_tenant_id,'quick_ratio','Quick ratio','(cash + accounts_receivable) / current_liabilities','ratio','Current ratio without inventory',40),
   (p_tenant_id,'dso','Days sales outstanding','accounts_receivable / revenue * days','days','Average days to collect from customers',50),
   (p_tenant_id,'dpo','Days payable outstanding','accounts_payable / cogs * days','days','Average days to pay suppliers (on COGS)',60),
   (p_tenant_id,'inventory_turnover','Inventory turnover (period)','cogs / inventory','ratio','Times inventory sold through in the period, on ending inventory',70),
   (p_tenant_id,'days_inventory','Days of inventory on hand','inventory / cogs * days','days',NULL,80),
   (p_tenant_id,'runway_months','Cash runway','cash / monthly_burn','months','Months of cash at the period''s burn rate; empty when cash grew',90),
   (p_tenant_id,'debt_to_equity','Debt to equity','total_liabilities / equity','ratio',NULL,100)
  ON CONFLICT (tenant_id, code) DO NOTHING;
$$;

-- @seq 126
CREATE FUNCTION public.acct__settings(p_tenant_id uuid, p_entity_id uuid) RETURNS public.acct_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s acct_settings%ROWTYPE;
BEGIN
  INSERT INTO acct_settings(tenant_id, entity_id) VALUES (p_tenant_id, p_entity_id) ON CONFLICT DO NOTHING;
  SELECT * INTO s FROM acct_settings WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id;
  RETURN s;
END $$;

-- @seq 127
CREATE FUNCTION public.acct__sync_erp_order(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o erp_orders%ROWTYPE; v_entity uuid; p acct_order_postings%ROWTYPE; s acct_settings%ROWTYPE; v_mode text; v_st text;
        v_date date; v_reg uuid; v_delta numeric; v_done jsonb := '[]'::jsonb; v_recognize boolean;
BEGIN
  SELECT * INTO o FROM acct__order_for_books(p_order_id) x WHERE x.id IS NOT NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('status','missing'); END IF;
  v_entity := acct_default_entity(o.tenant_id);
  IF v_entity IS NULL THEN RETURN jsonb_build_object('status','no_books'); END IF;
  -- legacy-migrated orders are already in the books
  IF EXISTS (SELECT 1 FROM acct_legacy_map WHERE tenant_id = o.tenant_id AND legacy_table = 'erp_orders' AND legacy_id = o.id::text) THEN
    RETURN jsonb_build_object('status','migrated_legacy'); END IF;
  INSERT INTO acct_order_postings(order_id, tenant_id, entity_id, party)
  VALUES (o.id, o.tenant_id, v_entity, coalesce(o.crm_customer_id::text, 'order:' || o.id)) ON CONFLICT (order_id) DO NOTHING;
  SELECT * INTO p FROM acct_order_postings WHERE order_id = o.id FOR UPDATE;
  s := acct__settings(o.tenant_id, v_entity);
  v_mode := acct__order_payment_mode(o.tenant_id, v_entity);
  v_st := lower(coalesce(o.status,''));
  v_date := coalesce(o.order_date::date, o.created_at::date);
  IF v_st NOT IN ('draft','quote','pending_payment') THEN v_date := greatest(v_date, least(current_date, coalesce(o.updated_at::date, current_date))); END IF;
  v_reg := acct__order_register(o.tenant_id, v_entity, to_jsonb(o)->>'sales_channel');

  -- 1. payments recorded on the order itself (cash at pickup, manual, or no processor feed)
  IF v_mode = 'order' THEN
    v_delta := coalesce(o.amount_paid,0) - p.payments_posted;
    IF v_delta > 0 THEN
      PERFORM acct__order_money_in(o.id, v_delta, 0, acct_bank_gl(v_reg), v_date, 'order', NULL);
      v_done := v_done || '"payment"';
    END IF;
  END IF;
  SELECT * INTO p FROM acct_order_postings WHERE order_id = o.id;

  -- 2. revenue
  v_recognize := v_st NOT IN ('cancelled','canceled','void','draft','quote','pending_payment','failed','abandoned')
                 AND (acct__order_is_fulfilled(v_st) OR (s.order_revenue_point = 'paid' AND p.payments_posted > 0));
  IF v_recognize AND p.sale_journal_id IS NULL AND coalesce(o.total,0) > 0 THEN
    PERFORM acct__order_recognize(o.id, v_date);
    v_done := v_done || '"sale"';
  END IF;
  SELECT * INTO p FROM acct_order_postings WHERE order_id = o.id;

  -- 3. refunds recorded on the order
  IF v_mode = 'order' THEN
    v_delta := coalesce(o.amount_refunded,0) - p.refunds_posted;
    IF v_delta > 0 THEN
      PERFORM acct__order_money_out(o.id, v_delta, acct_bank_gl(v_reg), v_date, 'order', NULL);
      v_done := v_done || '"refund"';
    END IF;
  END IF;
  SELECT * INTO p FROM acct_order_postings WHERE order_id = o.id;

  -- 4. cancelled after the sale was booked: reverse revenue and put stock back
  IF v_st IN ('cancelled','canceled','void') AND p.sale_journal_id IS NOT NULL AND NOT p.sale_reversed THEN
    PERFORM acct_reverse_journal(p.sale_journal_id, v_date, 'Order ' || o.order_number || ' cancelled');
    INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
                                      rule_id, tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason, journal_entry_id)
    SELECT tenant_id, entity_id, v_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id, rule_id, tax_category,
           -gross_amount, -taxable_amount, -exempt_amount, rate, -tax_amount, 'Order cancelled',
           (SELECT reversed_by_id FROM acct_journal_entries WHERE id = p.sale_journal_id)
      FROM acct_tax_transactions WHERE source_doc_type = 'erp_orders' AND source_doc_id = o.id AND journal_entry_id = p.sale_journal_id;
    PERFORM acct__inv_reverse_source('erp_orders', o.id, v_date, 'Order ' || o.order_number || ' cancelled: stock returned');
    -- money already applied to A/R becomes a customer credit held in deposits until refunded
    UPDATE acct_order_postings SET sale_reversed = true, updated_at = now() WHERE order_id = o.id;
    IF p.payments_posted - p.refunds_posted - p.deposits_held > 0 THEN
      PERFORM acct_post_entry(o.tenant_id, v_entity, v_date, jsonb_build_array(
        jsonb_build_object('account_id', acct_role_account(o.tenant_id, v_entity, 'accounts_receivable'), 'debit', p.payments_posted - p.refunds_posted - p.deposits_held,
                           'customer_id', p.party, 'description', 'Cancelled order payment moved to deposits'),
        jsonb_build_object('account_id', acct_role_account(o.tenant_id, v_entity, 'customer_deposits'), 'credit', p.payments_posted - p.refunds_posted - p.deposits_held,
                           'customer_id', p.party, 'description', 'Cancelled order payment held for refund')),
        'invoice', o.id::text, o.order_number, 'Order ' || o.order_number || ' cancelled', 'ordercancel:' || o.id, NULL, NULL, NULL, false, false, 'erp_orders', o.id);
      UPDATE acct_order_postings SET deposits_held = deposits_held + (p.payments_posted - p.refunds_posted - p.deposits_held) WHERE order_id = o.id;
    END IF;
    v_done := v_done || '"cancel"';
  END IF;

  UPDATE acct_order_postings SET last_status = v_st, last_error = NULL, synced_at = now() WHERE order_id = o.id;
  RETURN jsonb_build_object('status','ok','posted', v_done, 'payment_source', v_mode);
END $$;

-- @seq 128
CREATE FUNCTION public.acct_accept_bank_transaction(p_bank_txn_id uuid, p_override jsonb DEFAULT NULL::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_bank_transactions%ROWTYPE; b acct_bank_accounts%ROWTYPE; v_bank_gl uuid; v_abs numeric; v_in boolean;
        v_type text; v_splits jsonb; v_lines jsonb := '[]'::jsonb; s jsonb; v_sum numeric := 0; v_je uuid; v_other uuid;
        v_vendor text; v_customer text; v_bank_line uuid; v_acct uuid;
BEGIN
  SELECT * INTO t FROM acct_bank_transactions WHERE id = p_bank_txn_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank transaction not found'; END IF;
  PERFORM acct_assert_access(t.tenant_id);
  IF t.review_status IN ('posted','matched') THEN RAISE EXCEPTION 'Transaction already added to the books'; END IF;
  IF t.review_status = 'excluded' THEN RAISE EXCEPTION 'Transaction is excluded; undo the exclusion first'; END IF;
  SELECT * INTO b FROM acct_bank_accounts WHERE id = t.bank_account_id;
  v_bank_gl := b.gl_account_id; v_abs := abs(t.amount); v_in := t.amount > 0;
  IF t.amount = 0 THEN RAISE EXCEPTION 'Zero-amount transaction'; END IF;

  v_type    := coalesce(p_override->>'txn_type', t.txn_type, CASE WHEN v_in THEN 'deposit' ELSE 'expense' END);
  v_vendor  := coalesce(p_override->>'payee_vendor_id', t.payee_vendor_id::text);
  v_customer:= coalesce(p_override->>'payee_customer_id', t.payee_customer_id::text);
  v_splits  := coalesce(p_override->'splits', t.splits);
  v_other   := coalesce(nullif(p_override->>'transfer_bank_account_id','')::uuid, t.transfer_bank_account_id);
  v_acct    := coalesce(nullif(p_override->>'category_account_id','')::uuid, t.category_account_id);

  IF v_type IN ('transfer','credit_card_payment','loan_payment') THEN
    IF v_other IS NULL THEN RAISE EXCEPTION 'Choose the other account for this %', v_type; END IF;
    IF v_other = b.id THEN RAISE EXCEPTION 'Transfer to the same account'; END IF;
    v_splits := jsonb_build_array(jsonb_build_object('account_id', acct_bank_gl(v_other), 'amount', v_abs, 'memo', coalesce(t.memo, t.description)));
  ELSIF v_type = 'owner_draw' THEN
    v_splits := jsonb_build_array(jsonb_build_object('account_id', acct_role_account(t.tenant_id, b.entity_id, 'owner_draw'), 'amount', v_abs));
  ELSIF v_splits IS NULL OR jsonb_array_length(v_splits) = 0 THEN
    IF v_acct IS NULL THEN
      RAISE EXCEPTION 'Pick a category for this transaction (or let a bank rule do it)'; END IF;
    v_splits := jsonb_build_array(jsonb_build_object('account_id', v_acct, 'amount', v_abs, 'memo', coalesce(p_override->>'memo', t.memo)));
  END IF;

  FOR s IN SELECT value FROM jsonb_array_elements(v_splits) LOOP
    v_sum := v_sum + (s->>'amount')::numeric;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object(
      'account_id', s->>'account_id',
      'debit',  CASE WHEN v_in THEN 0 ELSE (s->>'amount')::numeric END,
      'credit', CASE WHEN v_in THEN (s->>'amount')::numeric ELSE 0 END,
      'description', coalesce(s->>'memo', t.description), 'vendor_id', v_vendor, 'customer_id', v_customer,
      'tax_code_id', s->>'tax_code_id', 'dimensions', coalesce(s->'dimensions','{}'::jsonb)));
  END LOOP;
  IF v_sum <> v_abs THEN RAISE EXCEPTION 'Split lines total % but the transaction is %', v_sum, v_abs; END IF;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', v_bank_gl,
               'debit', CASE WHEN v_in THEN v_abs ELSE 0 END, 'credit', CASE WHEN v_in THEN 0 ELSE v_abs END,
               'description', coalesce(t.payee, t.description), 'vendor_id', v_vendor, 'customer_id', v_customer)) || v_lines;

  v_je := acct_post_entry(t.tenant_id, b.entity_id, t.transaction_date, v_lines, 'bank', t.id::text, t.reference,
                          coalesce(p_override->>'memo', t.memo, t.description), 'banktxn:' || t.id,
                          NULL, NULL, t.currency, false, false, 'acct_bank_transactions', t.id);
  SELECT id INTO v_bank_line FROM acct_journal_lines WHERE journal_entry_id = v_je AND account_id = v_bank_gl ORDER BY line_no LIMIT 1;
  UPDATE acct_journal_lines SET cleared_status = 'cleared', cleared_at = now() WHERE id = v_bank_line;
  -- transfer: the other register's line is not cleared until its own feed matches it
  UPDATE acct_bank_transactions SET review_status = 'posted', match_status = 'matched', txn_type = v_type, posted_journal_id = v_je,
         matched_journal_line_id = v_bank_line, splits = v_splits, reviewed_by = auth.uid(), reviewed_at = now()
   WHERE id = t.id;
  RETURN v_je;
END $$;

-- @seq 129
CREATE FUNCTION public.acct_account_balance(p_account_id uuid, p_as_of date DEFAULT NULL::date) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE WHEN a.normal_balance = 'debit' THEN 1 ELSE -1 END * coalesce(sum(l.debit - l.credit), 0)
    FROM acct_chart_of_accounts a
    LEFT JOIN acct_journal_lines l ON l.account_id = a.id
    LEFT JOIN acct_journal_entries e ON e.id = l.journal_entry_id AND e.status IN ('posted','reversed')
   WHERE a.id = p_account_id AND acct_can_access(a.tenant_id)
     AND (l.id IS NULL OR (e.id IS NOT NULL AND (p_as_of IS NULL OR e.posting_date <= p_as_of)))
   GROUP BY a.normal_balance;
$$;

-- @seq 130
CREATE FUNCTION public.acct_account_register(p_account uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT CURRENT_DATE) RETURNS TABLE(posting_date date, journal_entry_id uuid, entry_no bigint, source text, reference text, payee text, memo text, split_account text, payment numeric, deposit numeric, cleared_status text, running_balance numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE v_acct acct_chart_of_accounts; v_open numeric := 0; v_sign int;
BEGIN
  SELECT a.* INTO v_acct FROM acct_chart_of_accounts a WHERE a.id = p_account;
  IF NOT FOUND THEN
    SELECT a.* INTO v_acct FROM acct_chart_of_accounts a WHERE a.id = acct_bank_gl(p_account);
  END IF;
  IF v_acct.id IS NULL THEN RAISE EXCEPTION 'Account % not found', p_account; END IF;
  PERFORM acct_assert_access(v_acct.tenant_id);
  v_sign := CASE WHEN v_acct.normal_balance = 'debit' THEN 1 ELSE -1 END;
  IF p_from IS NOT NULL THEN
    SELECT coalesce(sum(s.dr - s.cr),0) INTO v_open FROM acct__ledger_sums(v_acct.tenant_id, NULL, NULL, p_from - 1, false) s WHERE s.account_id = v_acct.id;
  END IF;
  RETURN QUERY
  SELECT e.posting_date, e.id, e.entry_no, e.source, e.reference,
         coalesce((SELECT coalesce(v.display_name, v.legal_name) FROM acct_vendors v WHERE v.id::text = l.vendor_id),
                  (SELECT acct_customer_name(c.id) FROM crm_customers c WHERE c.id::text = l.customer_id),
                  (SELECT coalesce(v.display_name, v.legal_name) FROM acct_journal_lines o JOIN acct_vendors v ON v.id::text = o.vendor_id
                    WHERE o.journal_entry_id = e.id AND o.vendor_id IS NOT NULL LIMIT 1),
                  (SELECT acct_customer_name(c.id) FROM acct_journal_lines o JOIN crm_customers c ON c.id::text = o.customer_id
                    WHERE o.journal_entry_id = e.id AND o.customer_id IS NOT NULL LIMIT 1)),
         coalesce(nullif(l.description,''), e.memo),
         (SELECT CASE WHEN count(DISTINCT o.account_id) > 1 THEN '-Split-' ELSE max(oa.code || ' ' || oa.name) END
            FROM acct_journal_lines o JOIN acct_chart_of_accounts oa ON oa.id = o.account_id
           WHERE o.journal_entry_id = e.id AND o.id <> l.id AND o.account_id <> v_acct.id),
         CASE WHEN v_sign = 1 THEN l.credit ELSE l.debit END,
         CASE WHEN v_sign = 1 THEN l.debit ELSE l.credit END,
         l.cleared_status,
         v_sign * (v_open + sum(l.debit - l.credit) OVER (ORDER BY e.posting_date, e.entry_no, l.line_no ROWS UNBOUNDED PRECEDING))
    FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
   WHERE l.account_id = v_acct.id AND e.status IN ('posted','reversed')
     AND (p_from IS NULL OR e.posting_date >= p_from) AND e.posting_date <= p_to
   ORDER BY e.posting_date, e.entry_no, l.line_no;
END $$;

-- @seq 131
CREATE FUNCTION public.acct_add_fixed_asset(p_tenant_id uuid, p_name text, p_cost numeric, p_acquired date, p_class_id uuid DEFAULT NULL::uuid, p_paid_from_bank_account_id uuid DEFAULT NULL::uuid, p_already_on_books boolean DEFAULT false, p_accumulated_to_date numeric DEFAULT 0, p_serial text DEFAULT NULL::text, p_location text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid; v_class acct_asset_classes%ROWTYPE; v_id uuid; v_je uuid; v_credit uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_cost <= 0 THEN RAISE EXCEPTION 'Asset cost must be positive'; END IF;
  v_entity := acct_default_entity(p_tenant_id);
  v_id := coalesce(p_class_id, acct__default_asset_class(p_tenant_id, v_entity));
  SELECT * INTO v_class FROM acct_asset_classes WHERE id = v_id AND tenant_id = p_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Asset class not found'; END IF;
  INSERT INTO acct_fixed_assets(tenant_id, entity_id, asset_class_id, asset_number, name, acquisition_date, original_cost, residual_value,
                                accumulated_depreciation, useful_life_months, status, location, serial_number, cost_account_id)
  VALUES (p_tenant_id, v_entity, v_class.id, acct_next_number(p_tenant_id, v_entity, 'fixed_asset', 'FA-'), p_name, p_acquired, p_cost,
          round(p_cost * coalesce(v_class.residual_percent,0) / 100, 2), coalesce(p_accumulated_to_date,0), v_class.default_useful_life_months,
          'draft', p_location, p_serial, v_class.asset_account_id)
  RETURNING id INTO v_id;
  IF NOT p_already_on_books THEN
    v_credit := CASE WHEN p_paid_from_bank_account_id IS NOT NULL THEN acct_bank_gl(p_paid_from_bank_account_id)
                     ELSE acct_role_account(p_tenant_id, v_entity, 'opening_balance_equity') END;
    v_je := acct_post_entry(p_tenant_id, v_entity, p_acquired, jsonb_build_array(
              jsonb_build_object('account_id', v_class.asset_account_id, 'debit', p_cost, 'description', p_name),
              jsonb_build_object('account_id', v_credit, 'credit', p_cost, 'description', p_name)),
            'fixed_asset', v_id::text, NULL, 'Acquire ' || p_name, 'faacq:' || v_id, NULL, NULL, NULL, false, false, 'acct_fixed_assets', v_id);
    IF coalesce(p_accumulated_to_date,0) > 0 THEN
      PERFORM acct_post_entry(p_tenant_id, v_entity, p_acquired, jsonb_build_array(
              jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'opening_balance_equity'), 'debit', p_accumulated_to_date, 'description', 'Prior depreciation ' || p_name),
              jsonb_build_object('account_id', v_class.accumulated_depreciation_account_id, 'credit', p_accumulated_to_date, 'description', 'Prior depreciation ' || p_name)),
            'fixed_asset', v_id::text, NULL, 'Prior depreciation ' || p_name, 'faacc:' || v_id, NULL, NULL, NULL, false, false, 'acct_fixed_assets', v_id);
    END IF;
    UPDATE acct_fixed_assets SET acquisition_journal_id = v_je WHERE id = v_id;
  END IF;
  RETURN v_id;
END $$;

-- @seq 132
CREATE FUNCTION public.acct_add_tax_holiday(p_tenant_id uuid, p_jurisdiction_code text, p_from date, p_to date, p_max_unit_price numeric, p_categories text[], p_name text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_j uuid; n int;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT id INTO v_j FROM acct_tax_jurisdictions WHERE tenant_id = p_tenant_id AND code = p_jurisdiction_code;
  IF v_j IS NULL THEN RAISE EXCEPTION 'Jurisdiction % not found', p_jurisdiction_code; END IF;
  INSERT INTO acct_tax_taxability_rules(tenant_id, jurisdiction_id, tax_category, treatment, max_unit_price, effective_from, effective_to, priority, name)
  SELECT p_tenant_id, v_j, c, 'exempt', p_max_unit_price, p_from, p_to, 500,
         coalesce(p_name, 'Sales tax holiday ' || extract(year FROM p_from)) || ' (' || c || ')'
    FROM unnest(p_categories) c;
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n;
END $$;

-- @seq 133
CREATE FUNCTION public.acct_address_text(p_party_type text, p_party_id uuid, p_type text DEFAULT 'mailing'::text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT concat_ws(E'\n', line1, line2, concat_ws(', ', city, concat_ws(' ', state, postal_code)), nullif(country,'US'))
    FROM acct_party_addresses WHERE party_type = p_party_type AND party_id = p_party_id AND is_default
   ORDER BY (address_type = p_type) DESC, (address_type = 'remit_to') DESC LIMIT 1;
$$;

-- @seq 134
CREATE FUNCTION public.acct_ai_context(p_tenant_id uuid, p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_close uuid; v jsonb;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT id INTO v_close FROM acct_closes WHERE tenant_id = p_tenant_id AND period_end BETWEEN p_from AND p_to ORDER BY period_end DESC LIMIT 1;
  v := jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'summary', acct__kpi_tokens(p_tenant_id, p_from, p_to),
    'kpis', (SELECT coalesce(jsonb_object_agg(k.code, jsonb_build_object('name', k.name, 'value', k.value, 'prior', k.prior_value, 'unit', k.unit)), '{}')
               FROM acct_kpis(p_tenant_id, p_from, p_to) k),
    'cash_accounts', (SELECT coalesce(jsonb_agg(jsonb_build_object('account', a.name, 'code', a.code, 'balance', a.ending_balance) ORDER BY a.code), '[]')
                        FROM acct__account_amounts(p_tenant_id, p_to, p_to) a WHERE a.subtype IN ('bank','cash','credit_card','line_of_credit')),
    'flux', (SELECT coalesce(jsonb_agg(jsonb_build_object('account', f.name, 'current', f.current_amount, 'prior', f.prior_amount, 'change', f.change,
                                                          'explained', f.explanation IS NOT NULL, 'drivers', f.top_drivers) ORDER BY abs(f.change) DESC), '[]')
               FROM acct_flux_analysis(p_tenant_id, p_from, p_to) f WHERE f.flagged),
    'open_findings', (SELECT coalesce(jsonb_object_agg(x.check_code, x.n), '{}') FROM (
                        SELECT check_code, count(*) n FROM acct_review_findings WHERE tenant_id = p_tenant_id AND status IN ('open','in_progress') GROUP BY 1) x),
    'bank_feed', (SELECT coalesce(jsonb_object_agg(coalesce(x.review_stage, 'unclassified'), x.n), '{}') FROM (
                    SELECT review_stage, count(*) n FROM acct_bank_transactions WHERE tenant_id = p_tenant_id AND review_status IN ('for_review','categorized') GROUP BY 1) x),
    'ar_aging', (SELECT jsonb_build_object('current', sum(current_due), '1_30', sum(days_1_30), '31_60', sum(days_31_60), '61_90', sum(days_61_90),
                                           'over_90', sum(days_over_90), 'total', sum(total_open)) FROM acct_v_ar_aging WHERE tenant_id = p_tenant_id),
    'ap_aging', (SELECT jsonb_build_object('current', sum(current_due), '1_30', sum(days_1_30), '31_60', sum(days_31_60), '61_90', sum(days_61_90),
                                           'over_90', sum(days_over_90), 'total', sum(total_open)) FROM acct_v_ap_aging WHERE tenant_id = p_tenant_id),
    'close', CASE WHEN v_close IS NOT NULL THEN acct_close_status(v_close, false) - 'tasks' END,
    'tasks_due', (SELECT coalesce(jsonb_agg(jsonb_build_object('title', title, 'due', due_date, 'status', status, 'overdue', overdue) ORDER BY due_date), '[]')
                    FROM (SELECT * FROM acct_v_tasks_due WHERE tenant_id = p_tenant_id ORDER BY due_date NULLS LAST LIMIT 20) td),
    'scheduled_reversals', (SELECT count(*) FROM acct_auto_reversals WHERE tenant_id = p_tenant_id AND status = 'scheduled'),
    'generated_at', now());
  RETURN v;
END $$;

-- @seq 135
CREATE FUNCTION public.acct_apply_bank_rules(p_tenant_id uuid, p_bank_txn_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t record; r record; n int := 0; v_hit boolean; v_splits jsonb; v_abs numeric; v_alloc numeric; s record; v_last int; v_cnt int; v_amt numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR t IN SELECT bt.* FROM acct_bank_transactions bt
            WHERE bt.tenant_id = p_tenant_id AND bt.review_status = 'for_review'
              AND (p_bank_txn_id IS NULL OR bt.id = p_bank_txn_id) LOOP
    v_hit := false;
    FOR r IN SELECT * FROM acct_bank_rules WHERE tenant_id = p_tenant_id AND entity_id = t.entity_id AND is_active ORDER BY priority, created_at LOOP
      CONTINUE WHEN NOT acct_bank_rule_matches(r.id, t.id);
      v_abs := abs(t.amount); v_splits := '[]'::jsonb; v_alloc := 0;
      SELECT count(*) INTO v_cnt FROM acct_bank_rule_splits WHERE rule_id = r.id;
      v_last := 0;
      -- fixed amounts first, then percentages of the remainder; last line absorbs rounding
      FOR s IN SELECT * FROM acct_bank_rule_splits WHERE rule_id = r.id ORDER BY (fixed_amount IS NULL), line_no LOOP
        v_last := v_last + 1;
        IF v_last = v_cnt THEN v_amt := v_abs - v_alloc;
        ELSIF s.fixed_amount IS NOT NULL THEN v_amt := least(s.fixed_amount, v_abs - v_alloc);
        ELSE v_amt := round((v_abs - coalesce((SELECT sum(fixed_amount) FROM acct_bank_rule_splits WHERE rule_id = r.id AND fixed_amount IS NOT NULL),0)) * s.percent / 100, 2);
        END IF;
        v_alloc := v_alloc + v_amt;
        v_splits := v_splits || jsonb_build_array(jsonb_build_object('account_id', s.account_id, 'amount', v_amt, 'memo', coalesce(s.memo, r.memo),
                                   'tax_code_id', s.tax_code_id, 'dimensions', coalesce(r.dimensions,'{}'::jsonb) || coalesce(s.dimensions,'{}'::jsonb)));
      END LOOP;
      UPDATE acct_bank_transactions SET
        -- a later rule (after one with stop_processing = false) only fills what is still blank
        review_status = CASE WHEN v_hit AND review_status <> 'for_review' THEN review_status
                             WHEN r.txn_type = 'exclude' THEN 'excluded' ELSE 'categorized' END,
        excluded_reason = CASE WHEN v_hit AND review_status <> 'for_review' THEN excluded_reason
                               WHEN r.txn_type = 'exclude' THEN 'Rule: ' || r.name END,
        txn_type = CASE WHEN v_hit AND review_status <> 'for_review' THEN txn_type ELSE r.txn_type END,
        suggested_rule_id = coalesce(CASE WHEN v_hit THEN suggested_rule_id END, r.id), payee_vendor_id = coalesce(payee_vendor_id, r.payee_vendor_id),
        payee_customer_id = coalesce(payee_customer_id, r.payee_customer_id),
        transfer_bank_account_id = coalesce(transfer_bank_account_id, r.transfer_bank_account_id),
        splits = CASE WHEN v_hit AND splits IS NOT NULL THEN
                        (SELECT jsonb_agg(e || jsonb_build_object('dimensions', coalesce(r.dimensions,'{}'::jsonb) || coalesce(e->'dimensions','{}'::jsonb)))
                           FROM jsonb_array_elements(splits) e)
                      WHEN jsonb_array_length(v_splits) > 0 THEN v_splits END,
        category_account_id = CASE WHEN v_hit AND category_account_id IS NOT NULL THEN category_account_id
                                   WHEN jsonb_array_length(v_splits) = 1 THEN (v_splits->0->>'account_id')::uuid END,
        memo = coalesce(memo, r.memo)
      WHERE id = t.id;
      UPDATE acct_bank_rules SET times_applied = times_applied + 1, last_applied_at = now() WHERE id = r.id;
      IF NOT v_hit THEN n := n + 1; END IF;
      v_hit := true;
      EXIT WHEN r.stop_processing;   -- default: first matching rule wins
    END LOOP;
    -- auto-add only after every applicable rule has run
    IF v_hit THEN
      SELECT * INTO r FROM acct_bank_rules WHERE id = (SELECT suggested_rule_id FROM acct_bank_transactions WHERE id = t.id);
      IF r.auto_confirm AND r.txn_type <> 'exclude'
         AND (SELECT review_status FROM acct_bank_transactions WHERE id = t.id) = 'categorized' THEN
        PERFORM acct_accept_bank_transaction(t.id);
      END IF;
    END IF;
  END LOOP;
  RETURN n;
END $$;

-- @seq 136
CREATE FUNCTION public.acct_apply_credit_memo(p_memo_id uuid, p_invoice_id uuid, p_amount numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE m acct_ar_credit_memos%ROWTYPE; iv acct_ar_invoices%ROWTYPE; v_amt numeric; v uuid;
BEGIN
  SELECT * INTO m FROM acct_ar_credit_memos WHERE id = p_memo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Credit memo not found'; END IF;
  PERFORM acct_assert_access(m.tenant_id);
  IF m.posted_journal_id IS NULL OR m.status <> 'posted' THEN RAISE EXCEPTION 'Credit memo % is not open', m.memo_number; END IF;
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND OR iv.tenant_id <> m.tenant_id THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  IF iv.customer_id <> m.customer_id THEN RAISE EXCEPTION 'Invoice belongs to a different customer'; END IF;
  IF iv.posted_journal_id IS NULL OR iv.status = 'void' THEN RAISE EXCEPTION 'Invoice % is not open', iv.invoice_number; END IF;
  v_amt := round(coalesce(p_amount, least(m.total - m.applied_amount, iv.open_balance)), 2);
  IF v_amt <= 0 THEN RAISE EXCEPTION 'Nothing to apply'; END IF;
  IF v_amt > m.total - m.applied_amount THEN RAISE EXCEPTION 'Only % of credit memo % is unapplied', m.total - m.applied_amount, m.memo_number; END IF;
  IF v_amt > iv.open_balance THEN RAISE EXCEPTION 'Invoice % only has % open', iv.invoice_number, iv.open_balance; END IF;
  INSERT INTO acct_credit_memo_applications(tenant_id, credit_memo_id, invoice_id, amount) VALUES (m.tenant_id, m.id, iv.id, v_amt) RETURNING id INTO v;
  UPDATE acct_ar_invoices SET amount_credited = amount_credited + v_amt WHERE id = iv.id;
  PERFORM acct_invoice_refresh_status(iv.id);
  UPDATE acct_ar_credit_memos SET applied_amount = applied_amount + v_amt,
         status = (CASE WHEN applied_amount + v_amt >= total THEN 'closed' ELSE 'posted' END)::acct_document_status, updated_at = now() WHERE id = m.id;
  RETURN v;
END $$;

-- @seq 137
CREATE FUNCTION public.acct_apply_unapplied_payment(p_receipt_id uuid, p_invoice_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_ar_receipts%ROWTYPE; iv acct_ar_invoices%ROWTYPE;
BEGIN
  SELECT * INTO r FROM acct_ar_receipts WHERE id = p_receipt_id FOR UPDATE;
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id FOR UPDATE;
  PERFORM acct_assert_access(r.tenant_id);
  IF r.customer_id <> iv.customer_id THEN RAISE EXCEPTION 'Different customers'; END IF;
  IF p_amount > r.unapplied_amount THEN RAISE EXCEPTION 'Only % is unapplied', r.unapplied_amount; END IF;
  IF iv.posted_journal_id IS NULL OR p_amount > iv.open_balance THEN RAISE EXCEPTION 'Invoice is not posted or has only % open', iv.open_balance; END IF;
  PERFORM acct_post_entry(r.tenant_id, r.entity_id, greatest(r.receipt_date, iv.invoice_date), jsonb_build_array(
    jsonb_build_object('account_id', acct_role_account(r.tenant_id, r.entity_id, 'unapplied_cash'), 'debit', p_amount, 'customer_id', r.customer_id::text),
    jsonb_build_object('account_id', acct_role_account(r.tenant_id, r.entity_id, 'accounts_receivable'), 'credit', p_amount, 'customer_id', r.customer_id::text)),
    'customer_receipt', r.id::text, r.receipt_number, 'Apply unapplied payment to ' || iv.invoice_number, NULL, NULL, NULL, NULL, false, false, 'acct_ar_receipts', r.id);
  INSERT INTO acct_ar_receipt_applications(tenant_id, receipt_id, invoice_id, applied_amount) VALUES (r.tenant_id, r.id, iv.id, p_amount)
    ON CONFLICT (receipt_id, invoice_id) DO UPDATE SET applied_amount = acct_ar_receipt_applications.applied_amount + EXCLUDED.applied_amount;
  UPDATE acct_ar_receipts SET unapplied_amount = unapplied_amount - p_amount WHERE id = r.id;
  UPDATE acct_ar_invoices SET amount_paid = amount_paid + p_amount WHERE id = iv.id;
  PERFORM acct_invoice_refresh_status(iv.id);
END $$;

-- @seq 138
CREATE FUNCTION public.acct_apply_vendor_credit(p_credit_id uuid, p_bill_id uuid, p_amount numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c acct_ap_vendor_credits%ROWTYPE; b acct_ap_bills%ROWTYPE;
BEGIN
  SELECT * INTO c FROM acct_ap_vendor_credits WHERE id = p_credit_id FOR UPDATE;
  SELECT * INTO b FROM acct_ap_bills WHERE id = p_bill_id FOR UPDATE;
  PERFORM acct_assert_access(c.tenant_id);
  IF c.vendor_id <> b.vendor_id THEN RAISE EXCEPTION 'Credit and bill are for different vendors'; END IF;
  IF c.status <> 'open' THEN RAISE EXCEPTION 'Vendor credit is %', c.status; END IF;
  IF b.status NOT IN ('open','partially_paid') THEN RAISE EXCEPTION 'Bill % is %', b.bill_number, b.status; END IF;
  IF p_amount > c.remaining THEN RAISE EXCEPTION 'Only % of this credit remains', c.remaining; END IF;
  IF p_amount > b.open_balance THEN RAISE EXCEPTION 'Bill % only has % open', b.bill_number, b.open_balance; END IF;
  INSERT INTO acct_ap_vendor_credit_applications(tenant_id, credit_id, bill_id, amount) VALUES (c.tenant_id, c.id, b.id, p_amount);
  UPDATE acct_ap_vendor_credits SET applied_amount = applied_amount + p_amount,
         status = CASE WHEN applied_amount + p_amount >= total THEN 'applied' ELSE 'open' END WHERE id = c.id;
  UPDATE acct_ap_bills SET amount_credited = amount_credited + p_amount WHERE id = b.id;
  PERFORM acct_bill_refresh_status(b.id);
END $$;

-- @seq 139
CREATE FUNCTION public.acct_approve_refund(p_refund_id uuid, p_approve boolean DEFAULT true) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f acct_refunds%ROWTYPE;
BEGIN
  SELECT * INTO f FROM acct_refunds WHERE id = p_refund_id FOR UPDATE;
  PERFORM acct_assert_access(f.tenant_id);
  IF auth.uid() IS NOT NULL AND auth.uid() = f.requested_by THEN RAISE EXCEPTION 'Segregation of duties: requester cannot approve their own refund'; END IF;
  UPDATE acct_refunds SET status = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END, approved_by = auth.uid(), approved_at = now() WHERE id = f.id;
END $$;

-- @seq 140
CREATE FUNCTION public.acct_assert_access(p_tenant_id uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF p_tenant_id IS NULL OR NOT acct_can_access(p_tenant_id) THEN
    RAISE EXCEPTION 'Tenant access denied' USING ERRCODE = '42501';
  END IF;
END $$;

-- @seq 141
CREATE FUNCTION public.acct_attach_standard_triggers(p_table regclass) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE t text := p_table::text;
BEGIN
  EXECUTE format('DROP TRIGGER IF EXISTS trg_acct_audit ON %s', t);
  EXECUTE format('CREATE TRIGGER trg_acct_audit AFTER INSERT OR UPDATE OR DELETE ON %s FOR EACH ROW EXECUTE FUNCTION acct_audit_row_change()', t);
  IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name = trim(both '"' from t) AND column_name = 'updated_at')
     AND t <> 'acct_chart_of_accounts' THEN
    EXECUTE format('DROP TRIGGER IF EXISTS trg_acct_updated_at ON %s', t);
    EXECUTE format('CREATE TRIGGER trg_acct_updated_at BEFORE UPDATE ON %s FOR EACH ROW EXECUTE FUNCTION acct_set_updated_at()', t);
  END IF;
END $$;

-- @seq 142
CREATE FUNCTION public.acct_audit_row_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_tenant uuid; v_prev text; v_row jsonb; v_old jsonb; v_hash text;
BEGIN
  v_row := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  v_old := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  v_tenant := coalesce((v_row->>'tenant_id')::uuid, (v_old->>'tenant_id')::uuid);
  IF v_tenant IS NULL THEN RETURN COALESCE(NEW, OLD); END IF;
  PERFORM pg_advisory_xact_lock(hashtext('acct_audit:' || v_tenant));
  SELECT entry_hash INTO v_prev FROM acct_audit_log WHERE tenant_id = v_tenant ORDER BY event_time DESC, id DESC LIMIT 1;
  v_hash := encode(digest(coalesce(v_prev,'') || TG_OP || TG_TABLE_NAME || coalesce(v_row::text, v_old::text), 'sha256'), 'hex');
  INSERT INTO acct_audit_log(tenant_id, actor_user_id, action, table_name, record_id, before_data, after_data, prev_hash, entry_hash)
  VALUES (v_tenant, auth.uid(), TG_OP, TG_TABLE_NAME, coalesce(v_row->>'id', v_old->>'id'), v_old, v_row, v_prev, v_hash);
  RETURN COALESCE(NEW, OLD);
END $$;

-- @seq 143
CREATE FUNCTION public.acct_available_credit(p_debt_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT d.credit_limit - coalesce(acct_debt_balance(d.id), 0) FROM acct_debt_instruments d WHERE d.id = p_debt_id;
$$;

-- @seq 144
CREATE FUNCTION public.acct_balance_sheet(p_tenant uuid, p_as_of date DEFAULT CURRENT_DATE, p_entity uuid DEFAULT NULL::uuid) RETURNS TABLE(section text, sort_order integer, account_id uuid, code text, name text, amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE v_fy date; v_prior_pl numeric; v_cur_pl numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant);
  v_fy := acct_fiscal_year_start(p_tenant, p_entity, p_as_of);
  -- residual P&L balances (closing entries INCLUDED: anything already closed nets to zero)
  SELECT coalesce(sum(s.cr - s.dr), 0) INTO v_prior_pl
    FROM acct__ledger_sums(p_tenant, p_entity, NULL, v_fy - 1, false) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id WHERE a.account_type IN ('revenue','expense');
  SELECT coalesce(sum(s.cr - s.dr), 0) INTO v_cur_pl
    FROM acct__ledger_sums(p_tenant, p_entity, v_fy, p_as_of, false) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id WHERE a.account_type IN ('revenue','expense');
  RETURN QUERY
  WITH s AS (SELECT * FROM acct__ledger_sums(p_tenant, p_entity, NULL, p_as_of, false)),
       r AS (
         SELECT CASE WHEN a.account_type IN ('asset','contra_asset') THEN 'Assets'
                     WHEN a.account_type = 'liability' THEN 'Liabilities' ELSE 'Equity' END sec,
                a.id aid, a.code acode, a.name aname,
                CASE WHEN a.account_type IN ('asset','contra_asset') THEN s.dr - s.cr ELSE s.cr - s.dr END amt
           FROM s JOIN acct_chart_of_accounts a ON a.id = s.account_id
          WHERE a.account_type IN ('asset','contra_asset','liability','equity','contra_equity') AND s.dr <> s.cr
         UNION ALL SELECT 'Equity', NULL, NULL, 'Retained Earnings (prior years, not yet closed)', v_prior_pl WHERE v_prior_pl <> 0
         UNION ALL SELECT 'Equity', NULL, NULL, 'Net Income', v_cur_pl),
       t AS (SELECT coalesce(sum(amt) FILTER (WHERE sec='Assets'),0) ta,
                    coalesce(sum(amt) FILTER (WHERE sec='Liabilities'),0) tl,
                    coalesce(sum(amt) FILTER (WHERE sec='Equity'),0) te FROM r)
  SELECT r.sec, CASE r.sec WHEN 'Assets' THEN 10 WHEN 'Liabilities' THEN 30 ELSE 50 END, r.aid, r.acode, r.aname, r.amt FROM r
  UNION ALL SELECT 'Total Assets', 20, NULL, NULL, 'Total Assets', t.ta FROM t
  UNION ALL SELECT 'Total Liabilities', 40, NULL, NULL, 'Total Liabilities', t.tl FROM t
  UNION ALL SELECT 'Total Equity', 60, NULL, NULL, 'Total Equity', t.te FROM t
  UNION ALL SELECT 'Total Liabilities and Equity', 70, NULL, NULL, 'Total Liabilities and Equity', t.tl + t.te FROM t
  UNION ALL SELECT 'Out of Balance', 99, NULL, NULL, 'Out of balance (must be 0)', t.ta - t.tl - t.te FROM t
  ORDER BY 2, 4 NULLS LAST, 5;
END $$;

-- @seq 152
CREATE FUNCTION public.acct_bill_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v acct_vendors%ROWTYPE; t acct_payment_terms%ROWTYPE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO v FROM acct_vendors WHERE id = NEW.vendor_id AND tenant_id = NEW.tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Vendor not found for this company'; END IF;
    IF NOT v.is_active THEN RAISE EXCEPTION 'Vendor % is inactive', v.display_name; END IF;
    NEW.entity_id := coalesce(NEW.entity_id, v.entity_id, acct_default_entity(NEW.tenant_id));
    NEW.bill_date := coalesce(NEW.bill_date, current_date);
    NEW.terms_id := coalesce(NEW.terms_id, v.default_terms_id);
    IF NEW.due_date IS NULL THEN
      SELECT * INTO t FROM acct_payment_terms WHERE id = NEW.terms_id;
      NEW.due_date := NEW.bill_date + coalesce(t.due_days, v.payment_terms_days, 30);
    END IF;
    NEW.mailing_address := coalesce(NEW.mailing_address, acct_address_text('vendor', v.id, 'remit_to'));
    IF NEW.bill_number IS NULL OR NEW.bill_number = '' THEN NEW.bill_number := acct_next_number(NEW.tenant_id, NEW.entity_id, 'bill', 'BILL-'); END IF;
    NEW.created_by := coalesce(NEW.created_by, auth.uid());
    IF NEW.source IN ('upload','email','photo') THEN NEW.review_status := 'for_review'; END IF;
  ELSIF OLD.status NOT IN ('draft','pending_approval','approved') THEN
    -- posted bills: only payment/credit/void bookkeeping may change
    IF (NEW.vendor_id, NEW.bill_date, NEW.total, NEW.subtotal, NEW.tax_total, NEW.entity_id) IS DISTINCT FROM
       (OLD.vendor_id, OLD.bill_date, OLD.total, OLD.subtotal, OLD.tax_total, OLD.entity_id) THEN
      RAISE EXCEPTION 'Bill % is posted; void it and re-enter to change vendor, date, or amounts', OLD.bill_number; END IF;
  END IF;
  RETURN NEW;
END $$;

-- @seq 153
CREATE FUNCTION public.acct_bill_from_purchase_order(p_po_id uuid, p_bill_number text, p_bill_date date DEFAULT CURRENT_DATE, p_basis text DEFAULT 'received'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE po erp_purchase_orders; v_bill uuid; v_lines int := 0; r record; v_qty numeric; v_acct uuid; v_fallback boolean := false;
BEGIN
  IF p_basis NOT IN ('received','ordered') THEN RAISE EXCEPTION 'Basis must be received or ordered'; END IF;
  SELECT * INTO po FROM erp_purchase_orders WHERE id = p_po_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order not found'; END IF;
  PERFORM acct_assert_access(po.tenant_id);
  IF po.vendor_id IS NULL THEN RAISE EXCEPTION 'Purchase order % has no vendor', po.po_number; END IF;
  IF coalesce(po.status, '') IN ('cancelled','canceled','void','draft') THEN
    RAISE EXCEPTION 'Purchase order % is %; approve or send it before billing', po.po_number, po.status;
  END IF;

  -- lines with no mapped item use the vendor's default category, else the default expense account,
  -- and the bill is sent to review so someone confirms the category
  SELECT coalesce(v.default_expense_account_id,
                  acct_role_account(po.tenant_id, acct_default_entity(po.tenant_id), 'default_expense'))
    INTO v_acct FROM acct_vendors v WHERE v.id = po.vendor_id;

  INSERT INTO acct_ap_bills (tenant_id, vendor_id, bill_number, bill_date, memo, purchase_order_id, currency)
  VALUES (po.tenant_id, po.vendor_id, p_bill_number, p_bill_date, 'PO ' || coalesce(po.po_number, po.id::text), po.id,
          coalesce(nullif(po.currency, ''), 'USD'))
  RETURNING id INTO v_bill;

  FOR r IN
    SELECT l.*, (SELECT i.id FROM acct_items i WHERE i.tenant_id = po.tenant_id AND i.sku_id = l.sku_id LIMIT 1) AS item_id,
           coalesce((SELECT sum(bl.quantity) FROM acct_ap_bill_lines bl JOIN acct_ap_bills b ON b.id = bl.bill_id
                      WHERE bl.erp_po_line_id = l.id AND b.status <> 'void' AND b.id <> v_bill), 0) AS billed
      FROM erp_purchase_order_lines l
     WHERE l.purchase_order_id = po.id
     ORDER BY l.created_at, l.id
  LOOP
    v_qty := CASE WHEN p_basis = 'received' THEN coalesce(r.quantity_received, 0)
                  ELSE coalesce(r.quantity_ordered, r.quantity, 0) END - r.billed;
    CONTINUE WHEN v_qty <= 0;
    v_lines := v_lines + 1;
    v_fallback := v_fallback OR r.item_id IS NULL;
    INSERT INTO acct_ap_bill_lines (tenant_id, bill_id, line_no, description, quantity, unit_cost, item_id, erp_po_line_id,
                                    purchase_order_ref, dimensions, expense_account_id)
    VALUES (po.tenant_id, v_bill, v_lines, coalesce(r.description, 'PO line'), v_qty, coalesce(r.unit_cost, 0), r.item_id, r.id,
            po.po_number, '{}', CASE WHEN r.item_id IS NULL THEN v_acct END);
  END LOOP;

  IF coalesce(po.shipping_total, 0) > 0 AND NOT EXISTS (
       SELECT 1 FROM acct_ap_bills b WHERE b.purchase_order_id = po.id AND b.id <> v_bill AND b.status <> 'void') THEN
    v_lines := v_lines + 1;
    v_fallback := true;
    INSERT INTO acct_ap_bill_lines (tenant_id, bill_id, line_no, description, quantity, unit_cost, purchase_order_ref, dimensions, expense_account_id)
    VALUES (po.tenant_id, v_bill, v_lines, 'Freight on PO ' || coalesce(po.po_number, ''), 1, po.shipping_total, po.po_number, '{}', v_acct);
  END IF;

  IF v_lines = 0 THEN
    RAISE EXCEPTION 'Nothing left to bill on PO % (basis: %)', po.po_number, p_basis;
  END IF;
  IF v_fallback THEN UPDATE acct_ap_bills SET review_status = 'for_review' WHERE id = v_bill; END IF;
  UPDATE erp_purchase_orders SET ap_bill_id = coalesce(ap_bill_id, v_bill), updated_at = now() WHERE id = po.id;
  RETURN v_bill;
END $$;

-- @seq 154
CREATE FUNCTION public.acct_bill_inventory_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE l record; v_vendor text;
BEGIN
  IF TG_OP = 'UPDATE' AND TG_WHEN = 'BEFORE' THEN
    -- block voids that would orphan sold stock (raises inside acct__inv_unreceive's check)
    IF NEW.status = 'void' AND OLD.status IS DISTINCT FROM 'void' THEN
      IF EXISTS (SELECT 1 FROM acct_inventory_moves m JOIN acct_inventory_layers y ON y.source_move_id = m.id
                  WHERE m.source_type = 'acct_ap_bills' AND m.source_id = NEW.id AND m.reversed_by_move_id IS NULL AND y.qty_remaining < y.qty_in) THEN
        RAISE EXCEPTION 'Inventory from bill % has already been sold or used. Enter a vendor credit instead of voiding.', NEW.bill_number;
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.posted_journal_id IS NULL AND NEW.posted_journal_id IS NOT NULL THEN
    SELECT coalesce(display_name, legal_name) INTO v_vendor FROM acct_vendors WHERE id = NEW.vendor_id;
    FOR l IN SELECT * FROM acct_ap_bill_lines WHERE bill_id = NEW.id ORDER BY line_no LOOP
      PERFORM acct__purchase_line_posted(NEW.tenant_id, NEW.entity_id, 'acct_ap_bills', NEW.id, l.id, NEW.bill_date, NEW.bill_number,
                                         l.item_id, l.expense_account_id, l.quantity, l.line_subtotal + l.tax_amount, l.description, v_vendor);
    END LOOP;
  END IF;
  IF NEW.status = 'void' AND OLD.status IS DISTINCT FROM 'void' THEN
    PERFORM acct__inv_reverse_source('acct_ap_bills', NEW.id, coalesce(NEW.voided_at::date, NEW.bill_date), 'Void bill ' || NEW.bill_number);
    UPDATE acct_fixed_assets SET status = 'retired', description = coalesce(description,'') || ' (source bill voided)'
     WHERE source_doc_type = 'acct_ap_bills' AND source_doc_id = NEW.id AND status = 'draft';
  END IF;
  RETURN NULL;
END $$;

-- @seq 155
CREATE FUNCTION public.acct_bill_line_after_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_bill uuid := coalesce(NEW.bill_id, OLD.bill_id);
BEGIN
  UPDATE acct_ap_bills b SET subtotal = s.sub, tax_total = s.tax, total = s.sub + s.tax - b.discount_total, updated_at = now()
    FROM (SELECT coalesce(sum(line_subtotal),0) sub, coalesce(sum(tax_amount),0) tax FROM acct_ap_bill_lines WHERE bill_id = v_bill) s
   WHERE b.id = v_bill AND b.status IN ('draft','pending_approval','approved');
  RETURN NULL;
END $$;

-- @seq 156
CREATE FUNCTION public.acct_bill_line_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_ap_bills%ROWTYPE; i acct_items%ROWTYPE;
BEGIN
  SELECT * INTO b FROM acct_ap_bills WHERE id = NEW.bill_id;
  IF b.status NOT IN ('draft','pending_approval','approved') THEN RAISE EXCEPTION 'Bill % is %; void it or create a new one', b.bill_number, b.status; END IF;
  NEW.tenant_id := b.tenant_id;
  IF NEW.line_no IS NULL THEN SELECT coalesce(max(line_no),0)+1 INTO NEW.line_no FROM acct_ap_bill_lines WHERE bill_id = NEW.bill_id; END IF;
  IF NEW.item_id IS NOT NULL THEN
    SELECT * INTO i FROM acct_items WHERE id = NEW.item_id AND tenant_id = b.tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Item not found'; END IF;
    IF NOT i.is_purchased THEN RAISE EXCEPTION 'Item % is not set up as purchased from a supplier', i.name; END IF;
    NEW.line_type := 'item';
    NEW.expense_account_id := coalesce(NEW.expense_account_id, CASE WHEN i.item_type='inventory' THEN i.inventory_asset_account_id ELSE i.expense_account_id END);
    NEW.description := coalesce(NEW.description, i.purchase_description, i.name);
    IF NEW.unit_cost = 0 AND i.purchase_cost IS NOT NULL THEN NEW.unit_cost := i.purchase_cost; END IF;
  END IF;
  IF NEW.expense_account_id IS NULL THEN
    SELECT default_expense_account_id INTO NEW.expense_account_id FROM acct_vendors WHERE id = b.vendor_id;
  END IF;
  IF NEW.expense_account_id IS NULL THEN RAISE EXCEPTION 'Choose a category (account) for line %', NEW.line_no; END IF;
  IF EXISTS (SELECT 1 FROM acct_chart_of_accounts WHERE id = NEW.expense_account_id AND (is_control_account OR NOT is_posting_allowed)) THEN
    RAISE EXCEPTION 'Bill lines cannot post to a control or header account'; END IF;
  NEW.line_subtotal := round(NEW.quantity * NEW.unit_cost, 2);
  IF NEW.billable AND NEW.billable_customer_id IS NULL THEN RAISE EXCEPTION 'Billable lines need a customer'; END IF;
  RETURN NEW;
END $$;

-- @seq 157
CREATE FUNCTION public.acct_bill_refresh_status(p_bill_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  UPDATE acct_ap_bills SET status = CASE WHEN total - amount_paid - amount_credited <= 0 THEN 'paid'
                                         WHEN amount_paid + amount_credited > 0 THEN 'partially_paid' ELSE 'open' END
   WHERE id = p_bill_id AND status IN ('open','partially_paid','paid');
$$;

-- @seq 158
CREATE FUNCTION public.acct_block_posted_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_status text;
BEGIN
  IF TG_TABLE_NAME = 'acct_journal_entries' THEN
    IF OLD.status IN ('posted','reversed','void') THEN
      IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Posted journal entries cannot be deleted; reverse them'; END IF;
      IF (to_jsonb(NEW) - ARRAY['status','reversed_by_id','reversal_of_id','memo']) IS DISTINCT FROM
         (to_jsonb(OLD) - ARRAY['status','reversed_by_id','reversal_of_id','memo'])
         OR NOT (NEW.status = OLD.status OR (OLD.status = 'posted' AND NEW.status = 'reversed')) THEN
        RAISE EXCEPTION 'Posted journal entry % is immutable; use a reversal', OLD.entry_no;
      END IF;
    END IF;
    RETURN COALESCE(NEW, OLD);
  END IF;
  -- acct_journal_lines
  SELECT status INTO v_status FROM acct_journal_entries WHERE id = COALESCE(NEW.journal_entry_id, OLD.journal_entry_id);
  IF v_status IN ('posted','reversed','void') THEN
    IF TG_OP IN ('INSERT','DELETE') THEN RAISE EXCEPTION 'Lines of a posted journal cannot be added or deleted'; END IF;
    IF (to_jsonb(NEW) - ARRAY['cleared_status','reconciliation_id','cleared_at']) IS DISTINCT FROM
       (to_jsonb(OLD) - ARRAY['cleared_status','reconciliation_id','cleared_at']) THEN
      RAISE EXCEPTION 'Posted journal lines are immutable (only reconciliation status may change)';
    END IF;
  END IF;
  RETURN COALESCE(NEW, OLD);
END $$;

-- @seq 159
CREATE FUNCTION public.acct_bootstrap_company(p_tenant_id uuid, p_legal_name text DEFAULT NULL::text, p_currency text DEFAULT 'USD'::text, p_fiscal_year_start_month integer DEFAULT 1, p_seed_coa boolean DEFAULT true, p_state_code text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_entity uuid; v_book uuid; t tenants%ROWTYPE;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT * INTO t FROM tenants WHERE id = p_tenant_id;
  v_entity := acct_default_entity(p_tenant_id);
  -- currency codes are a global list; seed the one we need if the platform seed never ran
  INSERT INTO acct_currencies(code, name, symbol, minor_units, tenant_id)
  SELECT upper(coalesce(p_currency, t.default_currency, 'USD')), upper(coalesce(p_currency, t.default_currency, 'USD')),
         CASE upper(coalesce(p_currency, t.default_currency, 'USD')) WHEN 'USD' THEN '$' END, 2, p_tenant_id
  WHERE NOT EXISTS (SELECT 1 FROM acct_currencies WHERE code = upper(coalesce(p_currency, t.default_currency, 'USD')));
  IF v_entity IS NULL THEN
    INSERT INTO acct_entities(tenant_id, code, legal_name, display_name, country_code, functional_currency, reporting_currency, fiscal_year_start_month, metadata)
    VALUES (p_tenant_id, 'MAIN', coalesce(p_legal_name, t.legal_name, t.name, 'Company'), coalesce(t.dba_name, t.name), 'US',
            upper(coalesce(p_currency, t.default_currency, 'USD')), upper(coalesce(p_currency, t.default_currency, 'USD')), p_fiscal_year_start_month,
            jsonb_build_object('state_code', p_state_code))
    RETURNING id INTO v_entity;
  END IF;
  v_book := acct_primary_book(p_tenant_id, v_entity);
  IF v_book IS NULL THEN
    INSERT INTO acct_books(tenant_id, entity_id, code, name, book_type, accounting_basis, currency, is_primary)
    VALUES (p_tenant_id, v_entity, 'GL', 'General Ledger', 'primary', 'accrual', upper(coalesce(p_currency,'USD')), true)
    RETURNING id INTO v_book;
  END IF;
  PERFORM acct_ensure_fiscal_year(v_book, current_date);
  PERFORM acct_ensure_fiscal_year(v_book, (current_date + interval '1 year')::date);
  IF p_seed_coa THEN PERFORM acct_seed_default_coa(p_tenant_id, v_entity); END IF;
  RETURN v_entity;
END $_$;

-- @seq 160
CREATE FUNCTION public.acct_budget_from_actuals(p_budget_id uuid, p_source_year integer, p_growth_pct numeric DEFAULT 0) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE bv acct_budget_versions%ROWTYPE; v_book uuid; n int;
BEGIN
  SELECT * INTO bv FROM acct_budget_versions WHERE id = p_budget_id;
  PERFORM acct_assert_access(bv.tenant_id);
  v_book := acct_primary_book(bv.tenant_id, bv.entity_id);
  PERFORM acct_ensure_fiscal_year(v_book, make_date(bv.fiscal_year, 6, 1));
  DELETE FROM acct_budget_lines WHERE budget_id = bv.id;
  INSERT INTO acct_budget_lines(budget_id, period_id, account_id, amount, notes)
  SELECT bv.id, tp.id, l.account_id,
         round(sum(CASE WHEN c.normal_balance = 'credit' THEN l.credit - l.debit ELSE l.debit - l.credit END) * (1 + p_growth_pct / 100), 2),
         'From ' || p_source_year || ' actuals'
    FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
    JOIN acct_chart_of_accounts c ON c.id = l.account_id AND c.account_type IN ('revenue','expense')
    JOIN acct_periods tp ON tp.book_id = v_book AND extract(year FROM tp.start_date) = bv.fiscal_year AND extract(month FROM tp.start_date) = extract(month FROM e.posting_date)
   WHERE e.tenant_id = bv.tenant_id AND e.status IN ('posted','reversed') AND NOT e.is_closing AND extract(year FROM e.posting_date) = p_source_year
   GROUP BY tp.id, l.account_id;
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END $$;

-- @seq 161
CREATE FUNCTION public.acct_budget_vs_actual(p_tenant_id uuid, p_budget_id uuid, p_from date, p_to date) RETURNS TABLE(account_id uuid, code text, name text, account_type text, budget numeric, actual numeric, variance numeric, variance_pct numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF NOT EXISTS (SELECT 1 FROM acct_budget_versions WHERE id = p_budget_id AND tenant_id = p_tenant_id) THEN RAISE EXCEPTION 'Budget not found'; END IF;
  RETURN QUERY
  WITH b AS (SELECT bl.account_id, sum(bl.amount) amt FROM acct_budget_lines bl JOIN acct_periods p ON p.id = bl.period_id
              WHERE bl.budget_id = p_budget_id AND p.start_date <= p_to AND p.end_date >= p_from GROUP BY 1),
       a AS (SELECT l.account_id, sum(l.debit - l.credit) dr FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
              WHERE e.tenant_id = p_tenant_id AND e.status IN ('posted','reversed') AND NOT e.is_closing AND e.posting_date BETWEEN p_from AND p_to GROUP BY 1)
  SELECT c.id, c.code, c.name, c.account_type, coalesce(b.amt,0),
         CASE WHEN c.normal_balance = 'credit' THEN -coalesce(a.dr,0) ELSE coalesce(a.dr,0) END,
         CASE WHEN c.normal_balance = 'credit' THEN -coalesce(a.dr,0) ELSE coalesce(a.dr,0) END - coalesce(b.amt,0),
         round(100 * (CASE WHEN c.normal_balance = 'credit' THEN -coalesce(a.dr,0) ELSE coalesce(a.dr,0) END - coalesce(b.amt,0)) / nullif(b.amt,0), 1)
    FROM acct_chart_of_accounts c LEFT JOIN b ON b.account_id = c.id LEFT JOIN a ON a.account_id = c.id
   WHERE c.tenant_id = p_tenant_id AND (b.amt IS NOT NULL OR (a.dr IS NOT NULL AND c.account_type IN ('revenue','expense')))
   ORDER BY c.code;
END $$;

-- @seq 162
CREATE FUNCTION public.acct_build_amortization(p_debt_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d acct_debt_instruments%ROWTYPE; v_bal numeric; v_r numeric; v_n int; v_pmt numeric; v_int numeric; v_prin numeric; i int;
        v_start int; v_due date; v_step interval; v_periods_per_year int; v_paid int;
BEGIN
  SELECT * INTO d FROM acct_debt_instruments WHERE id = p_debt_id;
  PERFORM acct_assert_access(d.tenant_id);
  IF d.kind IN ('credit_card','line_of_credit') THEN RAISE EXCEPTION 'Revolving accounts have no amortization schedule'; END IF;
  IF d.term_months IS NULL OR d.first_payment_date IS NULL THEN RAISE EXCEPTION 'Loan needs term_months and first_payment_date'; END IF;
  v_periods_per_year := CASE d.payment_frequency WHEN 'weekly' THEN 52 WHEN 'biweekly' THEN 26 WHEN 'monthly' THEN 12 WHEN 'quarterly' THEN 4 ELSE 1 END;
  v_step := CASE d.payment_frequency WHEN 'weekly' THEN interval '7 days' WHEN 'biweekly' THEN interval '14 days' WHEN 'monthly' THEN interval '1 month'
                 WHEN 'quarterly' THEN interval '3 months' ELSE interval '1 year' END;
  SELECT count(*) INTO v_paid FROM acct_debt_schedule WHERE debt_id = d.id AND status = 'paid';
  DELETE FROM acct_debt_schedule WHERE debt_id = d.id AND status <> 'paid';
  v_bal := CASE WHEN v_paid = 0 THEN coalesce(d.original_principal, acct_debt_balance(d.id)) ELSE acct_debt_balance(d.id) END;
  v_n := ceil(d.term_months * v_periods_per_year / 12.0)::int - v_paid;
  IF v_n <= 0 OR v_bal <= 0 THEN RETURN 0; END IF;
  v_r := d.apr / v_periods_per_year;
  v_pmt := coalesce(d.payment_amount, CASE WHEN v_r = 0 THEN round(v_bal / v_n, 2) ELSE round(v_bal * v_r / (1 - power(1 + v_r, -v_n)), 2) END);
  v_start := v_paid + 1;
  FOR i IN v_start..(v_paid + v_n) LOOP
    v_due := CASE WHEN d.payment_frequency IN ('weekly','biweekly') THEN d.first_payment_date + (i - 1) * v_step
                  ELSE (d.first_payment_date + (i - 1) * v_step)::date END;
    v_int := round(v_bal * v_r, 2);
    v_prin := CASE WHEN i = v_paid + v_n THEN v_bal ELSE least(v_pmt - v_int, v_bal) END;
    v_bal := v_bal - v_prin;
    INSERT INTO acct_debt_schedule(tenant_id, debt_id, installment_no, due_date, payment, principal, interest, balance_after)
    VALUES (d.tenant_id, d.id, i, v_due, v_prin + v_int, v_prin, v_int, v_bal);
    EXIT WHEN v_bal <= 0;
  END LOOP;
  RETURN v_n;
END $$;

-- @seq 163
CREATE FUNCTION public.acct_bulk_accept(p_tenant_id uuid, p_ids uuid[] DEFAULT NULL::uuid[], p_stages text[] DEFAULT ARRAY['potential_match'::text, 'rule'::text, 'auto_classification'::text]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t record; ok int := 0; errs jsonb := '[]'::jsonb;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR t IN SELECT * FROM acct_bank_transactions WHERE tenant_id = p_tenant_id AND review_status IN ('for_review','categorized')
             AND (p_ids IS NULL OR id = ANY (p_ids)) AND (p_ids IS NOT NULL OR review_stage = ANY (p_stages))
           ORDER BY transaction_date, id LOOP
    BEGIN
      IF t.review_stage = 'potential_match' AND t.suggested_journal_line_id IS NOT NULL THEN
        PERFORM acct_match_bank_transaction(t.id, t.suggested_journal_line_id);
      ELSE
        PERFORM acct_accept_bank_transaction(t.id, CASE WHEN t.category_account_id IS NULL AND t.splits IS NULL AND t.suggested_account_id IS NOT NULL
                                                        THEN jsonb_build_object('category_account_id', t.suggested_account_id) END);
      END IF;
      ok := ok + 1;
    EXCEPTION WHEN others THEN
      errs := errs || jsonb_build_object('bank_transaction_id', t.id, 'description', t.description, 'error', SQLERRM);
    END;
  END LOOP;
  RETURN jsonb_build_object('accepted', ok, 'errors', errs);
END $$;

-- @seq 164
CREATE FUNCTION public.acct_calculate_tax(p_tenant_id uuid, p_entity_id uuid, p_tax_date date, p_jurisdiction_id uuid, p_customer_id uuid, p_lines jsonb, p_direction text DEFAULT 'sale'::text) RETURNS TABLE(line_ref text, jurisdiction_id uuid, tax_code_id uuid, rule_id uuid, tax_category text, gross_amount numeric, taxable_amount numeric, exempt_amount numeric, rate numeric, tax_amount numeric, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  l jsonb; j record; v_amount numeric; v_qty numeric; v_unit numeric; v_cat text; v_code acct_tax_codes%ROWTYPE;
  v_rule acct_tax_taxability_rules%ROWTYPE; v_rate numeric; v_state uuid; v_has_nexus boolean; v_exempt_cert boolean;
  v_ref text; v_i int := 0; v_cat_default boolean; v_currency text;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT functional_currency INTO v_currency FROM acct_entities WHERE id = p_entity_id;
  IF p_jurisdiction_id IS NULL THEN
    FOR l IN SELECT value FROM jsonb_array_elements(coalesce(p_lines,'[]')) LOOP
      v_i := v_i + 1;
      line_ref := coalesce(l->>'line_ref', v_i::text); jurisdiction_id := NULL; tax_code_id := NULL; rule_id := NULL;
      tax_category := coalesce(l->>'tax_category','general'); gross_amount := coalesce((l->>'amount')::numeric,0);
      taxable_amount := 0; exempt_amount := gross_amount; rate := 0; tax_amount := 0; reason := 'No tax location on document';
      RETURN NEXT;
    END LOOP;
    RETURN;
  END IF;

  -- nexus is decided at the state (or highest) level in the chain
  SELECT c.jurisdiction_id INTO v_state FROM acct_tax_chain(p_jurisdiction_id) c ORDER BY (c.level = 'state') DESC, c.depth DESC LIMIT 1;
  SELECT EXISTS (SELECT 1 FROM acct_tax_nexus n
                  WHERE n.entity_id = p_entity_id AND n.collect_tax AND n.jurisdiction_id IN (SELECT c.jurisdiction_id FROM acct_tax_chain(p_jurisdiction_id) c)
                    AND p_tax_date >= n.effective_from AND (n.effective_to IS NULL OR p_tax_date <= n.effective_to))
    INTO v_has_nexus;

  FOR l IN SELECT value FROM jsonb_array_elements(coalesce(p_lines,'[]')) LOOP
    v_i := v_i + 1;
    v_ref := coalesce(l->>'line_ref', v_i::text);
    v_amount := coalesce((l->>'amount')::numeric, 0);
    v_qty := nullif(coalesce((l->>'quantity')::numeric, 1), 0);
    v_unit := coalesce((l->>'unit_price')::numeric, v_amount / coalesce(v_qty,1));
    v_cat := coalesce(nullif(l->>'tax_category',''), 'general');
    SELECT default_taxable INTO v_cat_default FROM acct_tax_categories
     WHERE code = v_cat AND (tenant_id = p_tenant_id OR tenant_id IS NULL) ORDER BY tenant_id NULLS LAST LIMIT 1;

    FOR j IN SELECT c.jurisdiction_id AS jid, c.depth FROM acct_tax_chain(p_jurisdiction_id) c ORDER BY c.depth DESC LOOP
      line_ref := v_ref; jurisdiction_id := j.jid; tax_category := v_cat; gross_amount := v_amount;
      tax_code_id := NULL; rule_id := NULL; rate := 0; tax_amount := 0; taxable_amount := 0; exempt_amount := v_amount;

      -- the rate in force for this jurisdiction on the tax date
      SELECT * INTO v_code FROM acct_tax_codes tc
       WHERE tc.tenant_id = p_tenant_id AND tc.jurisdiction_id = j.jid AND tc.is_active
         AND tc.tax_type::text IN ('sales','use','vat','gst')
         AND tc.effective_from <= p_tax_date AND (tc.effective_to IS NULL OR tc.effective_to >= p_tax_date)
         AND (nullif(l->>'tax_code_id','') IS NULL OR tc.id = (l->>'tax_code_id')::uuid
              OR NOT EXISTS (SELECT 1 FROM acct_tax_codes x WHERE x.id = (l->>'tax_code_id')::uuid AND x.jurisdiction_id = j.jid))
       ORDER BY tc.effective_from DESC LIMIT 1;
      IF NOT FOUND THEN CONTINUE; END IF;   -- jurisdiction levies nothing
      tax_code_id := v_code.id;

      IF NOT v_has_nexus THEN reason := 'No nexus/registration in this state'; RETURN NEXT; CONTINUE; END IF;
      IF (l ? 'taxable') AND NOT (l->>'taxable')::boolean THEN reason := 'Item marked non-taxable'; RETURN NEXT; CONTINUE; END IF;

      -- customer exemption certificate
      IF p_customer_id IS NOT NULL THEN
        SELECT EXISTS (SELECT 1 FROM acct_tax_exemptions e WHERE e.customer_id = p_customer_id
                        AND (e.jurisdiction_id IS NULL OR e.jurisdiction_id IN (SELECT c.jurisdiction_id FROM acct_tax_chain(p_jurisdiction_id) c))
                        AND p_tax_date >= e.valid_from AND (e.valid_to IS NULL OR p_tax_date <= e.valid_to))
            OR EXISTS (SELECT 1 FROM acct_customers cu WHERE (cu.id = p_customer_id OR cu.external_customer_id = p_customer_id::text) AND cu.tax_exempt)
          INTO v_exempt_cert;
        IF v_exempt_cert THEN reason := 'Customer exemption certificate'; RETURN NEXT; CONTINUE; END IF;
      END IF;

      -- most specific matching rule: own jurisdiction beats inherited, then priority
      SELECT r.* INTO v_rule FROM acct_tax_taxability_rules r JOIN acct_tax_chain(j.jid) c ON c.jurisdiction_id = r.jurisdiction_id
       WHERE r.tenant_id = p_tenant_id AND r.is_active AND r.tax_category = v_cat
         AND r.direction IN (p_direction, 'both')
         AND (c.depth = 0 OR r.applies_to_children)
         AND r.effective_from <= p_tax_date AND (r.effective_to IS NULL OR r.effective_to >= p_tax_date)
         AND (r.min_unit_price IS NULL OR v_unit >= r.min_unit_price)
         AND (r.max_unit_price IS NULL OR v_unit <  r.max_unit_price)
       ORDER BY c.depth ASC, r.priority DESC, r.effective_from DESC LIMIT 1;

      IF FOUND THEN
        rule_id := v_rule.id;
        IF v_rule.treatment = 'exempt' THEN reason := v_rule.name; RETURN NEXT; CONTINUE; END IF;
        -- a reduced rate belongs to the jurisdiction that set it; child levies keep their own rate
        v_rate := CASE WHEN v_rule.treatment = 'reduced' AND v_rule.jurisdiction_id = j.jid THEN v_rule.rate_override ELSE v_code.rate END;
        reason := v_rule.name;
      ELSIF coalesce(v_cat_default, true) = false THEN
        reason := 'Category ' || v_cat || ' is not taxable by default'; RETURN NEXT; CONTINUE;
      ELSE
        v_rate := v_code.rate; reason := 'Standard rate';
      END IF;

      rate := v_rate; taxable_amount := v_amount; exempt_amount := 0;
      tax_amount := acct_round(v_amount * v_rate, coalesce(v_currency,'USD'));
      RETURN NEXT;
    END LOOP;
  END LOOP;
END $$;

-- @seq 165
CREATE FUNCTION public.acct_calculate_tax_summary(p_tenant_id uuid, p_entity_id uuid, p_tax_date date, p_jurisdiction_id uuid, p_customer_id uuid, p_lines jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT jsonb_build_object(
    'tax_total', coalesce(sum(tax_amount),0),
    'lines', coalesce((SELECT jsonb_object_agg(line_ref, t) FROM (
        SELECT line_ref, sum(tax_amount) t FROM acct_calculate_tax(p_tenant_id, p_entity_id, p_tax_date, p_jurisdiction_id, p_customer_id, p_lines) GROUP BY line_ref) x), '{}'::jsonb),
    'detail', coalesce(jsonb_agg(to_jsonb(c)), '[]'::jsonb))
  FROM acct_calculate_tax(p_tenant_id, p_entity_id, p_tax_date, p_jurisdiction_id, p_customer_id, p_lines) c;
$$;

-- @seq 166
CREATE FUNCTION public.acct_can_access(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT current_user IN ('postgres','supabase_admin','service_role')
      OR coalesce(auth.role(),'') = 'service_role'
      OR acct_is_tenant_member(p_tenant_id);
$$;

-- @seq 167
CREATE FUNCTION public.acct_cancel_recognition_schedule(p_schedule_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s acct_recognition_schedules%ROWTYPE;
BEGIN
  SELECT * INTO s FROM acct_recognition_schedules WHERE id = p_schedule_id FOR UPDATE;
  PERFORM acct_assert_access(s.tenant_id);
  UPDATE acct_recognition_lines SET status = 'cancelled' WHERE schedule_id = s.id AND status = 'pending';
  UPDATE acct_recognition_schedules SET status = 'cancelled', memo = concat_ws(' / ', memo, 'Cancelled: ' || p_reason) WHERE id = s.id;
END $$;

-- @seq 168
CREATE FUNCTION public.acct_cash_flow(p_tenant uuid, p_from date, p_to date, p_entity uuid DEFAULT NULL::uuid) RETURNS TABLE(section text, sort_order integer, account_id uuid, code text, name text, amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE v_ni numeric; v_begin numeric; v_end numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant);
  SELECT coalesce(sum(s.cr - s.dr),0) INTO v_ni FROM acct__ledger_sums(p_tenant, p_entity, p_from, p_to, true) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id WHERE a.account_type IN ('revenue','expense');
  SELECT coalesce(sum(s.dr - s.cr),0) INTO v_begin FROM acct__ledger_sums(p_tenant, p_entity, NULL, p_from - 1, false) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id WHERE a.cash_flow_category = 'cash';
  SELECT coalesce(sum(s.dr - s.cr),0) INTO v_end FROM acct__ledger_sums(p_tenant, p_entity, NULL, p_to, false) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id WHERE a.cash_flow_category = 'cash';
  RETURN QUERY
  WITH r AS (
    SELECT CASE WHEN a.subtype = 'accumulated_depreciation' OR a.cash_flow_category = 'operating' THEN 'Operating Activities'
                WHEN a.cash_flow_category = 'investing' THEN 'Investing Activities'
                WHEN a.cash_flow_category = 'financing' THEN 'Financing Activities'
                ELSE 'Unclassified' END sec,
           a.id aid, a.code acode, a.name aname, (s.cr - s.dr) amt          -- cash effect of the balance change
      FROM acct__ledger_sums(p_tenant, p_entity, p_from, p_to, true) s
      JOIN acct_chart_of_accounts a ON a.id = s.account_id
     WHERE a.account_type IN ('asset','contra_asset','liability','equity','contra_equity')
       AND coalesce(a.cash_flow_category,'none') <> 'cash' AND s.dr <> s.cr
    UNION ALL SELECT 'Operating Activities', NULL, NULL, 'Net Income', v_ni),
  t AS (SELECT sec, sum(amt) amt FROM r GROUP BY sec)
  SELECT r.sec, CASE r.sec WHEN 'Operating Activities' THEN 10 WHEN 'Investing Activities' THEN 30 WHEN 'Financing Activities' THEN 50 ELSE 70 END,
         r.aid, r.acode, r.aname, r.amt FROM r
  UNION ALL SELECT 'Net cash from ' || lower(t.sec), CASE t.sec WHEN 'Operating Activities' THEN 20 WHEN 'Investing Activities' THEN 40 WHEN 'Financing Activities' THEN 60 ELSE 75 END,
                   NULL, NULL, 'Net cash from ' || lower(t.sec), t.amt FROM t
  UNION ALL SELECT 'Net Change in Cash', 80, NULL, NULL, 'Net change in cash', (SELECT coalesce(sum(amt),0) FROM r)
  UNION ALL SELECT 'Cash at Beginning', 85, NULL, NULL, 'Cash at beginning of period', v_begin
  UNION ALL SELECT 'Cash at End', 90, NULL, NULL, 'Cash at end of period', v_end
  UNION ALL SELECT 'Out of Balance', 99, NULL, NULL, 'Difference (must be 0)', v_end - v_begin - (SELECT coalesce(sum(amt),0) FROM r)
  ORDER BY 2, 4 NULLS LAST, 5;
END $$;

-- @seq 170
CREATE FUNCTION public.acct_classify_bank_feed(p_tenant_id uuid, p_bank_account_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t record; s jsonb; v_line uuid; n int := 0;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR t IN SELECT bt.*, ba.gl_account_id FROM acct_bank_transactions bt JOIN acct_bank_accounts ba ON ba.id = bt.bank_account_id
            WHERE bt.tenant_id = p_tenant_id AND bt.review_status IN ('for_review','categorized')
              AND (p_bank_account_id IS NULL OR bt.bank_account_id = p_bank_account_id) LOOP
    SELECT l.id INTO v_line FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id
     WHERE l.tenant_id = p_tenant_id AND l.account_id = t.gl_account_id AND je.status = 'posted'
       AND coalesce(l.cleared_status,'uncleared') = 'uncleared'
       AND (l.debit - l.credit) = t.amount
       AND je.entry_date BETWEEN t.transaction_date - 5 AND t.transaction_date + 5
       AND NOT EXISTS (SELECT 1 FROM acct_bank_transactions o WHERE o.matched_journal_line_id = l.id)
     ORDER BY abs(je.entry_date - t.transaction_date), l.created_at LIMIT 1;
    IF v_line IS NOT NULL THEN
      UPDATE acct_bank_transactions SET review_stage = 'potential_match', suggested_journal_line_id = v_line,
             suggestion_source = 'match', suggestion_confidence = 'high' WHERE id = t.id;
    ELSIF t.suggested_rule_id IS NOT NULL AND t.review_status = 'categorized' THEN
      UPDATE acct_bank_transactions SET review_stage = 'rule', suggestion_source = 'rule' WHERE id = t.id;
    ELSE
      s := acct_suggest_coding(t.id);
      UPDATE acct_bank_transactions SET
        suggested_account_id = (s->>'account_id')::uuid, suggested_vendor_id = (s->>'vendor_id')::uuid,
        suggestion_confidence = s->>'confidence', suggestion_source = s->>'source', suggestion_detail = s,
        review_stage = CASE WHEN s->>'confidence' = 'high' AND s->>'account_id' IS NOT NULL THEN 'auto_classification' ELSE 'needs_review' END,
        payee_vendor_id = coalesce(payee_vendor_id, CASE WHEN s->>'confidence' IN ('high','medium') THEN (s->>'vendor_id')::uuid END),
        payee_customer_id = coalesce(payee_customer_id, CASE WHEN s->>'confidence' IN ('high','medium') THEN (s->>'customer_id')::uuid END),
        -- only a high-confidence suggestion pre-fills the category; it still waits for the user to accept
        category_account_id = coalesce(category_account_id, CASE WHEN s->>'confidence' = 'high' THEN (s->>'account_id')::uuid END)
       WHERE id = t.id;
    END IF;
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;

-- @seq 171
CREATE FUNCTION public.acct_close_dispute(p_dispute_id uuid, p_won boolean, p_date date DEFAULT CURRENT_DATE, p_fee_returned numeric DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d acct_disputes%ROWTYPE; v_je uuid; v_lines jsonb; v_stripe uuid;
BEGIN
  SELECT * INTO d FROM acct_disputes WHERE id = p_dispute_id FOR UPDATE;
  PERFORM acct_assert_access(d.tenant_id);
  IF d.closed_journal_id IS NOT NULL THEN RETURN d.closed_journal_id; END IF;
  IF d.opened_journal_id IS NULL THEN PERFORM acct_open_dispute(d.id, p_date); SELECT * INTO d FROM acct_disputes WHERE id = p_dispute_id; END IF;
  v_stripe := acct_bank_gl(acct_system_register(d.tenant_id, d.entity_id, 'stripe'));
  IF p_won THEN
    v_lines := jsonb_build_array(
      jsonb_build_object('account_id', v_stripe, 'debit', d.amount + coalesce(p_fee_returned,0), 'description', 'Dispute won ' || d.dispute_number),
      jsonb_build_object('account_id', acct_role_account(d.tenant_id, d.entity_id, 'dispute_holding'), 'credit', d.amount, 'customer_id', d.customer_id::text));
    IF coalesce(p_fee_returned,0) > 0 THEN
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(d.tenant_id, d.entity_id, 'processor_fees'), 'credit', p_fee_returned, 'description', 'Dispute fee returned'));
    END IF;
  ELSE
    v_lines := jsonb_build_array(
      jsonb_build_object('account_id', acct_role_account(d.tenant_id, d.entity_id, 'chargeback_loss'), 'debit', d.amount, 'customer_id', d.customer_id::text, 'description', 'Dispute lost ' || d.dispute_number),
      jsonb_build_object('account_id', acct_role_account(d.tenant_id, d.entity_id, 'dispute_holding'), 'credit', d.amount, 'customer_id', d.customer_id::text));
  END IF;
  v_je := acct_post_entry(d.tenant_id, d.entity_id, p_date, v_lines, 'integration', d.id::text, d.dispute_number, CASE WHEN p_won THEN 'Dispute won' ELSE 'Dispute lost' END,
                          'dispute-close:' || d.id, NULL, NULL, d.currency, false, false, 'acct_disputes', d.id);
  UPDATE acct_disputes SET closed_journal_id = v_je, closed_on = p_date, status = CASE WHEN p_won THEN 'won' ELSE 'lost' END WHERE id = d.id;
  RETURN v_je;
END $$;

-- @seq 172
CREATE FUNCTION public.acct_close_fiscal_year(p_fiscal_year_id uuid, p_book_id uuid DEFAULT NULL::uuid, p_lock boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE fy acct_fiscal_years%ROWTYPE; v_book uuid; v_re uuid; v_lines jsonb; v_net numeric; v_je uuid; pr record;
BEGIN
  SELECT * INTO fy FROM acct_fiscal_years WHERE id = p_fiscal_year_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Fiscal year not found'; END IF;
  PERFORM acct_assert_access(fy.tenant_id);
  v_book := coalesce(p_book_id, acct_primary_book(fy.tenant_id, fy.entity_id));
  IF EXISTS (SELECT 1 FROM acct_journal_entries e JOIN acct_periods p ON p.id = e.period_id
              WHERE p.fiscal_year_id = fy.id AND e.book_id = v_book AND e.is_closing AND e.status = 'posted') THEN
    RAISE EXCEPTION 'Fiscal year % is already closed', fy.fiscal_year;
  END IF;
  v_re := acct_role_account(fy.tenant_id, fy.entity_id, 'retained_earnings');
  -- zero every P&L account into retained earnings
  SELECT jsonb_agg(jsonb_build_object('account_id', account_id,
           'debit', CASE WHEN bal < 0 THEN -bal ELSE 0 END, 'credit', CASE WHEN bal > 0 THEN bal ELSE 0 END,
           'description', 'Year-end close FY' || fy.fiscal_year)), coalesce(sum(-bal),0)
    INTO v_lines, v_net
    FROM (SELECT l.account_id, sum(l.debit - l.credit) AS bal
            FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
            JOIN acct_chart_of_accounts c ON c.id = l.account_id
           WHERE e.book_id = v_book AND e.status IN ('posted','reversed')
             AND e.posting_date BETWEEN fy.start_date AND fy.end_date AND c.account_type IN ('revenue','expense')
           GROUP BY l.account_id HAVING sum(l.debit - l.credit) <> 0) s;
  IF v_lines IS NULL THEN RAISE NOTICE 'No P&L activity in FY%', fy.fiscal_year; RETURN NULL; END IF;
  -- v_net = credits - debits = net income; credit RE for profit
  v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', v_re,
               'debit', CASE WHEN v_net < 0 THEN -v_net ELSE 0 END, 'credit', CASE WHEN v_net > 0 THEN v_net ELSE 0 END,
               'description', 'Net income FY' || fy.fiscal_year || ' to retained earnings'));
  v_je := acct_post_entry(fy.tenant_id, fy.entity_id, fy.end_date, v_lines, 'system', fy.id::text, 'CLOSE-FY' || fy.fiscal_year,
                          'Year-end closing entry FY' || fy.fiscal_year, 'yearclose:' || v_book || ':' || fy.id, v_book,
                          NULL, NULL, false, true);
  FOR pr IN SELECT id FROM acct_periods WHERE fiscal_year_id = fy.id AND book_id = v_book AND status IN ('open','soft_closed') ORDER BY start_date LOOP
    PERFORM acct_set_period_status(pr.id, 'closed');
  END LOOP;
  IF p_lock THEN UPDATE acct_periods SET status = 'locked' WHERE fiscal_year_id = fy.id AND book_id = v_book; END IF;
  RETURN v_je;
END $$;

-- @seq 173
CREATE FUNCTION public.acct_close_status(p_close_id uuid, p_run_checks boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c acct_closes%ROWTYPE; t record; v_tasks jsonb := '[]'::jsonb; r jsonb;
BEGIN
  SELECT * INTO c FROM acct_closes WHERE id = p_close_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Close not found'; END IF;
  PERFORM acct_assert_access(c.tenant_id);
  FOR t IN SELECT * FROM acct_close_tasks WHERE close_id = c.id ORDER BY sort_order, created_at LOOP
    r := CASE WHEN p_run_checks AND t.check_code IS NOT NULL AND t.status NOT IN ('done','skipped')
              THEN acct__close_check(c.tenant_id, t.check_code, c.period_start, c.period_end) ELSE t.check_result END;
    IF p_run_checks AND r IS DISTINCT FROM t.check_result THEN UPDATE acct_close_tasks SET check_result = r WHERE id = t.id; END IF;
    v_tasks := v_tasks || jsonb_build_object('id', t.id, 'section', t.section, 'title', t.title, 'status', t.status, 'due', t.due_date,
      'overdue', t.status NOT IN ('done','skipped') AND t.due_date < current_date, 'priority', t.priority, 'assignee', t.assignee_id,
      'reviewer', t.reviewer_id, 'check', r, 'parent', t.parent_task_id, 'tags', to_jsonb(t.tags));
  END LOOP;
  RETURN jsonb_build_object('close_id', c.id, 'period_start', c.period_start, 'period_end', c.period_end, 'status', c.status,
    'tasks_total', jsonb_array_length(v_tasks),
    'tasks_done', (SELECT count(*) FROM acct_close_tasks WHERE close_id = c.id AND status IN ('done','skipped')),
    'tasks_overdue', (SELECT count(*) FROM acct_close_tasks WHERE close_id = c.id AND status NOT IN ('done','skipped') AND due_date < current_date),
    'open_error_findings', (SELECT count(*) FROM acct_review_findings WHERE tenant_id = c.tenant_id AND status IN ('open','in_progress') AND severity = 'error'
                               AND (txn_date IS NULL OR txn_date <= c.period_end)),
    'period_status', (SELECT status FROM acct_periods WHERE id = c.period_id), 'tasks', v_tasks);
END $$;

-- @seq 174
CREATE FUNCTION public.acct_coa_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p acct_chart_of_accounts%ROWTYPE; v_has_activity boolean; v_bal numeric;
BEGIN
  -- default normal balance from type
  IF NEW.normal_balance IS NULL OR NEW.normal_balance = '' THEN
    NEW.normal_balance := CASE WHEN NEW.account_type IN ('asset','expense','contra_liability','contra_equity') THEN 'debit' ELSE 'credit' END;
  END IF;
  NEW.metadata := coalesce(NEW.metadata, '{}'::jsonb);
  -- default cash-flow classification from subtype
  IF NEW.cash_flow_category IS NULL THEN
    NEW.cash_flow_category := CASE
      WHEN NEW.subtype IN ('bank','cash','checking','savings','cash_on_hand','money_market') THEN 'cash'
      WHEN NEW.subtype IN ('fixed_asset','accumulated_depreciation','other_asset','intangible') THEN 'investing'
      WHEN NEW.subtype IN ('long_term_liability','loan','line_of_credit','notes_payable') OR NEW.account_type IN ('equity','contra_equity') THEN 'financing'
      WHEN NEW.account_type IN ('revenue','expense','statistical') THEN 'none'
      ELSE 'operating' END;
  END IF;
  -- parent must be same tenant + entity and same class
  IF NEW.parent_account_id IS NOT NULL THEN
    IF NEW.parent_account_id = NEW.id THEN RAISE EXCEPTION 'An account cannot be its own parent'; END IF;
    SELECT * INTO p FROM acct_chart_of_accounts WHERE id = NEW.parent_account_id;
    IF NOT FOUND OR p.tenant_id <> NEW.tenant_id OR p.entity_id <> NEW.entity_id THEN
      RAISE EXCEPTION 'Parent account must belong to the same company';
    END IF;
    IF (p.account_type IN ('revenue','expense')) <> (NEW.account_type IN ('revenue','expense')) THEN
      RAISE EXCEPTION 'Sub-account % must be the same class (P&L vs balance sheet) as its parent %', NEW.code, p.code;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    SELECT EXISTS (SELECT 1 FROM acct_journal_lines WHERE account_id = OLD.id) INTO v_has_activity;
    IF v_has_activity AND (OLD.account_type IN ('revenue','expense')) <> (NEW.account_type IN ('revenue','expense')) THEN
      RAISE EXCEPTION 'Account % has posted activity; it cannot move between balance sheet and P&L. Create a new account and reclassify with a journal entry.', OLD.code;
    END IF;
    IF v_has_activity AND NEW.entity_id <> OLD.entity_id THEN RAISE EXCEPTION 'Account % has activity; it cannot change company', OLD.code; END IF;
    IF OLD.is_active AND NOT NEW.is_active THEN
      SELECT coalesce(sum(l.debit - l.credit),0) INTO v_bal
        FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
       WHERE l.account_id = OLD.id AND e.status IN ('posted','reversed');
      IF v_bal <> 0 THEN RAISE EXCEPTION 'Account % has a balance of %; move the balance before making it inactive', OLD.code, v_bal; END IF;
      IF EXISTS (SELECT 1 FROM acct_chart_of_accounts c WHERE c.parent_account_id = OLD.id AND c.is_active) THEN
        RAISE EXCEPTION 'Account % has active sub-accounts', OLD.code; END IF;
    END IF;
    IF OLD.is_system AND (NEW.account_type <> OLD.account_type OR NOT NEW.is_active) THEN
      RAISE EXCEPTION 'System account % cannot change type or be deactivated', OLD.code;
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- @seq 175
CREATE FUNCTION public.acct_complete_close_task(p_task_id uuid, p_note text DEFAULT NULL::text, p_override_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_close_tasks%ROWTYPE; c acct_closes%ROWTYPE; r jsonb;
BEGIN
  SELECT * INTO t FROM acct_close_tasks WHERE id = p_task_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;
  PERFORM acct_assert_access(t.tenant_id);
  SELECT * INTO c FROM acct_closes WHERE id = t.close_id;
  IF c.status = 'closed' THEN RAISE EXCEPTION 'This close is finalized'; END IF;
  IF EXISTS (SELECT 1 FROM acct_close_tasks s WHERE s.parent_task_id = t.id AND s.status NOT IN ('done','skipped')) THEN
    RAISE EXCEPTION 'Finish the subtasks first'; END IF;
  IF t.check_code IS NOT NULL AND c.id IS NOT NULL THEN
    r := acct__close_check(t.tenant_id, t.check_code, c.period_start, c.period_end);
    IF NOT (r->>'passed')::boolean AND p_override_note IS NULL THEN
      UPDATE acct_close_tasks SET check_result = r, updated_at = now() WHERE id = t.id;
      RAISE EXCEPTION 'Check "%" has not passed: %', t.check_code, r->>'detail';
    END IF;
  END IF;
  UPDATE acct_close_tasks SET status = CASE WHEN requires_signoff THEN 'ready_for_review' ELSE 'done' END,
         completed_by = auth.uid(), completed_at = now(), check_result = coalesce(r, check_result), updated_at = now() WHERE id = t.id;
  IF coalesce(p_note, p_override_note) IS NOT NULL THEN
    INSERT INTO acct_close_task_comments(tenant_id, task_id, author_id, body)
    VALUES (t.tenant_id, t.id, auth.uid(), concat_ws(E'\n', p_note, CASE WHEN p_override_note IS NOT NULL THEN 'Completed with failing check: ' || p_override_note END));
  END IF;
  RETURN jsonb_build_object('task_id', t.id, 'status', (SELECT status FROM acct_close_tasks WHERE id = t.id), 'check', r);
END $$;

-- @seq 176
CREATE FUNCTION public.acct_complete_contractor_profile(p_token text, p_profile jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE i acct_contractor_invites%ROWTYPE;
BEGIN
  SELECT * INTO i FROM acct_contractor_invites WHERE token_hash = encode(sha256(convert_to(p_token,'UTF8')),'hex') FOR UPDATE;
  IF NOT FOUND OR i.status NOT IN ('sent','opened') OR i.expires_at < now() THEN RAISE EXCEPTION 'Invite link is invalid or expired'; END IF;
  UPDATE acct_vendors SET
    legal_name = coalesce(p_profile->>'legal_name', legal_name), company_name = coalesce(p_profile->>'business_name', company_name),
    tin_type = coalesce(p_profile->>'tin_type', tin_type), tin_last4 = coalesce(p_profile->>'tin_last4', tin_last4),
    tin_vault_id = coalesce(nullif(p_profile->>'tin_vault_id','')::uuid, tin_vault_id),
    ach_routing_number = coalesce(p_profile->>'routing_number', ach_routing_number),
    ach_account_last4 = coalesce(p_profile->>'account_last4', ach_account_last4),
    ach_account_vault_id = coalesce(nullif(p_profile->>'account_vault_id','')::uuid, ach_account_vault_id),
    ach_account_type = coalesce(p_profile->>'account_type', ach_account_type),
    w9_received_at = now(), backup_withholding = coalesce((p_profile->>'backup_withholding')::boolean, backup_withholding)
  WHERE id = i.vendor_id;
  IF p_profile ? 'address' THEN
    INSERT INTO acct_party_addresses(tenant_id, party_type, party_id, address_type, line1, line2, city, state, postal_code)
    VALUES (i.tenant_id, 'vendor', i.vendor_id, 'mailing', p_profile#>>'{address,line1}', p_profile#>>'{address,line2}',
            p_profile#>>'{address,city}', p_profile#>>'{address,state}', p_profile#>>'{address,postal_code}')
    ON CONFLICT (party_type, party_id, address_type) WHERE is_default DO UPDATE SET line1 = EXCLUDED.line1, line2 = EXCLUDED.line2,
       city = EXCLUDED.city, state = EXCLUDED.state, postal_code = EXCLUDED.postal_code, updated_at = now();
  END IF;
  INSERT INTO acct_payroll_tax_forms(tenant_id, vendor_id, form_type, tax_year, status, box_values, filed_at)
  VALUES (i.tenant_id, i.vendor_id, 'W-9', extract(year FROM now())::int, 'accepted', p_profile - 'tin_vault_id' - 'account_vault_id', now());
  UPDATE acct_contractor_invites SET status = 'completed', completed_at = now() WHERE id = i.id;
  RETURN i.vendor_id;
END $$;

-- @seq 177
CREATE FUNCTION public.acct_convert_estimate(p_estimate_id uuid, p_invoice_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE e acct_estimates%ROWTYPE; v_inv uuid; l record; j jsonb; n int := 0;
BEGIN
  SELECT * INTO e FROM acct_estimates WHERE id = p_estimate_id FOR UPDATE;
  PERFORM acct_assert_access(e.tenant_id);
  IF e.converted_invoice_id IS NOT NULL THEN RETURN e.converted_invoice_id; END IF;
  IF e.status IN ('declined','expired','void','closed') THEN RAISE EXCEPTION 'Estimate is %', e.status; END IF;
  IF e.expiry_date IS NOT NULL AND e.expiry_date < p_invoice_date AND e.status <> 'accepted' THEN RAISE EXCEPTION 'Estimate expired on %', e.expiry_date; END IF;
  INSERT INTO acct_ar_invoices(tenant_id, entity_id, customer_id, invoice_number, invoice_date, due_date, currency, status, estimate_id, discount_total, notes, terms)
  VALUES (e.tenant_id, coalesce(e.entity_id, acct_default_entity(e.tenant_id)), e.customer_id, NULL, p_invoice_date, NULL, e.currency, 'draft', e.id, e.discount_total, e.notes, e.terms)
  RETURNING id INTO v_inv;
  FOR l IN SELECT * FROM acct_estimate_lines WHERE estimate_id = e.id ORDER BY line_number LOOP
    INSERT INTO acct_ar_invoice_lines(invoice_id, line_no, description, quantity, unit_price, discount_amount, revenue_account_id, dimensions, tenant_id)
    VALUES (v_inv, NULL, l.description, l.quantity, l.unit_price, l.discount_amount, NULL, '{}'::jsonb, e.tenant_id);
    n := n + 1;
  END LOOP;
  IF n = 0 THEN
    FOR j IN SELECT value FROM jsonb_array_elements(e.lines) LOOP
      INSERT INTO acct_ar_invoice_lines(invoice_id, line_no, description, quantity, unit_price, item_id, revenue_account_id, dimensions, tenant_id)
      VALUES (v_inv, NULL, coalesce(j->>'description',''), coalesce((j->>'quantity')::numeric,1), coalesce((j->>'unit_price')::numeric, (j->>'rate')::numeric, 0),
              nullif(j->>'item_id','')::uuid, nullif(j->>'revenue_account_id','')::uuid, '{}'::jsonb, e.tenant_id);
    END LOOP;
  END IF;
  UPDATE acct_estimates SET converted_invoice_id = v_inv, status = 'converted', updated_at = now() WHERE id = e.id;
  PERFORM acct_invoice_recalc(v_inv);
  RETURN v_inv;
END $$;

-- @seq 178
CREATE FUNCTION public.acct_create_credit_memo(p_tenant_id uuid, p_customer_id uuid, p_date date, p_subtotal numeric, p_tax numeric DEFAULT 0, p_reason text DEFAULT NULL::text, p_invoice_id uuid DEFAULT NULL::uuid, p_rma_id uuid DEFAULT NULL::uuid, p_revenue_account_id uuid DEFAULT NULL::uuid, p_post boolean DEFAULT true, p_entity_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid; v_entity uuid; iv acct_ar_invoices%ROWTYPE;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF coalesce(p_subtotal,0) < 0 OR coalesce(p_tax,0) < 0 OR coalesce(p_subtotal,0) + coalesce(p_tax,0) <= 0 THEN
    RAISE EXCEPTION 'Credit memo amount must be positive';
  END IF;
  IF p_invoice_id IS NOT NULL THEN
    SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id AND tenant_id = p_tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
    IF iv.customer_id <> p_customer_id THEN RAISE EXCEPTION 'Invoice belongs to a different customer'; END IF;
    IF coalesce(p_tax,0) > iv.tax_total THEN RAISE EXCEPTION 'Credited tax (%) exceeds the tax charged on % (%)', p_tax, iv.invoice_number, iv.tax_total; END IF;
  ELSIF coalesce(p_tax,0) > 0 THEN
    RAISE EXCEPTION 'Link the original invoice to credit sales tax (the tax must reverse in the jurisdictions it was charged)';
  END IF;
  v_entity := coalesce(p_entity_id, iv.entity_id, acct_default_entity(p_tenant_id));
  INSERT INTO acct_ar_credit_memos(tenant_id, entity_id, customer_id, memo_number, memo_date, currency, subtotal, tax_total, total, status,
                                   applied_amount, reason, invoice_id, rma_id, revenue_account_id)
  VALUES (p_tenant_id, v_entity, p_customer_id, acct_next_number(p_tenant_id, v_entity, 'credit_memo', 'CM-'), p_date,
          coalesce(iv.currency, (SELECT functional_currency FROM acct_entities WHERE id = v_entity), 'USD'),
          round(p_subtotal,2), round(coalesce(p_tax,0),2), round(p_subtotal,2) + round(coalesce(p_tax,0),2), 'draft', 0, p_reason, p_invoice_id, p_rma_id,
          p_revenue_account_id)
  RETURNING id INTO v;
  IF p_post THEN PERFORM acct_post_credit_memo(v); END IF;
  RETURN v;
END $$;

-- @seq 179
CREATE FUNCTION public.acct_create_payment_link(p_tenant_id uuid, p_title text, p_amount numeric DEFAULT NULL::numeric, p_description text DEFAULT NULL::text, p_invoice_id uuid DEFAULT NULL::uuid, p_item_id uuid DEFAULT NULL::uuid, p_min numeric DEFAULT NULL::numeric, p_max numeric DEFAULT NULL::numeric, p_collect_tax boolean DEFAULT false, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_max_uses integer DEFAULT NULL::integer, p_provider text DEFAULT 'stripe'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid; iv acct_ar_invoices%ROWTYPE;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_invoice_id IS NOT NULL THEN
    SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id AND tenant_id = p_tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  END IF;
  IF p_amount IS NULL AND p_invoice_id IS NULL AND (p_min IS NULL OR p_max IS NULL) THEN
    RAISE EXCEPTION 'Set a fixed amount, an invoice, or a minimum and maximum';
  END IF;
  INSERT INTO acct_payment_links(tenant_id, entity_id, kind, title, description, amount, min_amount, max_amount, currency, item_id, invoice_id,
                                 collect_tax, provider, expires_at, max_uses, public_token, status, created_by)
  VALUES (p_tenant_id, coalesce(iv.entity_id, acct_default_entity(p_tenant_id)),
          CASE WHEN p_invoice_id IS NOT NULL THEN 'invoice' WHEN p_amount IS NULL THEN 'custom_amount' ELSE 'fixed' END,
          p_title, p_description, coalesce(p_amount, iv.open_balance), p_min, p_max, coalesce(iv.currency, 'USD'), p_item_id, p_invoice_id,
          p_collect_tax, p_provider, p_expires_at, p_max_uses, replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-',''),
          'active', auth.uid())
  RETURNING id INTO v;
  IF p_invoice_id IS NOT NULL THEN UPDATE acct_ar_invoices SET payment_link_id = v WHERE id = p_invoice_id; END IF;
  RETURN v;   -- the app creates the provider checkout (provider_url / provider_link_id) and renders the share link and QR from public_token
END $$;

-- @seq 180
CREATE FUNCTION public.acct_create_recognition_schedule(p_tenant_id uuid, p_kind text, p_name text, p_amount numeric, p_start date, p_months integer, p_pl_account_id uuid, p_balance_account_id uuid DEFAULT NULL::uuid, p_method text DEFAULT 'straight_line'::text, p_initial_offset_account_id uuid DEFAULT NULL::uuid, p_vendor_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_source_doc_type text DEFAULT NULL::text, p_source_doc_id uuid DEFAULT NULL::uuid, p_auto_reverse boolean DEFAULT true, p_recognized_through date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid; v_bal uuid; v_id uuid; i int; v_month_start date; v_month_end date; v_end date; v_days int; v_amt numeric; v_alloc numeric := 0;
        v_je uuid; v_pl_type text;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  v_entity := acct_default_entity(p_tenant_id);
  SELECT account_type INTO v_pl_type FROM acct_chart_of_accounts WHERE id = p_pl_account_id AND tenant_id = p_tenant_id;
  IF p_kind IN ('prepaid_expense','accrued_expense') AND v_pl_type NOT IN ('expense') THEN RAISE EXCEPTION 'Choose an expense account'; END IF;
  IF p_kind IN ('deferred_revenue','accrued_revenue') AND v_pl_type NOT IN ('revenue') THEN RAISE EXCEPTION 'Choose an income account'; END IF;
  v_bal := coalesce(p_balance_account_id, CASE p_kind
             WHEN 'prepaid_expense' THEN acct__role(p_tenant_id, v_entity, 'prepaid_expenses')
             WHEN 'deferred_revenue' THEN acct__role(p_tenant_id, v_entity, 'deferred_revenue')
             WHEN 'accrued_expense' THEN acct__role(p_tenant_id, v_entity, 'accrued_liabilities')
             ELSE NULL END);
  IF v_bal IS NULL THEN RAISE EXCEPTION 'Choose the balance sheet account for this schedule'; END IF;
  INSERT INTO acct_recognition_schedules(tenant_id, entity_id, kind, name, total_amount, start_date, months, method, balance_account_id, pl_account_id,
                                         vendor_id, customer_id, source_doc_type, source_doc_id, auto_reverse)
  VALUES (p_tenant_id, v_entity, p_kind, p_name, p_amount, p_start, CASE WHEN p_kind LIKE 'accrued%' THEN 1 ELSE p_months END, p_method, v_bal, p_pl_account_id,
          p_vendor_id, p_customer_id, p_source_doc_type, p_source_doc_id, p_auto_reverse)
  RETURNING id INTO v_id;
  IF p_kind IN ('accrued_expense','accrued_revenue') THEN
    INSERT INTO acct_recognition_lines(tenant_id, schedule_id, line_no, recognize_on, amount) VALUES (p_tenant_id, v_id, 1, p_start, p_amount);
    IF p_auto_reverse THEN
      INSERT INTO acct_recognition_lines(tenant_id, schedule_id, line_no, recognize_on, amount)
      VALUES (p_tenant_id, v_id, 2, (date_trunc('month', p_start) + interval '1 month')::date, -p_amount);
    END IF;
  ELSE
    v_end := (date_trunc('month', p_start) + make_interval(months => p_months) - interval '1 day')::date;
    v_days := v_end - p_start + 1;
    FOR i IN 1..p_months LOOP
      v_month_start := greatest(p_start, (date_trunc('month', p_start) + make_interval(months => i - 1))::date);
      v_month_end := (date_trunc('month', p_start) + make_interval(months => i) - interval '1 day')::date;
      v_amt := CASE WHEN i = p_months THEN p_amount - v_alloc
                    WHEN p_method = 'daily' THEN round(p_amount * (v_month_end - v_month_start + 1) / v_days, 2)
                    ELSE round(p_amount / p_months, 2) END;
      v_alloc := v_alloc + v_amt;
      INSERT INTO acct_recognition_lines(tenant_id, schedule_id, line_no, recognize_on, amount, status)
      VALUES (p_tenant_id, v_id, i, v_month_end, v_amt, CASE WHEN v_month_end <= p_recognized_through THEN 'imported' ELSE 'pending' END);
    END LOOP;
    IF p_initial_offset_account_id IS NOT NULL THEN
      v_je := acct_post_entry(p_tenant_id, v_entity, p_start, jsonb_build_array(
                jsonb_build_object('account_id', CASE WHEN p_kind = 'prepaid_expense' THEN v_bal ELSE p_initial_offset_account_id END, 'debit', p_amount,
                                   'description', p_name, 'vendor_id', p_vendor_id, 'customer_id', p_customer_id),
                jsonb_build_object('account_id', CASE WHEN p_kind = 'prepaid_expense' THEN p_initial_offset_account_id ELSE v_bal END, 'credit', p_amount,
                                   'description', p_name, 'vendor_id', p_vendor_id, 'customer_id', p_customer_id)),
              'revenue_recognition', v_id::text, NULL, p_name, 'recog-init:' || v_id, NULL, NULL, NULL, false, false, 'acct_recognition_schedules', v_id);
      UPDATE acct_recognition_schedules SET initial_journal_id = v_je WHERE id = v_id;
    END IF;
  END IF;
  RETURN v_id;
END $$;

-- @seq 181
CREATE FUNCTION public.acct_create_statement_batch(p_tenant_id uuid, p_period_start date, p_period_end date, p_customer_filter text DEFAULT 'open_balance'::text, p_customer_ids uuid[] DEFAULT NULL::uuid[], p_statement_type text DEFAULT 'balance_forward'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_customer_filter = 'selected' AND coalesce(array_length(p_customer_ids,1),0) = 0 THEN RAISE EXCEPTION 'Select at least one customer'; END IF;
  INSERT INTO acct_statement_batches(tenant_id, statement_type, period_start, period_end, customer_filter, customer_ids)
  VALUES (p_tenant_id, p_statement_type, p_period_start, p_period_end, p_customer_filter, p_customer_ids) RETURNING id INTO v;
  RETURN v;
END $$;

-- @seq 182
CREATE FUNCTION public.acct_customer_name(p_customer_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(nullif(company_name,''), nullif(concat_ws(' ', coalesce(preferred_name, first_name), last_name),''), email, 'Customer')
    FROM crm_customers WHERE id = p_customer_id;
$$;

-- @seq 183
CREATE FUNCTION public.acct_customer_statement(p_tenant uuid, p_customer uuid, p_from date, p_to date DEFAULT CURRENT_DATE) RETURNS TABLE(line_date date, doc_type text, doc_number text, description text, charges numeric, payments numeric, balance numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE v_open numeric; v_ar uuid[];
BEGIN
  PERFORM acct_assert_access(p_tenant);
  SELECT array_agg(DISTINCT r.account_id) INTO v_ar FROM acct_account_roles r WHERE r.tenant_id = p_tenant AND r.role = 'accounts_receivable';
  SELECT coalesce(sum(l.debit - l.credit),0) INTO v_open
    FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
   WHERE e.tenant_id = p_tenant AND e.status IN ('posted','reversed') AND l.account_id = ANY (v_ar)
     AND l.customer_id = p_customer::text AND e.posting_date < p_from;
  RETURN QUERY
  SELECT y.pd, y.src, y.ref, y.dsc, y.dr, y.cr, y.bal FROM (
  SELECT p_from - 1 pd, 'opening'::text src, NULL::text ref, 'Balance forward'::text dsc, NULL::numeric dr, NULL::numeric cr, v_open bal, 0::bigint eno, 0 lno
  UNION ALL
  SELECT x.pd, x.src, x.ref, x.dsc, x.dr, x.cr, v_open + sum(x.dr - x.cr) OVER (ORDER BY x.pd, x.eno, x.lno ROWS UNBOUNDED PRECEDING), x.eno, x.lno
    FROM (SELECT e.posting_date pd, CASE e.source WHEN 'invoice' THEN 'Invoice' WHEN 'customer_receipt' THEN 'Payment'
                   WHEN 'credit_memo' THEN 'Credit' ELSE initcap(replace(e.source,'_',' ')) END src,
                 e.reference ref, coalesce(nullif(l.description,''), e.memo) dsc, l.debit dr, l.credit cr, e.entry_no eno, l.line_no lno
            FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
           WHERE e.tenant_id = p_tenant AND e.status IN ('posted','reversed') AND l.account_id = ANY (v_ar)
             AND l.customer_id = p_customer::text AND e.posting_date BETWEEN p_from AND p_to) x) y
  ORDER BY y.pd, y.eno, y.lno;
END $$;

-- @seq 185
CREATE FUNCTION public.acct_decide_bill(p_bill_id uuid, p_approve boolean, p_comments text DEFAULT NULL::text, p_stage text DEFAULT 'bill'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_ap_bills%ROWTYPE; a acct_ap_approvals%ROWTYPE; v_left int; v_me uuid := auth.uid();
BEGIN
  SELECT * INTO b FROM acct_ap_bills WHERE id = p_bill_id FOR UPDATE;
  PERFORM acct_assert_access(b.tenant_id);
  SELECT * INTO a FROM acct_ap_approvals WHERE bill_id = b.id AND stage = p_stage AND status = 'pending' ORDER BY sequence_no LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Nothing waiting for approval'; END IF;
  IF v_me IS NOT NULL AND v_me = b.created_by THEN RAISE EXCEPTION 'Segregation of duties: the person who entered a bill cannot approve it'; END IF;
  IF v_me IS NOT NULL AND a.approver_id IS NOT NULL AND a.approver_id <> v_me THEN RAISE EXCEPTION 'This step is assigned to a different approver'; END IF;
  UPDATE acct_ap_approvals SET status = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END::acct_workflow_status,
         acted_at = now(), comments = p_comments, approver_id = coalesce(approver_id, v_me) WHERE id = a.id;
  IF NOT p_approve THEN
    IF p_stage = 'bill' THEN UPDATE acct_ap_bills SET approval_status = 'rejected', status = 'draft' WHERE id = b.id;
    ELSE UPDATE acct_ap_bills SET payment_approval_status = 'rejected' WHERE id = b.id; END IF;
    RETURN 'rejected';
  END IF;
  SELECT count(*) INTO v_left FROM acct_ap_approvals WHERE bill_id = b.id AND stage = p_stage AND status = 'pending';
  IF v_left = 0 THEN
    IF p_stage = 'bill' THEN UPDATE acct_ap_bills SET approval_status = 'approved', status = 'approved' WHERE id = b.id;
    ELSE UPDATE acct_ap_bills SET payment_approval_status = 'approved' WHERE id = b.id; END IF;
    RETURN 'approved';
  END IF;
  RETURN 'pending';
END $$;

-- @seq 186
CREATE FUNCTION public.acct_default_entity(p_tenant_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT id FROM acct_entities WHERE tenant_id = p_tenant_id AND is_active
  ORDER BY (parent_entity_id IS NULL) DESC, created_at LIMIT 1;
$$;

-- @seq 187
CREATE FUNCTION public.acct_dispose_fixed_asset(p_asset_id uuid, p_date date, p_proceeds numeric DEFAULT 0, p_deposit_bank_account_id uuid DEFAULT NULL::uuid, p_memo text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE a acct_fixed_assets%ROWTYPE; c acct_asset_classes%ROWTYPE; v_gain numeric; v_lines jsonb; v_je uuid;
BEGIN
  SELECT * INTO a FROM acct_fixed_assets WHERE id = p_asset_id FOR UPDATE;
  PERFORM acct_assert_access(a.tenant_id);
  IF a.status IN ('disposed','retired') THEN RAISE EXCEPTION 'Asset already %', a.status; END IF;
  IF p_proceeds > 0 AND p_deposit_bank_account_id IS NULL THEN RAISE EXCEPTION 'Choose the account the sale money went to'; END IF;
  v_je := coalesce(a.asset_class_id, acct__default_asset_class(a.tenant_id, a.entity_id));
  SELECT * INTO c FROM acct_asset_classes WHERE id = v_je;
  v_je := NULL;
  v_gain := p_proceeds - (a.original_cost - a.accumulated_depreciation);
  v_lines := jsonb_build_array(
    jsonb_build_object('account_id', coalesce(a.cost_account_id, c.asset_account_id), 'credit', a.original_cost, 'description', 'Dispose ' || a.name),
    jsonb_build_object('account_id', c.accumulated_depreciation_account_id, 'debit', a.accumulated_depreciation, 'description', 'Dispose ' || a.name),
    jsonb_build_object('account_id', acct__role(a.tenant_id, a.entity_id, 'asset_disposal_gain_loss'), 'debit', greatest(-v_gain,0), 'credit', greatest(v_gain,0),
                       'description', CASE WHEN v_gain >= 0 THEN 'Gain' ELSE 'Loss' END || ' on disposal of ' || a.name));
  IF p_proceeds > 0 THEN
    v_lines := v_lines || jsonb_build_object('account_id', acct_bank_gl(p_deposit_bank_account_id), 'debit', p_proceeds, 'description', 'Sale of ' || a.name);
  END IF;
  SELECT coalesce(jsonb_agg(x), '[]'::jsonb) INTO v_lines FROM jsonb_array_elements(v_lines) x
   WHERE coalesce((x->>'debit')::numeric,0) <> 0 OR coalesce((x->>'credit')::numeric,0) <> 0;
  v_je := acct_post_entry(a.tenant_id, a.entity_id, p_date, v_lines, 'fixed_asset', a.id::text, a.asset_number, coalesce(p_memo, 'Dispose ' || a.name),
                          'fadisp:' || a.id, NULL, NULL, NULL, false, false, 'acct_fixed_assets', a.id);
  UPDATE acct_fixed_assets SET status = 'disposed', disposal_date = p_date, disposal_proceeds = p_proceeds, disposal_gain_loss = v_gain,
         disposal_journal_id = v_je, updated_at = now() WHERE id = a.id;
  RETURN v_je;
END $$;

-- @seq 188
CREATE FUNCTION public.acct_draft_from_template(p_template_id uuid, p_entry_date date, p_params jsonb DEFAULT '{}'::jsonb, p_memo text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_transaction_templates%ROWTYPE; v_entity uuid; v_book uuid; v_period uuid; v_batch uuid; v_je uuid; l jsonb; i int := 0;
        v_tokens jsonb := '{}'::jsonb; k text; v_acct uuid; v_dr numeric; v_cr numeric; v_tdr numeric := 0; v_tcr numeric := 0;
BEGIN
  SELECT * INTO t FROM acct_transaction_templates WHERE id = p_template_id AND is_active;
  IF NOT FOUND THEN RAISE EXCEPTION 'Template not found or inactive'; END IF;
  PERFORM acct_assert_access(t.tenant_id);
  -- parameters: supplied value, else template default; every declared parameter must have a number
  FOR k IN SELECT x FROM jsonb_object_keys(t.parameters) x LOOP
    v_tokens := v_tokens || jsonb_build_object(k, coalesce(p_params->k, t.parameters->k->'default'));
    IF jsonb_typeof(v_tokens->k) IS DISTINCT FROM 'number' THEN RAISE EXCEPTION 'Template parameter "%" needs a number', k; END IF;
  END LOOP;
  FOR k IN SELECT x FROM jsonb_object_keys(p_params) x LOOP
    IF NOT v_tokens ? k AND jsonb_typeof(p_params->k) = 'number' THEN v_tokens := v_tokens || jsonb_build_object(k, p_params->k); END IF;
  END LOOP;
  v_entity := coalesce(t.entity_id, acct_default_entity(t.tenant_id));
  v_book := acct_primary_book(t.tenant_id, v_entity);
  v_period := acct_period_for(v_book, p_entry_date, true, false);
  INSERT INTO acct_journal_batches(tenant_id, entity_id, book_id, batch_no, source, status, description, created_by)
  VALUES (t.tenant_id, v_entity, v_book, 'T-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSUS'), 'manual', 'draft', t.name, auth.uid())
  RETURNING id INTO v_batch;
  INSERT INTO acct_journal_entries(tenant_id, entity_id, book_id, batch_id, period_id, entry_date, document_date, posting_date, source, source_id,
                                   reference, memo, currency, status, created_by, is_adjusting)
  VALUES (t.tenant_id, v_entity, v_book, v_batch, v_period, p_entry_date, p_entry_date, p_entry_date, 'manual', 'template:' || t.id,
          t.name, coalesce(p_memo, t.memo, t.name), coalesce((SELECT functional_currency FROM acct_entities WHERE id = v_entity), 'USD'), 'draft', auth.uid(), t.is_adjusting)
  RETURNING id INTO v_je;
  FOR l IN SELECT value FROM jsonb_array_elements(t.lines) LOOP
    i := i + 1;
    v_acct := CASE WHEN l ? 'account_id' THEN (l->>'account_id')::uuid
                   WHEN l ? 'account_code' THEN (SELECT id FROM acct_chart_of_accounts WHERE tenant_id = t.tenant_id AND code = l->>'account_code'
                                                    AND (entity_id = v_entity OR entity_id IS NULL) ORDER BY entity_id NULLS LAST LIMIT 1)
                   WHEN l ? 'role' THEN acct_role_account(t.tenant_id, v_entity, l->>'role', true) END;
    IF v_acct IS NULL THEN RAISE EXCEPTION 'Template line % has no resolvable account', i; END IF;
    v_dr := CASE WHEN l ? 'debit' THEN acct__eval_kpi(l->>'debit', v_tokens) ELSE 0 END;
    v_cr := CASE WHEN l ? 'credit' THEN acct__eval_kpi(l->>'credit', v_tokens) ELSE 0 END;
    IF v_dr IS NULL OR v_cr IS NULL THEN RAISE EXCEPTION 'Template line % formula divided by zero', i; END IF;
    IF v_dr < 0 THEN v_cr := v_cr - v_dr; v_dr := 0; END IF;
    IF v_cr < 0 THEN v_dr := v_dr - v_cr; v_cr := 0; END IF;
    CONTINUE WHEN v_dr = 0 AND v_cr = 0;
    INSERT INTO acct_journal_lines(tenant_id, entity_id, journal_entry_id, line_no, account_id, description, debit, credit, vendor_id, customer_id, dimensions)
    VALUES (t.tenant_id, v_entity, v_je, i, v_acct, coalesce(l->>'description', t.name), v_dr, v_cr, l->>'vendor_id', l->>'customer_id',
            coalesce(l->'dimensions', '{}'::jsonb));
    v_tdr := v_tdr + v_dr; v_tcr := v_tcr + v_cr;
  END LOOP;
  IF round(v_tdr, 2) <> round(v_tcr, 2) THEN RAISE EXCEPTION 'Template does not balance: debits % credits %', v_tdr, v_tcr; END IF;
  IF t.auto_reverse THEN PERFORM acct_schedule_auto_reversal(v_je, NULL); END IF;
  RETURN v_je;
END $$;

-- @seq 189
CREATE FUNCTION public.acct_duplicate_statement_batch(p_batch_id uuid, p_generate boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_statement_batches%ROWTYPE; v uuid; v_start date; v_end date;
BEGIN
  SELECT * INTO b FROM acct_statement_batches WHERE id = p_batch_id;
  PERFORM acct_assert_access(b.tenant_id);
  v_start := b.period_end + 1;
  -- whole calendar months roll by month; anything else by the same number of days
  IF b.period_start = date_trunc('month', b.period_start)::date AND b.period_end = (date_trunc('month', b.period_end) + interval '1 month - 1 day')::date THEN
    v_end := (date_trunc('month', v_start) + ((extract(year from age(b.period_end + 1, b.period_start)) * 12
              + extract(month from age(b.period_end + 1, b.period_start)))::int || ' months')::interval - interval '1 day')::date;
  ELSE
    v_end := v_start + (b.period_end - b.period_start);
  END IF;
  INSERT INTO acct_statement_batches(tenant_id, statement_type, period_start, period_end, customer_filter, customer_ids, previous_batch_id)
  VALUES (b.tenant_id, b.statement_type, v_start, v_end, b.customer_filter, b.customer_ids, b.id) RETURNING id INTO v;
  IF p_generate THEN PERFORM acct_generate_statement_batch(v); END IF;
  RETURN v;
END $$;

-- @seq 190
CREATE FUNCTION public.acct_ensure_fiscal_year(p_book_id uuid, p_date date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_books%ROWTYPE; e acct_entities%ROWTYPE; v_start date; v_fy uuid; v_year int; i int;
BEGIN
  SELECT * INTO b FROM acct_books WHERE id = p_book_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Book % not found', p_book_id; END IF;
  SELECT * INTO e FROM acct_entities WHERE id = b.entity_id;
  v_start := make_date(extract(year FROM p_date)::int, e.fiscal_year_start_month, 1);
  IF v_start > p_date THEN v_start := (v_start - interval '1 year')::date; END IF;
  v_year := extract(year FROM (v_start + interval '1 year' - interval '1 day'))::int;  -- FY named by end year
  SELECT id INTO v_fy FROM acct_fiscal_years WHERE entity_id = b.entity_id AND fiscal_year = v_year;
  IF v_fy IS NULL THEN
    INSERT INTO acct_fiscal_years(tenant_id, entity_id, fiscal_year, start_date, end_date)
    VALUES (b.tenant_id, b.entity_id, v_year, v_start, (v_start + interval '1 year' - interval '1 day')::date)
    RETURNING id INTO v_fy;
  END IF;
  FOR i IN 0..11 LOOP
    INSERT INTO acct_periods(tenant_id, book_id, fiscal_year_id, period_no, name, start_date, end_date, status)
    VALUES (b.tenant_id, b.id, v_fy, i + 1,
            to_char(v_start + make_interval(months => i), 'Mon YYYY'),
            (v_start + make_interval(months => i))::date,
            (v_start + make_interval(months => i + 1) - interval '1 day')::date, 'open')
    ON CONFLICT (book_id, start_date) DO NOTHING;
  END LOOP;
  RETURN v_fy;
END $$;

-- @seq 191
CREATE FUNCTION public.acct_entity_operating_accounts_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM acct_account_roles WHERE tenant_id = NEW.tenant_id AND entity_id = NEW.id) THEN
    PERFORM acct__ensure_operating_accounts(NEW.tenant_id, NEW.id);
  END IF;
  RETURN NULL;
END $$;

-- @seq 192
CREATE FUNCTION public.acct_erp_order_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF acct_default_entity(NEW.tenant_id) IS NULL THEN RETURN NULL; END IF;
  BEGIN
    PERFORM acct__sync_erp_order(NEW.id);
  EXCEPTION WHEN OTHERS THEN
    -- never block the shop: record the problem; acct_sync_pending_orders retries
    INSERT INTO acct_order_postings(order_id, tenant_id, entity_id, party, last_error, updated_at)
    VALUES (NEW.id, NEW.tenant_id, acct_default_entity(NEW.tenant_id), coalesce(NEW.crm_customer_id::text, 'order:' || NEW.id), SQLERRM, now())
    ON CONFLICT (order_id) DO UPDATE SET last_error = EXCLUDED.last_error, updated_at = now();
  END;
  RETURN NULL;
END $$;

-- @seq 193
CREATE FUNCTION public.acct_exclude_bank_transaction(p_bank_txn_id uuid, p_reason text DEFAULT NULL::text, p_undo boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_bank_transactions%ROWTYPE;
BEGIN
  SELECT * INTO t FROM acct_bank_transactions WHERE id = p_bank_txn_id FOR UPDATE;
  PERFORM acct_assert_access(t.tenant_id);
  IF t.review_status IN ('posted','matched') THEN RAISE EXCEPTION 'Undo the posting before excluding'; END IF;
  UPDATE acct_bank_transactions SET review_status = CASE WHEN p_undo THEN 'for_review' ELSE 'excluded' END,
         excluded_reason = CASE WHEN p_undo THEN NULL ELSE coalesce(p_reason,'Excluded') END WHERE id = t.id;
END $$;

-- @seq 194
CREATE FUNCTION public.acct_explain_flux(p_tenant_id uuid, p_account_id uuid, p_from date, p_to date, p_explanation text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  INSERT INTO acct_flux_explanations(tenant_id, account_id, period_start, period_end, explanation, explained_by)
  VALUES (p_tenant_id, p_account_id, p_from, p_to, p_explanation, auth.uid())
  ON CONFLICT (tenant_id, account_id, period_start, period_end) DO UPDATE SET explanation = EXCLUDED.explanation, explained_by = EXCLUDED.explained_by, explained_at = now()
  RETURNING id INTO v;
  RETURN v;
END $$;

-- @seq 195
CREATE FUNCTION public.acct_fill_tenant_from_parent() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
  IF NEW.tenant_id IS NULL THEN
    EXECUTE format('SELECT tenant_id FROM %I WHERE id = $1.%I', TG_ARGV[0], TG_ARGV[1]) INTO NEW.tenant_id USING NEW;
  END IF;
  RETURN NEW;
END $_$;

-- @seq 196
CREATE FUNCTION public.acct_finalize_close(p_close_id uuid, p_period_status text DEFAULT 'soft_closed'::text, p_force_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c acct_closes%ROWTYPE; n int; e int;
BEGIN
  SELECT * INTO c FROM acct_closes WHERE id = p_close_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Close not found'; END IF;
  PERFORM acct_assert_access(c.tenant_id);
  IF p_period_status NOT IN ('soft_closed','closed') THEN RAISE EXCEPTION 'Finalize to soft_closed or closed'; END IF;
  SELECT count(*) INTO n FROM acct_close_tasks WHERE close_id = c.id AND status NOT IN ('done','skipped');
  SELECT count(*) INTO e FROM acct_review_findings WHERE tenant_id = c.tenant_id AND status IN ('open','in_progress') AND severity = 'error'
     AND (txn_date IS NULL OR txn_date <= c.period_end);
  IF (n > 0 OR e > 0) AND p_force_note IS NULL THEN
    RAISE EXCEPTION 'Close is not finished: % open tasks, % open error findings', n, e;
  END IF;
  PERFORM acct_set_period_status(c.period_id, p_period_status);
  UPDATE acct_closes SET status = CASE WHEN p_period_status = 'closed' THEN 'closed' ELSE 'soft_closed' END, finalized_at = now(), finalized_by = auth.uid(),
         notes = concat_ws(E'\n', notes, CASE WHEN p_force_note IS NOT NULL THEN 'Finalized with open items: ' || p_force_note END)
   WHERE id = c.id;
  RETURN jsonb_build_object('close_id', c.id, 'period_status', p_period_status, 'open_tasks', n, 'open_errors', e);
END $$;

-- @seq 197
CREATE FUNCTION public.acct_finish_reconciliation(p_reconciliation_id uuid, p_post_adjustment boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_reconciliations%ROWTYPE; b acct_bank_accounts%ROWTYPE; s record; v_je uuid; v_liab boolean; v_acct uuid;
BEGIN
  SELECT * INTO r FROM acct_reconciliations WHERE id = p_reconciliation_id FOR UPDATE;
  PERFORM acct_assert_access(r.tenant_id);
  SELECT * INTO s FROM acct_reconciliation_summary(r.id);
  SELECT * INTO b FROM acct_bank_accounts WHERE id = r.bank_account_id;
  v_liab := b.account_kind IN ('credit_card','line_of_credit','loan');
  IF s.difference <> 0 THEN
    IF NOT p_post_adjustment THEN
      RAISE EXCEPTION 'Difference is % (statement % vs cleared %). Tick more items, or finish with an adjustment.', s.difference, s.statement_ending_balance, s.cleared_balance;
    END IF;
    v_acct := acct_role_account(r.tenant_id, b.entity_id, 'uncategorized_expense');
    -- register must move by +difference in register terms
    v_je := acct_post_entry(r.tenant_id, b.entity_id, r.as_of_date, jsonb_build_array(
              jsonb_build_object('account_id', b.gl_account_id,
                 'debit',  CASE WHEN (s.difference > 0) <> v_liab THEN abs(s.difference) ELSE 0 END,
                 'credit', CASE WHEN (s.difference > 0) <> v_liab THEN 0 ELSE abs(s.difference) END, 'description', 'Reconciliation discrepancy'),
              jsonb_build_object('account_id', v_acct,
                 'debit',  CASE WHEN (s.difference > 0) <> v_liab THEN 0 ELSE abs(s.difference) END,
                 'credit', CASE WHEN (s.difference > 0) <> v_liab THEN abs(s.difference) ELSE 0 END, 'description', 'Reconciliation discrepancy')),
            'bank', r.id::text, 'REC-ADJ', 'Reconciliation discrepancy adjustment', 'recadj:' || r.id, NULL, NULL, NULL, true, false, 'acct_reconciliations', r.id);
    UPDATE acct_journal_lines SET cleared_status = 'cleared', reconciliation_id = r.id WHERE journal_entry_id = v_je AND account_id = b.gl_account_id;
    UPDATE acct_reconciliations SET adjustment_journal_id = v_je WHERE id = r.id;
    SELECT * INTO s FROM acct_reconciliation_summary(r.id);
  END IF;
  UPDATE acct_journal_lines SET cleared_status = 'reconciled' WHERE reconciliation_id = r.id;
  -- stored proof: statement - books + outstanding deposits - outstanding payments = 0 (generated "difference" column)
  UPDATE acct_reconciliations x SET status = 'reconciled', completed_at = now(), reviewed_by = auth.uid(),
         gl_balance = acct_account_balance(b.gl_account_id, r.as_of_date),
         outstanding_deposits = o.dep, outstanding_payments = o.pay
    FROM (SELECT coalesce(sum(CASE WHEN v_liab THEN l.credit ELSE l.debit END),0) dep,
                 coalesce(sum(CASE WHEN v_liab THEN l.debit ELSE l.credit END),0) pay
            FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id AND e.status IN ('posted','reversed')
           WHERE l.account_id = b.gl_account_id AND e.posting_date <= r.as_of_date AND l.cleared_status <> 'reconciled') o
   WHERE x.id = r.id;
END $$;

-- @seq 198
CREATE FUNCTION public.acct_fiscal_year_start(p_tenant uuid, p_entity uuid, p_date date) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(
    (SELECT fy.start_date FROM acct_fiscal_years fy
      WHERE fy.tenant_id = p_tenant AND (p_entity IS NULL OR fy.entity_id = p_entity OR fy.entity_id IS NULL)
        AND p_date BETWEEN fy.start_date AND fy.end_date
      ORDER BY fy.start_date DESC LIMIT 1),
    date_trunc('year', p_date)::date);
$$;

-- @seq 199
CREATE FUNCTION public.acct_fixed_asset_register(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(asset_number text, name text, status text, acquired date, in_service date, method text, life_months integer, cost numeric, accumulated numeric, net_book_value numeric, last_depreciated date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  SELECT a.asset_number, a.name, a.status::text, a.acquisition_date, a.placed_in_service_date, b.depreciation_method, b.useful_life_months,
         a.original_cost, a.accumulated_depreciation, a.original_cost - a.accumulated_depreciation, b.last_depreciation_date
    FROM acct_fixed_assets a LEFT JOIN acct_asset_books b ON b.asset_id = a.id AND b.book_id = acct_primary_book(a.tenant_id, a.entity_id)
   WHERE a.tenant_id = p_tenant_id AND a.acquisition_date <= p_as_of
   ORDER BY a.asset_number;
END $$;

-- @seq 200
CREATE FUNCTION public.acct_flux_analysis(p_tenant_id uuid, p_from date, p_to date, p_amount_threshold numeric DEFAULT 500, p_pct_threshold numeric DEFAULT 0.10, p_entity_id uuid DEFAULT NULL::uuid) RETURNS TABLE(account_id uuid, code text, name text, account_type text, basis text, current_amount numeric, prior_amount numeric, change numeric, change_pct numeric, flagged boolean, explanation text, top_drivers jsonb)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE w record;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT * INTO w FROM acct__prior_window(p_from, p_to);
  RETURN QUERY
  WITH cur AS (SELECT * FROM acct__account_amounts(p_tenant_id, p_from, p_to, p_entity_id)),
       pri AS (SELECT * FROM acct__account_amounts(p_tenant_id, w.prior_from, w.prior_to, p_entity_id)),
       j AS (
    SELECT c.account_id, c.code, c.name, c.account_type,
           CASE WHEN c.account_type IN ('revenue','expense') THEN 'activity' ELSE 'balance' END AS basis,
           CASE WHEN c.account_type IN ('revenue','expense') THEN c.activity ELSE c.ending_balance END AS cur_amt,
           CASE WHEN c.account_type IN ('revenue','expense') THEN p.activity ELSE p.ending_balance END AS pri_amt
      FROM cur c JOIN pri p ON p.account_id = c.account_id)
  SELECT j.account_id, j.code, j.name, j.account_type, j.basis, j.cur_amt, j.pri_amt, j.cur_amt - j.pri_amt,
         CASE WHEN j.pri_amt <> 0 THEN round((j.cur_amt - j.pri_amt) / abs(j.pri_amt), 4) END,
         abs(j.cur_amt - j.pri_amt) >= p_amount_threshold AND (j.pri_amt = 0 OR abs((j.cur_amt - j.pri_amt) / j.pri_amt) >= p_pct_threshold),
         fx.explanation,
         (SELECT coalesce(jsonb_agg(jsonb_build_object('counterparty', x.cp, 'amount', x.amt, 'lines', x.n) ORDER BY abs(x.amt) DESC), '[]'::jsonb) FROM (
            SELECT coalesce(v.display_name, v.legal_name, nullif(trim(concat_ws(' ', cu."firstName", cu."lastName")),''), l.vendor_id, l.customer_id,
                            nullif(l.description,''), je.source) AS cp,
                   sum(l.debit - l.credit) * CASE WHEN j.account_type IN ('asset','contra_asset','expense') THEN 1 ELSE -1 END AS amt,
                   count(*) AS n
              FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id
              LEFT JOIN acct_vendors v ON v.id::text = l.vendor_id
              LEFT JOIN customers cu ON cu.id::text = l.customer_id
             WHERE l.account_id = j.account_id AND je.status IN ('posted','reversed') AND je.entry_date BETWEEN p_from AND p_to AND NOT je.is_closing
             GROUP BY 1 ORDER BY abs(sum(l.debit - l.credit)) DESC LIMIT 3) x)
    FROM j
    LEFT JOIN acct_flux_explanations fx ON fx.tenant_id = p_tenant_id AND fx.account_id = j.account_id AND fx.period_start = p_from AND fx.period_end = p_to
   WHERE j.cur_amt <> 0 OR j.pri_amt <> 0
   ORDER BY j.code;
END $$;

-- @seq 201
CREATE FUNCTION public.acct_fx_revalue(p_tenant_id uuid, p_as_of date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid; v_base text; d record; v_rate numeric; v_diff numeric; v_lines jsonb := '[]'::jsonb; v_net numeric := 0; v_je uuid; v_rev uuid; n int := 0;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  v_entity := acct_default_entity(p_tenant_id);
  SELECT currency INTO v_base FROM acct_books WHERE id = acct_primary_book(p_tenant_id, v_entity);
  FOR d IN SELECT 'ar' side, id, invoice_number ref, customer_id::text party, currency, exchange_rate, open_balance FROM acct_ar_invoices
            WHERE tenant_id = p_tenant_id AND currency <> v_base AND posted_journal_id IS NOT NULL AND open_balance > 0 AND status NOT IN ('void','written_off')
           UNION ALL
           SELECT 'ap', id, bill_number, vendor_id::text, currency, exchange_rate, open_balance FROM acct_ap_bills
            WHERE tenant_id = p_tenant_id AND currency <> v_base AND posted_journal_id IS NOT NULL AND open_balance > 0 AND status <> 'void' LOOP
    SELECT rate INTO v_rate FROM acct_exchange_rates WHERE (tenant_id = p_tenant_id OR tenant_id IS NULL) AND from_currency = d.currency AND to_currency = v_base
       AND rate_date <= p_as_of ORDER BY rate_date DESC, tenant_id NULLS LAST LIMIT 1;
    IF v_rate IS NULL THEN RAISE EXCEPTION 'No % to % exchange rate on or before %', d.currency, v_base, p_as_of; END IF;
    v_diff := round(d.open_balance * v_rate, 2) - round(d.open_balance * coalesce(d.exchange_rate,1), 2);
    CONTINUE WHEN v_diff = 0;
    n := n + 1;
    IF d.side = 'ar' THEN
      v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'accounts_receivable'), 'debit', greatest(v_diff,0),
                   'credit', greatest(-v_diff,0), 'customer_id', d.party, 'description', 'FX revaluation ' || d.ref);
      v_net := v_net + v_diff;
    ELSE
      v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'accounts_payable'), 'credit', greatest(v_diff,0),
                   'debit', greatest(-v_diff,0), 'vendor_id', d.party, 'description', 'FX revaluation ' || d.ref);
      v_net := v_net - v_diff;
    END IF;
  END LOOP;
  IF n = 0 THEN RETURN jsonb_build_object('documents', 0); END IF;
  v_lines := v_lines || jsonb_build_object('account_id', acct__role(p_tenant_id, v_entity, 'unrealized_fx_gain_loss'),
               'credit', greatest(v_net,0), 'debit', greatest(-v_net,0), 'description', 'Unrealized FX ' || CASE WHEN v_net >= 0 THEN 'gain' ELSE 'loss' END);
  v_je := acct_post_entry(p_tenant_id, v_entity, p_as_of, v_lines, 'system', NULL, 'FXREVAL', 'FX revaluation ' || p_as_of, 'fxreval:' || p_tenant_id || ':' || p_as_of,
                          NULL, NULL, NULL, true, false, NULL, NULL);
  BEGIN
    v_rev := acct_reverse_journal(v_je, p_as_of + 1, 'Auto-reverse FX revaluation ' || p_as_of);
  EXCEPTION WHEN OTHERS THEN v_rev := NULL;   -- next period not open yet: reverse when it opens
  END;
  RETURN jsonb_build_object('documents', n, 'net_gain', v_net, 'journal_id', v_je, 'reversal_id', v_rev);
END $$;

-- @seq 202
CREATE FUNCTION public.acct_general_ledger(p_tenant uuid, p_from date, p_to date, p_account_id uuid DEFAULT NULL::uuid, p_entity uuid DEFAULT NULL::uuid) RETURNS TABLE(account_id uuid, code text, account_name text, journal_entry_id uuid, entry_no bigint, posting_date date, source text, reference text, memo text, description text, debit numeric, credit numeric, running_balance numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
BEGIN
  PERFORM acct_assert_access(p_tenant);
  RETURN QUERY
  WITH a AS (SELECT * FROM acct_chart_of_accounts a WHERE a.tenant_id = p_tenant AND (p_account_id IS NULL OR a.id = p_account_id)),
       ob AS (SELECT s.account_id, s.dr - s.cr net FROM acct__ledger_sums(p_tenant, p_entity, NULL, p_from - 1, false) s),
       mv AS (
         SELECT l.account_id, e.id eid, e.entry_no, e.posting_date, e.source, e.reference, e.memo, l.description, l.debit, l.credit, l.line_no
           FROM acct_journal_lines l JOIN acct_journal_entries e ON e.id = l.journal_entry_id
          WHERE e.tenant_id = p_tenant AND e.status IN ('posted','reversed') AND (p_entity IS NULL OR e.entity_id = p_entity)
            AND e.posting_date BETWEEN p_from AND p_to AND (p_account_id IS NULL OR l.account_id = p_account_id)),
       u AS (
         SELECT a.id aid, NULL::uuid eid, NULL::bigint eno, p_from - 1 pd, 'opening'::text src, NULL::text ref, NULL::text mm,
                'Opening balance'::text dsc, greatest(coalesce(ob.net,0),0) dr, greatest(-coalesce(ob.net,0),0) cr, 0 ord, 0 lno
           FROM a LEFT JOIN ob ON ob.account_id = a.id
          WHERE ob.net IS NOT NULL OR EXISTS (SELECT 1 FROM mv WHERE mv.account_id = a.id)
         UNION ALL
         SELECT mv.account_id, mv.eid, mv.entry_no, mv.posting_date, mv.source, mv.reference, mv.memo, mv.description, mv.debit, mv.credit, 1, mv.line_no FROM mv)
  SELECT u.aid, a.code, a.name, u.eid, u.eno, u.pd, u.src, u.ref, u.mm, u.dsc, u.dr, u.cr,
         (CASE WHEN a.normal_balance = 'debit' THEN 1 ELSE -1 END)
           * sum(u.dr - u.cr) OVER (PARTITION BY u.aid ORDER BY u.ord, u.pd, u.eno, u.lno ROWS UNBOUNDED PRECEDING)
    FROM u JOIN a ON a.id = u.aid
   ORDER BY a.code, u.ord, u.pd, u.eno, u.lno;
END $$;

-- @seq 203
CREATE FUNCTION public.acct_generate_1099s(p_tenant_id uuid, p_tax_year integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r record; n int := 0;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR r IN SELECT s.vendor_id, s.form, jsonb_object_agg('box_' || s.box, s.amount) AS boxes, bool_and(s.tin_on_file) AS tin_ok,
                  max(s.vendor_name) AS name, max(s.mailing_address) AS addr
             FROM acct_1099_summary(p_tenant_id, p_tax_year) s WHERE s.must_file GROUP BY s.vendor_id, s.form LOOP
    UPDATE acct_payroll_tax_forms SET box_values = r.boxes, metadata = metadata || jsonb_build_object('payee', r.name, 'address', r.addr, 'tin_on_file', r.tin_ok),
           updated_at = now()
     WHERE tenant_id = p_tenant_id AND vendor_id = r.vendor_id AND form_type = r.form AND tax_year = p_tax_year AND status IN ('draft','generated');
    IF NOT FOUND AND NOT EXISTS (SELECT 1 FROM acct_payroll_tax_forms WHERE tenant_id = p_tenant_id AND vendor_id = r.vendor_id AND form_type = r.form
                                   AND tax_year = p_tax_year AND status NOT IN ('void')) THEN
      INSERT INTO acct_payroll_tax_forms(tenant_id, vendor_id, form_type, tax_year, status, box_values, metadata)
      VALUES (p_tenant_id, r.vendor_id, r.form, p_tax_year, 'draft', r.boxes, jsonb_build_object('payee', r.name, 'address', r.addr, 'tin_on_file', r.tin_ok));
    END IF;
    n := n + 1;
  END LOOP;
  RETURN n;
END $$;

-- @seq 204
CREATE FUNCTION public.acct_generate_close(p_tenant_id uuid, p_period_end date, p_template_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid; v_book uuid; p acct_periods%ROWTYPE; v_close uuid; v_tpl uuid; t record; v_q boolean; v_y boolean; v_fy_end date; v_map jsonb := '{}'::jsonb; v_new uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  v_entity := acct_default_entity(p_tenant_id);
  v_book := acct_primary_book(p_tenant_id, v_entity);
  SELECT * INTO p FROM acct_periods WHERE book_id = v_book AND p_period_end BETWEEN start_date AND end_date ORDER BY start_date LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'No accounting period contains %', p_period_end; END IF;
  SELECT id INTO v_close FROM acct_closes WHERE tenant_id = p_tenant_id AND period_id = p.id;
  IF v_close IS NOT NULL THEN RETURN v_close; END IF;
  v_tpl := coalesce(p_template_id, acct__default_close_template(p_tenant_id));
  INSERT INTO acct_closes(tenant_id, entity_id, period_id, template_id, period_start, period_end)
  VALUES (p_tenant_id, v_entity, p.id, v_tpl, p.start_date, p.end_date) RETURNING id INTO v_close;
  SELECT max(end_date) INTO v_fy_end FROM acct_periods WHERE fiscal_year_id = p.fiscal_year_id;
  v_y := p.end_date = v_fy_end;
  v_q := v_y OR ((extract(year FROM age(v_fy_end + 1, p.end_date + 1)) * 12 + extract(month FROM age(v_fy_end + 1, p.end_date + 1)))::int % 3 = 0);
  FOR t IN SELECT * FROM acct_close_template_tasks WHERE template_id = v_tpl
             AND (applies_to = 'every_close' OR (applies_to = 'quarter_end' AND v_q) OR (applies_to = 'year_end' AND v_y))
           ORDER BY parent_id NULLS FIRST, sort_order LOOP
    INSERT INTO acct_close_tasks(tenant_id, close_id, template_task_id, parent_task_id, section, title, description, sort_order, assignee_id, reviewer_id,
                                 due_date, priority, tags, check_code, requires_signoff)
    VALUES (p_tenant_id, v_close, t.id, (v_map->>t.parent_id::text)::uuid, t.section, t.title, t.description, t.sort_order, t.default_assignee, t.default_reviewer,
            p.end_date + t.due_offset_days, t.priority, t.tags, t.check_code, t.requires_signoff)
    RETURNING id INTO v_new;
    v_map := v_map || jsonb_build_object(t.id::text, v_new);
  END LOOP;
  RETURN v_close;
END $$;

-- @seq 205
CREATE FUNCTION public.acct_generate_statement_batch(p_batch_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_statement_batches%ROWTYPE; c record; v_open numeric; v_chg numeric; v_pay numeric; v_close numeric; n int := 0;
        a record;
BEGIN
  SELECT * INTO b FROM acct_statement_batches WHERE id = p_batch_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Statement batch not found'; END IF;
  PERFORM acct_assert_access(b.tenant_id);
  IF b.status = 'sent' THEN RAISE EXCEPTION 'Batch was already sent; duplicate it for the next period'; END IF;
  DELETE FROM acct_customer_statements WHERE batch_id = b.id AND status IN ('draft','generated');
  FOR c IN
    SELECT cu.id, cu.email FROM crm_customers cu
     WHERE cu.tenant_id = b.tenant_id
       AND (b.customer_filter <> 'selected' OR cu.id = ANY (b.customer_ids))
       AND (b.customer_filter IN ('selected','all_active')
            OR EXISTS (SELECT 1 FROM acct_ar_invoices i WHERE i.tenant_id = b.tenant_id AND i.customer_id = cu.id
                         AND i.status NOT IN ('draft','void','paid','deposited','written_off') AND i.open_balance > 0
                         AND (b.customer_filter = 'open_balance' OR i.due_date < b.period_end)))
  LOOP
    SELECT coalesce(max(balance) FILTER (WHERE doc_type = 'opening'), 0),
           coalesce(sum(charges) FILTER (WHERE doc_type <> 'opening'), 0),
           coalesce(sum(payments) FILTER (WHERE doc_type <> 'opening'), 0)
      INTO v_open, v_chg, v_pay
      FROM acct_customer_statement(b.tenant_id, c.id, b.period_start, b.period_end);
    v_close := v_open + v_chg - v_pay;
    CONTINUE WHEN b.customer_filter IN ('open_balance','overdue') AND v_close <= 0;
    SELECT coalesce(sum(i.open_balance) FILTER (WHERE i.due_date >= b.period_end), 0) cur,
           coalesce(sum(i.open_balance) FILTER (WHERE b.period_end - i.due_date BETWEEN 1 AND 30), 0) d30,
           coalesce(sum(i.open_balance) FILTER (WHERE b.period_end - i.due_date BETWEEN 31 AND 60), 0) d60,
           coalesce(sum(i.open_balance) FILTER (WHERE b.period_end - i.due_date BETWEEN 61 AND 90), 0) d90,
           coalesce(sum(i.open_balance) FILTER (WHERE b.period_end - i.due_date > 90), 0) d91
      INTO a FROM acct_ar_invoices i
     WHERE i.tenant_id = b.tenant_id AND i.customer_id = c.id AND i.invoice_date <= b.period_end
       AND i.status NOT IN ('draft','void','written_off') AND i.open_balance > 0;
    INSERT INTO acct_customer_statements(tenant_id, customer_id, statement_number, period_start, period_end, opening_balance, charges_total,
           payments_total, credits_total, closing_balance, aging_current, aging_1_30, aging_31_60, aging_61_90, aging_over_90, status,
           generated_at, batch_id)
    VALUES (b.tenant_id, c.id, acct_next_number(b.tenant_id, acct_default_entity(b.tenant_id), 'statement', 'ST-'), b.period_start, b.period_end,
            v_open, v_chg, v_pay, 0, v_close, a.cur, a.d30, a.d60, a.d90, a.d91, 'generated', now(), b.id);
    n := n + 1;
  END LOOP;
  UPDATE acct_statement_batches SET status = 'generated', statement_count = n, generated_at = now() WHERE id = b.id;
  RETURN n;
END $$;

-- @seq 207
CREATE FUNCTION public.acct_import_bank_file(p_bank_account_id uuid, p_format text, p_content text, p_mapping jsonb DEFAULT '{}'::jsonb, p_file_name text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE b acct_bank_accounts%ROWTYPE; v_job uuid; v_fmt text := lower(p_format); v_new int := 0; v_dup int := 0; v_total int := 0;
        v_err jsonb := '[]'::jsonb; hdr text[]; rec text[]; v_line int := 0; v_skip int := coalesce((p_mapping->>'skip_rows')::int, 0);
        i_date int; i_desc int; i_amt int; i_deb int; i_cred int; i_ref int; i_id int; i_payee int;
        v_neg boolean := coalesce((p_mapping->>'negate')::boolean, false); v_dfmt text := p_mapping->>'date_format';
        v_date date; v_amt numeric; v_desc text; v_ref text; v_fit text; v_payee text; v_meta jsonb := '{}'::jsonb;
        blk text; r record; v_hash text; v_ins int; v_rules int := 0; v_class int; v_min date; v_max date;
BEGIN
  SELECT * INTO b FROM acct_bank_accounts WHERE id = p_bank_account_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank account not found'; END IF;
  PERFORM acct_assert_access(b.tenant_id);
  IF v_fmt NOT IN ('csv','ofx','qfx','qbo') THEN RAISE EXCEPTION 'Supported formats: csv, ofx, qfx, qbo'; END IF;
  IF length(coalesce(p_content,'')) = 0 THEN RAISE EXCEPTION 'The file is empty'; END IF;

  INSERT INTO acct_import_jobs(tenant_id, entity_type, source_file_name, status, started_at, created_by, bank_account_id, file_format)
  VALUES (b.tenant_id, 'acct_bank_transactions', p_file_name, 'running', now(), auth.uid(), b.id, v_fmt) RETURNING id INTO v_job;

  CREATE TEMP TABLE IF NOT EXISTS _acct_bank_import(line int, d date, amt numeric, descr text, payee text, ref text, fitid text) ON COMMIT DROP;
  DELETE FROM _acct_bank_import;

  IF v_fmt = 'csv' THEN
    FOR rec IN SELECT x FROM acct__csv_rows(p_content, coalesce(p_mapping->>'delimiter', ',')) x LOOP
      v_line := v_line + 1;
      CONTINUE WHEN v_line <= v_skip;
      IF hdr IS NULL THEN
        hdr := rec;
        i_date := acct__csv_header_index(hdr, 'date', p_mapping);
        i_desc := acct__csv_header_index(hdr, 'description', p_mapping);
        i_amt  := acct__csv_header_index(hdr, 'amount', p_mapping);
        i_deb  := acct__csv_header_index(hdr, 'debit', p_mapping);
        i_cred := acct__csv_header_index(hdr, 'credit', p_mapping);
        i_ref  := acct__csv_header_index(hdr, 'reference', p_mapping);
        i_id   := acct__csv_header_index(hdr, 'id', p_mapping);
        i_payee:= acct__csv_header_index(hdr, 'payee', p_mapping);
        IF i_date IS NULL THEN RAISE EXCEPTION 'Could not find a date column in: %. Pass a mapping.', array_to_string(hdr, ', '); END IF;
        IF i_amt IS NULL AND i_deb IS NULL AND i_cred IS NULL THEN
          RAISE EXCEPTION 'Could not find an amount column (or debit/credit columns) in: %. Pass a mapping.', array_to_string(hdr, ', ');
        END IF;
        CONTINUE;
      END IF;
      CONTINUE WHEN array_length(rec,1) IS NULL OR btrim(array_to_string(rec,'')) = '';
      v_total := v_total + 1;
      BEGIN
        v_date := acct__parse_date(rec[i_date], v_dfmt);
        IF v_date IS NULL THEN RAISE EXCEPTION 'missing date'; END IF;
        IF i_amt IS NOT NULL THEN
          v_amt := acct__parse_amount(rec[i_amt]);
        ELSE  -- separate columns: money out (debit) negative, money in (credit) positive
          v_amt := coalesce(abs(acct__parse_amount(CASE WHEN i_cred IS NOT NULL THEN rec[i_cred] END)),0)
                 - coalesce(abs(acct__parse_amount(CASE WHEN i_deb IS NOT NULL THEN rec[i_deb] END)),0);
        END IF;
        IF v_amt IS NULL THEN RAISE EXCEPTION 'missing amount'; END IF;
        IF v_neg THEN v_amt := -v_amt; END IF;
        INSERT INTO _acct_bank_import VALUES (v_line, v_date, round(v_amt, 2),
          nullif(btrim(CASE WHEN i_desc IS NOT NULL THEN rec[i_desc] END),''), nullif(btrim(CASE WHEN i_payee IS NOT NULL THEN rec[i_payee] END),''),
          nullif(btrim(CASE WHEN i_ref IS NOT NULL THEN rec[i_ref] END),''), nullif(btrim(CASE WHEN i_id IS NOT NULL THEN rec[i_id] END),''));
      EXCEPTION WHEN others THEN
        v_err := v_err || jsonb_build_object('line', v_line, 'error', SQLERRM, 'row', to_jsonb(rec));
      END;
    END LOOP;
    IF hdr IS NULL THEN RAISE EXCEPTION 'The file has no header row'; END IF;
  ELSE
    -- OFX / QFX / QBO (QFX and QBO are OFX with vendor tags)
    IF p_content !~* '<STMTTRN>' THEN RAISE EXCEPTION 'No <STMTTRN> transactions found; is this an OFX/QFX/QBO file?'; END IF;
    FOR blk IN SELECT x FROM unnest(regexp_split_to_array(p_content, '(?i)<STMTTRN>')) WITH ORDINALITY AS u(x, n) WHERE n > 1 LOOP
      v_line := v_line + 1; v_total := v_total + 1;
      blk := split_part(regexp_replace(blk, '(?i)</STMTTRN>', '§'), '§', 1);
      BEGIN
        v_date := acct__parse_date(left(acct__ofx_tag(blk, 'DTPOSTED'), 8), NULL);
        v_amt  := acct__parse_amount(acct__ofx_tag(blk, 'TRNAMT'));
        IF v_date IS NULL OR v_amt IS NULL THEN RAISE EXCEPTION 'missing DTPOSTED or TRNAMT'; END IF;
        IF v_neg THEN v_amt := -v_amt; END IF;
        INSERT INTO _acct_bank_import VALUES (v_line, v_date, round(v_amt,2),
          coalesce(acct__ofx_tag(blk,'MEMO'), acct__ofx_tag(blk,'NAME')), acct__ofx_tag(blk,'NAME'),
          coalesce(acct__ofx_tag(blk,'CHECKNUM'), acct__ofx_tag(blk,'REFNUM')), acct__ofx_tag(blk,'FITID'));
      EXCEPTION WHEN others THEN
        v_err := v_err || jsonb_build_object('transaction', v_line, 'error', SQLERRM);
      END;
    END LOOP;
    v_meta := jsonb_strip_nulls(jsonb_build_object(
      'ledger_balance', acct__ofx_tag(substring(p_content FROM '(?is)<LEDGERBAL>(.*?)(</LEDGERBAL>|<AVAILBAL>|$)'), 'BALAMT'),
      'ledger_balance_date', acct__ofx_tag(substring(p_content FROM '(?is)<LEDGERBAL>(.*?)(</LEDGERBAL>|<AVAILBAL>|$)'), 'DTASOF'),
      'available_balance', acct__ofx_tag(substring(p_content FROM '(?is)<AVAILBAL>(.*?)(</AVAILBAL>|$)'), 'BALAMT'),
      'statement_start', acct__ofx_tag(p_content, 'DTSTART'), 'statement_end', acct__ofx_tag(p_content, 'DTEND'),
      'account_last4', right(acct__ofx_tag(p_content, 'ACCTID'), 4), 'currency', acct__ofx_tag(p_content, 'CURDEF')));
  END IF;

  -- insert with stable de-duplication keys
  FOR r IN SELECT t.*, row_number() OVER (PARTITION BY d, amt, lower(coalesce(descr,'')) ORDER BY line) AS occ FROM _acct_bank_import t ORDER BY line LOOP
    v_hash := CASE WHEN r.fitid IS NULL THEN encode(sha256(convert_to(b.id::text || '|' || r.d || '|' || r.amt::text || '|' ||
                     lower(coalesce(r.descr,'')) || '|' || r.occ, 'UTF8')), 'hex') END;
    INSERT INTO acct_bank_transactions(tenant_id, bank_account_id, transaction_date, posted_date, amount, currency, description, payee,
                                       reference, provider_transaction_id, transaction_hash)
    VALUES (b.tenant_id, b.id, r.d, r.d, r.amt, coalesce(b.currency,'USD'), r.descr, r.payee, r.ref, r.fitid, v_hash)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS v_ins = ROW_COUNT;
    IF v_ins = 1 THEN v_new := v_new + 1; ELSE v_dup := v_dup + 1; END IF;
    v_min := least(v_min, r.d); v_max := greatest(v_max, r.d);
  END LOOP;

  -- route new lines through rules, then history-based suggestions (part 9) when installed
  IF v_new > 0 THEN
    v_rules := acct_apply_bank_rules(b.tenant_id, NULL);
    IF to_regprocedure('public.acct_classify_bank_feed(uuid,uuid)') IS NOT NULL THEN
      EXECUTE 'SELECT public.acct_classify_bank_feed($1, $2)' INTO v_class USING b.tenant_id, b.id;
    END IF;
  END IF;

  UPDATE acct_import_jobs SET status = CASE WHEN jsonb_array_length(v_err) > 0 AND v_new = 0 AND v_dup = 0 THEN 'failed'
                                            WHEN jsonb_array_length(v_err) > 0 THEN 'completed_with_errors' ELSE 'completed' END,
         total_rows = v_total, processed_rows = v_total, success_rows = v_new, error_rows = jsonb_array_length(v_err),
         completed_at = now(),
         metadata = v_meta || jsonb_build_object('duplicates_skipped', v_dup, 'errors', v_err, 'first_date', v_min, 'last_date', v_max)
  WHERE id = v_job;
  UPDATE acct_bank_accounts SET last_sync_at = now() WHERE id = b.id;

  RETURN jsonb_build_object('import_job_id', v_job, 'rows_read', v_total, 'imported', v_new, 'duplicates_skipped', v_dup,
    'errors', v_err, 'rules_applied', v_rules, 'auto_classified', v_class, 'first_date', v_min, 'last_date', v_max, 'statement', v_meta);
END $_$;

-- @seq 208
CREATE FUNCTION public.acct_import_channel_settlement(p_tenant_id uuid, p_channel text, p_payload jsonb, p_post boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE ch acct_channel_accounts%ROWTYPE; v_id uuid; x jsonb; v_sum numeric := 0; v_tax numeric := 0; v_gross numeric := 0; v_fees numeric := 0;
        v_type text; v_order uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT * INTO ch FROM acct_channel_accounts WHERE tenant_id = p_tenant_id AND channel = lower(p_channel) AND is_active
   ORDER BY created_at LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'Channel % is not set up; run channel setup first', p_channel; END IF;
  IF coalesce(p_payload->>'external_id','') = '' THEN RAISE EXCEPTION 'Settlement external_id is required'; END IF;
  SELECT id INTO v_id FROM acct_channel_settlements WHERE tenant_id = p_tenant_id AND channel = ch.channel AND external_id = p_payload->>'external_id';
  IF v_id IS NOT NULL THEN RETURN v_id; END IF;      -- idempotent re-import
  IF jsonb_typeof(p_payload->'lines') <> 'array' OR jsonb_array_length(p_payload->'lines') = 0 THEN RAISE EXCEPTION 'Settlement has no lines'; END IF;
  FOR x IN SELECT value FROM jsonb_array_elements(p_payload->'lines') LOOP
    v_sum := v_sum + (x->>'amount')::numeric;
    IF x->>'type' LIKE 'marketplace_tax%' THEN v_tax := v_tax + (x->>'amount')::numeric; END IF;
    IF x->>'type' IN ('sale','shipping_charged','refund') THEN v_gross := v_gross + (x->>'amount')::numeric; END IF;
    IF x->>'type' IN ('fee','ad_fee','shipping_label','subscription_fee','chargeback') THEN v_fees := v_fees - (x->>'amount')::numeric; END IF;
  END LOOP;
  IF v_sum <> (p_payload->>'payout_amount')::numeric THEN
    RAISE EXCEPTION 'Settlement lines total % but the payout is %', v_sum, p_payload->>'payout_amount';
  END IF;
  IF v_tax <> 0 THEN RAISE EXCEPTION 'Marketplace tax collected and remitted must net to zero (off by %)', v_tax; END IF;
  INSERT INTO acct_channel_settlements(tenant_id, entity_id, channel_account_id, channel, external_id, period_start, period_end, payout_date,
         currency, payout_amount, gross_sales, fees_total, bank_account_id, raw_payload)
  VALUES (p_tenant_id, ch.entity_id, ch.id, ch.channel, p_payload->>'external_id', nullif(p_payload->>'period_start','')::date,
          nullif(p_payload->>'period_end','')::date, (p_payload->>'payout_date')::date, coalesce(p_payload->>'currency','USD'),
          (p_payload->>'payout_amount')::numeric, v_gross, v_fees, ch.payout_bank_account_id, p_payload)
  RETURNING id INTO v_id;
  FOR x IN SELECT value FROM jsonb_array_elements(p_payload->'lines') LOOP
    v_type := x->>'type';
    v_order := NULL;
    IF coalesce(x->>'order_ref','') <> '' THEN
      SELECT o.id INTO v_order FROM erp_orders o WHERE o.tenant_id = p_tenant_id
         AND (o.order_number = x->>'order_ref' OR o.source_order_id = x->>'order_ref') ORDER BY o.created_at LIMIT 1;
    END IF;
    INSERT INTO acct_channel_settlement_lines(tenant_id, settlement_id, line_type, amount, description, order_ref, erp_order_id, account_id, external_ref)
    VALUES (p_tenant_id, v_id, v_type, (x->>'amount')::numeric, x->>'description', x->>'order_ref', v_order,
            nullif(x->>'account_id','')::uuid, x->>'external_ref');
  END LOOP;
  IF p_post THEN PERFORM acct_post_channel_settlement(v_id); END IF;
  RETURN v_id;
END $$;

-- @seq 209
CREATE FUNCTION public.acct_inbox_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  NEW.entity_id := coalesce(NEW.entity_id, acct_default_entity(NEW.tenant_id));
  NEW.sha256 := lower(NEW.sha256);
  SELECT id INTO NEW.duplicate_of_id FROM acct_document_inbox WHERE tenant_id = NEW.tenant_id AND sha256 = NEW.sha256 AND status <> 'rejected' ORDER BY created_at LIMIT 1;
  IF NEW.duplicate_of_id IS NOT NULL THEN NEW.status := 'duplicate'; END IF;
  NEW.uploaded_by := coalesce(NEW.uploaded_by, auth.uid());
  RETURN NEW;
END $$;

-- @seq 210
CREATE FUNCTION public.acct_inbox_create_bill(p_inbox_id uuid, p_overrides jsonb DEFAULT '{}'::jsonb, p_post boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d acct_document_inbox%ROWTYPE; v_bill uuid; v_vendor uuid; l jsonb; v_lines jsonb; v_acct uuid;
BEGIN
  SELECT * INTO d FROM acct_document_inbox WHERE id = p_inbox_id FOR UPDATE;
  PERFORM acct_assert_access(d.tenant_id);
  IF d.status = 'duplicate' AND NOT coalesce((p_overrides->>'allow_duplicate')::boolean, false) THEN
    RAISE EXCEPTION 'This file was already uploaded (inbox %)', d.duplicate_of_id; END IF;
  IF d.created_bill_id IS NOT NULL THEN RETURN d.created_bill_id; END IF;
  v_vendor := coalesce(nullif(p_overrides->>'vendor_id','')::uuid, d.vendor_id);
  IF v_vendor IS NULL THEN RAISE EXCEPTION 'Pick or create the vendor for this bill'; END IF;
  SELECT default_expense_account_id INTO v_acct FROM acct_vendors WHERE id = v_vendor;
  v_acct := coalesce(nullif(p_overrides->>'expense_account_id','')::uuid, v_acct, acct_role_account(d.tenant_id, d.entity_id, 'uncategorized_expense'));
  INSERT INTO acct_ap_bills(tenant_id, entity_id, vendor_id, bill_number, bill_date, due_date, currency, status, source, memo, inbox_id, review_status)
  VALUES (d.tenant_id, d.entity_id, v_vendor, coalesce(p_overrides->>'bill_number', d.doc_number), coalesce(nullif(p_overrides->>'bill_date','')::date, d.doc_date, current_date),
          coalesce(nullif(p_overrides->>'due_date','')::date, d.due_date), coalesce(d.extracted->>'currency','USD'), 'draft',
          CASE WHEN d.source = 'api' THEN 'upload' ELSE d.source END, coalesce(p_overrides->>'memo', d.extracted->>'memo'), d.id, 'for_review')
  RETURNING id INTO v_bill;
  v_lines := coalesce(p_overrides->'lines', d.extracted->'lines');
  IF v_lines IS NULL OR jsonb_array_length(v_lines) = 0 THEN
    v_lines := jsonb_build_array(jsonb_build_object('description', coalesce(d.extracted->>'vendor_name','Bill'), 'unit_cost', d.total));
  END IF;
  FOR l IN SELECT value FROM jsonb_array_elements(v_lines) LOOP
    INSERT INTO acct_ap_bill_lines(bill_id, line_no, description, quantity, unit_cost, tax_amount, expense_account_id, item_id, dimensions, tenant_id)
    VALUES (v_bill, NULL, coalesce(l->>'description','Line'), coalesce((l->>'quantity')::numeric,1),
            coalesce((l->>'unit_cost')::numeric, (l->>'amount')::numeric, 0), coalesce((l->>'tax_amount')::numeric, 0),
            coalesce(nullif(l->>'expense_account_id','')::uuid, CASE WHEN l ? 'item_id' THEN NULL ELSE v_acct END), nullif(l->>'item_id','')::uuid, '{}'::jsonb, d.tenant_id);
  END LOOP;
  IF d.attachment_id IS NOT NULL THEN
    UPDATE acct_attachments SET entity_type = 'acct_ap_bills', entity_id = v_bill::text WHERE id = d.attachment_id;
  END IF;
  UPDATE acct_document_inbox SET created_bill_id = v_bill, status = 'processed', updated_at = now() WHERE id = d.id;
  IF p_post THEN
    UPDATE acct_ap_bills SET review_status = 'ready' WHERE id = v_bill;
    PERFORM acct_post_bill(v_bill);
  END IF;
  RETURN v_bill;
END $$;

-- @seq 211
CREATE FUNCTION public.acct_inbox_set_extraction(p_inbox_id uuid, p_extracted jsonb, p_confidence numeric DEFAULT NULL::numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d acct_document_inbox%ROWTYPE; v_vendor uuid;
BEGIN
  SELECT * INTO d FROM acct_document_inbox WHERE id = p_inbox_id FOR UPDATE;
  PERFORM acct_assert_access(d.tenant_id);
  SELECT id INTO v_vendor FROM acct_vendors WHERE tenant_id = d.tenant_id AND is_active
     AND lower(coalesce(display_name, legal_name)) = lower(btrim(p_extracted->>'vendor_name')) LIMIT 1;
  IF v_vendor IS NULL THEN
    SELECT id INTO v_vendor FROM acct_vendors WHERE tenant_id = d.tenant_id AND is_active
       AND lower(legal_name) LIKE lower(btrim(p_extracted->>'vendor_name')) || '%' LIMIT 1;
  END IF;
  UPDATE acct_document_inbox SET extracted = p_extracted, confidence = p_confidence, status = CASE WHEN status = 'duplicate' THEN status ELSE 'for_review' END,
         vendor_id = coalesce(vendor_id, v_vendor), doc_number = p_extracted->>'doc_number', doc_date = nullif(p_extracted->>'doc_date','')::date,
         due_date = nullif(p_extracted->>'due_date','')::date, total = nullif(p_extracted->>'total','')::numeric,
         doc_kind = CASE WHEN doc_kind = 'unknown' THEN coalesce(p_extracted->>'doc_kind', 'bill') ELSE doc_kind END, updated_at = now()
   WHERE id = d.id;
  -- receipts: suggest the bank feed line it belongs to
  UPDATE acct_document_inbox x SET matched_bank_transaction_id = t.id
    FROM acct_bank_transactions t
   WHERE x.id = d.id AND x.doc_kind = 'receipt' AND x.matched_bank_transaction_id IS NULL
     AND t.tenant_id = d.tenant_id AND t.amount = -abs(nullif(p_extracted->>'total','')::numeric)
     AND abs(t.transaction_date - nullif(p_extracted->>'doc_date','')::date) <= 5
     AND t.review_status IN ('for_review','categorized');
END $$;

-- @seq 212
CREATE FUNCTION public.acct_ingest_processor_event(p_event jsonb, p_provider text DEFAULT 'stripe'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_id uuid; v_tenant uuid; v_status text;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' AND current_user NOT IN ('postgres','supabase_admin','service_role') THEN
    RAISE EXCEPTION 'Webhook ingestion is service-role only' USING ERRCODE = '42501'; END IF;
  SELECT id INTO v_tenant FROM tenants WHERE stripe_connect_account_id = p_event->>'account' AND p_event->>'account' IS NOT NULL;
  v_tenant := coalesce(v_tenant, nullif(p_event#>>'{data,object,metadata,tenant_id}','')::uuid);
  INSERT INTO acct_processor_events(provider, event_id, event_type, account_ref, tenant_id, livemode, payload)
  VALUES (p_provider, p_event->>'id', p_event->>'type', p_event->>'account', v_tenant, (p_event->>'livemode')::boolean, p_event)
  ON CONFLICT (provider, event_id) DO NOTHING
  RETURNING id INTO v_id;
  IF v_id IS NULL THEN   -- replay of an event we already have
    SELECT id, status INTO v_id, v_status FROM acct_processor_events WHERE provider = p_provider AND event_id = p_event->>'id';
    IF v_status IN ('processed','ignored') THEN RETURN jsonb_build_object('event', v_id, 'status', v_status, 'duplicate', true); END IF;
  END IF;
  RETURN acct_process_processor_event(v_id);
END $$;

-- @seq 217
CREATE FUNCTION public.acct_invite_contractor(p_vendor_id uuid, p_email text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v acct_vendors%ROWTYPE; v_token text := encode(gen_random_uuid()::text::bytea, 'hex') || encode(gen_random_uuid()::text::bytea, 'hex');
BEGIN
  SELECT * INTO v FROM acct_vendors WHERE id = p_vendor_id;
  PERFORM acct_assert_access(v.tenant_id);
  UPDATE acct_contractor_invites SET status = 'revoked' WHERE vendor_id = v.id AND status IN ('sent','opened');
  UPDATE acct_vendors SET vendor_kind = 'contractor', email = coalesce(email, p_email) WHERE id = v.id;
  INSERT INTO acct_contractor_invites(tenant_id, vendor_id, email, token_hash, invited_by)
  VALUES (v.tenant_id, v.id, lower(p_email), encode(sha256(convert_to(v_token,'UTF8')),'hex'), auth.uid());
  RETURN v_token;   -- the app emails this once
END $$;

-- @seq 218
CREATE FUNCTION public.acct_invoice_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_payment_terms%ROWTYPE; c crm_customers%ROWTYPE;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO c FROM crm_customers WHERE id = NEW.customer_id AND tenant_id = NEW.tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Customer not found for this company'; END IF;
    NEW.entity_id := coalesce(NEW.entity_id, acct_default_entity(NEW.tenant_id));
    NEW.invoice_date := coalesce(NEW.invoice_date, current_date);
    IF NEW.due_date IS NULL THEN
      SELECT * INTO t FROM acct_payment_terms WHERE id = NEW.terms_id;
      NEW.due_date := CASE WHEN NEW.document_kind = 'sales_receipt' THEN NEW.invoice_date ELSE NEW.invoice_date + coalesce(t.due_days, 30) END;
      NEW.terms := coalesce(NEW.terms, t.name);
    END IF;
    IF NEW.invoice_number IS NULL OR NEW.invoice_number = '' THEN
      NEW.invoice_number := acct_next_number(NEW.tenant_id, NEW.entity_id, NEW.document_kind, CASE WHEN NEW.document_kind = 'sales_receipt' THEN 'SR-' ELSE '' END);
    END IF;
    NEW.customer_email := coalesce(NEW.customer_email, c.email);
    NEW.bill_to_address := coalesce(NEW.bill_to_address, nullif(concat_ws(E'\n', acct_customer_name(c.id), c.address_line1, c.address_line2,
                            concat_ws(', ', c.city, concat_ws(' ', c.state, c.postal_code))), ''));
    NEW.public_token := coalesce(NEW.public_token, replace(gen_random_uuid()::text,'-','') || replace(gen_random_uuid()::text,'-',''));
    NEW.created_by := coalesce(NEW.created_by, auth.uid());
  ELSIF OLD.posted_journal_id IS NOT NULL THEN
    IF (NEW.customer_id, NEW.invoice_date, NEW.total, NEW.subtotal, NEW.tax_total, NEW.entity_id, NEW.shipping_amount, NEW.discount_total) IS DISTINCT FROM
       (OLD.customer_id, OLD.invoice_date, OLD.total, OLD.subtotal, OLD.tax_total, OLD.entity_id, OLD.shipping_amount, OLD.discount_total) THEN
      RAISE EXCEPTION 'Invoice % is posted; void it and re-issue to change customer, date or amounts', OLD.invoice_number; END IF;
  END IF;
  RETURN NEW;
END $$;

-- @seq 219
CREATE FUNCTION public.acct_invoice_inventory_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF OLD.posted_journal_id IS NULL AND NEW.posted_journal_id IS NOT NULL THEN
    PERFORM acct__inv_invoice_posted(NEW.id);
  END IF;
  IF NEW.status = 'void' AND OLD.status IS DISTINCT FROM 'void' THEN
    PERFORM acct__inv_reverse_source('acct_ar_invoices', NEW.id, coalesce(NEW.voided_at::date, NEW.invoice_date),
                                     'Void ' || NEW.invoice_number || ': inventory returned to stock');
  END IF;
  RETURN NULL;
END $$;

-- @seq 220
CREATE FUNCTION public.acct_invoice_line_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE iv acct_ar_invoices%ROWTYPE; it acct_items%ROWTYPE;
BEGIN
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = NEW.invoice_id;
  IF iv.posted_journal_id IS NOT NULL OR iv.status IN ('void','paid','written_off') THEN
    RAISE EXCEPTION 'Invoice % is posted; void it or issue a credit memo instead', iv.invoice_number; END IF;
  NEW.tenant_id := iv.tenant_id;
  IF NEW.line_no IS NULL THEN SELECT coalesce(max(line_no),0)+1 INTO NEW.line_no FROM acct_ar_invoice_lines WHERE invoice_id = NEW.invoice_id; END IF;
  IF NEW.item_id IS NOT NULL THEN
    SELECT * INTO it FROM acct_items WHERE id = NEW.item_id AND tenant_id = iv.tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Product/service not found'; END IF;
    IF NOT it.is_sold THEN RAISE EXCEPTION '% is not set up for sale', it.name; END IF;
    IF NOT it.is_active THEN RAISE EXCEPTION '% is inactive', it.name; END IF;
    NEW.revenue_account_id := coalesce(NEW.revenue_account_id, it.income_account_id);
    NEW.description := coalesce(nullif(NEW.description,''), it.sales_description, it.name);
    IF NEW.unit_price = 0 AND it.sales_price IS NOT NULL THEN NEW.unit_price := it.sales_price; END IF;
    NEW.sku := it.sku; NEW.tax_category := coalesce(NEW.tax_category, it.tax_category);
    IF TG_OP = 'INSERT' THEN NEW.taxable := it.taxable; END IF;
    IF it.item_type = 'gift_card' THEN NEW.taxable := false; NEW.tax_category := 'gift_card'; END IF;
    IF it.item_type = 'discount' THEN NEW.line_type := 'discount'; END IF;
  END IF;
  NEW.revenue_account_id := coalesce(NEW.revenue_account_id, acct_role_account(iv.tenant_id, iv.entity_id, 'default_income'));
  IF EXISTS (SELECT 1 FROM acct_chart_of_accounts WHERE id = NEW.revenue_account_id AND (is_control_account OR NOT is_posting_allowed OR tenant_id <> iv.tenant_id)) THEN
    RAISE EXCEPTION 'Line % cannot post to a control/header account', NEW.line_no; END IF;
  NEW.line_subtotal := round(NEW.quantity * NEW.unit_price - NEW.discount_amount, 2);
  IF NEW.line_type = 'discount' AND NEW.line_subtotal > 0 THEN NEW.line_subtotal := -NEW.line_subtotal; END IF;
  RETURN NEW;
END $$;

-- @seq 221
CREATE FUNCTION public.acct_invoice_recalc(p_invoice_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE iv acct_ar_invoices%ROWTYPE; v_sub numeric; v_disc numeric; v_tax jsonb; v_payload jsonb; v_taxtotal numeric := 0;
BEGIN
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id;
  PERFORM acct_assert_access(iv.tenant_id);
  SELECT coalesce(sum(line_subtotal),0) INTO v_sub FROM acct_ar_invoice_lines WHERE invoice_id = iv.id;
  v_disc := CASE WHEN iv.discount_percent IS NOT NULL THEN round(v_sub * iv.discount_percent / 100, 2) ELSE iv.discount_total END;
  v_payload := acct_invoice_tax_payload(iv.id, v_disc);
  IF iv.tax_jurisdiction_id IS NOT NULL THEN
    v_tax := acct_calculate_tax_summary(iv.tenant_id, iv.entity_id, iv.invoice_date, iv.tax_jurisdiction_id, iv.customer_id, v_payload);
    v_taxtotal := coalesce((v_tax->>'tax_total')::numeric, 0);
  END IF;
  IF iv.posted_journal_id IS NULL THEN
    UPDATE acct_ar_invoices SET subtotal = v_sub, discount_total = v_disc, tax_total = v_taxtotal,
           total = v_sub - v_disc + shipping_amount + v_taxtotal, updated_at = now() WHERE id = iv.id;
  END IF;
  RETURN jsonb_build_object('subtotal', v_sub, 'discount', v_disc, 'shipping', iv.shipping_amount, 'tax', v_taxtotal,
                            'total', v_sub - v_disc + iv.shipping_amount + v_taxtotal, 'deposit_requested', iv.deposit_requested,
                            'tax_detail', v_tax);
END $$;

-- @seq 222
CREATE FUNCTION public.acct_invoice_refresh_status(p_invoice_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  UPDATE acct_ar_invoices SET
    status = CASE WHEN posted_journal_id IS NULL THEN status
                  WHEN total - amount_paid - amount_credited <= 0 THEN 'paid'
                  WHEN amount_paid + amount_credited > 0 THEN 'partially_paid'
                  WHEN status IN ('paid','partially_paid') THEN 'open' ELSE status END,
    paid_at = CASE WHEN posted_journal_id IS NOT NULL AND total - amount_paid - amount_credited <= 0 THEN coalesce(paid_at, now()) END
   WHERE id = p_invoice_id AND status NOT IN ('void','written_off');
$$;

-- @seq 223
CREATE FUNCTION public.acct_invoice_tax_payload(p_invoice_id uuid, p_discount numeric) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  WITH l AS (SELECT * FROM acct_ar_invoice_lines WHERE invoice_id = p_invoice_id),
       pos AS (SELECT coalesce(sum(line_subtotal),0) s FROM l WHERE line_subtotal > 0),
       neg AS (SELECT coalesce(-sum(line_subtotal),0) s FROM l WHERE line_subtotal < 0)
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'line_ref', l.id::text,
           'amount', round(l.line_subtotal * (1 - (coalesce(p_discount,0) + neg.s) / nullif(pos.s,0)), 2),
           'quantity', l.quantity, 'tax_category', coalesce(l.tax_category,'general'), 'taxable', l.taxable, 'tax_code_id', l.tax_code_id)
         ) FILTER (WHERE l.line_subtotal > 0), '[]'::jsonb)
         || CASE WHEN (SELECT shipping_amount FROM acct_ar_invoices WHERE id = p_invoice_id) > 0 THEN
              jsonb_build_array(jsonb_build_object('line_ref','shipping','amount',(SELECT shipping_amount FROM acct_ar_invoices WHERE id = p_invoice_id),
                                                   'tax_category','shipping')) ELSE '[]'::jsonb END
    FROM l, pos, neg;
$$;

-- @seq 224
CREATE FUNCTION public.acct_invoice_unbilled_time(p_tenant_id uuid, p_customer_id uuid, p_through date DEFAULT CURRENT_DATE, p_invoice_id uuid DEFAULT NULL::uuid, p_invoice_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_inv uuid := p_invoice_id; t record; v_line uuid; v_rate numeric; n int := 0;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF v_inv IS NOT NULL AND NOT EXISTS (SELECT 1 FROM acct_ar_invoices WHERE id = v_inv AND tenant_id = p_tenant_id AND customer_id = p_customer_id AND status = 'draft') THEN
    RAISE EXCEPTION 'Time can only be added to a draft invoice for the same customer';
  END IF;
  FOR t IN SELECT te.*, it.sales_price, it.name item_name FROM acct_time_entries te LEFT JOIN acct_items it ON it.id = te.item_id
            WHERE te.tenant_id = p_tenant_id AND te.customer_id = p_customer_id AND te.billable AND te.invoiced_line_id IS NULL
              AND te.status IN ('open','approved') AND te.work_date <= p_through
            ORDER BY te.work_date, te.created_at FOR UPDATE OF te LOOP
    v_rate := coalesce(t.rate, t.sales_price);
    IF v_rate IS NULL THEN RAISE EXCEPTION 'Time on % has no rate; set a rate or a service item with a price', t.work_date; END IF;
    IF v_inv IS NULL THEN
      INSERT INTO acct_ar_invoices(tenant_id, entity_id, customer_id, invoice_number, invoice_date, due_date, currency, status)
      VALUES (p_tenant_id, coalesce(t.entity_id, acct_default_entity(p_tenant_id)), p_customer_id, NULL, p_invoice_date, NULL, 'USD', 'draft')
      RETURNING id INTO v_inv;
    END IF;
    INSERT INTO acct_ar_invoice_lines(invoice_id, line_no, description, quantity, unit_price, item_id, service_date, dimensions, tenant_id)
    VALUES (v_inv, NULL, to_char(t.work_date, 'Mon DD') || ': ' || coalesce(t.description, t.item_name, 'Services'), t.hours, v_rate, t.item_id,
            t.work_date, jsonb_build_object('time_entry_id', t.id), p_tenant_id)
    RETURNING id INTO v_line;
    UPDATE acct_time_entries SET invoiced_line_id = v_line, invoice_id = v_inv, status = 'invoiced' WHERE id = t.id;
    n := n + 1;
  END LOOP;
  IF n = 0 THEN RAISE EXCEPTION 'No unbilled time for this customer through %', p_through; END IF;
  PERFORM acct_invoice_recalc(v_inv);
  RETURN v_inv;
END $$;

-- @seq 225
CREATE FUNCTION public.acct_is_tenant_member(p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$ SELECT platform_is_tenant_member(p_tenant_id); $$;

-- @seq 226
CREATE FUNCTION public.acct_issue_gift_card(p_tenant_id uuid, p_amount numeric, p_code text DEFAULT NULL::text, p_customer_id uuid DEFAULT NULL::uuid, p_promotional_expense_account_id uuid DEFAULT NULL::uuid, p_sold_on_invoice_id uuid DEFAULT NULL::uuid, p_email text DEFAULT NULL::text, p_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid := acct_default_entity(p_tenant_id); v_id uuid; v_je uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_amount <= 0 THEN RAISE EXCEPTION 'Gift card amount must be positive'; END IF;
  IF p_sold_on_invoice_id IS NULL AND p_promotional_expense_account_id IS NULL THEN
    RAISE EXCEPTION 'Either sell the card on an invoice/sales receipt (gift card item) or give a promotional expense account'; END IF;
  INSERT INTO acct_gift_cards(tenant_id, entity_id, code, kind, status, initial_amount, balance, customer_id, issued_to_email, issued_reason)
  VALUES (p_tenant_id, v_entity, coalesce(p_code, 'GC-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))), 'gift_card', 'active', p_amount, p_amount,
          p_customer_id, p_email, CASE WHEN p_sold_on_invoice_id IS NOT NULL THEN 'sold' ELSE 'promotional' END)
  RETURNING id INTO v_id;
  IF p_promotional_expense_account_id IS NOT NULL THEN
    v_je := acct_post_entry(p_tenant_id, v_entity, p_date, jsonb_build_array(
              jsonb_build_object('account_id', p_promotional_expense_account_id, 'debit', p_amount, 'description', 'Promotional gift card'),
              jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'gift_card_liability'), 'credit', p_amount, 'description', 'Promotional gift card')),
            'manual', v_id::text, 'GC', 'Promotional gift card', 'gc-issue:' || v_id, NULL, NULL, NULL, false, false, 'acct_gift_cards', v_id);
  END IF;
  UPDATE acct_gift_cards SET posted_journal_id = v_je WHERE id = v_id;
  INSERT INTO acct_gift_card_transactions(tenant_id, gift_card_id, txn_type, amount, balance_after, reference, posted_journal_id)
  VALUES (p_tenant_id, v_id, 'issue', p_amount, p_amount, coalesce(p_sold_on_invoice_id::text, 'promo'), v_je);
  RETURN v_id;
END $$;

-- @seq 231
CREATE FUNCTION public.acct_je_after_post() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.status = 'posted' AND OLD.status IS DISTINCT FROM 'posted' AND OLD.status NOT IN ('reversed') THEN
    INSERT INTO acct_account_balances AS b (tenant_id, entity_id, book_id, account_id, period_id, debit, credit, closing_debit, closing_credit)
    SELECT NEW.tenant_id, NEW.entity_id, NEW.book_id, l.account_id, NEW.period_id, sum(l.debit), sum(l.credit),
           CASE WHEN NEW.is_closing THEN sum(l.debit) ELSE 0 END, CASE WHEN NEW.is_closing THEN sum(l.credit) ELSE 0 END
      FROM acct_journal_lines l WHERE l.journal_entry_id = NEW.id GROUP BY l.account_id
    ON CONFLICT (book_id, account_id, period_id) DO UPDATE
      SET debit = b.debit + EXCLUDED.debit, credit = b.credit + EXCLUDED.credit,
          closing_debit = b.closing_debit + EXCLUDED.closing_debit, closing_credit = b.closing_credit + EXCLUDED.closing_credit,
          updated_at = now();
  END IF;
  RETURN NEW;
END $$;

-- @seq 232
CREATE FUNCTION public.acct_je_before_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.entry_no IS NULL THEN NEW.entry_no := acct_next_seq(NEW.tenant_id, NEW.entity_id, 'journal'); END IF;
  IF NEW.status NOT IN ('draft','approved') THEN
    RAISE EXCEPTION 'Journal entries must be inserted as draft/approved and posted through acct_post_journal';
  END IF;
  RETURN NEW;
END $$;

-- @seq 233
CREATE FUNCTION public.acct_kpi_definitions_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct__eval_kpi(NEW.formula, (SELECT jsonb_object_agg(k, 1) FROM jsonb_object_keys(acct__kpi_tokens(NEW.tenant_id, current_date, current_date)) k));
  RETURN NEW;
END $$;

-- @seq 234
CREATE FUNCTION public.acct_kpi_value(p_tenant_id uuid, p_code text, p_from date, p_to date, p_entity_id uuid DEFAULT NULL::uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f text;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF NOT EXISTS (SELECT 1 FROM acct_kpi_definitions d WHERE d.tenant_id = p_tenant_id) THEN PERFORM acct__seed_kpis(p_tenant_id); END IF;
  SELECT formula INTO f FROM acct_kpi_definitions WHERE tenant_id = p_tenant_id AND code = p_code;
  IF f IS NULL THEN RAISE EXCEPTION 'Unknown KPI %', p_code; END IF;
  RETURN acct__eval_kpi(f, acct__kpi_tokens(p_tenant_id, p_from, p_to, p_entity_id));
END $$;

-- @seq 235
CREATE FUNCTION public.acct_kpis(p_tenant_id uuid, p_from date, p_to date, p_entity_id uuid DEFAULT NULL::uuid) RETURNS TABLE(code text, name text, unit text, value numeric, prior_value numeric, formula text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE w record; t_cur jsonb; t_pri jsonb;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF NOT EXISTS (SELECT 1 FROM acct_kpi_definitions d WHERE d.tenant_id = p_tenant_id) THEN PERFORM acct__seed_kpis(p_tenant_id); END IF;
  SELECT * INTO w FROM acct__prior_window(p_from, p_to);
  t_cur := acct__kpi_tokens(p_tenant_id, p_from, p_to, p_entity_id);
  t_pri := acct__kpi_tokens(p_tenant_id, w.prior_from, w.prior_to, p_entity_id);
  RETURN QUERY SELECT d.code, d.name, d.unit, acct__eval_kpi(d.formula, t_cur), acct__eval_kpi(d.formula, t_pri), d.formula
    FROM acct_kpi_definitions d WHERE d.tenant_id = p_tenant_id AND d.is_active ORDER BY d.sort_order, d.code;
END $$;

-- @seq 236
CREATE FUNCTION public.acct_legacy_preflight(p_tenant uuid) RETURNS TABLE(severity text, area text, item_count bigint, detail text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE v_entity uuid;
BEGIN
  PERFORM acct__assert_migrator(p_tenant);
  v_entity := acct_default_entity(p_tenant);

  RETURN QUERY SELECT 'info', 'legacy rows', count(*), 'chart_of_accounts' FROM chart_of_accounts WHERE tenant_id = p_tenant
  UNION ALL SELECT 'info', 'legacy rows', count(*), 'vendors' FROM vendors WHERE tenant_id = p_tenant
  UNION ALL SELECT 'info', 'legacy rows', count(*), 'bank_accounts' FROM bank_accounts WHERE tenant_id = p_tenant
  UNION ALL SELECT 'info', 'legacy rows', count(*), 'journal_entries' FROM journal_entries WHERE tenant_id = p_tenant
  UNION ALL SELECT 'info', 'legacy rows', count(*), 'bills' FROM bills WHERE tenant_id = p_tenant
  UNION ALL SELECT 'info', 'legacy rows', count(*), 'invoices' FROM invoices WHERE tenant_id = p_tenant
  UNION ALL SELECT 'info', 'legacy rows', count(*), 'erp_orders' FROM erp_orders WHERE tenant_id = p_tenant
  UNION ALL SELECT 'info', 'legacy rows', count(*), 'acct_tax_rates + acct_tax_rules'
              FROM (SELECT id FROM acct_tax_rates WHERE tenant_id = p_tenant UNION ALL SELECT id FROM acct_tax_rules WHERE tenant_id = p_tenant) x;

  IF v_entity IS NULL THEN
    RETURN QUERY SELECT 'error', 'company', 1::bigint, 'No accounting company yet - acct_migrate_legacy will bootstrap one (acct_bootstrap_company).';
  END IF;

  RETURN QUERY
  SELECT 'error', 'legacy journals', count(*), 'Unbalanced legacy journal entries (debits <> credits); they will be skipped: ' || string_agg(left(x.id::text,8), ', ')
    FROM (SELECT j.id FROM journal_entries j JOIN journal_lines l ON l.journal_id = j.id
           WHERE j.tenant_id = p_tenant GROUP BY j.id HAVING round(sum(coalesce(l.debit,0)) - sum(coalesce(l.credit,0)), 2) <> 0) x
  HAVING count(*) > 0
  UNION ALL
  SELECT 'warn', 'legacy journals', count(*), 'Legacy journals not marked posted; they will be skipped'
    FROM journal_entries WHERE tenant_id = p_tenant AND NOT coalesce(posted, false) HAVING count(*) > 0
  UNION ALL
  SELECT 'warn', 'chart of accounts', count(*), 'Legacy account codes that collide with an existing account of a different class; they will be created with a "-L" suffix: '
         || string_agg(c.code, ', ')
    FROM chart_of_accounts c JOIN acct_chart_of_accounts a ON a.tenant_id = c.tenant_id AND a.code = c.code
   WHERE c.tenant_id = p_tenant
     AND (c.type::text IN ('income','expense')) <> (a.account_type IN ('revenue','expense'))
  HAVING count(*) > 0
  UNION ALL
  SELECT 'error', 'account roles', count(*), 'System roles pointing at the wrong kind of account: ' || string_agg(r.role || '->' || a.code || ' ' || a.account_type, ', ')
    FROM acct_account_roles r JOIN acct_chart_of_accounts a ON a.id = r.account_id
   WHERE r.tenant_id = p_tenant AND (
         (r.role IN ('accounts_receivable','undeposited_funds','processor_clearing','inventory_asset','dispute_holding') AND a.account_type <> 'asset')
      OR (r.role IN ('accounts_payable','sales_tax_payable','gift_card_liability','customer_deposits','unapplied_cash') AND a.account_type <> 'liability')
      OR (r.role IN ('default_income','shipping_income','sales_returns','discounts_given','interest_income') AND a.account_type <> 'revenue')
      OR (r.role IN ('cogs','default_expense','processor_fees','bank_service_charges','chargeback_loss') AND a.account_type <> 'expense'))
  HAVING count(*) > 0
  UNION ALL
  SELECT 'info', 'bill payments', count(*), 'Payments whose cash_account_id is a bank register id: now resolved through acct_bank_gl() (the reported pay-flow bug)'
    FROM acct_ap_payments p WHERE p.tenant_id = p_tenant AND EXISTS (SELECT 1 FROM acct_bank_accounts b WHERE b.id = p.cash_account_id)
  HAVING count(*) > 0
  UNION ALL
  SELECT 'warn', 'bills', count(*), 'Open bills in the new tables with no ledger posting (call acct_post_bill or void)'
    FROM acct_ap_bills b WHERE b.tenant_id = p_tenant AND b.posted_journal_id IS NULL AND b.status IN ('open','partially_paid','paid')
  HAVING count(*) > 0
  UNION ALL
  SELECT 'warn', 'gift cards', count(*), 'Gift cards that expire less than 5 years after issue (CARD Act); fix before editing them'
    FROM acct_gift_cards g WHERE g.tenant_id = p_tenant AND g.expires_at IS NOT NULL AND g.expires_at < (g.created_at + interval '5 years')::date
  HAVING count(*) > 0
  UNION ALL
  SELECT 'warn', 'ledger', count(*), 'Existing journal entries whose lines do not balance'
    FROM (SELECT e.id FROM acct_journal_entries e JOIN acct_journal_lines l ON l.journal_entry_id = e.id
           WHERE e.tenant_id = p_tenant GROUP BY e.id HAVING sum(l.debit) <> sum(l.credit)) x
  HAVING count(*) > 0
  UNION ALL
  SELECT 'warn', 'customers', count(*), 'Legacy invoices whose customerId does not match a CRM customer; they will be skipped'
    FROM invoices i WHERE i.tenant_id = p_tenant AND NOT EXISTS (
      SELECT 1 FROM crm_customers c WHERE c.tenant_id = p_tenant
         AND (c.id::text = i."customerId" OR c.source_customer_id::text = i."customerId" OR c.external_customer_number = i."customerId"
              OR lower(c.email) = (SELECT lower(lc.email) FROM customers lc WHERE lc.id = i."customerId")))
  HAVING count(*) > 0;

  IF v_entity IS NOT NULL THEN
    RETURN QUERY
    SELECT CASE WHEN abs(x.gl - x.sub) > 0.005 THEN 'warn' ELSE 'info' END, 'tie-out', 1::bigint,
           format('A/R ledger %s vs open invoices %s', x.gl, x.sub)
      FROM (SELECT coalesce(acct_account_balance(acct_role_account(p_tenant, v_entity, 'accounts_receivable')),0) gl,
                   coalesce((SELECT sum(open_balance) FROM acct_ar_invoices WHERE tenant_id = p_tenant AND posted_journal_id IS NOT NULL AND status <> 'void'),0) sub) x
    UNION ALL
    SELECT CASE WHEN abs(x.gl - x.sub) > 0.005 THEN 'warn' ELSE 'info' END, 'tie-out', 1::bigint,
           format('A/P ledger %s vs open bills %s', x.gl, x.sub)
      FROM (SELECT coalesce(acct_account_balance(acct_role_account(p_tenant, v_entity, 'accounts_payable')),0) gl,
                   coalesce((SELECT sum(open_balance) FROM acct_ap_bills WHERE tenant_id = p_tenant AND posted_journal_id IS NOT NULL AND status <> 'void'),0) sub) x;
  END IF;
END $$;

-- @seq 237
CREATE FUNCTION public.acct_make_deposit(p_bank_account_id uuid, p_date date, p_receipt_ids uuid[], p_other_lines jsonb DEFAULT '[]'::jsonb, p_memo text DEFAULT NULL::text, p_cash_back numeric DEFAULT 0, p_cash_back_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_bank_accounts%ROWTYPE; v_id uuid; r record; o jsonb; v_lines jsonb := '[]'::jsonb; v_total numeric := 0; v_je uuid; v_src_gl uuid;
BEGIN
  SELECT * INTO b FROM acct_bank_accounts WHERE id = p_bank_account_id;
  PERFORM acct_assert_access(b.tenant_id);
  IF b.account_kind NOT IN ('checking','savings','money_market','cash','petty_cash') THEN RAISE EXCEPTION 'Deposits go into a bank account'; END IF;
  INSERT INTO acct_bank_deposits(tenant_id, entity_id, deposit_number, bank_account_id, deposit_date, memo, cash_back_amount, cash_back_account_id)
  VALUES (b.tenant_id, b.entity_id, acct_next_number(b.tenant_id, b.entity_id, 'deposit', 'DEP-'), b.id, p_date, p_memo, coalesce(p_cash_back,0), p_cash_back_account_id)
  RETURNING id INTO v_id;
  FOR r IN SELECT * FROM acct_ar_receipts WHERE id = ANY (coalesce(p_receipt_ids, '{}')) FOR UPDATE LOOP
    IF r.tenant_id <> b.tenant_id THEN RAISE EXCEPTION 'Payment belongs to another company'; END IF;
    IF r.status = 'void' THEN RAISE EXCEPTION 'Payment % is void', r.receipt_number; END IF;
    IF r.deposit_id IS NOT NULL THEN RAISE EXCEPTION 'Payment % is already deposited', r.receipt_number; END IF;
    IF r.payment_method = 'gift_card' THEN RAISE EXCEPTION 'Gift card redemptions are not cash and cannot be deposited'; END IF;
    IF r.deposit_account_id = b.id THEN RAISE EXCEPTION 'Payment % already went straight to this bank account', r.receipt_number; END IF;
    v_src_gl := acct_bank_gl(r.deposit_account_id);
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', v_src_gl, 'credit', r.amount - r.fee_amount, 'customer_id', r.customer_id::text,
                 'description', 'Deposit ' || r.receipt_number));
    INSERT INTO acct_bank_deposit_lines(tenant_id, deposit_id, receipt_id, received_from, amount) VALUES (b.tenant_id, v_id, r.id, acct_customer_name(r.customer_id), r.amount - r.fee_amount);
    UPDATE acct_ar_receipts SET deposit_id = v_id WHERE id = r.id;
    UPDATE acct_ar_invoices i SET status = 'deposited' FROM acct_ar_receipt_applications a
     WHERE a.receipt_id = r.id AND i.id = a.invoice_id AND i.status = 'paid';
    v_total := v_total + r.amount - r.fee_amount;
  END LOOP;
  FOR o IN SELECT value FROM jsonb_array_elements(coalesce(p_other_lines,'[]'::jsonb)) LOOP
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', o->>'account_id',
                 'credit', greatest((o->>'amount')::numeric, 0), 'debit', greatest(-(o->>'amount')::numeric, 0), 'description', coalesce(o->>'description','Other deposit')));
    INSERT INTO acct_bank_deposit_lines(tenant_id, deposit_id, account_id, received_from, description, amount)
    VALUES (b.tenant_id, v_id, (o->>'account_id')::uuid, o->>'received_from', o->>'description', (o->>'amount')::numeric);
    v_total := v_total + (o->>'amount')::numeric;
  END LOOP;
  IF coalesce(p_cash_back,0) > 0 THEN
    IF p_cash_back_account_id IS NULL THEN RAISE EXCEPTION 'Choose where the cash back goes'; END IF;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', p_cash_back_account_id, 'debit', p_cash_back, 'description', 'Cash back'));
    v_total := v_total - p_cash_back;
  END IF;
  IF v_total <= 0 THEN RAISE EXCEPTION 'Deposit total must be positive'; END IF;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', b.gl_account_id, 'debit', v_total, 'description', coalesce(p_memo, 'Bank deposit'))) || v_lines;
  v_je := acct_post_entry(b.tenant_id, b.entity_id, p_date, v_lines, 'bank', v_id::text, 'DEP', coalesce(p_memo, 'Bank deposit'), 'deposit:' || v_id,
                          NULL, NULL, NULL, false, false, 'acct_bank_deposits', v_id);
  UPDATE acct_bank_deposits SET total = v_total, posted_journal_id = v_je WHERE id = v_id;
  RETURN v_id;
END $$;

-- @seq 238
CREATE FUNCTION public.acct_mark_bill_reviewed(p_bill_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_ap_bills%ROWTYPE;
BEGIN
  SELECT * INTO b FROM acct_ap_bills WHERE id = p_bill_id;
  PERFORM acct_assert_access(b.tenant_id);
  UPDATE acct_ap_bills SET review_status = 'ready' WHERE id = b.id;
END $$;

-- @seq 239
CREATE FUNCTION public.acct_mark_invoice_paid(p_invoice_id uuid, p_date date, p_method text, p_deposit_bank_account_id uuid DEFAULT NULL::uuid, p_reference text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE iv acct_ar_invoices%ROWTYPE; v_amt numeric;
BEGIN
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  PERFORM acct_assert_access(iv.tenant_id);
  IF iv.posted_journal_id IS NULL THEN PERFORM acct_post_invoice(iv.id); SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id; END IF;
  v_amt := coalesce(p_amount, iv.open_balance);
  IF v_amt <= 0 THEN RAISE EXCEPTION 'Invoice % has no open balance', iv.invoice_number; END IF;
  RETURN acct_record_receipt(iv.tenant_id, iv.customer_id, p_date, v_amt, p_method, p_deposit_bank_account_id,
           jsonb_build_array(jsonb_build_object('invoice_id', iv.id, 'amount', v_amt)), p_reference, NULL, NULL,
           'mark_paid:' || iv.id || ':' || v_amt, 0, iv.entity_id, 'Marked paid');
END $$;

-- @seq 240
CREATE FUNCTION public.acct_match_bank_transaction(p_bank_txn_id uuid, p_journal_line_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_bank_transactions%ROWTYPE; b acct_bank_accounts%ROWTYPE; l acct_journal_lines%ROWTYPE; v_signed numeric;
BEGIN
  SELECT * INTO t FROM acct_bank_transactions WHERE id = p_bank_txn_id FOR UPDATE;
  PERFORM acct_assert_access(t.tenant_id);
  IF t.review_status IN ('posted','matched') THEN RAISE EXCEPTION 'Already in the books'; END IF;
  SELECT * INTO b FROM acct_bank_accounts WHERE id = t.bank_account_id;
  SELECT * INTO l FROM acct_journal_lines WHERE id = p_journal_line_id;
  IF NOT FOUND OR l.account_id <> b.gl_account_id THEN RAISE EXCEPTION 'That ledger line is not on this register'; END IF;
  IF EXISTS (SELECT 1 FROM acct_bank_transactions WHERE matched_journal_line_id = l.id AND id <> t.id) THEN
    RAISE EXCEPTION 'That ledger line is already matched to another bank transaction'; END IF;
  v_signed := l.debit - l.credit;   -- money in = debit on the register GL (asset or liability alike)
  IF v_signed <> t.amount THEN RAISE EXCEPTION 'Amounts differ: bank % vs books %', t.amount, v_signed; END IF;
  UPDATE acct_journal_lines SET cleared_status = 'cleared', cleared_at = now() WHERE id = l.id AND cleared_status = 'uncleared';
  UPDATE acct_bank_transactions SET review_status = 'matched', match_status = 'matched', matched_journal_line_id = l.id,
         posted_journal_id = l.journal_entry_id, reviewed_by = auth.uid(), reviewed_at = now() WHERE id = t.id;
END $$;

-- @seq 241
CREATE FUNCTION public.acct_match_receipts(p_tenant_id uuid, p_days integer DEFAULT 5, p_min_similarity numeric DEFAULT 0.30) RETURNS TABLE(receipt_source text, receipt_id uuid, vendor_name text, total numeric, receipt_date date, outcome text, matched_type text, matched_id uuid, score numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r record; c record; c2 record; v_att uuid; v_path text; v_name text; v_mime text; v_bt uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR r IN
    SELECT 'extraction'::text AS src, re.id, re.vendor_name AS vname, re.extracted_total AS amt, re.receipt_date AS rdate, re.attachment_id
      FROM acct_receipt_extractions re
     WHERE re.tenant_id = p_tenant_id AND re.matched_bank_transaction_id IS NULL AND coalesce(re.status,'') NOT IN ('matched','ignored','rejected')
       AND re.extracted_total IS NOT NULL AND re.receipt_date IS NOT NULL
    UNION ALL
    SELECT 'inbox', d.id, coalesce(d.extracted->>'vendor_name', (SELECT coalesce(v.display_name, v.legal_name) FROM acct_vendors v WHERE v.id = d.vendor_id)),
           d.total, d.doc_date, d.attachment_id
      FROM acct_document_inbox d
     WHERE d.tenant_id = p_tenant_id AND d.doc_kind = 'receipt' AND d.status IN ('uploaded','for_review')
       AND d.matched_bank_transaction_id IS NULL AND d.created_spend_id IS NULL AND d.created_bill_id IS NULL
       AND d.total IS NOT NULL AND d.doc_date IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM acct_receipt_extractions re WHERE re.inbox_id = d.id)
  LOOP
    c := NULL; c2 := NULL;
    FOR c IN
      WITH cand AS (
        SELECT 'acct_spend_transactions'::text AS typ, sp.id, sp.bank_transaction_id AS bt_id, sp.payment_date AS dt,
               coalesce(sp.payee_name, v.display_name, v.legal_name, '') AS nm
          FROM acct_spend_transactions sp LEFT JOIN acct_vendors v ON v.id = sp.payee_vendor_id
         WHERE sp.tenant_id = p_tenant_id AND sp.status = 'posted' AND sp.total = r.amt AND abs(sp.payment_date - r.rdate) <= p_days
           AND sp.inbox_id IS NULL
           AND NOT EXISTS (SELECT 1 FROM acct_attachments at WHERE at.entity_type = 'acct_spend_transactions' AND at.entity_id = sp.id::text)
        UNION ALL
        SELECT 'acct_bank_transactions', bt.id, bt.id, bt.transaction_date, coalesce(bt.normalized_descriptor, bt.payee, bt.description, '')
          FROM acct_bank_transactions bt
         WHERE bt.tenant_id = p_tenant_id AND bt.amount = -r.amt AND abs(bt.transaction_date - r.rdate) <= p_days
           AND bt.receipt_attachment_id IS NULL AND bt.review_status <> 'excluded'
           AND NOT EXISTS (SELECT 1 FROM acct_receipt_extractions re WHERE re.matched_bank_transaction_id = bt.id)
           AND NOT EXISTS (SELECT 1 FROM acct_document_inbox d WHERE d.matched_bank_transaction_id = bt.id)
           AND NOT EXISTS (SELECT 1 FROM acct_spend_transactions sp WHERE sp.bank_transaction_id = bt.id AND sp.status = 'posted'))  -- covered by the spend candidate
      SELECT cand.*, round(0.5 + 0.2 * (1 - abs(cand.dt - r.rdate)::numeric / (p_days + 1))
                       + 0.3 * coalesce(similarity(lower(coalesce(r.vname,'')), lower(cand.nm)), 0)::numeric, 3) AS sc,
             coalesce(similarity(lower(coalesce(r.vname,'')), lower(cand.nm)), 0)::numeric AS sim
        FROM cand ORDER BY 6 DESC LIMIT 2
    LOOP
      IF c2 IS NULL THEN c2 := c; ELSE EXIT; END IF;
    END LOOP;
    -- after the loop: c2 = best, c = second best (or the same row when only one)
    IF c2 IS NULL THEN
      receipt_source := r.src; receipt_id := r.id; vendor_name := r.vname; total := r.amt; receipt_date := r.rdate;
      outcome := 'no_match'; matched_type := NULL; matched_id := NULL; score := NULL; RETURN NEXT; CONTINUE;
    END IF;
    IF (c.id IS DISTINCT FROM c2.id AND c2.sc - c.sc < 0.05) OR (c2.sim < p_min_similarity AND c.id IS DISTINCT FROM c2.id) THEN
      receipt_source := r.src; receipt_id := r.id; vendor_name := r.vname; total := r.amt; receipt_date := r.rdate;
      outcome := 'ambiguous'; matched_type := c2.typ; matched_id := c2.id; score := c2.sc; RETURN NEXT;
      IF r.src = 'inbox' THEN UPDATE acct_document_inbox SET status = 'for_review', updated_at = now() WHERE id = r.id; END IF;
      CONTINUE;
    END IF;
    -- link the receipt file to the matched record(s)
    v_att := NULL;
    IF r.attachment_id IS NOT NULL THEN
      SELECT storage_path, file_name, mime_type INTO v_path, v_name, v_mime FROM acct_attachments WHERE id = r.attachment_id;
    ELSIF r.src = 'inbox' THEN
      SELECT storage_path, coalesce(file_name, 'receipt'), NULL INTO v_path, v_name, v_mime FROM acct_document_inbox WHERE id = r.id;
    END IF;
    IF v_path IS NOT NULL THEN
      INSERT INTO acct_attachments(tenant_id, entity_type, entity_id, file_name, storage_path, mime_type, uploaded_by)
      VALUES (p_tenant_id, c2.typ, c2.id::text, v_name, v_path, v_mime, auth.uid()) RETURNING id INTO v_att;
    END IF;
    v_bt := c2.bt_id;
    IF v_bt IS NOT NULL THEN
      UPDATE acct_bank_transactions SET receipt_attachment_id = coalesce(receipt_attachment_id, v_att) WHERE id = v_bt;
    END IF;
    IF r.src = 'extraction' THEN
      UPDATE acct_receipt_extractions SET matched_bank_transaction_id = v_bt, status = 'matched', updated_at = now(),
             raw_extraction = coalesce(raw_extraction,'{}'::jsonb) || jsonb_build_object('matched_type', c2.typ, 'matched_id', c2.id, 'match_score', c2.sc)
       WHERE id = r.id;
    ELSE
      UPDATE acct_document_inbox SET matched_bank_transaction_id = v_bt, status = 'processed', updated_at = now(),
             created_spend_id = CASE WHEN c2.typ = 'acct_spend_transactions' THEN c2.id ELSE created_spend_id END
       WHERE id = r.id;
    END IF;
    receipt_source := r.src; receipt_id := r.id; vendor_name := r.vname; total := r.amt; receipt_date := r.rdate;
    outcome := 'matched'; matched_type := c2.typ; matched_id := c2.id; score := c2.sc; RETURN NEXT;
  END LOOP;
END $$;

-- @seq 242
CREATE FUNCTION public.acct_migrate_legacy(p_tenant uuid, p_dry_run boolean DEFAULT true, p_include_orders boolean DEFAULT false) RETURNS TABLE(step text, found integer, migrated integer, linked integer, skipped integer, issues jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE
  v_entity uuid; v_cash uuid; v_ar uuid; v_ap uuid; v_obe uuid;
  r record; l record; v_id uuid; v_je uuid; v_lines jsonb; v_type text; v_sub text; v_code text; v_n int;
  v_amt numeric; v_diff numeric; v_first_acct uuid; v_cust uuid; v_status text; v_date date;
  res jsonb := '{}'::jsonb;   -- step -> {found,migrated,linked,skipped,issues[]}
  v_step text;
BEGIN
  PERFORM acct__assert_migrator(p_tenant);

  <<work>>
  BEGIN
    -- ---------------------------------------------------------------- company
    v_entity := acct_default_entity(p_tenant);
    IF v_entity IS NULL THEN v_entity := acct_bootstrap_company(p_tenant); END IF;
    PERFORM acct_seed_default_coa(p_tenant, v_entity);           -- adds missing system accounts/roles only
    v_ar  := acct_role_account(p_tenant, v_entity, 'accounts_receivable');
    v_ap  := acct_role_account(p_tenant, v_entity, 'accounts_payable');
    v_obe := acct_role_account(p_tenant, v_entity, 'opening_balance_equity');

    -- ---------------------------------------------------------------- chart of accounts
    v_step := 'chart_of_accounts';
    res := res || jsonb_build_object(v_step, jsonb_build_object('found',0,'migrated',0,'linked',0,'skipped',0,'issues','[]'::jsonb));
    FOR r IN SELECT * FROM chart_of_accounts WHERE tenant_id = p_tenant ORDER BY code LOOP
      res := jsonb_set(res, ARRAY[v_step,'found'], to_jsonb((res#>>ARRAY[v_step,'found'])::int + 1));
      CONTINUE WHEN acct__legacy_id(p_tenant, 'chart_of_accounts', r.id::text) IS NOT NULL;
      BEGIN
        v_type := CASE r.type::text WHEN 'income' THEN 'revenue' ELSE r.type::text END;
        v_sub := CASE
          WHEN lower(coalesce(r.subtype,'')) IN ('bank','cash','accounts_receivable','inventory','fixed_asset','other_current_asset','other_asset',
               'accounts_payable','credit_card','other_current_liability','long_term_liability','line_of_credit','equity',
               'income','other_income','cogs','expense','other_expense') THEN lower(r.subtype)
          WHEN r.subtype ILIKE '%cost of goods%' OR r.subtype ILIKE '%cogs%' THEN 'cogs'
          WHEN r.subtype ILIKE '%bank%' OR r.subtype ILIKE '%checking%' OR r.subtype ILIKE '%saving%' THEN 'bank'
          WHEN r.subtype ILIKE '%receivable%' THEN 'accounts_receivable'
          WHEN r.subtype ILIKE '%payable%' AND r.subtype NOT ILIKE '%tax%' THEN 'accounts_payable'
          WHEN r.subtype ILIKE '%credit card%' THEN 'credit_card'
          ELSE CASE v_type WHEN 'asset' THEN 'other_current_asset' WHEN 'liability' THEN 'other_current_liability'
                           WHEN 'equity' THEN 'equity' WHEN 'revenue' THEN 'income' ELSE 'expense' END END;
        SELECT a.id INTO v_id FROM acct_chart_of_accounts a
         WHERE a.tenant_id = p_tenant AND a.code = r.code AND (a.account_type IN ('revenue','expense')) = (v_type IN ('revenue','expense'));
        IF v_id IS NOT NULL THEN
          INSERT INTO acct_legacy_map VALUES (p_tenant, 'chart_of_accounts', r.id::text, 'acct_chart_of_accounts', v_id, 'matched existing code ' || r.code);
          res := jsonb_set(res, ARRAY[v_step,'linked'], to_jsonb((res#>>ARRAY[v_step,'linked'])::int + 1));
        ELSE
          v_code := CASE WHEN EXISTS (SELECT 1 FROM acct_chart_of_accounts WHERE tenant_id = p_tenant AND code = r.code) THEN r.code || '-L' ELSE r.code END;
          INSERT INTO acct_chart_of_accounts(tenant_id, entity_id, code, name, account_type, subtype, detail_type, description, currency,
                 is_control_account, is_reconcilable, is_posting_allowed, is_system, is_active, metadata)
          VALUES (p_tenant, v_entity, v_code, r.name, v_type, v_sub, coalesce(nullif(r.subtype,''), v_sub), r.description,
                  upper(coalesce(nullif(r.currency,''),'USD')), false, v_sub IN ('bank','cash','credit_card','line_of_credit'), true, false,
                  coalesce(r.is_active, true), jsonb_build_object('legacy_id', r.id, 'legacy_table', 'chart_of_accounts'))
          RETURNING id INTO v_id;
          INSERT INTO acct_legacy_map VALUES (p_tenant, 'chart_of_accounts', r.id::text, 'acct_chart_of_accounts', v_id, NULL);
          res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
        END IF;
        -- legacy opening balance -> opening entry against Opening Balance Equity
        IF coalesce(r.opening_balance,0) <> 0 THEN
          PERFORM acct_post_entry(p_tenant, v_entity, coalesce((SELECT min(entry_date) - 1 FROM journal_entries WHERE tenant_id = p_tenant), r.created_at::date, current_date),
            jsonb_build_array(
              jsonb_build_object('account_id', v_id,
                 'debit',  CASE WHEN (v_type IN ('asset','expense')) = (r.opening_balance > 0) THEN abs(r.opening_balance) ELSE 0 END,
                 'credit', CASE WHEN (v_type IN ('asset','expense')) = (r.opening_balance > 0) THEN 0 ELSE abs(r.opening_balance) END,
                 'description','Legacy opening balance'),
              jsonb_build_object('account_id', v_obe,
                 'debit',  CASE WHEN (v_type IN ('asset','expense')) = (r.opening_balance > 0) THEN 0 ELSE abs(r.opening_balance) END,
                 'credit', CASE WHEN (v_type IN ('asset','expense')) = (r.opening_balance > 0) THEN abs(r.opening_balance) ELSE 0 END,
                 'description','Legacy opening balance')),
            'opening_balance', r.id::text, r.code, 'Legacy opening balance ' || r.code, 'legacy-ob:' || r.id);
        END IF;
      EXCEPTION WHEN OTHERS THEN
        res := jsonb_set(res, ARRAY[v_step,'skipped'], to_jsonb((res#>>ARRAY[v_step,'skipped'])::int + 1));
        res := jsonb_set(res, ARRAY[v_step,'issues'], (res#>ARRAY[v_step,'issues']) || jsonb_build_object('legacy_id', r.id, 'code', r.code, 'error', SQLERRM));
      END;
    END LOOP;

    -- ---------------------------------------------------------------- vendors
    v_step := 'vendors';
    res := res || jsonb_build_object(v_step, jsonb_build_object('found',0,'migrated',0,'linked',0,'skipped',0,'issues','[]'::jsonb));
    FOR r IN SELECT * FROM vendors WHERE tenant_id = p_tenant ORDER BY created_at LOOP
      res := jsonb_set(res, ARRAY[v_step,'found'], to_jsonb((res#>>ARRAY[v_step,'found'])::int + 1));
      CONTINUE WHEN acct__legacy_id(p_tenant, 'vendors', r.id::text) IS NOT NULL;
      BEGIN
        SELECT v.id INTO v_id FROM acct_vendors v
         WHERE v.tenant_id = p_tenant AND (v.external_vendor_id = r.id::text OR lower(v.legal_name) = lower(r.name)
               OR (r.email IS NOT NULL AND lower(v.email) = lower(r.email))) LIMIT 1;
        IF v_id IS NOT NULL THEN
          INSERT INTO acct_legacy_map VALUES (p_tenant, 'vendors', r.id::text, 'acct_vendors', v_id, 'matched existing vendor');
          res := jsonb_set(res, ARRAY[v_step,'linked'], to_jsonb((res#>>ARRAY[v_step,'linked'])::int + 1));
        ELSE
          INSERT INTO acct_vendors(tenant_id, entity_id, external_vendor_id, vendor_number, legal_name, display_name, company_name, email, phone,
                 payment_terms_days, is_active, notes, metadata)
          VALUES (p_tenant, v_entity, r.id::text, nullif(r.code,''), r.name, r.name, r.name, r.email, r.phone,
                  nullif(regexp_replace(coalesce(r.payment_terms,''), '\D', '', 'g'), '')::int,
                  coalesce(r.status,'active') NOT IN ('inactive','archived','disabled','deleted'),
                  CASE WHEN r.contact_name IS NOT NULL THEN 'Contact: ' || r.contact_name END,
                  jsonb_build_object('legacy_table','vendors','legacy_payment_terms', r.payment_terms))
          RETURNING id INTO v_id;
          INSERT INTO acct_legacy_map VALUES (p_tenant, 'vendors', r.id::text, 'acct_vendors', v_id, NULL);
          res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
        END IF;
      EXCEPTION WHEN OTHERS THEN
        res := jsonb_set(res, ARRAY[v_step,'skipped'], to_jsonb((res#>>ARRAY[v_step,'skipped'])::int + 1));
        res := jsonb_set(res, ARRAY[v_step,'issues'], (res#>ARRAY[v_step,'issues']) || jsonb_build_object('legacy_id', r.id, 'name', r.name, 'error', SQLERRM));
      END;
    END LOOP;

    -- ---------------------------------------------------------------- bank accounts
    v_step := 'bank_accounts';
    res := res || jsonb_build_object(v_step, jsonb_build_object('found',0,'migrated',0,'linked',0,'skipped',0,'issues','[]'::jsonb));
    FOR r IN SELECT * FROM bank_accounts WHERE tenant_id = p_tenant ORDER BY created_at LOOP
      res := jsonb_set(res, ARRAY[v_step,'found'], to_jsonb((res#>>ARRAY[v_step,'found'])::int + 1));
      CONTINUE WHEN acct__legacy_id(p_tenant, 'bank_accounts', r.id::text) IS NOT NULL;
      BEGIN
        v_id := acct__legacy_id(p_tenant, 'chart_of_accounts', r.account_id::text);
        IF v_id IS NULL THEN v_id := (SELECT id FROM acct_chart_of_accounts WHERE id = r.account_id AND tenant_id = p_tenant); END IF;
        IF v_id IS NULL THEN RAISE EXCEPTION 'Bank account % has no mapped GL account', r.name; END IF;
        INSERT INTO acct_bank_accounts(tenant_id, entity_id, name, institution_name, account_type, account_kind, masked_account_number, currency,
               gl_account_id, provider, provider_account_id, last_sync_at, is_active, metadata)
        VALUES (p_tenant, v_entity, r.name, r.bank_name, 'checking',
                CASE WHEN r.name ILIKE '%saving%' THEN 'savings' ELSE 'checking' END,
                CASE WHEN r.account_number IS NOT NULL THEN '****' || right(regexp_replace(r.account_number, '\D', '', 'g'), 4) END,
                upper(coalesce(nullif(r.currency,''),'USD')), v_id,
                CASE WHEN r.stripe_financial_connection_id IS NOT NULL THEN 'stripe_financial_connections' END,
                r.stripe_financial_connection_id, r.last_synced_at, true,
                jsonb_build_object('legacy_table','bank_accounts','branch', r.bank_branch, 'stripe_account_id', r.stripe_account_id))
        RETURNING id INTO v_id;
        INSERT INTO acct_legacy_map VALUES (p_tenant, 'bank_accounts', r.id::text, 'acct_bank_accounts', v_id, 'full account number NOT copied (last 4 only)');
        res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
      EXCEPTION WHEN OTHERS THEN
        res := jsonb_set(res, ARRAY[v_step,'skipped'], to_jsonb((res#>>ARRAY[v_step,'skipped'])::int + 1));
        res := jsonb_set(res, ARRAY[v_step,'issues'], (res#>ARRAY[v_step,'issues']) || jsonb_build_object('legacy_id', r.id, 'name', r.name, 'error', SQLERRM));
      END;
    END LOOP;

    -- cash account used for legacy payments that never had their own journal
    v_cash := coalesce((SELECT b.gl_account_id FROM acct_bank_accounts b WHERE b.tenant_id = p_tenant AND b.account_kind = 'checking' AND b.is_active ORDER BY b.created_at LIMIT 1),
                       (SELECT id FROM acct_chart_of_accounts WHERE tenant_id = p_tenant AND code = '1000'));

    -- ---------------------------------------------------------------- legacy journals
    v_step := 'journal_entries';
    res := res || jsonb_build_object(v_step, jsonb_build_object('found',0,'migrated',0,'linked',0,'skipped',0,'issues','[]'::jsonb));
    FOR r IN SELECT * FROM journal_entries WHERE tenant_id = p_tenant ORDER BY entry_date, created_at LOOP
      res := jsonb_set(res, ARRAY[v_step,'found'], to_jsonb((res#>>ARRAY[v_step,'found'])::int + 1));
      CONTINUE WHEN acct__legacy_id(p_tenant, 'journal_entries', r.id::text) IS NOT NULL;
      BEGIN
        IF NOT coalesce(r.posted, false) THEN RAISE EXCEPTION 'not posted in the legacy system'; END IF;
        v_lines := '[]'::jsonb;
        FOR l IN SELECT * FROM journal_lines WHERE journal_id = r.id ORDER BY created_at, id LOOP
          v_id := coalesce(acct__legacy_id(p_tenant, 'chart_of_accounts', l.account_id::text),
                           (SELECT id FROM acct_chart_of_accounts WHERE id = l.account_id AND tenant_id = p_tenant));
          IF v_id IS NULL THEN RAISE EXCEPTION 'line % uses unmapped account %', l.id, l.account_id; END IF;
          CONTINUE WHEN coalesce(l.debit,0) = 0 AND coalesce(l.credit,0) = 0;
          -- control accounts need a party: take it from the line, its legacy invoice, or the bill that owns this journal
          v_cust := coalesce(acct__legacy_customer(p_tenant, l.customer_id),
                             acct__legacy_customer(p_tenant, (SELECT i."customerId" FROM invoices i WHERE i.id = l.invoice_id)));
          v_first_acct := acct__legacy_vendor(p_tenant, v_entity, (SELECT b.vendor_id FROM bills b WHERE b.journal_id = r.id LIMIT 1));
          v_lines := v_lines || jsonb_build_object('account_id', v_id, 'debit', coalesce(l.debit,0), 'credit', coalesce(l.credit,0),
                       'description', l.description, 'customer_id', v_cust::text, 'vendor_id', v_first_acct::text,
                       'dimensions', jsonb_strip_nulls(jsonb_build_object('legacy_invoice_id', l.invoice_id, 'legacy_payment_id', l.payment_id,
                                     'legacy_order_id', l.order_id, 'legacy_product_id', l.product_id)));
        END LOOP;
        IF jsonb_array_length(v_lines) < 2 THEN RAISE EXCEPTION 'fewer than two non-zero lines'; END IF;
        v_je := acct_post_entry(p_tenant, v_entity, r.entry_date, v_lines, 'import', r.id::text, r.reference,
                                coalesce(r.memo, 'Legacy journal') , 'legacy-je:' || r.id, NULL, NULL,
                                upper(coalesce(nullif(r.currency,''),'USD')), false, false, 'journal_entries', NULL);
        INSERT INTO acct_legacy_map VALUES (p_tenant, 'journal_entries', r.id::text, 'acct_journal_entries', v_je, r.source);
        res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
      EXCEPTION WHEN OTHERS THEN
        res := jsonb_set(res, ARRAY[v_step,'skipped'], to_jsonb((res#>>ARRAY[v_step,'skipped'])::int + 1));
        res := jsonb_set(res, ARRAY[v_step,'issues'], (res#>ARRAY[v_step,'issues']) || jsonb_build_object('legacy_id', r.id, 'reference', r.reference, 'error', SQLERRM));
      END;
    END LOOP;

    -- ---------------------------------------------------------------- bills
    v_step := 'bills';
    res := res || jsonb_build_object(v_step, jsonb_build_object('found',0,'migrated',0,'linked',0,'skipped',0,'issues','[]'::jsonb));
    FOR r IN SELECT * FROM bills WHERE tenant_id = p_tenant ORDER BY issue_date, created_at LOOP
      res := jsonb_set(res, ARRAY[v_step,'found'], to_jsonb((res#>>ARRAY[v_step,'found'])::int + 1));
      CONTINUE WHEN acct__legacy_id(p_tenant, 'bills', r.id::text) IS NOT NULL;
      BEGIN
        IF r.status::text = 'void' THEN RAISE EXCEPTION 'void in the legacy system (not migrated)'; END IF;
        v_id := acct__legacy_vendor(p_tenant, v_entity, r.vendor_id);
        IF v_id IS NULL THEN RAISE EXCEPTION 'vendor % not found in legacy vendors or customers', r.vendor_id; END IF;
        INSERT INTO acct_ap_bills(tenant_id, entity_id, vendor_id, bill_number, bill_date, due_date, currency, exchange_rate,
               subtotal, tax_total, total, status, source, source_system, external_id, memo)
        VALUES (p_tenant, v_entity, v_id, nullif(r.number,''), r.issue_date, r.due_date, upper(coalesce(nullif(r.currency,''),'USD')),
                coalesce(r.exchange_rate,1), coalesce(r.subtotal,0), coalesce(r.tax_total,0), coalesce(r.total,0), 'draft',
                'import', 'legacy_bills', r.id::text, r.notes)
        RETURNING id INTO v_id;
        v_n := 0; v_first_acct := NULL;
        FOR l IN SELECT * FROM bill_items WHERE bill_id = r.id ORDER BY position NULLS LAST, created_at LOOP
          v_n := v_n + 1;
          v_je := coalesce(acct__legacy_id(p_tenant, 'chart_of_accounts', l.account_id::text),
                           (SELECT id FROM acct_chart_of_accounts WHERE id = l.account_id AND tenant_id = p_tenant));
          IF v_je IS NULL THEN RAISE EXCEPTION 'bill line uses unmapped account %', l.account_id; END IF;
          v_first_acct := coalesce(v_first_acct, v_je);
          INSERT INTO acct_ap_bill_lines(bill_id, line_no, description, quantity, unit_cost, expense_account_id, item_ref, tenant_id, dimensions)
          VALUES (v_id, v_n, coalesce(nullif(l.description,''), 'Legacy line'), coalesce(l.quantity,1),
                  coalesce(l.unit_price,0) - coalesce(l.discount,0) / nullif(coalesce(l.quantity,1),0),
                  v_je, coalesce(l.product_id, l.inventory_item_id), p_tenant, '{}'::jsonb);
        END LOOP;
        IF v_n = 0 THEN   -- header-only legacy bill: one line for the whole amount
          v_first_acct := coalesce(acct__legacy_id(p_tenant, 'chart_of_accounts', r.ap_account_id::text), acct_role_account(p_tenant, v_entity, 'default_expense'));
          IF (SELECT account_type FROM acct_chart_of_accounts WHERE id = v_first_acct) = 'liability' THEN
            v_first_acct := acct_role_account(p_tenant, v_entity, 'default_expense'); END IF;
          INSERT INTO acct_ap_bill_lines(bill_id, line_no, description, quantity, unit_cost, expense_account_id, tenant_id, dimensions)
          VALUES (v_id, 1, 'Legacy bill ' || coalesce(r.number,''), 1, coalesce(r.subtotal, r.total, 0), v_first_acct, p_tenant, '{}'::jsonb);
        END IF;

        v_je := acct__legacy_id(p_tenant, 'journal_entries', r.journal_id::text);
        v_status := CASE r.status::text WHEN 'draft' THEN 'draft' WHEN 'paid' THEN 'paid'
                      WHEN 'partial' THEN 'partially_paid' ELSE 'open' END;
        IF v_status <> 'draft' AND v_je IS NULL THEN
          -- no legacy journal: post the bill (and its payment) so the A/P ledger matches
          v_amt := coalesce(r.total,0);
          SELECT jsonb_agg(jsonb_build_object('account_id', expense_account_id, 'debit', line_subtotal, 'credit', 0,
                           'description', description, 'vendor_id', (SELECT vendor_id FROM acct_ap_bills WHERE id = v_id)::text))
            INTO v_lines FROM acct_ap_bill_lines WHERE bill_id = v_id;
          v_diff := v_amt - coalesce((SELECT sum(line_subtotal) FROM acct_ap_bill_lines WHERE bill_id = v_id),0);
          IF v_diff <> 0 THEN   -- legacy tax / rounding goes to the first line's account
            v_lines := v_lines || jsonb_build_object('account_id', v_first_acct, 'debit', greatest(v_diff,0), 'credit', greatest(-v_diff,0), 'description', 'Legacy tax / rounding');
          END IF;
          v_lines := v_lines || jsonb_build_object('account_id', v_ap, 'debit', 0, 'credit', v_amt, 'description', 'Legacy bill ' || coalesce(r.number,''),
                                                   'vendor_id', (SELECT vendor_id FROM acct_ap_bills WHERE id = v_id)::text);
          v_je := acct_post_entry(p_tenant, v_entity, r.issue_date, v_lines, 'vendor_bill', v_id::text, r.number, 'Legacy bill ' || coalesce(r.number,''),
                                  'legacy-bill:' || r.id, NULL, NULL, NULL, false, false, 'acct_ap_bills', v_id);
          IF coalesce(r.amount_paid,0) > 0 THEN
            PERFORM acct_post_entry(p_tenant, v_entity, coalesce(r.paid_at::date, r.issue_date), jsonb_build_array(
              jsonb_build_object('account_id', v_ap, 'debit', r.amount_paid, 'description', 'Legacy bill payment', 'vendor_id', (SELECT vendor_id FROM acct_ap_bills WHERE id = v_id)::text),
              jsonb_build_object('account_id', v_cash, 'credit', r.amount_paid, 'description', 'Legacy bill payment ' || coalesce(r.number,''))),
              'vendor_payment', v_id::text, r.number, 'Legacy bill payment', 'legacy-billpay:' || r.id, NULL, NULL, NULL, false, false, 'acct_ap_bills', v_id);
          END IF;
          res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
        ELSIF v_je IS NOT NULL THEN
          res := jsonb_set(res, ARRAY[v_step,'linked'], to_jsonb((res#>>ARRAY[v_step,'linked'])::int + 1));
        ELSE
          res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
        END IF;
        UPDATE acct_ap_bills SET subtotal = coalesce(r.subtotal,0), tax_total = coalesce(r.tax_total,0), total = coalesce(r.total,0),
               amount_paid = CASE WHEN v_status = 'draft' THEN 0 ELSE least(coalesce(r.amount_paid,0), coalesce(r.total,0)) END,
               posted_journal_id = CASE WHEN v_status = 'draft' THEN NULL ELSE v_je END,
               review_status = 'ready', status = v_status
         WHERE id = v_id;
        INSERT INTO acct_legacy_map VALUES (p_tenant, 'bills', r.id::text, 'acct_ap_bills', v_id, CASE WHEN r.journal_id IS NOT NULL THEN 'linked legacy journal' END);
      EXCEPTION WHEN OTHERS THEN
        res := jsonb_set(res, ARRAY[v_step,'skipped'], to_jsonb((res#>>ARRAY[v_step,'skipped'])::int + 1));
        res := jsonb_set(res, ARRAY[v_step,'issues'], (res#>ARRAY[v_step,'issues']) || jsonb_build_object('legacy_id', r.id, 'number', r.number, 'error', SQLERRM));
      END;
    END LOOP;

    -- ---------------------------------------------------------------- invoices
    v_step := 'invoices';
    res := res || jsonb_build_object(v_step, jsonb_build_object('found',0,'migrated',0,'linked',0,'skipped',0,'issues','[]'::jsonb));
    FOR r IN SELECT * FROM invoices WHERE tenant_id = p_tenant ORDER BY "createdAt" LOOP
      res := jsonb_set(res, ARRAY[v_step,'found'], to_jsonb((res#>>ARRAY[v_step,'found'])::int + 1));
      CONTINUE WHEN acct__legacy_id(p_tenant, 'invoices', r.id) IS NOT NULL;
      BEGIN
        IF lower(coalesce(r.status,'')) IN ('void','voided','cancelled','canceled','deleted') THEN RAISE EXCEPTION 'void in the legacy system (not migrated)'; END IF;
        v_cust := acct__legacy_customer(p_tenant, r."customerId");
        IF v_cust IS NULL THEN RAISE EXCEPTION 'customer % not found in CRM', r."customerId"; END IF;
        v_date := coalesce(r."createdAt"::date, r."sentAt"::date, current_date);
        v_amt := acct__legacy_numeric(r.total);
        INSERT INTO acct_ar_invoices(tenant_id, entity_id, customer_id, invoice_number, invoice_date, due_date, currency, status,
               subtotal, total, notes, external_id, source_system, sent_at, document_kind)
        VALUES (p_tenant, v_entity, v_cust, nullif(r.number,''), v_date, r."dueDate", upper(coalesce(nullif(r.currency,''),'USD')), 'draft',
                acct__legacy_numeric(r.subtotal), v_amt, r.notes, r.id, 'legacy_invoices', r."sentAt", 'invoice')
        RETURNING id INTO v_id;
        v_n := 0;
        FOR l IN SELECT * FROM invoice_items WHERE "invoiceId" = r.id ORDER BY "createdAt" LOOP
          v_n := v_n + 1;
          INSERT INTO acct_ar_invoice_lines(invoice_id, line_no, description, quantity, unit_price, revenue_account_id, tenant_id, dimensions, taxable)
          VALUES (v_id, v_n, coalesce(nullif(l.description,''),'Legacy line'), coalesce(l.quantity,1), acct__legacy_numeric(l."unitPrice"),
                  acct_role_account(p_tenant, v_entity, 'default_income'), p_tenant, '{}'::jsonb, false);
        END LOOP;
        IF v_n = 0 THEN
          INSERT INTO acct_ar_invoice_lines(invoice_id, line_no, description, quantity, unit_price, revenue_account_id, tenant_id, dimensions, taxable)
          VALUES (v_id, 1, 'Legacy invoice ' || coalesce(r.number,''), 1, acct__legacy_numeric(r.subtotal),
                  acct_role_account(p_tenant, v_entity, 'default_income'), p_tenant, '{}'::jsonb, false);
        END IF;
        -- an existing legacy journal that mentions this invoice?
        SELECT m.new_id INTO v_je FROM journal_lines jl JOIN acct_legacy_map m ON m.tenant_id = p_tenant AND m.legacy_table = 'journal_entries' AND m.legacy_id = jl.journal_id::text
         WHERE jl.tenant_id = p_tenant AND jl.invoice_id = r.id
           AND jl.debit > 0 AND (jl.account_id = r.ar_account_id OR acct__legacy_id(p_tenant,'chart_of_accounts', jl.account_id::text) = v_ar)
         LIMIT 1;
        v_status := CASE WHEN lower(coalesce(r.status,'')) = 'draft' THEN 'draft'
                         WHEN lower(coalesce(r.status,'')) = 'paid' OR coalesce(r.amount_paid,0) >= v_amt THEN 'paid'
                         WHEN coalesce(r.amount_paid,0) > 0 THEN 'partially_paid' ELSE 'open' END;
        IF v_status <> 'draft' AND v_je IS NULL THEN
          v_diff := v_amt - acct__legacy_numeric(r.subtotal);   -- legacy tax
          v_lines := jsonb_build_array(
            jsonb_build_object('account_id', v_ar, 'debit', v_amt, 'customer_id', v_cust::text, 'description', 'Legacy invoice ' || coalesce(r.number,'')),
            jsonb_build_object('account_id', acct_role_account(p_tenant, v_entity, 'default_income'), 'credit', acct__legacy_numeric(r.subtotal), 'customer_id', v_cust::text, 'description', 'Legacy invoice ' || coalesce(r.number,'')));
          IF v_diff <> 0 THEN
            v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p_tenant, v_entity, 'sales_tax_payable'),
                                                     'credit', greatest(v_diff,0), 'debit', greatest(-v_diff,0), 'description', 'Legacy invoice tax');
          END IF;
          v_je := acct_post_entry(p_tenant, v_entity, v_date, v_lines, 'invoice', v_id::text, r.number, 'Legacy invoice ' || coalesce(r.number,''),
                                  'legacy-inv:' || r.id, NULL, NULL, NULL, false, false, 'acct_ar_invoices', v_id);
          IF least(coalesce(r.amount_paid,0), v_amt) > 0 THEN
            PERFORM acct_post_entry(p_tenant, v_entity, coalesce(r."paidAt"::date, v_date), jsonb_build_array(
              jsonb_build_object('account_id', v_cash, 'debit', least(r.amount_paid, v_amt), 'description', 'Legacy invoice payment ' || coalesce(r.number,'')),
              jsonb_build_object('account_id', v_ar, 'credit', least(r.amount_paid, v_amt), 'customer_id', v_cust::text, 'description', 'Legacy invoice payment')),
              'customer_receipt', v_id::text, r.number, 'Legacy invoice payment', 'legacy-invpay:' || r.id, NULL, NULL, NULL, false, false, 'acct_ar_invoices', v_id);
          END IF;
          res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
        ELSIF v_je IS NOT NULL THEN
          res := jsonb_set(res, ARRAY[v_step,'linked'], to_jsonb((res#>>ARRAY[v_step,'linked'])::int + 1));
        ELSE
          res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
        END IF;
        UPDATE acct_ar_invoices SET subtotal = acct__legacy_numeric(r.subtotal), tax_total = v_amt - acct__legacy_numeric(r.subtotal), total = v_amt,
               amount_paid = CASE WHEN v_status = 'draft' THEN 0 ELSE least(coalesce(r.amount_paid,0), v_amt) END,
               posted_journal_id = CASE WHEN v_status = 'draft' THEN NULL ELSE v_je END,
               paid_at = r."paidAt", status = v_status
         WHERE id = v_id;
        INSERT INTO acct_legacy_map VALUES (p_tenant, 'invoices', r.id, 'acct_ar_invoices', v_id, NULL);
      EXCEPTION WHEN OTHERS THEN
        res := jsonb_set(res, ARRAY[v_step,'skipped'], to_jsonb((res#>>ARRAY[v_step,'skipped'])::int + 1));
        res := jsonb_set(res, ARRAY[v_step,'issues'], (res#>ARRAY[v_step,'issues']) || jsonb_build_object('legacy_id', r.id, 'number', r.number, 'error', SQLERRM));
      END;
    END LOOP;

    -- ---------------------------------------------------------------- legacy tax rates -> tax codes
    v_step := 'tax_rates';
    res := res || jsonb_build_object(v_step, jsonb_build_object('found',0,'migrated',0,'linked',0,'skipped',0,'issues','[]'::jsonb));
    FOR r IN
      SELECT 'acct_tax_rates' src, t.id, t.name, t.jurisdiction, NULL::text state_code, t.rate_percent / 100.0 rate, t.gl_account_id, t.is_active, NULL::text code, t.created_at
        FROM acct_tax_rates t WHERE t.tenant_id = p_tenant
      UNION ALL
      SELECT 'acct_tax_rules', t.id, coalesce(t.tax_code, t.jurisdiction), t.jurisdiction, t.state_code,
             CASE WHEN t.rate > 1 THEN t.rate / 100.0 ELSE t.rate END, NULL, t.is_active, t.tax_code, t.created_at
        FROM acct_tax_rules t WHERE t.tenant_id = p_tenant
    LOOP
      res := jsonb_set(res, ARRAY[v_step,'found'], to_jsonb((res#>>ARRAY[v_step,'found'])::int + 1));
      CONTINUE WHEN acct__legacy_id(p_tenant, r.src, r.id::text) IS NOT NULL;
      BEGIN
        SELECT j.id INTO v_id FROM acct_tax_jurisdictions j
         WHERE j.tenant_id = p_tenant AND (lower(j.name) = lower(r.jurisdiction) OR lower(j.code) = lower(r.jurisdiction)
               OR (r.state_code IS NOT NULL AND j.state_code = upper(r.state_code) AND j.level = 'state'))
         ORDER BY (lower(j.name) = lower(r.jurisdiction)) DESC LIMIT 1;
        IF v_id IS NULL THEN RAISE EXCEPTION 'no tax jurisdiction named "%" - seed it (e.g. acct_seed_tax_mississippi) and re-run', r.jurisdiction; END IF;
        v_code := upper(left(regexp_replace(coalesce(r.code, r.name, 'LEGACY'), '[^A-Za-z0-9]+', '-', 'g'), 30));
        SELECT id INTO v_je FROM acct_tax_codes WHERE tenant_id = p_tenant AND jurisdiction_id = v_id AND abs(rate - r.rate) < 0.0000001 AND is_active LIMIT 1;
        IF v_je IS NOT NULL THEN
          INSERT INTO acct_legacy_map VALUES (p_tenant, r.src, r.id::text, 'acct_tax_codes', v_je, 'same rate already configured');
          res := jsonb_set(res, ARRAY[v_step,'linked'], to_jsonb((res#>>ARRAY[v_step,'linked'])::int + 1));
        ELSE
          IF EXISTS (SELECT 1 FROM acct_tax_codes WHERE tenant_id = p_tenant AND code = v_code) THEN v_code := v_code || '-L'; END IF;
          INSERT INTO acct_tax_codes(tenant_id, jurisdiction_id, code, name, tax_type, rate, payable_account_id, effective_from, is_active)
          VALUES (p_tenant, v_id, v_code, coalesce(r.name, v_code) || ' (legacy)', 'sales', r.rate,
                  coalesce(acct__legacy_id(p_tenant, 'chart_of_accounts', r.gl_account_id::text), acct_role_account(p_tenant, v_entity, 'sales_tax_payable')),
                  coalesce(r.created_at::date, current_date), coalesce(r.is_active, true))
          RETURNING id INTO v_je;
          INSERT INTO acct_legacy_map VALUES (p_tenant, r.src, r.id::text, 'acct_tax_codes', v_je, 'review: the tax engine uses jurisdiction rules, legacy code kept for history');
          res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
        END IF;
      EXCEPTION WHEN OTHERS THEN
        res := jsonb_set(res, ARRAY[v_step,'skipped'], to_jsonb((res#>>ARRAY[v_step,'skipped'])::int + 1));
        res := jsonb_set(res, ARRAY[v_step,'issues'], (res#>ARRAY[v_step,'issues']) || jsonb_build_object('legacy_id', r.id, 'name', r.name, 'error', SQLERRM));
      END;
    END LOOP;

    -- ---------------------------------------------------------------- erp orders (opt-in)
    v_step := 'erp_orders';
    res := res || jsonb_build_object(v_step, jsonb_build_object('found',0,'migrated',0,'linked',0,'skipped',0,'issues','[]'::jsonb));
    IF p_include_orders THEN
      FOR r IN SELECT * FROM erp_orders WHERE tenant_id = p_tenant ORDER BY order_date, created_at LOOP
        res := jsonb_set(res, ARRAY[v_step,'found'], to_jsonb((res#>>ARRAY[v_step,'found'])::int + 1));
        CONTINUE WHEN acct__legacy_id(p_tenant, 'erp_orders', r.id::text) IS NOT NULL;
        BEGIN
          IF lower(coalesce(r.status,'')) IN ('cancelled','canceled','draft','void','failed','pending_payment','abandoned','quote')
             OR coalesce(r.total,0) <= 0 THEN RAISE EXCEPTION 'status % / total % - not a completed sale', r.status, r.total; END IF;
          SELECT e.id INTO v_je FROM acct_journal_entries e
           WHERE e.tenant_id = p_tenant AND (e.source_doc_id = r.id OR (e.source_id = r.id::text AND e.source <> 'import')) LIMIT 1;
          IF v_je IS NULL THEN
            SELECT m.new_id INTO v_je FROM journal_lines jl JOIN acct_legacy_map m
                ON m.tenant_id = p_tenant AND m.legacy_table = 'journal_entries' AND m.legacy_id = jl.journal_id::text
             WHERE jl.tenant_id = p_tenant AND jl.order_id = r.id::text LIMIT 1;
          END IF;
          IF v_je IS NOT NULL THEN
            INSERT INTO acct_legacy_map VALUES (p_tenant, 'erp_orders', r.id::text, 'acct_journal_entries', v_je, 'already journaled');
            res := jsonb_set(res, ARRAY[v_step,'linked'], to_jsonb((res#>>ARRAY[v_step,'linked'])::int + 1));
            CONTINUE;
          END IF;
          v_date := coalesce(r.order_date::date, r.created_at::date);
          v_diff := coalesce(r.total,0) - (coalesce(r.subtotal,0) - coalesce(r.discount_total,0) + coalesce(r.shipping_total,0) + coalesce(r.tax_total,0));
          v_lines := jsonb_build_array(
            jsonb_build_object('account_id', v_ar, 'debit', r.total, 'customer_id', r.crm_customer_id::text, 'description', 'Order ' || r.order_number),
            jsonb_build_object('account_id', acct_role_account(p_tenant, v_entity, 'default_income'), 'credit', coalesce(r.subtotal,0), 'description', 'Order ' || r.order_number));
          IF coalesce(r.discount_total,0) <> 0 THEN v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p_tenant, v_entity, 'discounts_given'), 'debit', r.discount_total, 'description', 'Order discount'); END IF;
          IF coalesce(r.shipping_total,0) <> 0 THEN v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p_tenant, v_entity, 'shipping_income'), 'credit', r.shipping_total, 'description', 'Order shipping'); END IF;
          IF coalesce(r.tax_total,0) <> 0 THEN v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p_tenant, v_entity, 'sales_tax_payable'), 'credit', r.tax_total, 'description', 'Order sales tax'); END IF;
          IF v_diff <> 0 THEN v_lines := v_lines || jsonb_build_object('account_id', acct_role_account(p_tenant, v_entity, 'rounding'), 'credit', greatest(v_diff,0), 'debit', greatest(-v_diff,0), 'description', 'Order rounding'); END IF;
          v_je := acct_post_entry(p_tenant, v_entity, v_date, v_lines, 'import', r.id::text, r.order_number, 'Legacy order ' || r.order_number,
                                  'legacy-order:' || r.id, NULL, NULL, upper(coalesce(nullif(r.currency,''),'USD')), false, false, 'erp_orders', r.id);
          IF least(coalesce(r.amount_paid,0), r.total) > 0 THEN
            PERFORM acct_post_entry(p_tenant, v_entity, v_date, jsonb_build_array(
              jsonb_build_object('account_id', v_cash, 'debit', least(r.amount_paid, r.total), 'description', 'Order payment ' || r.order_number),
              jsonb_build_object('account_id', v_ar, 'credit', least(r.amount_paid, r.total), 'customer_id', r.crm_customer_id::text, 'description', 'Order payment')),
              'import', r.id::text, r.order_number, 'Legacy order payment', 'legacy-orderpay:' || r.id, NULL, NULL, NULL, false, false, 'erp_orders', r.id);
          END IF;
          IF coalesce(r.amount_refunded,0) > 0 THEN
            PERFORM acct_post_entry(p_tenant, v_entity, coalesce(r.updated_at::date, v_date), jsonb_build_array(
              jsonb_build_object('account_id', acct_role_account(p_tenant, v_entity, 'sales_returns'), 'debit', r.amount_refunded, 'description', 'Order refund ' || r.order_number),
              jsonb_build_object('account_id', v_cash, 'credit', r.amount_refunded, 'description', 'Order refund ' || r.order_number)),
              'import', r.id::text, r.order_number, 'Legacy order refund', 'legacy-orderrefund:' || r.id, NULL, NULL, NULL, false, false, 'erp_orders', r.id);
          END IF;
          INSERT INTO acct_legacy_map VALUES (p_tenant, 'erp_orders', r.id::text, 'acct_journal_entries', v_je,
                  'order sales tax is in 2200 but not in jurisdiction detail - review before filing');
          res := jsonb_set(res, ARRAY[v_step,'migrated'], to_jsonb((res#>>ARRAY[v_step,'migrated'])::int + 1));
        EXCEPTION WHEN OTHERS THEN
          res := jsonb_set(res, ARRAY[v_step,'skipped'], to_jsonb((res#>>ARRAY[v_step,'skipped'])::int + 1));
          res := jsonb_set(res, ARRAY[v_step,'issues'], (res#>ARRAY[v_step,'issues']) || jsonb_build_object('legacy_id', r.id, 'order', r.order_number, 'error', SQLERRM));
        END;
      END LOOP;
    END IF;

    -- ---------------------------------------------------------------- cached balances
    v_step := 'rebuild_balances';
    v_n := 0;
    FOR r IN SELECT id FROM acct_books WHERE tenant_id = p_tenant LOOP PERFORM acct_rebuild_balances(r.id); v_n := v_n + 1; END LOOP;
    res := res || jsonb_build_object(v_step, jsonb_build_object('found', v_n, 'migrated', v_n, 'linked', 0, 'skipped', 0, 'issues', '[]'::jsonb));

    IF p_dry_run THEN RAISE EXCEPTION USING ERRCODE = 'P0D01', MESSAGE = 'dry run rollback'; END IF;
  EXCEPTION WHEN SQLSTATE 'P0D01' THEN
    NULL;   -- everything above rolled back; the counts in res survive
  END work;

  RETURN QUERY
  SELECT k || CASE WHEN p_dry_run THEN ' (dry run)' ELSE '' END,
         (v->>'found')::int, (v->>'migrated')::int, (v->>'linked')::int, (v->>'skipped')::int, v->'issues'
    FROM jsonb_each(res) AS e(k, v)
   ORDER BY array_position(ARRAY['chart_of_accounts','vendors','bank_accounts','journal_entries','bills','invoices','tax_rates','erp_orders','rebuild_balances'], k);
END $$;

-- @seq 244
CREATE FUNCTION public.acct_minor_to_major(p_amount_minor bigint, p_currency text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT p_amount_minor::numeric / power(10, coalesce((SELECT minor_units FROM acct_currencies WHERE code = upper(p_currency)),
         CASE WHEN upper(p_currency) IN ('JPY','KRW','VND','CLP','ISK','UGX','XAF','XOF','PYG','RWF','KMF','GNF','MGA','BIF','DJF','VUV','XPF') THEN 0 ELSE 2 END));
$$;

-- @seq 245
CREATE FUNCTION public.acct_next_number(p_tenant_id uuid, p_entity_id uuid, p_doc_type text, p_default_prefix text DEFAULT ''::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v bigint; s acct_number_sequences%ROWTYPE;
BEGIN
  INSERT INTO acct_number_sequences(tenant_id, entity_id, doc_type, prefix)
  VALUES (p_tenant_id, p_entity_id, p_doc_type, p_default_prefix)
  ON CONFLICT DO NOTHING;
  v := acct_next_seq(p_tenant_id, p_entity_id, p_doc_type);
  SELECT * INTO s FROM acct_number_sequences WHERE tenant_id=p_tenant_id AND entity_id=p_entity_id AND doc_type=p_doc_type;
  RETURN s.prefix || CASE WHEN s.padding > 0 THEN lpad(v::text, s.padding, '0') ELSE v::text END;
END $$;

-- @seq 246
CREATE FUNCTION public.acct_next_seq(p_tenant_id uuid, p_entity_id uuid, p_doc_type text) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v bigint;
BEGIN
  INSERT INTO acct_number_sequences(tenant_id, entity_id, doc_type, next_value)
  VALUES (p_tenant_id, p_entity_id, p_doc_type,
          CASE WHEN p_doc_type = 'journal'
               THEN coalesce((SELECT max(entry_no) + 1 FROM acct_journal_entries
                              WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id), 1)
               ELSE 1 END)
  ON CONFLICT (tenant_id, entity_id, doc_type) DO NOTHING;
  UPDATE acct_number_sequences SET next_value = next_value + 1, updated_at = now()
   WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id AND doc_type = p_doc_type
  RETURNING next_value - 1 INTO v;
  RETURN v;
END $$;

-- @seq 247
CREATE FUNCTION public.acct_normalize_descriptor(p text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE s text := lower(coalesce(p,''));
BEGIN
  s := regexp_replace(s, '^(pos |debit card |dbt crd |checkcard |check card |purchase |recurring |ach |ppd |web |pmt |payment to |online transfer to |online transfer from )+', '', 'g');
  s := regexp_replace(s, '^(sq \*|sq\*|tst\* ?|tst \*|paypal \*|pp\*|sp \* ?|sp\*|amzn mktp us\*?|in \*|pyp\*)', '', 'g');
  s := regexp_replace(s, '(x{2,}|\*{2,})\d+', ' ', 'g');                -- masked card numbers
  s := regexp_replace(s, '#\s*\d+', ' ', 'g');                           -- store numbers
  s := regexp_replace(s, '\m\d{2}/\d{2}(/\d{2,4})?\M', ' ', 'g');         -- dates
  s := regexp_replace(s, '\m[a-z0-9]*\d{4,}[a-z0-9]*\M', ' ', 'g');       -- long ids
  s := regexp_replace(s, '\s+(al|ak|az|ar|ca|co|ct|de|fl|ga|hi|id|il|in|ia|ks|ky|la|me|md|ma|mi|mn|ms|mo|mt|ne|nv|nh|nj|nm|ny|nc|nd|oh|ok|or|pa|ri|sc|sd|tn|tx|ut|vt|va|wa|wv|wi|wy)\s*$', '', 'g');
  s := regexp_replace(s, '[^a-z0-9&'' ]', ' ', 'g');
  s := btrim(regexp_replace(s, '\s+', ' ', 'g'));
  RETURN nullif(s, '');
END $_$;

-- @seq 248
CREATE FUNCTION public.acct_open_dispute(p_dispute_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d acct_disputes%ROWTYPE; v_entity uuid; v_je uuid; v_lines jsonb;
BEGIN
  SELECT * INTO d FROM acct_disputes WHERE id = p_dispute_id FOR UPDATE;
  PERFORM acct_assert_access(d.tenant_id);
  IF d.opened_journal_id IS NOT NULL THEN RETURN d.opened_journal_id; END IF;
  v_entity := coalesce(d.entity_id, acct_default_entity(d.tenant_id));
  v_lines := jsonb_build_array(
    jsonb_build_object('account_id', acct_role_account(d.tenant_id, v_entity, 'dispute_holding'), 'debit', d.amount, 'customer_id', d.customer_id::text, 'description', 'Disputed ' || d.dispute_number),
    jsonb_build_object('account_id', acct_bank_gl(acct_system_register(d.tenant_id, v_entity, 'stripe')), 'credit', d.amount + d.fee_amount, 'description', 'Dispute withdrawal ' || d.dispute_number));
  IF d.fee_amount > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(d.tenant_id, v_entity, 'processor_fees'), 'debit', d.fee_amount, 'description', 'Dispute fee'));
  END IF;
  v_je := acct_post_entry(d.tenant_id, v_entity, p_date, v_lines, 'integration', d.id::text, d.dispute_number, 'Dispute opened ' || coalesce(d.reason,''),
                          'dispute-open:' || d.id, NULL, NULL, d.currency, false, false, 'acct_disputes', d.id);
  UPDATE acct_disputes SET opened_journal_id = v_je, opened_on = p_date, entity_id = v_entity, status = CASE WHEN status IN ('open','needs_response') THEN status ELSE 'open' END WHERE id = d.id;
  RETURN v_je;
END $$;

-- @seq 249
CREATE FUNCTION public.acct_pay_bills(p_bank_account_id uuid, p_payment_date date, p_items jsonb, p_method text DEFAULT 'check'::text, p_starting_check_no bigint DEFAULT NULL::bigint, p_print_later boolean DEFAULT false, p_memo text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS TABLE(vendor_id uuid, payment_id uuid, check_number bigint, amount numeric, journal_entry_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE r acct_bank_accounts%ROWTYPE; v_gl uuid; v_vendor uuid; v_items jsonb; it jsonb; b acct_ap_bills%ROWTYPE; v acct_vendors%ROWTYPE;
        v_total numeric; v_pay uuid; v_je uuid; v_check bigint; v_amt numeric; v_batch uuid := gen_random_uuid(); v_cr numeric;
BEGIN
  SELECT * INTO r FROM acct_bank_accounts WHERE id = p_bank_account_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payment account must be a bank/card register (acct_bank_accounts.id)'; END IF;
  PERFORM acct_assert_access(r.tenant_id);
  v_gl := acct_bank_gl(r.id);                                    -- <- the cash_account_id fix
  IF r.account_kind IN ('loan','payment_processor') THEN RAISE EXCEPTION 'Bills cannot be paid from a % register', r.account_kind; END IF;
  IF p_method = 'credit_card' AND r.account_kind <> 'credit_card' THEN RAISE EXCEPTION 'Card payments must come from a credit card register'; END IF;
  IF p_method = 'check' AND r.account_kind NOT IN ('checking','savings','money_market') THEN RAISE EXCEPTION 'Checks must be drawn on a bank account'; END IF;
  IF p_idempotency_key IS NOT NULL AND EXISTS (SELECT 1 FROM acct_ap_payments WHERE reference = 'idem:' || p_idempotency_key) THEN
    RETURN QUERY SELECT p.vendor_id, p.id, p.check_number, p.amount, p.posted_journal_id FROM acct_ap_payments p WHERE p.batch_id =
      (SELECT batch_id FROM acct_ap_payments WHERE reference = 'idem:' || p_idempotency_key LIMIT 1);
    RETURN;
  END IF;
  v_check := CASE WHEN p_method = 'check' AND NOT p_print_later THEN coalesce(p_starting_check_no, r.next_check_number, 1001) END;

  FOR v_vendor, v_items IN
    SELECT (SELECT x.vendor_id FROM acct_ap_bills x WHERE x.id = (e->>'bill_id')::uuid), jsonb_agg(e)
      FROM jsonb_array_elements(p_items) e GROUP BY 1 ORDER BY 1
  LOOP
    IF v_vendor IS NULL THEN RAISE EXCEPTION 'Unknown bill in payment list'; END IF;
    SELECT * INTO v FROM acct_vendors WHERE id = v_vendor;
    v_total := 0;
    -- validate first
    FOR it IN SELECT value FROM jsonb_array_elements(v_items) LOOP
      SELECT * INTO b FROM acct_ap_bills WHERE id = (it->>'bill_id')::uuid FOR UPDATE;
      IF b.tenant_id <> r.tenant_id OR b.entity_id <> r.entity_id THEN RAISE EXCEPTION 'Bill % belongs to another company', b.bill_number; END IF;
      IF b.status NOT IN ('open','partially_paid') THEN RAISE EXCEPTION 'Bill % is % and cannot be paid', b.bill_number, b.status; END IF;
      IF b.payment_approval_status IN ('pending','rejected') THEN RAISE EXCEPTION 'Payment for bill % is % approval', b.bill_number, b.payment_approval_status; END IF;
      v_cr := coalesce((it->>'credit_amount')::numeric, 0);
      IF it ? 'credit_id' AND v_cr > 0 THEN PERFORM acct_apply_vendor_credit((it->>'credit_id')::uuid, b.id, v_cr); SELECT * INTO b FROM acct_ap_bills WHERE id = b.id; END IF;
      v_amt := coalesce((it->>'amount')::numeric, b.open_balance);
      IF v_amt <= 0 THEN CONTINUE; END IF;
      IF v_amt > b.open_balance THEN RAISE EXCEPTION 'Payment % exceeds open balance % on bill %', v_amt, b.open_balance, b.bill_number; END IF;
      v_total := v_total + v_amt;
    END LOOP;
    CONTINUE WHEN v_total = 0;
    INSERT INTO acct_ap_payments(tenant_id, entity_id, vendor_id, payment_number, payment_date, currency, amount, payment_method, status,
                                 cash_account_id, reference, check_number, print_status, payee_address, memo, batch_id, created_by)
    VALUES (r.tenant_id, r.entity_id, v_vendor, acct_next_number(r.tenant_id, r.entity_id, 'bill_payment', 'BP-'), p_payment_date, r.currency, v_total,
            p_method, 'posted', r.id, CASE WHEN p_idempotency_key IS NOT NULL THEN 'idem:' || p_idempotency_key END, v_check,
            CASE WHEN p_method = 'check' THEN CASE WHEN p_print_later THEN 'to_print' ELSE 'printed' END ELSE 'not_applicable' END,
            acct_address_text('vendor', v_vendor, 'remit_to'), p_memo, v_batch, auth.uid())
    RETURNING id INTO v_pay;
    v_je := acct_post_entry(r.tenant_id, r.entity_id, p_payment_date, jsonb_build_array(
              jsonb_build_object('account_id', v.ap_account_id, 'debit', v_total, 'vendor_id', v_vendor, 'description', 'Bill payment ' || coalesce(v.display_name, v.legal_name)),
              jsonb_build_object('account_id', v_gl, 'credit', v_total, 'vendor_id', v_vendor,
                                 'description', coalesce('Check ' || v_check, initcap(p_method)) || ' ' || coalesce(v.display_name, v.legal_name))),
            'vendor_payment', v_pay::text, coalesce(v_check::text, 'BP'), coalesce(p_memo, 'Bill payment'), 'billpay:' || v_pay,
            NULL, NULL, r.currency, false, false, 'acct_ap_payments', v_pay);
    UPDATE acct_ap_payments SET posted_journal_id = v_je WHERE id = v_pay;
    FOR it IN SELECT value FROM jsonb_array_elements(v_items) LOOP
      SELECT * INTO b FROM acct_ap_bills WHERE id = (it->>'bill_id')::uuid;
      v_amt := coalesce((it->>'amount')::numeric, b.open_balance);
      CONTINUE WHEN v_amt <= 0;
      INSERT INTO acct_ap_payment_applications(tenant_id, payment_id, bill_id, applied_amount) VALUES (r.tenant_id, v_pay, b.id, v_amt);
      UPDATE acct_ap_bills SET amount_paid = amount_paid + v_amt WHERE id = b.id;
      PERFORM acct_bill_refresh_status(b.id);
    END LOOP;
    vendor_id := v_vendor; payment_id := v_pay; check_number := v_check; amount := v_total; journal_entry_id := v_je;
    RETURN NEXT;
    IF v_check IS NOT NULL THEN v_check := v_check + 1; END IF;
  END LOOP;
  IF v_check IS NOT NULL THEN UPDATE acct_bank_accounts SET next_check_number = v_check WHERE id = r.id; END IF;
END $$;

-- @seq 250
CREATE FUNCTION public.acct_pay_payroll_liabilities(p_tenant_id uuid, p_date date, p_bank_account_id uuid, p_amount numeric, p_payee text, p_reference text DEFAULT NULL::text, p_vendor_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_amount <= 0 THEN RAISE EXCEPTION 'Amount must be positive'; END IF;
  v_entity := acct_default_entity(p_tenant_id);
  RETURN acct_post_entry(p_tenant_id, v_entity, p_date, jsonb_build_array(
           jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'payroll_liabilities'), 'debit', p_amount, 'description', 'Payroll liability: ' || p_payee,
                              'vendor_id', p_vendor_id::text),
           jsonb_build_object('account_id', acct_bank_gl(p_bank_account_id), 'credit', p_amount, 'description', 'Payroll liability: ' || p_payee,
                              'vendor_id', p_vendor_id::text)),
         'payroll', NULL, p_reference, 'Payroll liability payment ' || p_payee, NULL, NULL, NULL, NULL, false, false, NULL, NULL);
END $$;

-- @seq 251
CREATE FUNCTION public.acct_pay_sales_tax_filing(p_filing_id uuid, p_bank_account_id uuid, p_payment_date date, p_amount numeric DEFAULT NULL::numeric, p_adjustment_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f acct_tax_filings%ROWTYPE; v_paid numeric; v_liab uuid; v_lines jsonb; v_je uuid; v_diff numeric;
BEGIN
  SELECT * INTO f FROM acct_tax_filings WHERE id = p_filing_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Filing not found'; END IF;
  PERFORM acct_assert_access(f.tenant_id);
  IF f.payment_journal_id IS NOT NULL THEN RAISE EXCEPTION 'Filing already paid'; END IF;
  v_paid := coalesce(p_amount, f.amount_due);
  v_liab := acct_role_account(f.tenant_id, f.entity_id, 'sales_tax_payable');
  v_diff := v_paid - f.tax_collected;      -- >0 penalty/interest, <0 vendor discount
  v_lines := jsonb_build_array(
     jsonb_build_object('account_id', v_liab, 'debit', f.tax_collected, 'description', 'Sales tax ' || f.period_label),
     jsonb_build_object('account_id', acct_bank_gl(p_bank_account_id), 'credit', v_paid, 'description', 'Sales tax payment ' || f.period_label));
  IF v_diff <> 0 THEN
    IF p_adjustment_account_id IS NULL THEN RAISE EXCEPTION 'Payment differs from tax collected by %; pass an adjustment account', v_diff; END IF;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', p_adjustment_account_id,
                 'debit', greatest(v_diff,0), 'credit', greatest(-v_diff,0), 'description', 'Sales tax adjustment'));
  END IF;
  v_je := acct_post_entry(f.tenant_id, f.entity_id, p_payment_date, v_lines, 'tax', f.id::text, 'STX-' || f.period_label,
                          'Sales tax payment', 'salestax:' || f.id, NULL, NULL, NULL, false, false, 'acct_tax_filings', f.id);
  UPDATE acct_tax_filings SET tax_remitted = v_paid, paid_on = p_payment_date, payment_journal_id = v_je, status = 'paid' WHERE id = f.id;
  RETURN v_je;
EXCEPTION WHEN check_violation THEN
  -- acct_tax_filings.status may have a legacy CHECK without 'paid'
  UPDATE acct_tax_filings SET tax_remitted = v_paid, paid_on = p_payment_date, payment_journal_id = v_je, status = 'filed' WHERE id = f.id;
  RETURN v_je;
END $$;

-- @seq 252
CREATE FUNCTION public.acct_payout_register(p_tenant_id uuid, p_entity_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT id FROM acct_bank_accounts WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id AND is_active AND account_kind IN ('checking','savings')
   ORDER BY coalesce((metadata->>'stripe_payouts')::boolean, false) DESC, created_at LIMIT 1;
$$;

-- @seq 254
CREATE FUNCTION public.acct_period_for(p_book_id uuid, p_date date, p_allow_soft_closed boolean DEFAULT false, p_allow_closed boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p acct_periods%ROWTYPE;
BEGIN
  SELECT * INTO p FROM acct_periods WHERE book_id = p_book_id AND p_date BETWEEN start_date AND end_date ORDER BY start_date DESC LIMIT 1;
  IF NOT FOUND THEN
    PERFORM acct_ensure_fiscal_year(p_book_id, p_date);
    SELECT * INTO p FROM acct_periods WHERE book_id = p_book_id AND p_date BETWEEN start_date AND end_date ORDER BY start_date DESC LIMIT 1;
  END IF;
  IF p.status = 'locked' THEN RAISE EXCEPTION 'Period % is locked; no postings allowed', p.name; END IF;
  IF p.status = 'closed' AND NOT p_allow_closed THEN RAISE EXCEPTION 'Period % is closed. Reopen it or post to an open period.', p.name; END IF;
  IF p.status = 'soft_closed' AND NOT (p_allow_soft_closed OR p_allow_closed) THEN
    RAISE EXCEPTION 'Period % is soft-closed; only adjusting entries are allowed', p.name; END IF;
  IF p.status = 'future' THEN RAISE EXCEPTION 'Period % is not open yet', p.name; END IF;
  RETURN p.id;
END $$;

-- @seq 255
CREATE FUNCTION public.acct_place_asset_in_service(p_asset_id uuid, p_in_service date, p_method text DEFAULT NULL::text, p_life_months integer DEFAULT NULL::integer, p_residual numeric DEFAULT NULL::numeric, p_convention text DEFAULT 'full_month'::text, p_class_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE a acct_fixed_assets%ROWTYPE; c acct_asset_classes%ROWTYPE; v_book uuid; v_ab uuid; v_method text; v_life int;
BEGIN
  SELECT * INTO a FROM acct_fixed_assets WHERE id = p_asset_id FOR UPDATE;
  PERFORM acct_assert_access(a.tenant_id);
  IF a.status NOT IN ('draft','in_service') THEN RAISE EXCEPTION 'Asset is %', a.status; END IF;
  v_ab := coalesce(p_class_id, a.asset_class_id, acct__default_asset_class(a.tenant_id, a.entity_id));
  SELECT * INTO c FROM acct_asset_classes WHERE id = v_ab;
  v_ab := NULL;
  v_method := coalesce(p_method, c.default_method, 'straight_line');
  IF v_method NOT IN ('straight_line','declining_balance','double_declining') THEN RAISE EXCEPTION 'Unknown depreciation method %', v_method; END IF;
  IF p_convention NOT IN ('full_month','mid_month','next_month') THEN RAISE EXCEPTION 'Unknown convention %', p_convention; END IF;
  v_life := coalesce(p_life_months, a.useful_life_months, c.default_useful_life_months);
  IF v_life IS NULL OR v_life <= 0 THEN RAISE EXCEPTION 'Useful life (months) is required'; END IF;
  v_book := acct_primary_book(a.tenant_id, a.entity_id);
  UPDATE acct_fixed_assets SET asset_class_id = c.id, placed_in_service_date = p_in_service, useful_life_months = v_life,
         residual_value = coalesce(p_residual, residual_value, 0), status = 'in_service', updated_at = now() WHERE id = a.id;
  INSERT INTO acct_asset_books(asset_id, book_id, depreciation_method, convention, useful_life_months, depreciation_start_date, in_service_cost,
                               accumulated_depreciation, net_book_value)
  VALUES (a.id, v_book, v_method, p_convention, v_life, p_in_service, a.original_cost, a.accumulated_depreciation, a.original_cost - a.accumulated_depreciation)
  ON CONFLICT (asset_id, book_id) DO UPDATE SET depreciation_method = EXCLUDED.depreciation_method, convention = EXCLUDED.convention,
     useful_life_months = EXCLUDED.useful_life_months, depreciation_start_date = EXCLUDED.depreciation_start_date
  RETURNING id INTO v_ab;
  RETURN v_ab;
END $$;

-- @seq 256
CREATE FUNCTION public.acct_po_match(p_po_id uuid, p_price_tolerance_pct numeric DEFAULT 2) RETURNS TABLE(po_line_id uuid, description text, qty_ordered numeric, qty_received numeric, qty_billed numeric, po_unit_cost numeric, billed_unit_cost numeric, match_status text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM erp_purchase_orders WHERE id = p_po_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'Purchase order not found'; END IF;
  PERFORM acct_assert_access(v_tenant);
  RETURN QUERY
  SELECT l.id, l.description, coalesce(l.quantity_ordered, l.quantity, 0), coalesce(l.quantity_received, 0),
         coalesce(b.qty, 0), l.unit_cost, b.unit_cost,
         CASE
           WHEN coalesce(b.qty, 0) > coalesce(l.quantity_received, 0) THEN 'billed_more_than_received'
           WHEN coalesce(l.quantity_received, 0) > coalesce(l.quantity_ordered, l.quantity, 0) THEN 'received_more_than_ordered'
           WHEN b.qty IS NOT NULL AND l.unit_cost IS NOT NULL AND l.unit_cost <> 0
                AND abs(b.unit_cost - l.unit_cost) / abs(l.unit_cost) * 100 > p_price_tolerance_pct THEN 'price_variance'
           WHEN coalesce(b.qty, 0) = 0 AND coalesce(l.quantity_received, 0) > 0 THEN 'received_not_billed'
           WHEN coalesce(l.quantity_received, 0) < coalesce(l.quantity_ordered, l.quantity, 0) THEN 'awaiting_receipt'
           ELSE 'matched' END
    FROM erp_purchase_order_lines l
    LEFT JOIN LATERAL (
      SELECT sum(bl.quantity) qty, round(sum(bl.quantity * bl.unit_cost) / nullif(sum(bl.quantity), 0), 4) unit_cost
        FROM acct_ap_bill_lines bl JOIN acct_ap_bills bb ON bb.id = bl.bill_id
       WHERE bl.erp_po_line_id = l.id AND bb.status <> 'void') b ON true
   WHERE l.purchase_order_id = p_po_id
   ORDER BY l.created_at, l.id;
END $$;

-- @seq 257
CREATE FUNCTION public.acct_post_bill(p_bill_id uuid, p_allow_possible_duplicate boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_ap_bills%ROWTYPE; v acct_vendors%ROWTYPE; v_lines jsonb; v_je uuid; v_dup text;
BEGIN
  SELECT * INTO b FROM acct_ap_bills WHERE id = p_bill_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bill not found'; END IF;
  PERFORM acct_assert_access(b.tenant_id);
  IF b.posted_journal_id IS NOT NULL THEN RETURN b.posted_journal_id; END IF;
  IF b.status = 'draft' AND b.approval_status = 'not_required' THEN PERFORM acct_submit_bill(b.id); SELECT * INTO b FROM acct_ap_bills WHERE id = p_bill_id; END IF;
  IF b.approval_status IN ('pending','rejected') THEN RAISE EXCEPTION 'Bill % is % approval', b.bill_number, b.approval_status; END IF;
  IF b.review_status = 'for_review' THEN RAISE EXCEPTION 'Bill % came from an upload and has not been reviewed', b.bill_number; END IF;
  IF b.total <= 0 THEN RAISE EXCEPTION 'Bill total must be greater than zero (use a vendor credit for negatives)'; END IF;
  IF NOT EXISTS (SELECT 1 FROM acct_ap_bill_lines WHERE bill_id = b.id) THEN RAISE EXCEPTION 'Bill has no lines'; END IF;
  -- duplicate guard: same vendor, same amount, within 7 days
  SELECT bill_number INTO v_dup FROM acct_ap_bills x
   WHERE x.tenant_id = b.tenant_id AND x.vendor_id = b.vendor_id AND x.id <> b.id AND x.status NOT IN ('void','draft')
     AND x.total = b.total AND abs(x.bill_date - b.bill_date) <= 7 LIMIT 1;
  IF v_dup IS NOT NULL AND NOT p_allow_possible_duplicate THEN
    RAISE EXCEPTION 'Possible duplicate of bill % (same vendor and amount within 7 days). Re-post with p_allow_possible_duplicate => true if intended.', v_dup; END IF;
  SELECT * INTO v FROM acct_vendors WHERE id = b.vendor_id;
  SELECT jsonb_agg(jsonb_build_object('account_id', l.expense_account_id, 'debit', l.line_subtotal + l.tax_amount, 'description', l.description,
           'vendor_id', b.vendor_id, 'item_id', l.item_id, 'dimensions', l.dimensions,
           'customer_id', CASE WHEN l.billable THEN l.billable_customer_id END) ORDER BY l.line_no)
    INTO v_lines FROM acct_ap_bill_lines l WHERE l.bill_id = b.id AND l.line_subtotal + l.tax_amount <> 0;
  -- Cr A/P the net total; an early-pay/vendor discount on the face of the bill reduces expense
  v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', v.ap_account_id, 'credit', b.total,
               'description', 'Bill ' || b.bill_number || ' ' || coalesce(v.display_name, v.legal_name), 'vendor_id', b.vendor_id));
  IF b.discount_total <> 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', coalesce(
                 (SELECT expense_account_id FROM acct_ap_bill_lines WHERE bill_id = b.id ORDER BY line_no LIMIT 1),
                 acct_role_account(b.tenant_id, b.entity_id, 'default_expense')),
                 'credit', b.discount_total, 'description', 'Bill discount', 'vendor_id', b.vendor_id));
  END IF;
  v_je := acct_post_entry(b.tenant_id, b.entity_id, b.bill_date, v_lines, 'vendor_bill', b.id::text, b.bill_number, coalesce(b.memo, 'Bill ' || b.bill_number),
                          'bill:' || b.id, NULL, NULL, b.currency, false, false, 'acct_ap_bills', b.id);
  UPDATE acct_ap_bills SET posted_journal_id = v_je, status = 'open' WHERE id = b.id;
  IF b.payment_approval_status = 'not_required' THEN PERFORM acct_submit_bill(b.id, 'payment'); END IF;
  RETURN v_je;
END $$;

-- @seq 258
CREATE FUNCTION public.acct_post_channel_settlement(p_settlement_id uuid, p_bank_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s acct_channel_settlements%ROWTYPE; ch acct_channel_accounts%ROWTYPE; v_bank uuid; v_clear uuid; l record; v_lines jsonb := '[]'::jsonb;
        v_acct uuid; v_clear_amt numeric := 0; v_je uuid; v_fee uuid; v_cb uuid;
BEGIN
  SELECT * INTO s FROM acct_channel_settlements WHERE id = p_settlement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Settlement not found'; END IF;
  PERFORM acct_assert_access(s.tenant_id);
  IF s.status <> 'draft' THEN RAISE EXCEPTION 'Settlement is already %', s.status; END IF;
  SELECT * INTO ch FROM acct_channel_accounts WHERE id = s.channel_account_id;
  v_bank := coalesce(p_bank_account_id, s.bank_account_id, ch.payout_bank_account_id);
  IF v_bank IS NULL THEN RAISE EXCEPTION 'Choose the bank account the % payout landed in', s.channel; END IF;
  v_clear := acct_bank_gl(ch.clearing_register_id);
  v_fee := coalesce(ch.fee_account_id, acct__role(s.tenant_id, s.entity_id, 'processor_fees'));
  FOR l IN SELECT * FROM acct_channel_settlement_lines WHERE settlement_id = s.id ORDER BY created_at, id LOOP
    CASE
      WHEN l.line_type IN ('sale','refund','shipping_charged') THEN
        v_clear_amt := v_clear_amt + l.amount; CONTINUE;
      WHEN l.line_type LIKE 'marketplace_tax%' THEN CONTINUE;
      WHEN l.line_type IN ('fee','subscription_fee') THEN v_acct := coalesce(l.account_id, v_fee);
      WHEN l.line_type = 'ad_fee' THEN v_acct := coalesce(l.account_id, ch.advertising_account_id, v_fee);
      WHEN l.line_type = 'shipping_label' THEN v_acct := coalesce(l.account_id, ch.shipping_account_id, v_fee);
      WHEN l.line_type = 'chargeback' THEN
        v_cb := coalesce(l.account_id, acct_role_account(s.tenant_id, s.entity_id, 'chargeback_loss', false), v_fee); v_acct := v_cb;
      WHEN l.line_type IN ('reserve_hold','reserve_release') THEN
        v_acct := coalesce(l.account_id, ch.reserve_account_id);
        IF v_acct IS NULL THEN RAISE EXCEPTION 'Channel % has no reserve account; set it up with a reserve', s.channel; END IF;
      ELSE
        v_acct := l.account_id;
        IF v_acct IS NULL THEN RAISE EXCEPTION 'Adjustment line "%" needs an account', coalesce(l.description, l.id::text); END IF;
    END CASE;
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', v_acct,
                 'debit', greatest(-l.amount, 0), 'credit', greatest(l.amount, 0),
                 'description', coalesce(l.description, initcap(replace(l.line_type,'_',' ')) || coalesce(' ' || l.order_ref, ''))));
  END LOOP;
  IF v_clear_amt <> 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', v_clear, 'debit', greatest(-v_clear_amt,0), 'credit', greatest(v_clear_amt,0),
                 'description', initcap(s.channel) || ' sales cleared'));
  END IF;
  IF s.payout_amount <> 0 THEN
    v_lines := jsonb_build_array(jsonb_build_object('account_id', acct_bank_gl(v_bank), 'debit', greatest(s.payout_amount,0), 'credit', greatest(-s.payout_amount,0),
                 'description', initcap(s.channel) || ' payout ' || s.external_id)) || v_lines;
  END IF;
  v_je := acct_post_entry(s.tenant_id, s.entity_id, s.payout_date, v_lines, 'channel_settlement', s.id::text, s.external_id,
                          initcap(s.channel) || ' settlement ' || s.external_id, 'chsettle:' || s.id,
                          NULL, NULL, s.currency, false, false, 'acct_channel_settlements', s.id);
  UPDATE acct_channel_settlements SET status = 'posted', journal_entry_id = v_je, bank_account_id = v_bank, updated_at = now() WHERE id = s.id;
  RETURN v_je;
END $$;

-- @seq 259
CREATE FUNCTION public.acct_post_credit_memo(p_memo_id uuid, p_apply_to_invoice boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE m acct_ar_credit_memos%ROWTYPE; iv acct_ar_invoices%ROWTYPE; v_lines jsonb; v_je uuid; v_ratio numeric; r record; v_tax_left numeric; v_n int; v_i int := 0; v_amt numeric;
BEGIN
  SELECT * INTO m FROM acct_ar_credit_memos WHERE id = p_memo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Credit memo not found'; END IF;
  PERFORM acct_assert_access(m.tenant_id);
  IF m.posted_journal_id IS NOT NULL THEN RETURN m.posted_journal_id; END IF;
  IF m.status = 'void' THEN RAISE EXCEPTION 'Credit memo is void'; END IF;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', coalesce(m.revenue_account_id, acct_role_account(m.tenant_id, m.entity_id, 'sales_returns')),
               'debit', m.subtotal, 'customer_id', m.customer_id::text, 'description', 'Credit memo ' || m.memo_number || coalesce(' - ' || m.reason, '')));
  IF m.tax_total > 0 THEN
    SELECT * INTO iv FROM acct_ar_invoices WHERE id = m.invoice_id;
    v_ratio := m.tax_total / NULLIF(iv.tax_total, 0);
    v_tax_left := m.tax_total;
    SELECT count(DISTINCT coalesce(tc.payable_account_id, acct_role_account(m.tenant_id, m.entity_id, 'sales_tax_payable'))) INTO v_n
      FROM acct_tax_transactions t LEFT JOIN acct_tax_codes tc ON tc.id = t.tax_code_id
     WHERE t.source_doc_type = 'acct_ar_invoices' AND t.source_doc_id = iv.id;
    FOR r IN SELECT coalesce(tc.payable_account_id, acct_role_account(m.tenant_id, m.entity_id, 'sales_tax_payable')) acct, sum(t.tax_amount) amt
               FROM acct_tax_transactions t LEFT JOIN acct_tax_codes tc ON tc.id = t.tax_code_id
              WHERE t.source_doc_type = 'acct_ar_invoices' AND t.source_doc_id = iv.id GROUP BY 1 HAVING sum(t.tax_amount) <> 0 ORDER BY 1 LOOP
      v_i := v_i + 1;
      v_amt := CASE WHEN v_i = v_n THEN v_tax_left ELSE round(r.amt * v_ratio, 2) END;   -- last jurisdiction absorbs rounding
      v_tax_left := v_tax_left - v_amt;
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', r.acct, 'debit', v_amt, 'customer_id', m.customer_id::text, 'description', 'Sales tax credited'));
    END LOOP;
    IF v_i = 0 THEN   -- invoice tax booked without jurisdiction detail
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(m.tenant_id, m.entity_id, 'sales_tax_payable'),
                   'debit', m.tax_total, 'customer_id', m.customer_id::text, 'description', 'Sales tax credited'));
    END IF;
  END IF;
  v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(m.tenant_id, m.entity_id, 'accounts_receivable'),
               'credit', m.total, 'customer_id', m.customer_id::text, 'description', 'Credit memo ' || m.memo_number));
  v_je := acct_post_entry(m.tenant_id, m.entity_id, m.memo_date, v_lines, 'credit_memo', m.id::text, m.memo_number, 'Credit memo ' || m.memo_number,
                          'credit_memo:' || m.id, NULL, NULL, m.currency, false, false, 'acct_ar_credit_memos', m.id);
  IF m.tax_total > 0 THEN
    INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
                                      tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason, journal_entry_id)
    SELECT m.tenant_id, m.entity_id, m.memo_date, 'sale', 'acct_ar_credit_memos', m.id, t.source_line_ref, t.jurisdiction_id, t.tax_code_id,
           t.tax_category, -round(t.gross_amount * v_ratio, 2), -round(t.taxable_amount * v_ratio, 2), -round(t.exempt_amount * v_ratio, 2), t.rate,
           -round(t.tax_amount * v_ratio, 2), 'Credit memo ' || m.memo_number, v_je
      FROM acct_tax_transactions t WHERE t.source_doc_type = 'acct_ar_invoices' AND t.source_doc_id = iv.id AND t.journal_entry_id = iv.posted_journal_id;
  END IF;
  UPDATE acct_ar_credit_memos SET posted_journal_id = v_je, status = 'posted', posted_at = now(), updated_at = now() WHERE id = m.id;
  IF p_apply_to_invoice AND m.invoice_id IS NOT NULL THEN
    SELECT open_balance INTO v_amt FROM acct_ar_invoices WHERE id = m.invoice_id;
    IF coalesce(v_amt,0) > 0 THEN PERFORM acct_apply_credit_memo(m.id, m.invoice_id, least(v_amt, m.total)); END IF;
  END IF;
  RETURN v_je;
END $$;

-- @seq 260
CREATE FUNCTION public.acct_post_draft_journal(p_journal_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o acct_journal_entries%ROWTYPE; v_lines jsonb; v_new uuid;
BEGIN
  SELECT * INTO o FROM acct_journal_entries WHERE id = p_journal_id FOR UPDATE;
  IF NOT FOUND OR o.status NOT IN ('draft','approved') THEN RAISE EXCEPTION 'Draft journal not found'; END IF;
  PERFORM acct_assert_access(o.tenant_id);
  SELECT jsonb_agg(to_jsonb(l) ORDER BY line_no) INTO v_lines FROM acct_journal_lines l WHERE journal_entry_id = p_journal_id;
  v_new := acct_post_entry(o.tenant_id, o.entity_id, o.entry_date, v_lines, o.source, o.source_id, o.reference, o.memo,
                           'draft:' || o.id, o.book_id, NULL, o.currency, o.is_adjusting);
  UPDATE acct_journal_entries SET status = 'void', memo = coalesce(o.memo,'') || ' [posted as #' ||
         (SELECT entry_no FROM acct_journal_entries WHERE id = v_new) || ']' WHERE id = p_journal_id;
  UPDATE acct_auto_reversals SET journal_entry_id = v_new WHERE journal_entry_id = p_journal_id AND status = 'scheduled';
  RETURN v_new;
END $$;

-- @seq 261
CREATE FUNCTION public.acct_post_entry(p_tenant_id uuid, p_entity_id uuid, p_entry_date date, p_lines jsonb, p_source text DEFAULT 'manual'::text, p_source_id text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_memo text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_book_id uuid DEFAULT NULL::uuid, p_period_id uuid DEFAULT NULL::uuid, p_currency text DEFAULT NULL::text, p_is_adjusting boolean DEFAULT false, p_is_closing boolean DEFAULT false, p_source_doc_type text DEFAULT NULL::text, p_source_doc_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE
  v_entity uuid := p_entity_id; v_book uuid := p_book_id; v_period uuid; v_currency text;
  b acct_books%ROWTYPE; p acct_periods%ROWTYPE; a acct_chart_of_accounts%ROWTYPE;
  v_batch uuid; v_entry uuid; v_existing uuid; v_line jsonb; v_no int := 0;
  v_dr numeric; v_cr numeric; v_tdr numeric := 0; v_tcr numeric := 0; v_source text;
  r record;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_lines IS NULL OR jsonb_typeof(p_lines) <> 'array' OR jsonb_array_length(p_lines) < 2 THEN
    RAISE EXCEPTION 'A journal entry needs at least two lines';
  END IF;
  -- idempotency: same key returns the same entry, never double-posts
  IF p_idempotency_key IS NOT NULL THEN
    SELECT e.id INTO v_existing FROM acct_journal_batches bt JOIN acct_journal_entries e ON e.batch_id = bt.id
     WHERE bt.tenant_id = p_tenant_id AND bt.idempotency_key = p_idempotency_key ORDER BY e.created_at LIMIT 1;
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;
  -- resolve company/book/period
  IF v_book IS NOT NULL THEN
    SELECT * INTO b FROM acct_books WHERE id = v_book AND tenant_id = p_tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Book not found for this tenant'; END IF;
    v_entity := b.entity_id;
  ELSE
    v_entity := coalesce(v_entity, acct_default_entity(p_tenant_id));
    IF v_entity IS NULL THEN RAISE EXCEPTION 'No company (acct_entities) set up for this tenant. Run acct_bootstrap_company first.'; END IF;
    v_book := acct_primary_book(p_tenant_id, v_entity);
    IF v_book IS NULL THEN RAISE EXCEPTION 'No primary book for company %', v_entity; END IF;
    SELECT * INTO b FROM acct_books WHERE id = v_book;
  END IF;
  IF p_entity_id IS NOT NULL AND p_entity_id <> b.entity_id THEN RAISE EXCEPTION 'Book does not belong to the given company'; END IF;
  v_currency := upper(coalesce(p_currency, b.currency));
  IF p_period_id IS NOT NULL THEN
    SELECT * INTO p FROM acct_periods WHERE id = p_period_id;
    IF NOT FOUND OR p.book_id <> v_book THEN RAISE EXCEPTION 'Period does not belong to this book'; END IF;
    IF p_entry_date NOT BETWEEN p.start_date AND p.end_date THEN RAISE EXCEPTION 'Entry date % is outside period %', p_entry_date, p.name; END IF;
    IF p.status = 'locked' OR (p.status = 'closed' AND NOT p_is_closing) OR (p.status = 'soft_closed' AND NOT (p_is_adjusting OR p_is_closing)) OR p.status = 'future' THEN
      RAISE EXCEPTION 'Period % is %; posting not allowed', p.name, p.status;
    END IF;
    v_period := p.id;
  ELSE
    v_period := acct_period_for(v_book, p_entry_date, p_is_adjusting OR p_is_closing, p_is_closing);
  END IF;
  -- source must be a known source type
  v_source := coalesce(p_source, 'manual');
  IF NOT v_source = ANY (enum_range(NULL::acct_source_type)::text[]) THEN
    RAISE EXCEPTION 'Unknown journal source "%"', v_source;
  END IF;

  INSERT INTO acct_journal_batches(tenant_id, entity_id, book_id, batch_no, source, status, description, idempotency_key, created_by)
  VALUES (p_tenant_id, v_entity, v_book, 'B-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSUS'), v_source, 'approved', p_memo, p_idempotency_key, auth.uid())
  RETURNING id INTO v_batch;
  INSERT INTO acct_journal_entries(tenant_id, entity_id, book_id, batch_id, period_id, entry_date, document_date, posting_date,
       source, source_id, reference, memo, currency, status, created_by, is_adjusting, is_closing, source_doc_type, source_doc_id)
  VALUES (p_tenant_id, v_entity, v_book, v_batch, v_period, p_entry_date, p_entry_date, p_entry_date,
       v_source, p_source_id, p_reference, p_memo, v_currency, 'approved', auth.uid(), p_is_adjusting, p_is_closing, p_source_doc_type, p_source_doc_id)
  RETURNING id INTO v_entry;

  FOR v_line IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    v_dr := acct_round(nullif(v_line->>'debit','')::numeric, v_currency);
    v_cr := acct_round(nullif(v_line->>'credit','')::numeric, v_currency);
    -- normalize negatives: a negative debit is a credit
    IF v_dr < 0 THEN v_cr := v_cr - v_dr; v_dr := 0; END IF;
    IF v_cr < 0 THEN v_dr := v_dr - v_cr; v_cr := 0; END IF;
    IF v_dr > 0 AND v_cr > 0 THEN
      IF v_dr >= v_cr THEN v_dr := v_dr - v_cr; v_cr := 0; ELSE v_cr := v_cr - v_dr; v_dr := 0; END IF;
    END IF;
    CONTINUE WHEN v_dr = 0 AND v_cr = 0;   -- zero lines are dropped
    SELECT * INTO a FROM acct_chart_of_accounts WHERE id = (v_line->>'account_id')::uuid;
    IF NOT FOUND THEN RAISE EXCEPTION 'Line %: account % does not exist', v_no + 1, v_line->>'account_id'; END IF;
    IF a.tenant_id <> p_tenant_id OR a.entity_id <> v_entity THEN RAISE EXCEPTION 'Line %: account % belongs to another company', v_no + 1, a.code; END IF;
    IF NOT a.is_active THEN RAISE EXCEPTION 'Line %: account % (%) is inactive', v_no + 1, a.code, a.name; END IF;
    IF NOT a.is_posting_allowed THEN RAISE EXCEPTION 'Line %: account % (%) is a header account; post to a sub-account', v_no + 1, a.code, a.name; END IF;
    IF a.account_type = 'statistical' THEN RAISE EXCEPTION 'Line %: statistical accounts cannot carry money', v_no + 1; END IF;
    -- control accounts (A/R, A/P) must carry the customer/vendor so subledgers tie out
    IF a.is_control_account AND coalesce(v_line->>'customer_id', v_line->>'vendor_id', v_line->>'employee_id') IS NULL THEN
      RAISE EXCEPTION 'Line %: % is a control account; a customer or vendor is required', v_no + 1, a.name;
    END IF;
    v_no := v_no + 1;
    INSERT INTO acct_journal_lines(tenant_id, entity_id, journal_entry_id, line_no, account_id, description, debit, credit,
         transaction_currency, transaction_debit, transaction_credit, exchange_rate, customer_id, vendor_id, employee_id,
         project_id, department_id, location_id, tax_code_id, source_line_id, dimensions, item_id)
    VALUES (p_tenant_id, v_entity, v_entry, v_no, a.id, v_line->>'description', v_dr, v_cr,
         upper(coalesce(v_line->>'transaction_currency', v_currency)),
         coalesce(nullif(v_line->>'transaction_debit','')::numeric, v_dr), coalesce(nullif(v_line->>'transaction_credit','')::numeric, v_cr),
         coalesce(nullif(v_line->>'exchange_rate','')::numeric, 1),
         v_line->>'customer_id', v_line->>'vendor_id', v_line->>'employee_id', v_line->>'project_id',
         v_line->>'department_id', v_line->>'location_id', nullif(v_line->>'tax_code_id','')::uuid,
         v_line->>'source_line_id', coalesce(v_line->'dimensions', '{}'::jsonb), nullif(v_line->>'item_id','')::uuid);
    v_tdr := v_tdr + v_dr; v_tcr := v_tcr + v_cr;
  END LOOP;

  IF v_no < 2 THEN RAISE EXCEPTION 'A journal entry needs at least two non-zero lines'; END IF;
  IF v_tdr <> v_tcr THEN RAISE EXCEPTION 'Journal not balanced: debits % <> credits % (difference %)', v_tdr, v_tcr, v_tdr - v_tcr; END IF;

  -- required dimensions (acct_account_dimension_rules)
  FOR r IN SELECT l.line_no, d.code, c.code AS acct
             FROM acct_journal_lines l
             JOIN acct_account_dimension_rules dr ON dr.account_id = l.account_id AND dr.is_required
             JOIN acct_dimensions d ON d.id = dr.dimension_id
             JOIN acct_chart_of_accounts c ON c.id = l.account_id
            WHERE l.journal_entry_id = v_entry AND NOT (l.dimensions ? d.code) LOOP
    RAISE EXCEPTION 'Line %: account % requires dimension "%"', r.line_no, r.acct, r.code;
  END LOOP;

  UPDATE acct_journal_entries SET total_debit = v_tdr, total_credit = v_tcr, status = 'posted', posted_by = auth.uid(), posted_at = now()
   WHERE id = v_entry;
  UPDATE acct_journal_batches SET status = 'posted', posted_by = auth.uid(), posted_at = now() WHERE id = v_batch;
  RETURN v_entry;
END $$;

-- @seq 262
CREATE FUNCTION public.acct_post_erp_count_session(p_tenant_id uuid, p_session_id uuid, p_count_date date DEFAULT CURRENT_DATE) RETURNS SETOF record
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v jsonb;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT jsonb_agg(jsonb_build_object('item_id', i.id, 'counted_qty', s.qty)) INTO v
    FROM (SELECT sku_id, sum(counted_quantity) qty FROM erp_inventory_count_lines WHERE tenant_id = p_tenant_id AND count_session_id = p_session_id
           AND counted_quantity IS NOT NULL GROUP BY sku_id) s
    JOIN acct_items i ON i.tenant_id = p_tenant_id AND i.sku_id = s.sku_id AND i.item_type = 'inventory';
  IF v IS NULL THEN RAISE EXCEPTION 'No counted lines linked to inventory items in that session'; END IF;
  PERFORM acct_post_inventory_count(p_tenant_id, p_count_date, v, 'COUNT ' || p_session_id);
END $$;

-- @seq 263
CREATE FUNCTION public.acct_post_inventory_count(p_tenant_id uuid, p_count_date date, p_counts jsonb, p_reference text DEFAULT NULL::text) RETURNS TABLE(item_id uuid, item_name text, on_hand numeric, counted numeric, change numeric, value_change numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE x jsonb; it acct_items%ROWTYPE; v_oh numeric; v_move uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR x IN SELECT value FROM jsonb_array_elements(p_counts) LOOP
    SELECT * INTO it FROM acct_items WHERE id = (x->>'item_id')::uuid AND tenant_id = p_tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Item % not found', x->>'item_id'; END IF;
    SELECT coalesce(sum(m.quantity),0) INTO v_oh FROM acct_inventory_moves m WHERE m.item_id = it.id AND m.move_date <= p_count_date;
    v_move := NULL;
    IF (x->>'counted_qty')::numeric <> v_oh THEN
      v_move := acct_inventory_adjust(it.id, (x->>'counted_qty')::numeric - v_oh, p_count_date, 'Physical count', NULL, NULL, coalesce(p_reference,'COUNT'), 'count');
    END IF;
    item_id := it.id; item_name := it.name; on_hand := v_oh; counted := (x->>'counted_qty')::numeric; change := counted - v_oh;
    value_change := coalesce((SELECT total_cost FROM acct_inventory_moves WHERE id = v_move), 0);
    RETURN NEXT;
  END LOOP;
END $$;

-- @seq 264
CREATE FUNCTION public.acct_post_invoice(p_invoice_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE iv acct_ar_invoices%ROWTYPE; v_ar uuid; v_lines jsonb := '[]'::jsonb; v_je uuid; v_sub numeric; v_disc numeric; v_tax numeric := 0;
        v_total numeric; r record; v_cust text; v_sr_bank uuid;
BEGIN
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  PERFORM acct_assert_access(iv.tenant_id);
  IF iv.posted_journal_id IS NOT NULL THEN RETURN iv.posted_journal_id; END IF;
  IF iv.status = 'void' THEN RAISE EXCEPTION 'Invoice is void'; END IF;
  IF NOT EXISTS (SELECT 1 FROM acct_ar_invoice_lines WHERE invoice_id = iv.id) THEN RAISE EXCEPTION 'Invoice has no lines'; END IF;
  v_cust := iv.customer_id::text;
  v_ar := acct_role_account(iv.tenant_id, iv.entity_id, 'accounts_receivable');
  SELECT coalesce(sum(line_subtotal),0) INTO v_sub FROM acct_ar_invoice_lines WHERE invoice_id = iv.id;
  v_disc := CASE WHEN iv.discount_percent IS NOT NULL THEN round(v_sub * iv.discount_percent / 100, 2) ELSE iv.discount_total END;
  IF v_disc > v_sub THEN RAISE EXCEPTION 'Discount exceeds the subtotal'; END IF;

  -- revenue lines (discount-type lines are debits to their account)
  SELECT v_lines || coalesce(jsonb_agg(jsonb_build_object('account_id', l.revenue_account_id,
            'credit', greatest(l.line_subtotal,0), 'debit', greatest(-l.line_subtotal,0),
            'description', l.description, 'customer_id', v_cust, 'item_id', l.item_id, 'dimensions', l.dimensions) ORDER BY l.line_no), '[]'::jsonb)
    INTO v_lines FROM acct_ar_invoice_lines l WHERE l.invoice_id = iv.id AND l.line_subtotal <> 0;
  IF iv.shipping_amount > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(iv.tenant_id, iv.entity_id, 'shipping_income'),
                 'credit', iv.shipping_amount, 'description', 'Shipping', 'customer_id', v_cust));
  END IF;
  IF v_disc > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(iv.tenant_id, iv.entity_id, 'discounts_given'),
                 'debit', v_disc, 'description', 'Discount', 'customer_id', v_cust));
  END IF;

  -- sales tax, fixed at posting and written to the tax subledger
  DELETE FROM acct_tax_transactions WHERE source_doc_type = 'acct_ar_invoices' AND source_doc_id = iv.id AND journal_entry_id IS NULL;
  IF iv.tax_jurisdiction_id IS NOT NULL THEN
    INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id,
                                      tax_code_id, rule_id, tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason)
    SELECT iv.tenant_id, iv.entity_id, iv.invoice_date, 'sale', 'acct_ar_invoices', iv.id, c.line_ref, c.jurisdiction_id, c.tax_code_id, c.rule_id,
           c.tax_category, c.gross_amount, c.taxable_amount, c.exempt_amount, c.rate, c.tax_amount, c.reason
      FROM acct_calculate_tax(iv.tenant_id, iv.entity_id, iv.invoice_date, iv.tax_jurisdiction_id, iv.customer_id,
                              acct_invoice_tax_payload(iv.id, v_disc), 'sale') c;
    FOR r IN SELECT coalesce(tc.payable_account_id, acct_role_account(iv.tenant_id, iv.entity_id, 'sales_tax_payable')) acct,
                    j.name jname, sum(t.tax_amount) amt
               FROM acct_tax_transactions t LEFT JOIN acct_tax_codes tc ON tc.id = t.tax_code_id
               LEFT JOIN acct_tax_jurisdictions j ON j.id = t.jurisdiction_id
              WHERE t.source_doc_type = 'acct_ar_invoices' AND t.source_doc_id = iv.id AND t.journal_entry_id IS NULL
              GROUP BY 1, 2 HAVING sum(t.tax_amount) <> 0 LOOP
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', r.acct, 'credit', r.amt, 'description', 'Sales tax ' || coalesce(r.jname,''),
                   'customer_id', v_cust));
      v_tax := v_tax + r.amt;
    END LOOP;
    UPDATE acct_ar_invoice_lines l SET tax_amount = coalesce((SELECT sum(t.tax_amount) FROM acct_tax_transactions t
           WHERE t.source_doc_id = iv.id AND t.source_doc_type = 'acct_ar_invoices' AND t.source_line_ref = l.id::text AND t.journal_entry_id IS NULL), 0)
     WHERE l.invoice_id = iv.id;
  END IF;
  v_total := v_sub - v_disc + iv.shipping_amount + v_tax;
  IF v_total < 0 THEN RAISE EXCEPTION 'Invoice total cannot be negative (use a credit memo)'; END IF;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', v_ar, 'debit', v_total, 'customer_id', v_cust,
               'description', initcap(replace(iv.document_kind,'_',' ')) || ' ' || iv.invoice_number || ' ' || coalesce(acct_customer_name(iv.customer_id),''))) || v_lines;
  -- apply deposits received before posting
  IF iv.deposit_paid > 0 THEN
    v_lines := v_lines || jsonb_build_array(
      jsonb_build_object('account_id', acct_role_account(iv.tenant_id, iv.entity_id, 'customer_deposits'), 'debit', least(iv.deposit_paid, v_total), 'customer_id', v_cust, 'description', 'Apply deposit'),
      jsonb_build_object('account_id', v_ar, 'credit', least(iv.deposit_paid, v_total), 'customer_id', v_cust, 'description', 'Apply deposit'));
  END IF;
  v_je := acct_post_entry(iv.tenant_id, iv.entity_id, iv.invoice_date, v_lines, 'invoice', iv.id::text, iv.invoice_number,
                          coalesce(iv.memo_on_statement, initcap(replace(iv.document_kind,'_',' ')) || ' ' || iv.invoice_number),
                          'invoice:' || iv.id, NULL, NULL, iv.currency, false, false, 'acct_ar_invoices', iv.id);
  UPDATE acct_tax_transactions SET journal_entry_id = v_je WHERE source_doc_type = 'acct_ar_invoices' AND source_doc_id = iv.id AND journal_entry_id IS NULL;
  UPDATE acct_ar_invoices SET subtotal = v_sub, discount_total = v_disc, tax_total = v_tax, total = v_total,
         amount_paid = least(deposit_paid, v_total), posted_journal_id = v_je,
         status = CASE WHEN least(deposit_paid, v_total) >= v_total THEN 'paid' WHEN deposit_paid > 0 THEN 'partially_paid'
                       WHEN status IN ('draft','pending','scheduled') THEN 'open' ELSE status END,
         paid_at = CASE WHEN least(deposit_paid, v_total) >= v_total THEN now() END
   WHERE id = iv.id;
  -- sales receipt = invoice + immediate payment
  IF iv.document_kind = 'sales_receipt' AND v_total > 0 THEN
    v_sr_bank := coalesce(iv.sales_receipt_bank_account_id, acct_system_register(iv.tenant_id, iv.entity_id, 'undeposited_funds'));
    PERFORM acct_record_receipt(iv.tenant_id, iv.customer_id, iv.invoice_date, v_total, coalesce(iv.sales_receipt_method, 'cash'), v_sr_bank,
                                jsonb_build_array(jsonb_build_object('invoice_id', iv.id, 'amount', v_total)), iv.invoice_number, NULL, NULL,
                                'salesreceipt:' || iv.id, 0, iv.entity_id);
  END IF;
  RETURN v_je;
END $$;

-- @seq 265
CREATE FUNCTION public.acct_post_journal(p_tenant_id uuid, p_book_id uuid, p_period_id uuid, p_entry_date date, p_currency character, p_lines jsonb, p_source public.acct_source_type DEFAULT 'manual'::public.acct_source_type, p_source_id text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_memo text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT acct_post_entry(p_tenant_id, NULL, p_entry_date, p_lines, p_source::text, p_source_id, p_reference, p_memo,
                         p_idempotency_key, p_book_id, p_period_id, p_currency::text);
$$;

-- @seq 266
CREATE FUNCTION public.acct_post_payroll_run(p_run_id uuid, p_pay_from_bank_account_id uuid DEFAULT NULL::uuid, p_pay_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_payroll_runs%ROWTYPE; v_entity uuid; t record; v_bank uuid; v_date date; v_lines jsonb; v_je uuid; v_wages numeric;
BEGIN
  SELECT * INTO r FROM acct_payroll_runs WHERE id = p_run_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Payroll run not found'; END IF;
  PERFORM acct_assert_access(r.tenant_id);
  IF r.gl_journal_entry_id IS NOT NULL THEN RETURN r.gl_journal_entry_id; END IF;
  v_entity := acct_default_entity(r.tenant_id);
  SELECT coalesce(sum(gross_pay),0) gross, coalesce(sum(tips_pay),0) tips,
         coalesce(sum(federal_income_tax + state_income_tax + local_income_tax + social_security_ee + medicare_ee),0) ee_tax,
         coalesce(sum(social_security_er + medicare_er + futa_er + suta_er),0) er_tax,
         coalesce(sum(pretax_deductions + posttax_deductions),0) deductions, coalesce(sum(net_pay),0) net, count(*) n
    INTO t FROM acct_payroll_run_items WHERE payroll_run_id = r.id;
  IF t.n = 0 THEN RAISE EXCEPTION 'Payroll run has no employees'; END IF;
  IF abs(t.gross - t.ee_tax - t.deductions - t.net) > 0.01 THEN
    RAISE EXCEPTION 'Payroll does not add up: gross % - employee taxes % - deductions % <> net pay % (difference %)',
      t.gross, t.ee_tax, t.deductions, t.net, t.gross - t.ee_tax - t.deductions - t.net; END IF;
  v_bank := coalesce(p_pay_from_bank_account_id, nullif(r.metadata->>'bank_account_id','')::uuid, acct_payout_register(r.tenant_id, v_entity));
  IF v_bank IS NULL THEN RAISE EXCEPTION 'Choose the bank account payroll is paid from'; END IF;
  v_date := coalesce(p_pay_date, r.processed_at::date, r.approved_at::date, current_date);
  v_wages := t.gross - t.tips;   -- tips paid through payroll clear the Tips Payable collected at sale time
  v_lines := jsonb_build_array(
    jsonb_build_object('account_id', acct_role_account(r.tenant_id, v_entity, 'wages_expense'), 'debit', v_wages, 'description', 'Gross wages ' || coalesce(r.run_number,'')),
    jsonb_build_object('account_id', acct_role_account(r.tenant_id, v_entity, 'tips_payable'), 'debit', t.tips, 'description', 'Tips paid through payroll'),
    jsonb_build_object('account_id', acct__role(r.tenant_id, v_entity, 'payroll_tax_expense'), 'debit', t.er_tax, 'description', 'Employer payroll taxes'),
    jsonb_build_object('account_id', acct_role_account(r.tenant_id, v_entity, 'payroll_liabilities'), 'credit', t.ee_tax + t.er_tax + t.deductions,
                       'description', 'Payroll taxes and deductions owed'),
    jsonb_build_object('account_id', acct_bank_gl(v_bank), 'credit', t.net, 'description', 'Net pay ' || coalesce(r.run_number,'')));
  SELECT jsonb_agg(x) INTO v_lines FROM jsonb_array_elements(v_lines) x
   WHERE coalesce((x->>'debit')::numeric,0) <> 0 OR coalesce((x->>'credit')::numeric,0) <> 0;
  v_je := acct_post_entry(r.tenant_id, v_entity, v_date, v_lines, 'payroll', r.id::text, r.run_number, 'Payroll ' || coalesce(r.run_number,''),
                          'payroll:' || r.id, NULL, NULL, NULL, false, false, 'acct_payroll_runs', r.id);
  UPDATE acct_payroll_runs SET gl_journal_entry_id = v_je, gross_total = t.gross, net_total = t.net, employee_tax_total = t.ee_tax,
         employer_tax_total = t.er_tax, deduction_total = t.deductions, employee_count = t.n, updated_at = now() WHERE id = r.id;
  RETURN v_je;
END $$;

-- @seq 267
CREATE FUNCTION public.acct_post_refund(p_refund_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f acct_refunds%ROWTYPE; iv acct_ar_invoices%ROWTYPE; pol acct_refund_policies%ROWTYPE; v_entity uuid; v_tax numeric := 0; v_net numeric;
        v_lines jsonb; v_je uuid; v_credit_acct uuid; v_reg uuid; v_ratio numeric; v_paid_refunded numeric; v_gc uuid; r record; v_cust text;
BEGIN
  SELECT * INTO f FROM acct_refunds WHERE id = p_refund_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Refund not found'; END IF;
  PERFORM acct_assert_access(f.tenant_id);
  IF f.posted_journal_id IS NOT NULL THEN RETURN f.posted_journal_id; END IF;
  IF f.amount <= 0 THEN RAISE EXCEPTION 'Refund amount must be positive'; END IF;
  SELECT * INTO pol FROM acct_refund_policies WHERE tenant_id = f.tenant_id;
  -- refund policy: manual refunds at/above the approval line wait for a second person (Stripe-initiated refunds already happened)
  IF f.status = 'pending_approval' THEN RAISE EXCEPTION 'Refund % is waiting for approval', f.refund_number; END IF;
  IF f.status = 'requested' THEN
    IF pol.id IS NOT NULL AND f.processor IS DISTINCT FROM 'stripe' AND f.amount >= pol.require_approval_above THEN
      UPDATE acct_refunds SET status = 'pending_approval' WHERE id = f.id;
      RETURN NULL;   -- caller shows "sent for approval"
    END IF;
  ELSIF f.status <> 'approved' THEN RAISE EXCEPTION 'Refund is %', f.status; END IF;
  v_entity := coalesce(f.entity_id, acct_default_entity(f.tenant_id));
  v_cust := f.customer_id::text;
  IF f.invoice_id IS NOT NULL THEN
    SELECT * INTO iv FROM acct_ar_invoices WHERE id = f.invoice_id;
    v_cust := coalesce(v_cust, iv.customer_id::text);
    SELECT coalesce(sum(amount),0) INTO v_paid_refunded FROM acct_refunds WHERE invoice_id = iv.id AND posted_journal_id IS NOT NULL AND id <> f.id;
    IF f.amount + v_paid_refunded > iv.amount_paid THEN RAISE EXCEPTION 'Refunds (% + %) would exceed the % collected on %', v_paid_refunded, f.amount, iv.amount_paid, iv.invoice_number; END IF;
    IF iv.total > 0 AND iv.tax_total > 0 THEN
      v_ratio := f.amount / iv.total;
      SELECT coalesce(sum(x.amt),0) INTO v_tax FROM (SELECT round(sum(t.tax_amount) * v_ratio, 2) amt FROM acct_tax_transactions t
         LEFT JOIN acct_tax_codes tc ON tc.id = t.tax_code_id
        WHERE t.source_doc_type = 'acct_ar_invoices' AND t.source_doc_id = iv.id
        GROUP BY coalesce(tc.payable_account_id, acct_role_account(f.tenant_id, iv.entity_id, 'sales_tax_payable'))) x;
    END IF;
  END IF;
  v_net := f.amount - v_tax;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', acct_role_account(f.tenant_id, v_entity, 'sales_returns'), 'debit', v_net + f.restocking_fee,
               'customer_id', v_cust, 'description', 'Refund ' || f.refund_number || coalesce(' - ' || f.reason, '')));
  IF f.restocking_fee > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(f.tenant_id, v_entity, 'default_income'), 'credit', f.restocking_fee,
                 'customer_id', v_cust, 'description', 'Restocking fee'));
  END IF;
  IF v_tax > 0 THEN
    -- reverse tax by jurisdiction in the same proportion
    FOR r IN SELECT coalesce(tc.payable_account_id, acct_role_account(f.tenant_id, v_entity, 'sales_tax_payable')) acct, sum(t.tax_amount) amt
               FROM acct_tax_transactions t LEFT JOIN acct_tax_codes tc ON tc.id = t.tax_code_id
              WHERE t.source_doc_type = 'acct_ar_invoices' AND t.source_doc_id = iv.id GROUP BY 1 HAVING sum(t.tax_amount) <> 0 LOOP
      v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', r.acct, 'debit', round(r.amt * v_ratio, 2), 'customer_id', v_cust, 'description', 'Sales tax refunded'));
    END LOOP;
  END IF;
  IF f.refund_type = 'store_credit' THEN
    v_credit_acct := acct_role_account(f.tenant_id, v_entity, 'gift_card_liability');
    INSERT INTO acct_gift_cards(tenant_id, entity_id, code, kind, status, initial_amount, balance, customer_id, issued_reason)
    VALUES (f.tenant_id, v_entity, 'SC-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)), 'store_credit', 'active', f.amount, f.amount, f.customer_id, 'Refund ' || f.refund_number)
    RETURNING id INTO v_gc;
  ELSE
    v_reg := coalesce(f.refund_from_bank_account_id,
                      (SELECT deposit_account_id FROM acct_ar_receipts WHERE id = f.receipt_id),
                      CASE WHEN f.processor = 'stripe' THEN acct_system_register(f.tenant_id, v_entity, 'stripe') END);
    IF v_reg IS NULL THEN RAISE EXCEPTION 'Choose the account the refund is paid from'; END IF;
    v_credit_acct := acct_bank_gl(v_reg);
  END IF;
  v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', v_credit_acct, 'credit', f.amount, 'customer_id', v_cust, 'description', 'Refund ' || f.refund_number));
  -- balance check for float rounding on multi-jurisdiction tax split
  v_je := acct_post_entry(f.tenant_id, v_entity, coalesce(f.issued_at::date, current_date), v_lines, 'credit_memo', f.id::text, f.refund_number,
                          'Refund ' || f.refund_number, 'refund:' || f.id, NULL, NULL, f.currency, false, false, 'acct_refunds', f.id);
  IF v_tax > 0 THEN
    INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
                                      tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason, journal_entry_id)
    SELECT f.tenant_id, v_entity, coalesce(f.issued_at::date, current_date), 'sale', 'acct_refunds', f.id, t.source_line_ref, t.jurisdiction_id, t.tax_code_id,
           t.tax_category, -round(t.gross_amount * v_ratio, 2), -round(t.taxable_amount * v_ratio, 2), -round(t.exempt_amount * v_ratio, 2), t.rate,
           -round(t.tax_amount * v_ratio, 2), 'Refund ' || f.refund_number, v_je
      FROM acct_tax_transactions t WHERE t.source_doc_type = 'acct_ar_invoices' AND t.source_doc_id = iv.id AND t.journal_entry_id = iv.posted_journal_id;
  END IF;
  UPDATE acct_refunds SET posted_journal_id = v_je, status = 'issued', issued_at = coalesce(issued_at, now()), tax_amount = v_tax, entity_id = v_entity, gift_card_id = v_gc WHERE id = f.id;
  IF v_gc IS NOT NULL THEN
    INSERT INTO acct_gift_card_transactions(tenant_id, gift_card_id, txn_type, amount, balance_after, reference, posted_journal_id)
    VALUES (f.tenant_id, v_gc, 'issue', f.amount, f.amount, f.refund_number, v_je);
  END IF;
  RETURN v_je;
END $$;

-- @seq 268
CREATE FUNCTION public.acct_post_spend(p_spend_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s acct_spend_transactions%ROWTYPE; v_gl uuid; v_lines jsonb; v_credit boolean; v_je uuid; v_bank_line uuid;
BEGIN
  SELECT * INTO s FROM acct_spend_transactions WHERE id = p_spend_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Transaction not found'; END IF;
  PERFORM acct_assert_access(s.tenant_id);
  IF s.status = 'posted' THEN RETURN s.posted_journal_id; END IF;
  IF s.status = 'void' THEN RAISE EXCEPTION 'Transaction is void'; END IF;
  IF s.total <= 0 THEN RAISE EXCEPTION 'Total must be greater than zero'; END IF;
  v_gl := acct_bank_gl(s.bank_account_id); v_credit := s.txn_kind = 'cc_credit';
  SELECT jsonb_agg(jsonb_build_object('account_id', l.account_id,
           'debit',  CASE WHEN v_credit THEN 0 ELSE l.amount + l.tax_amount END,
           'credit', CASE WHEN v_credit THEN l.amount + l.tax_amount ELSE 0 END,
           'description', coalesce(l.description, s.memo), 'vendor_id', s.payee_vendor_id, 'item_id', l.item_id, 'dimensions', l.dimensions,
           'customer_id', CASE WHEN l.billable THEN l.billable_customer_id END) ORDER BY l.line_no)
    INTO v_lines FROM acct_spend_lines l WHERE l.spend_id = s.id AND l.amount + l.tax_amount <> 0;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', v_gl,
               'debit', CASE WHEN v_credit THEN s.total ELSE 0 END, 'credit', CASE WHEN v_credit THEN 0 ELSE s.total END,
               'description', concat_ws(' ', initcap(replace(s.txn_kind,'_',' ')), s.ref_no, coalesce(s.payee_name, (SELECT coalesce(display_name, legal_name) FROM acct_vendors WHERE id = s.payee_vendor_id))),
               'vendor_id', s.payee_vendor_id)) || v_lines;
  v_je := acct_post_entry(s.tenant_id, s.entity_id, s.payment_date, v_lines, 'expense', s.id::text, s.ref_no, coalesce(s.memo, initcap(replace(s.txn_kind,'_',' '))),
                          'spend:' || s.id, NULL, NULL, s.currency, false, false, 'acct_spend_transactions', s.id);
  UPDATE acct_spend_transactions SET status = 'posted', posted_journal_id = v_je WHERE id = s.id;
  -- created from a bank-feed line: tie them together and clear it
  IF s.bank_transaction_id IS NOT NULL THEN
    SELECT id INTO v_bank_line FROM acct_journal_lines WHERE journal_entry_id = v_je AND account_id = v_gl LIMIT 1;
    PERFORM acct_match_bank_transaction(s.bank_transaction_id, v_bank_line);
  END IF;
  RETURN v_je;
END $$;

-- @seq 269
CREATE FUNCTION public.acct_post_vendor_credit(p_credit_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c acct_ap_vendor_credits%ROWTYPE; v acct_vendors%ROWTYPE; v_lines jsonb; v_total numeric; v_je uuid;
BEGIN
  SELECT * INTO c FROM acct_ap_vendor_credits WHERE id = p_credit_id FOR UPDATE;
  PERFORM acct_assert_access(c.tenant_id);
  IF c.status <> 'draft' THEN RETURN c.posted_journal_id; END IF;
  SELECT * INTO v FROM acct_vendors WHERE id = c.vendor_id;
  SELECT coalesce(sum(amount),0), jsonb_agg(jsonb_build_object('account_id', account_id, 'credit', amount, 'description', description,
           'vendor_id', c.vendor_id, 'item_id', item_id) ORDER BY line_no)
    INTO v_total, v_lines FROM acct_ap_vendor_credit_lines WHERE credit_id = c.id;
  IF v_total <= 0 THEN RAISE EXCEPTION 'Vendor credit has no lines'; END IF;
  v_lines := jsonb_build_array(jsonb_build_object('account_id', v.ap_account_id, 'debit', v_total, 'vendor_id', c.vendor_id,
               'description', 'Vendor credit ' || c.credit_number)) || v_lines;
  v_je := acct_post_entry(c.tenant_id, c.entity_id, c.credit_date, v_lines, 'vendor_credit', c.id::text, c.credit_number, coalesce(c.memo, 'Vendor credit'),
                          'vcredit:' || c.id, NULL, NULL, c.currency, false, false, 'acct_ap_vendor_credits', c.id);
  UPDATE acct_ap_vendor_credits SET total = v_total, status = 'open', posted_journal_id = v_je WHERE id = c.id;
  RETURN v_je;
END $$;

-- @seq 270
CREATE FUNCTION public.acct_prepare_sales_tax_filing(p_tenant_id uuid, p_entity_id uuid, p_jurisdiction_id uuid, p_start date, p_end date, p_due_date date DEFAULT NULL::date, p_adjustments numeric DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_id uuid; s record;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  -- include child jurisdictions (cities file with the state in MS)
  SELECT coalesce(sum(gross_amount),0) g, coalesce(sum(taxable_amount),0) tx, coalesce(sum(exempt_amount),0) ex, coalesce(sum(tax_amount),0) tax
    INTO s FROM acct_tax_transactions t
   WHERE t.tenant_id = p_tenant_id AND t.entity_id = p_entity_id AND t.direction = 'sale' AND t.filing_id IS NULL
     AND t.tax_date BETWEEN p_start AND p_end
     AND t.jurisdiction_id IN (WITH RECURSIVE d AS (SELECT id FROM acct_tax_jurisdictions WHERE id = p_jurisdiction_id
                               UNION ALL SELECT x.id FROM acct_tax_jurisdictions x JOIN d ON x.parent_id = d.id) SELECT id FROM d);
  INSERT INTO acct_tax_filings(tenant_id, entity_id, jurisdiction_id, period_label, period_start, period_end, taxable_sales,
         exempt_sales, tax_collected, tax_remitted, adjustments, amount_due, due_date, status)
  VALUES (p_tenant_id, p_entity_id, p_jurisdiction_id, to_char(p_start,'Mon YYYY') || ' - ' || to_char(p_end,'Mon YYYY'),
          p_start, p_end, s.tx, s.ex, s.tax, 0, p_adjustments, s.tax + p_adjustments, p_due_date, 'draft')
  RETURNING id INTO v_id;
  UPDATE acct_tax_transactions t SET filing_id = v_id
   WHERE t.tenant_id = p_tenant_id AND t.entity_id = p_entity_id AND t.direction = 'sale' AND t.filing_id IS NULL
     AND t.tax_date BETWEEN p_start AND p_end
     AND t.jurisdiction_id IN (WITH RECURSIVE d AS (SELECT id FROM acct_tax_jurisdictions WHERE id = p_jurisdiction_id
                               UNION ALL SELECT x.id FROM acct_tax_jurisdictions x JOIN d ON x.parent_id = d.id) SELECT id FROM d);
  RETURN v_id;
END $$;

-- @seq 271
CREATE FUNCTION public.acct_primary_book(p_tenant_id uuid, p_entity_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT id FROM acct_books WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id AND active
  ORDER BY is_primary DESC, created_at LIMIT 1;
$$;

-- @seq 272
CREATE FUNCTION public.acct_print_checks(p_bank_account_id uuid, p_payment_ids uuid[], p_starting_check_no bigint DEFAULT NULL::bigint) RETURNS TABLE(payment_id uuid, check_number bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE r acct_bank_accounts%ROWTYPE; v_no bigint; p record;
BEGIN
  SELECT * INTO r FROM acct_bank_accounts WHERE id = p_bank_account_id FOR UPDATE;
  PERFORM acct_assert_access(r.tenant_id);
  v_no := coalesce(p_starting_check_no, r.next_check_number, 1001);
  FOR p IN SELECT x.id, 'ap' AS k FROM acct_ap_payments x WHERE x.id = ANY (p_payment_ids) AND x.cash_account_id = r.id AND x.print_status = 'to_print'
           UNION ALL
           SELECT s.id, 'spend' FROM acct_spend_transactions s WHERE s.id = ANY (p_payment_ids) AND s.bank_account_id = r.id AND s.print_status = 'to_print'
           ORDER BY 1 LOOP
    IF p.k = 'ap' THEN UPDATE acct_ap_payments SET check_number = v_no, print_status = 'printed' WHERE id = p.id;
    ELSE UPDATE acct_spend_transactions SET check_number = v_no, print_status = 'printed', ref_no = coalesce(ref_no, v_no::text) WHERE id = p.id; END IF;
    payment_id := p.id; check_number := v_no; RETURN NEXT;
    v_no := v_no + 1;
  END LOOP;
  UPDATE acct_bank_accounts SET next_check_number = v_no WHERE id = r.id;
END $$;

-- @seq 273
CREATE FUNCTION public.acct_process_processor_event(p_event_row_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE ev acct_processor_events%ROWTYPE; o jsonb; v_entity uuid; v_cur text; v_amt numeric; v_fee numeric; v_res jsonb; v_rid uuid; v_cust uuid;
        v_inv uuid; v_link uuid; v_charge text; rf jsonb; v_fid uuid; v_inv_row acct_ar_invoices%ROWTYPE; v_disp uuid; v_reg uuid; v_je uuid; v_date date;
        v_ord uuid; v_ord_mode text;
BEGIN
  SELECT * INTO ev FROM acct_processor_events WHERE id = p_event_row_id FOR UPDATE;
  UPDATE acct_processor_events SET attempts = attempts + 1 WHERE id = ev.id;
  IF ev.tenant_id IS NULL THEN
    UPDATE acct_processor_events SET status = 'ignored', error = 'No tenant for this Stripe account', processed_at = now() WHERE id = ev.id;
    RETURN jsonb_build_object('event', ev.id, 'status', 'ignored');
  END IF;
  o := ev.payload#>'{data,object}';
  v_entity := coalesce(nullif(o#>>'{metadata,entity_id}','')::uuid, acct_default_entity(ev.tenant_id));
  v_cur := upper(coalesce(o->>'currency','usd'));
  v_date := to_timestamp(coalesce((ev.payload->>'created')::bigint, extract(epoch FROM now())::bigint))::date;
  BEGIN
    CASE ev.event_type
    WHEN 'charge.succeeded', 'payment_intent.succeeded' THEN
      v_charge := CASE WHEN ev.event_type = 'charge.succeeded' THEN o->>'id' ELSE coalesce(o->>'latest_charge', o->>'id') END;
      v_amt := acct_minor_to_major(coalesce((o->>'amount_received')::bigint, (o->>'amount_captured')::bigint, (o->>'amount')::bigint), v_cur);
      v_fee := acct_minor_to_major(coalesce((ev.payload->>'unsaid_fee')::bigint, (o#>>'{balance_transaction,fee}')::bigint, 0), v_cur);
      v_cust := nullif(o#>>'{metadata,customer_id}','')::uuid;
      v_inv  := nullif(o#>>'{metadata,invoice_id}','')::uuid;
      v_link := coalesce(nullif(o#>>'{metadata,payment_link_id}','')::uuid,
                         (SELECT id FROM acct_payment_links WHERE provider_link_id = o#>>'{metadata,stripe_payment_link}' OR provider_link_id = o->>'payment_link' LIMIT 1));
      -- shop orders (part 8): a charge for an erp_orders row posts against that order, not a loose receipt
      IF v_link IS NULL AND v_inv IS NULL AND to_regprocedure('public.acct__order_for_charge(uuid,jsonb)') IS NOT NULL THEN
        EXECUTE 'SELECT public.acct__order_for_charge($1, $2)' INTO v_ord USING ev.tenant_id, o;
      END IF;
      IF v_ord IS NOT NULL THEN
        EXECUTE 'SELECT public.acct__order_payment_mode($1, $2)' INTO v_ord_mode USING ev.tenant_id, v_entity;
        IF v_ord_mode = 'order' THEN
          -- company setting says payments are booked from the order's amount_paid; do not count the charge twice
          v_res := jsonb_build_object('order_id', v_ord, 'note', 'order payments are recorded from the order (acct_settings.order_payment_source = order)');
        ELSE
          EXECUTE 'SELECT public.acct__order_processor_payment($1, $2, $3, $4, $5)' INTO v_je USING v_ord, v_amt, v_fee, v_charge, v_date;
          v_res := jsonb_build_object('order_id', v_ord, 'journal_id', v_je);
        END IF;
      ELSIF v_link IS NOT NULL THEN
        v_rid := acct_record_payment_link_payment(v_link, v_cust, v_date, v_amt, coalesce((o#>>'{metadata,quantity}')::numeric,1), v_fee, v_charge, 'stripe:' || v_charge);
      ELSE
        IF v_cust IS NULL AND v_inv IS NOT NULL THEN SELECT customer_id INTO v_cust FROM acct_ar_invoices WHERE id = v_inv; END IF;
        IF v_cust IS NULL THEN RAISE EXCEPTION 'Charge % has no customer_id/invoice_id/payment_link metadata', v_charge; END IF;
        v_rid := acct_record_receipt(ev.tenant_id, v_cust, v_date, v_amt, 'card', acct_system_register(ev.tenant_id, v_entity, 'stripe'),
                   CASE WHEN v_inv IS NOT NULL THEN jsonb_build_array(jsonb_build_object('invoice_id', v_inv,
                        'amount', least(v_amt, coalesce((SELECT CASE WHEN posted_journal_id IS NULL THEN v_amt ELSE open_balance END FROM acct_ar_invoices WHERE id = v_inv), v_amt))))
                        ELSE '[]'::jsonb END,
                   v_charge, 'stripe', v_charge, 'stripe:' || v_charge, v_fee, v_entity);
      END IF;
      v_res := coalesce(v_res, jsonb_build_object('receipt_id', v_rid));
    WHEN 'charge.refunded' THEN
      v_charge := o->>'id';
      -- refund of a shop-order charge (part 8)
      IF to_regclass('public.acct_order_payments') IS NOT NULL THEN
        EXECUTE 'SELECT order_id FROM public.acct_order_payments WHERE tenant_id = $1 AND processor = ''stripe'' AND processor_ref = $2 AND kind = ''payment'' LIMIT 1'
          INTO v_ord USING ev.tenant_id, v_charge;
      END IF;
      IF v_ord IS NOT NULL THEN
        FOR rf IN SELECT value FROM jsonb_array_elements(coalesce(o#>'{refunds,data}', '[]'::jsonb)) LOOP
          EXECUTE 'SELECT public.acct__order_processor_refund($1, $2, $3, $4)' USING v_ord, acct_minor_to_major((rf->>'amount')::bigint, v_cur), rf->>'id',
            to_timestamp(coalesce((rf->>'created')::bigint, extract(epoch FROM now())::bigint))::date;
        END LOOP;
        v_res := jsonb_build_object('order_id', v_ord, 'charge', v_charge);
      ELSE
      SELECT r.id INTO v_rid FROM acct_ar_receipts r WHERE r.tenant_id = ev.tenant_id AND r.processor = 'stripe' AND r.processor_transaction_id = v_charge;
      SELECT a.invoice_id INTO v_inv FROM acct_ar_receipt_applications a WHERE a.receipt_id = v_rid LIMIT 1;
      SELECT * INTO v_inv_row FROM acct_ar_invoices WHERE id = v_inv;
      FOR rf IN SELECT value FROM jsonb_array_elements(coalesce(o#>'{refunds,data}', '[]'::jsonb)) LOOP
        CONTINUE WHEN EXISTS (SELECT 1 FROM acct_refunds WHERE tenant_id = ev.tenant_id AND processor = 'stripe' AND processor_refund_id = rf->>'id');
        INSERT INTO acct_refunds(tenant_id, entity_id, refund_number, customer_id, invoice_id, receipt_id, refund_type, reason, amount, currency, status,
                                 payment_method, processor, processor_refund_id, issued_at, refund_from_bank_account_id)
        VALUES (ev.tenant_id, v_entity, acct_next_number(ev.tenant_id, v_entity, 'refund', 'RF-'), v_inv_row.customer_id, v_inv, v_rid, 'refund',
                coalesce(rf->>'reason','requested_by_customer'), acct_minor_to_major((rf->>'amount')::bigint, v_cur), v_cur, 'approved', 'card', 'stripe', rf->>'id',
                to_timestamp((rf->>'created')::bigint), acct_system_register(ev.tenant_id, v_entity, 'stripe'))
        RETURNING id INTO v_fid;
        PERFORM acct_post_refund(v_fid);
      END LOOP;
      v_res := jsonb_build_object('charge', v_charge);
      END IF;
    WHEN 'charge.dispute.created' THEN
      SELECT r.customer_id, a.invoice_id INTO v_cust, v_inv FROM acct_ar_receipts r LEFT JOIN acct_ar_receipt_applications a ON a.receipt_id = r.id
       WHERE r.tenant_id = ev.tenant_id AND r.processor = 'stripe' AND r.processor_transaction_id = o->>'charge' LIMIT 1;
      INSERT INTO acct_disputes(tenant_id, entity_id, dispute_number, customer_id, invoice_id, processor, processor_dispute_id, kind, reason, amount, currency,
                                status, evidence_due_at, fee_amount, charge_id)
      VALUES (ev.tenant_id, v_entity, acct_next_number(ev.tenant_id, v_entity, 'dispute', 'DSP-'), v_cust, v_inv, 'stripe', o->>'id', 'chargeback', o->>'reason',
              acct_minor_to_major((o->>'amount')::bigint, v_cur), v_cur, 'needs_response',
              to_timestamp((o#>>'{evidence_details,due_by}')::bigint)::date,
              acct_minor_to_major(coalesce((o#>>'{balance_transactions,0,fee}')::bigint, 0), v_cur), o->>'charge')
      ON CONFLICT (tenant_id, processor, processor_dispute_id) WHERE processor_dispute_id IS NOT NULL DO NOTHING
      RETURNING id INTO v_disp;
      IF v_disp IS NOT NULL THEN PERFORM acct_open_dispute(v_disp, v_date); END IF;
      v_res := jsonb_build_object('dispute_id', v_disp);
    WHEN 'charge.dispute.closed' THEN
      SELECT id INTO v_disp FROM acct_disputes WHERE tenant_id = ev.tenant_id AND processor = 'stripe' AND processor_dispute_id = o->>'id';
      IF v_disp IS NULL THEN RAISE EXCEPTION 'Dispute % not on file (created event missing)', o->>'id'; END IF;
      PERFORM acct_close_dispute(v_disp, o->>'status' = 'won', v_date);
      v_res := jsonb_build_object('dispute_id', v_disp, 'outcome', o->>'status');
    WHEN 'payout.paid' THEN
      v_amt := acct_minor_to_major((o->>'amount')::bigint, v_cur);
      v_reg := coalesce(nullif(o#>>'{metadata,bank_account_id}','')::uuid, acct_payout_register(ev.tenant_id, v_entity));
      IF v_reg IS NULL THEN RAISE EXCEPTION 'No bank register to receive Stripe payouts'; END IF;
      INSERT INTO acct_payouts(tenant_id, payout_number, provider, provider_payout_id, gross_amount, net_amount, currency, status, arrived_at, scheduled_for)
      VALUES (ev.tenant_id, acct_next_number(ev.tenant_id, v_entity, 'payout', 'PO-'), 'stripe', o->>'id', v_amt, v_amt, v_cur, 'paid',
              to_timestamp((o->>'arrival_date')::bigint), to_timestamp((o->>'arrival_date')::bigint)::date)
      ON CONFLICT DO NOTHING;
      v_je := acct_post_entry(ev.tenant_id, v_entity, to_timestamp((o->>'arrival_date')::bigint)::date, jsonb_build_array(
                jsonb_build_object('account_id', acct_bank_gl(v_reg), 'debit', v_amt, 'description', 'Stripe payout ' || (o->>'id')),
                jsonb_build_object('account_id', acct_bank_gl(acct_system_register(ev.tenant_id, v_entity, 'stripe')), 'credit', v_amt, 'description', 'Stripe payout ' || (o->>'id'))),
              'integration', o->>'id', 'PAYOUT', 'Stripe payout', 'stripe:' || (o->>'id'), NULL, NULL, v_cur, false, false, 'acct_payouts', NULL);
      UPDATE acct_payouts SET gl_journal_entry_id = v_je WHERE tenant_id = ev.tenant_id AND provider_payout_id = o->>'id';
      v_res := jsonb_build_object('journal_entry_id', v_je);
    WHEN 'payout.failed' THEN
      SELECT gl_journal_entry_id INTO v_je FROM acct_payouts WHERE tenant_id = ev.tenant_id AND provider_payout_id = o->>'id';
      IF v_je IS NOT NULL THEN PERFORM acct_reverse_journal(v_je, v_date, 'Stripe payout failed: ' || coalesce(o->>'failure_message','')); END IF;
      UPDATE acct_payouts SET status = 'failed', failure_reason = o->>'failure_message' WHERE tenant_id = ev.tenant_id AND provider_payout_id = o->>'id';
      v_res := jsonb_build_object('reversed', v_je);
    ELSE
      UPDATE acct_processor_events SET status = 'ignored', processed_at = now() WHERE id = ev.id;
      RETURN jsonb_build_object('event', ev.id, 'status', 'ignored');
    END CASE;
    UPDATE acct_processor_events SET status = 'processed', processed_at = now(), result = v_res, error = NULL WHERE id = ev.id;
    RETURN jsonb_build_object('event', ev.id, 'status', 'processed') || coalesce(v_res, '{}'::jsonb);
  EXCEPTION WHEN OTHERS THEN
    UPDATE acct_processor_events SET status = 'failed', error = SQLERRM WHERE id = ev.id;
    RETURN jsonb_build_object('event', ev.id, 'status', 'failed', 'error', SQLERRM);
  END;
END $_$;

-- @seq 274
CREATE FUNCTION public.acct_profit_and_loss(p_tenant uuid, p_from date, p_to date, p_entity uuid DEFAULT NULL::uuid, p_compare_prior_year boolean DEFAULT true) RETURNS TABLE(section text, sort_order integer, account_id uuid, code text, name text, amount numeric, prior_amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
BEGIN
  PERFORM acct_assert_access(p_tenant);
  RETURN QUERY
  WITH cur AS (SELECT * FROM acct__ledger_sums(p_tenant, p_entity, p_from, p_to, true)),
       pri AS (SELECT * FROM acct__ledger_sums(p_tenant, p_entity, (p_from - interval '1 year')::date, (p_to - interval '1 year')::date, true)
                WHERE p_compare_prior_year),
       rows AS (
         SELECT acct__pnl_section(a) sec, a.id aid, a.code acode, a.name aname,
                CASE WHEN a.account_type = 'revenue' THEN coalesce(c.cr - c.dr, 0) ELSE coalesce(c.dr - c.cr, 0) END amt,
                CASE WHEN NOT p_compare_prior_year THEN NULL
                     WHEN a.account_type = 'revenue' THEN coalesce(p.cr - p.dr, 0) ELSE coalesce(p.dr - p.cr, 0) END pamt
           FROM acct_chart_of_accounts a
           LEFT JOIN cur c ON c.account_id = a.id
           LEFT JOIN pri p ON p.account_id = a.id
          WHERE a.tenant_id = p_tenant AND a.account_type IN ('revenue','expense')
            AND (c.account_id IS NOT NULL OR p.account_id IS NOT NULL)),
       t AS (SELECT sec, sum(amt) amt, sum(pamt) pamt FROM rows GROUP BY sec),
       v AS (SELECT
               coalesce((SELECT amt FROM t WHERE sec='Income'),0) inc,  coalesce((SELECT pamt FROM t WHERE sec='Income'),0) pinc,
               coalesce((SELECT amt FROM t WHERE sec='Cost of Goods Sold'),0) cogs, coalesce((SELECT pamt FROM t WHERE sec='Cost of Goods Sold'),0) pcogs,
               coalesce((SELECT amt FROM t WHERE sec='Expenses'),0) exp, coalesce((SELECT pamt FROM t WHERE sec='Expenses'),0) pexp,
               coalesce((SELECT amt FROM t WHERE sec='Other Income'),0) oi, coalesce((SELECT pamt FROM t WHERE sec='Other Income'),0) poi,
               coalesce((SELECT amt FROM t WHERE sec='Other Expenses'),0) oe, coalesce((SELECT pamt FROM t WHERE sec='Other Expenses'),0) poe)
  SELECT r.sec, CASE r.sec WHEN 'Income' THEN 10 WHEN 'Cost of Goods Sold' THEN 20 WHEN 'Expenses' THEN 40 WHEN 'Other Income' THEN 60 ELSE 70 END,
         r.aid, r.acode, r.aname, r.amt, r.pamt
    FROM rows r
  UNION ALL SELECT 'Total Income', 15, NULL, NULL, 'Total Income', v.inc, CASE WHEN p_compare_prior_year THEN v.pinc END FROM v
  UNION ALL SELECT 'Gross Profit', 30, NULL, NULL, 'Gross Profit', v.inc - v.cogs, CASE WHEN p_compare_prior_year THEN v.pinc - v.pcogs END FROM v
  UNION ALL SELECT 'Total Expenses', 45, NULL, NULL, 'Total Expenses', v.exp, CASE WHEN p_compare_prior_year THEN v.pexp END FROM v
  UNION ALL SELECT 'Net Operating Income', 50, NULL, NULL, 'Net Operating Income', v.inc - v.cogs - v.exp, CASE WHEN p_compare_prior_year THEN v.pinc - v.pcogs - v.pexp END FROM v
  UNION ALL SELECT 'Net Other Income', 80, NULL, NULL, 'Net Other Income', v.oi - v.oe, CASE WHEN p_compare_prior_year THEN v.poi - v.poe END FROM v
  UNION ALL SELECT 'Net Income', 90, NULL, NULL, 'Net Income', v.inc - v.cogs - v.exp + v.oi - v.oe,
                   CASE WHEN p_compare_prior_year THEN v.pinc - v.pcogs - v.pexp + v.poi - v.poe END FROM v
  ORDER BY 2, 4 NULLS LAST;
END $$;

-- @seq 276
CREATE FUNCTION public.acct_publish_report_package(p_tenant_id uuid, p_from date, p_to date, p_package_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_commentary text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE pk acct_report_packages%ROWTYPE; c jsonb := '{}'::jsonb; v uuid; v_close uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_package_id IS NOT NULL THEN
    SELECT * INTO pk FROM acct_report_packages WHERE id = p_package_id AND tenant_id = p_tenant_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Report package not found'; END IF;
  ELSE
    pk.sections := ARRAY['profit_and_loss','balance_sheet','cash_flow','trial_balance','kpis','flux','close_status'];
    pk.flux_amount_threshold := 500; pk.flux_pct_threshold := 0.10;
  END IF;
  IF 'profit_and_loss' = ANY(pk.sections) THEN
    c := c || jsonb_build_object('profit_and_loss', (SELECT coalesce(jsonb_agg(to_jsonb(x)), '[]') FROM acct_profit_and_loss(p_tenant_id, p_from, p_to, NULL, true) x)); END IF;
  IF 'balance_sheet' = ANY(pk.sections) THEN
    c := c || jsonb_build_object('balance_sheet', (SELECT coalesce(jsonb_agg(to_jsonb(x)), '[]') FROM acct_balance_sheet(p_tenant_id, p_to, NULL) x)); END IF;
  IF 'cash_flow' = ANY(pk.sections) THEN
    c := c || jsonb_build_object('cash_flow', (SELECT coalesce(jsonb_agg(to_jsonb(x)), '[]') FROM acct_cash_flow(p_tenant_id, p_from, p_to, NULL) x)); END IF;
  IF 'trial_balance' = ANY(pk.sections) THEN
    c := c || jsonb_build_object('trial_balance', (SELECT coalesce(jsonb_agg(to_jsonb(x)), '[]') FROM acct_trial_balance(p_tenant_id, p_to, NULL) x)); END IF;
  IF 'kpis' = ANY(pk.sections) THEN
    c := c || jsonb_build_object('kpis', (SELECT coalesce(jsonb_agg(to_jsonb(x)), '[]') FROM acct_kpis(p_tenant_id, p_from, p_to) x)); END IF;
  IF 'flux' = ANY(pk.sections) THEN
    c := c || jsonb_build_object('flux', (SELECT coalesce(jsonb_agg(to_jsonb(x)), '[]') FROM acct_flux_analysis(p_tenant_id, p_from, p_to, pk.flux_amount_threshold, pk.flux_pct_threshold) x WHERE x.flagged)); END IF;
  IF 'close_status' = ANY(pk.sections) THEN
    SELECT id INTO v_close FROM acct_closes WHERE tenant_id = p_tenant_id AND period_end = p_to ORDER BY started_at DESC LIMIT 1;
    IF v_close IS NOT NULL THEN c := c || jsonb_build_object('close_status', acct_close_status(v_close, false) - 'tasks'); END IF;
  END IF;
  -- aging views are as of today (the publish date), not as of p_to
  IF 'ar_aging' = ANY(pk.sections) THEN
    c := c || jsonb_build_object('ar_aging_as_of_today', (SELECT coalesce(jsonb_agg(to_jsonb(x) - 'tenant_id'), '[]') FROM acct_v_ar_aging x WHERE x.tenant_id = p_tenant_id)); END IF;
  IF 'ap_aging' = ANY(pk.sections) THEN
    c := c || jsonb_build_object('ap_aging_as_of_today', (SELECT coalesce(jsonb_agg(to_jsonb(x) - 'tenant_id'), '[]') FROM acct_v_ap_aging x WHERE x.tenant_id = p_tenant_id)); END IF;
  INSERT INTO acct_report_snapshots(tenant_id, package_id, title, period_start, period_end, contents, commentary, published_by)
  VALUES (p_tenant_id, p_package_id, coalesce(p_title, coalesce(pk.name, 'Financial report') || ' ' || p_from || ' to ' || p_to), p_from, p_to,
          c || jsonb_build_object('generated_at', now(), 'period', jsonb_build_object('from', p_from, 'to', p_to)), p_commentary, auth.uid())
  RETURNING id INTO v;
  RETURN v;
END $$;

-- @seq 277
CREATE FUNCTION public.acct_rebuild_balances(p_book_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE n int; v_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM acct_books WHERE id = p_book_id;
  PERFORM acct_assert_access(v_tenant);
  DELETE FROM acct_account_balances WHERE book_id = p_book_id;
  INSERT INTO acct_account_balances(tenant_id, entity_id, book_id, account_id, period_id, debit, credit, closing_debit, closing_credit)
  SELECT e.tenant_id, e.entity_id, e.book_id, l.account_id, e.period_id, sum(l.debit), sum(l.credit),
         sum(CASE WHEN e.is_closing THEN l.debit ELSE 0 END), sum(CASE WHEN e.is_closing THEN l.credit ELSE 0 END)
    FROM acct_journal_entries e JOIN acct_journal_lines l ON l.journal_entry_id = e.id
   WHERE e.book_id = p_book_id AND e.status IN ('posted','reversed')
   GROUP BY 1,2,3,4,5;
  GET DIAGNOSTICS n = ROW_COUNT; RETURN n;
END $$;

-- @seq 281
CREATE FUNCTION public.acct_record_debt_draw(p_debt_id uuid, p_to_bank_account_id uuid, p_date date, p_amount numeric, p_fees numeric DEFAULT 0) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d acct_debt_instruments%ROWTYPE; b acct_bank_accounts%ROWTYPE; v_bal numeric; v_lines jsonb;
BEGIN
  SELECT * INTO d FROM acct_debt_instruments WHERE id = p_debt_id;
  PERFORM acct_assert_access(d.tenant_id);
  IF d.status <> 'active' THEN RAISE EXCEPTION 'Debt account is %', d.status; END IF;
  IF p_amount <= 0 THEN RAISE EXCEPTION 'Draw amount must be positive'; END IF;
  SELECT * INTO b FROM acct_bank_accounts WHERE id = d.bank_account_id;
  v_bal := coalesce(acct_debt_balance(d.id, p_date), 0);
  IF d.credit_limit IS NOT NULL AND v_bal + p_amount + coalesce(p_fees,0) > d.credit_limit THEN
    RAISE EXCEPTION 'Draw would exceed the credit limit: owed % + % > limit %', v_bal, p_amount + coalesce(p_fees,0), d.credit_limit; END IF;
  v_lines := jsonb_build_array(
    jsonb_build_object('account_id', acct_bank_gl(p_to_bank_account_id), 'debit', p_amount, 'description', 'Proceeds from ' || d.name),
    jsonb_build_object('account_id', b.gl_account_id, 'credit', p_amount + coalesce(p_fees,0), 'description', 'Draw ' || d.name, 'vendor_id', d.lender_vendor_id));
  IF coalesce(p_fees,0) > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', coalesce(d.fees_account_id, d.interest_expense_account_id,
                 acct_role_account(d.tenant_id, d.entity_id, 'interest_expense')), 'debit', p_fees, 'description', 'Origination/draw fee'));
  END IF;
  RETURN acct_post_entry(d.tenant_id, d.entity_id, p_date, v_lines, 'manual', d.id::text, 'DRAW', 'Debt draw: ' || d.name,
                         NULL, NULL, NULL, NULL, false, false, 'acct_debt_instruments', d.id);
END $$;

-- @seq 282
CREATE FUNCTION public.acct_record_debt_payment(p_debt_id uuid, p_from_bank_account_id uuid, p_date date, p_amount numeric, p_interest numeric DEFAULT NULL::numeric, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d acct_debt_instruments%ROWTYPE; b acct_bank_accounts%ROWTYPE; s acct_debt_schedule%ROWTYPE; v_int numeric; v_prin numeric; v_je uuid; v_bal numeric;
BEGIN
  SELECT * INTO d FROM acct_debt_instruments WHERE id = p_debt_id;
  PERFORM acct_assert_access(d.tenant_id);
  SELECT * INTO b FROM acct_bank_accounts WHERE id = d.bank_account_id;
  SELECT * INTO s FROM acct_debt_schedule WHERE debt_id = d.id AND status = 'scheduled' ORDER BY installment_no LIMIT 1;
  v_int := coalesce(p_interest, CASE WHEN s.id IS NOT NULL THEN s.interest ELSE 0 END);
  IF v_int > p_amount THEN RAISE EXCEPTION 'Interest % exceeds payment %', v_int, p_amount; END IF;
  v_prin := p_amount - v_int;
  v_bal := acct_debt_balance(d.id, p_date);
  IF v_prin > v_bal THEN RAISE EXCEPTION 'Principal % exceeds the balance owed %', v_prin, v_bal; END IF;
  v_je := acct_post_entry(d.tenant_id, d.entity_id, p_date, jsonb_build_array(
            jsonb_build_object('account_id', b.gl_account_id, 'debit', v_prin, 'description', 'Principal ' || d.name, 'vendor_id', d.lender_vendor_id),
            jsonb_build_object('account_id', coalesce(d.interest_expense_account_id, acct_role_account(d.tenant_id, d.entity_id, 'interest_expense')),
                               'debit', v_int, 'description', 'Interest ' || d.name, 'vendor_id', d.lender_vendor_id),
            jsonb_build_object('account_id', acct_bank_gl(p_from_bank_account_id), 'credit', p_amount, 'description', 'Payment ' || d.name, 'vendor_id', d.lender_vendor_id)),
          'manual', d.id::text, 'PMT', 'Debt payment: ' || d.name, p_idempotency_key, NULL, NULL, NULL, false, false, 'acct_debt_instruments', d.id);
  IF s.id IS NOT NULL THEN UPDATE acct_debt_schedule SET status = 'paid', paid_on = p_date, paid_journal_id = v_je WHERE id = s.id; END IF;
  IF acct_debt_balance(d.id) = 0 AND d.kind NOT IN ('credit_card','line_of_credit') THEN UPDATE acct_debt_instruments SET status = 'paid_off' WHERE id = d.id; END IF;
  RETURN v_je;
END $$;

-- @seq 283
CREATE FUNCTION public.acct_record_payment_link_payment(p_link_id uuid, p_customer_id uuid, p_date date, p_gross numeric, p_quantity numeric DEFAULT 1, p_fee numeric DEFAULT 0, p_processor_txn_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE k acct_payment_links%ROWTYPE; v_inv uuid; v_rid uuid; v_tax jsonb; v_net numeric; v_existing uuid;
BEGIN
  SELECT * INTO k FROM acct_payment_links WHERE id = p_link_id FOR UPDATE;
  PERFORM acct_assert_access(k.tenant_id);
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_existing FROM acct_ar_receipts WHERE tenant_id = k.tenant_id AND idempotency_key = p_idempotency_key;
    IF v_existing IS NOT NULL THEN RETURN v_existing; END IF;
  END IF;
  IF k.status <> 'active' OR (k.expires_at IS NOT NULL AND k.expires_at < now()) OR (k.max_uses IS NOT NULL AND k.use_count >= k.max_uses) THEN
    RAISE EXCEPTION 'Payment link is not accepting payments'; END IF;
  IF p_customer_id IS NULL THEN RAISE EXCEPTION 'Payment link payments need a customer (create one from the checkout email)'; END IF;
  IF k.kind = 'invoice' THEN
    v_rid := acct_record_receipt(k.tenant_id, p_customer_id, p_date, p_gross, 'payment_link', NULL,
               jsonb_build_array(jsonb_build_object('invoice_id', k.invoice_id, 'amount', p_gross)), k.title, 'stripe', p_processor_txn_id,
               p_idempotency_key, p_fee, k.entity_id, NULL, k.id);
  ELSE
    -- gross includes tax when collect_tax: back the tax out so revenue is net
    v_net := p_gross;
    IF k.collect_tax AND k.tax_jurisdiction_id IS NOT NULL THEN
      v_tax := acct_calculate_tax_summary(k.tenant_id, k.entity_id, p_date, k.tax_jurisdiction_id, p_customer_id,
                 jsonb_build_array(jsonb_build_object('line_ref','1','amount',100,'quantity',1,
                   'tax_category', coalesce((SELECT tax_category FROM acct_items WHERE id = k.item_id),'general'))));
      v_net := round(p_gross / (1 + coalesce((v_tax->>'tax_total')::numeric,0) / 100), 2);
    END IF;
    INSERT INTO acct_ar_invoices(tenant_id, entity_id, customer_id, invoice_number, invoice_date, due_date, currency, status, document_kind,
                                 tax_jurisdiction_id, sales_receipt_bank_account_id, sales_receipt_method, payment_link_id, memo_on_statement)
    VALUES (k.tenant_id, k.entity_id, p_customer_id, NULL, p_date, NULL, k.currency, 'draft', 'sales_receipt',
            CASE WHEN k.collect_tax THEN k.tax_jurisdiction_id END, acct_system_register(k.tenant_id, k.entity_id, 'stripe'), 'payment_link', k.id, k.title)
    RETURNING id INTO v_inv;
    INSERT INTO acct_ar_invoice_lines(invoice_id, line_no, description, quantity, unit_price, revenue_account_id, item_id, dimensions, tenant_id)
    VALUES (v_inv, 1, k.title, coalesce(p_quantity,1), round(v_net / coalesce(nullif(p_quantity,0),1), 6), k.income_account_id, k.item_id, '{}'::jsonb, k.tenant_id);
    PERFORM acct_post_invoice(v_inv);
    -- engine rounding can leave a cent between gross and the posted total; book it to rounding
    SELECT r.id INTO v_rid FROM acct_ar_receipts r WHERE r.idempotency_key = 'salesreceipt:' || v_inv;
    IF p_gross <> (SELECT total FROM acct_ar_invoices WHERE id = v_inv) THEN
      PERFORM acct_post_entry(k.tenant_id, k.entity_id, p_date, jsonb_build_array(
        jsonb_build_object('account_id', acct_bank_gl(acct_system_register(k.tenant_id, k.entity_id, 'stripe')),
                           'debit', greatest(p_gross - (SELECT total FROM acct_ar_invoices WHERE id = v_inv), 0),
                           'credit', greatest((SELECT total FROM acct_ar_invoices WHERE id = v_inv) - p_gross, 0), 'description', 'Tax rounding'),
        jsonb_build_object('account_id', acct_role_account(k.tenant_id, k.entity_id, 'rounding'),
                           'credit', greatest(p_gross - (SELECT total FROM acct_ar_invoices WHERE id = v_inv), 0),
                           'debit', greatest((SELECT total FROM acct_ar_invoices WHERE id = v_inv) - p_gross, 0), 'description', 'Tax rounding')),
        'integration', v_rid::text, 'RND', 'Payment link tax rounding', 'plround:' || v_inv, NULL, NULL, NULL, false, false, 'acct_ar_invoices', v_inv);
    END IF;
    UPDATE acct_ar_receipts SET processor = 'stripe', processor_transaction_id = p_processor_txn_id,
           idempotency_key = coalesce(p_idempotency_key, idempotency_key), payment_link_id = k.id WHERE id = v_rid;
    IF coalesce(p_fee,0) > 0 THEN
      PERFORM acct_post_entry(k.tenant_id, k.entity_id, p_date, jsonb_build_array(
        jsonb_build_object('account_id', acct_role_account(k.tenant_id, k.entity_id, 'processor_fees'), 'debit', p_fee, 'description', 'Stripe fee ' || k.title),
        jsonb_build_object('account_id', acct_bank_gl(acct_system_register(k.tenant_id, k.entity_id, 'stripe')), 'credit', p_fee, 'description', 'Stripe fee')),
        'integration', v_rid::text, 'FEE', 'Payment link fee', 'plfee:' || v_rid, NULL, NULL, NULL, false, false, 'acct_ar_receipts', v_rid);
      UPDATE acct_ar_receipts SET fee_amount = p_fee WHERE id = v_rid;
    END IF;
  END IF;
  UPDATE acct_payment_links SET use_count = use_count + 1, total_collected = total_collected + p_gross, updated_at = now() WHERE id = k.id;
  RETURN v_rid;
END $$;

-- @seq 284
CREATE FUNCTION public.acct_record_receipt(p_tenant_id uuid, p_customer_id uuid, p_date date, p_amount numeric, p_method text, p_deposit_bank_account_id uuid DEFAULT NULL::uuid, p_applications jsonb DEFAULT '[]'::jsonb, p_reference text DEFAULT NULL::text, p_processor text DEFAULT NULL::text, p_processor_txn_id text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_fee numeric DEFAULT 0, p_entity_id uuid DEFAULT NULL::uuid, p_memo text DEFAULT NULL::text, p_payment_link_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid; v_reg uuid; v_gl uuid; v_rid uuid; a jsonb; iv acct_ar_invoices%ROWTYPE; v_amt numeric; v_applied numeric := 0;
        v_ar_cr numeric := 0; v_dep_cr numeric := 0; v_lines jsonb; v_je uuid; v_cust text := p_customer_id::text; v_unapplied numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_rid FROM acct_ar_receipts WHERE tenant_id = p_tenant_id AND idempotency_key = p_idempotency_key;
    IF v_rid IS NOT NULL THEN RETURN v_rid; END IF;
  END IF;
  IF p_amount <= 0 THEN RAISE EXCEPTION 'Payment amount must be positive'; END IF;
  IF coalesce(p_fee,0) < 0 OR coalesce(p_fee,0) >= p_amount THEN RAISE EXCEPTION 'Fee must be between 0 and the payment amount'; END IF;
  v_entity := coalesce(p_entity_id, acct_default_entity(p_tenant_id));
  v_reg := coalesce(p_deposit_bank_account_id,
                    CASE WHEN p_processor = 'stripe' OR p_method IN ('card','credit_card','payment_link','apple_pay','google_pay')
                         THEN acct_system_register(p_tenant_id, v_entity, 'stripe') ELSE acct_system_register(p_tenant_id, v_entity, 'undeposited_funds') END);
  v_gl := acct_bank_gl(v_reg);
  INSERT INTO acct_ar_receipts(tenant_id, entity_id, customer_id, receipt_number, receipt_date, currency, amount, payment_method, status, deposit_account_id,
                               reference, processor, processor_transaction_id, memo, fee_amount, idempotency_key, payment_link_id)
  VALUES (p_tenant_id, v_entity, p_customer_id, acct_next_number(p_tenant_id, v_entity, 'customer_payment', 'PMT-'), p_date, 'USD', p_amount, p_method, 'posted',
          v_reg, p_reference, p_processor, p_processor_txn_id, p_memo, coalesce(p_fee,0), p_idempotency_key, p_payment_link_id)
  RETURNING id INTO v_rid;

  FOR a IN SELECT value FROM jsonb_array_elements(coalesce(p_applications,'[]'::jsonb)) LOOP
    SELECT * INTO iv FROM acct_ar_invoices WHERE id = (a->>'invoice_id')::uuid FOR UPDATE;
    IF NOT FOUND OR iv.tenant_id <> p_tenant_id THEN RAISE EXCEPTION 'Invoice not found'; END IF;
    IF p_customer_id IS NOT NULL AND iv.customer_id <> p_customer_id THEN RAISE EXCEPTION 'Invoice % belongs to a different customer', iv.invoice_number; END IF;
    IF iv.status IN ('void','written_off') THEN RAISE EXCEPTION 'Invoice % is %', iv.invoice_number, iv.status; END IF;
    v_amt := coalesce((a->>'amount')::numeric, iv.open_balance);
    IF v_amt <= 0 THEN CONTINUE; END IF;
    IF iv.posted_journal_id IS NULL THEN
      -- deposit against a draft/unsent invoice
      v_dep_cr := v_dep_cr + v_amt;
      UPDATE acct_ar_invoices SET deposit_paid = deposit_paid + v_amt WHERE id = iv.id;
      INSERT INTO acct_ar_receipt_applications(tenant_id, receipt_id, invoice_id, applied_amount, as_deposit) VALUES (p_tenant_id, v_rid, iv.id, v_amt, true);
    ELSE
      IF v_amt > iv.open_balance THEN RAISE EXCEPTION 'Payment % exceeds open balance % on invoice %', v_amt, iv.open_balance, iv.invoice_number; END IF;
      v_ar_cr := v_ar_cr + v_amt;
      UPDATE acct_ar_invoices SET amount_paid = amount_paid + v_amt WHERE id = iv.id;
      INSERT INTO acct_ar_receipt_applications(tenant_id, receipt_id, invoice_id, applied_amount) VALUES (p_tenant_id, v_rid, iv.id, v_amt);
      PERFORM acct_invoice_refresh_status(iv.id);
    END IF;
    v_applied := v_applied + v_amt;
  END LOOP;
  IF v_applied > p_amount THEN RAISE EXCEPTION 'Applied % is more than the payment %', v_applied, p_amount; END IF;
  v_unapplied := p_amount - v_applied;
  IF v_unapplied > 0 AND p_customer_id IS NULL THEN RAISE EXCEPTION 'Unapplied payments need a customer'; END IF;

  v_lines := jsonb_build_array(jsonb_build_object('account_id', v_gl, 'debit', p_amount - coalesce(p_fee,0), 'customer_id', v_cust,
               'description', 'Payment ' || coalesce(acct_customer_name(p_customer_id), '') || coalesce(' ' || p_reference, '')));
  IF coalesce(p_fee,0) > 0 THEN
    v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'processor_fees'), 'debit', p_fee,
                 'description', 'Processing fee', 'customer_id', v_cust));
  END IF;
  IF v_ar_cr > 0 THEN v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'accounts_receivable'),
                                  'credit', v_ar_cr, 'customer_id', v_cust, 'description', 'Invoice payment')); END IF;
  IF v_dep_cr > 0 THEN v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'customer_deposits'),
                                  'credit', v_dep_cr, 'customer_id', v_cust, 'description', 'Customer deposit')); END IF;
  IF v_unapplied > 0 THEN v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'unapplied_cash'),
                                  'credit', v_unapplied, 'customer_id', v_cust, 'description', 'Unapplied payment')); END IF;
  v_je := acct_post_entry(p_tenant_id, v_entity, p_date, v_lines, 'customer_receipt', v_rid::text, p_reference, coalesce(p_memo, 'Customer payment'),
                          'receipt:' || v_rid, NULL, NULL, NULL, false, false, 'acct_ar_receipts', v_rid);
  UPDATE acct_ar_receipts SET posted_journal_id = v_je, unapplied_amount = v_unapplied WHERE id = v_rid;
  RETURN v_rid;
END $$;

-- @seq 285
CREATE FUNCTION public.acct_redeem_gift_card(p_code text, p_tenant_id uuid, p_invoice_id uuid, p_amount numeric, p_date date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE g acct_gift_cards%ROWTYPE; iv acct_ar_invoices%ROWTYPE; v_rid uuid; v_je uuid; v_entity uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT * INTO g FROM acct_gift_cards WHERE tenant_id = p_tenant_id AND code = upper(p_code) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Gift card not found'; END IF;
  IF g.status <> 'active' THEN RAISE EXCEPTION 'Gift card is %', g.status; END IF;
  IF g.expires_at IS NOT NULL AND g.expires_at < p_date THEN RAISE EXCEPTION 'Gift card expired on %', g.expires_at; END IF;
  IF p_amount > g.balance THEN RAISE EXCEPTION 'Gift card balance is only %', g.balance; END IF;
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF iv.posted_journal_id IS NULL OR p_amount > iv.open_balance THEN RAISE EXCEPTION 'Invoice is not posted or only % is open', iv.open_balance; END IF;
  v_entity := iv.entity_id;
  INSERT INTO acct_ar_receipts(tenant_id, entity_id, customer_id, receipt_number, receipt_date, currency, amount, payment_method, status, deposit_account_id, reference, deposit_id)
  VALUES (p_tenant_id, v_entity, iv.customer_id, acct_next_number(p_tenant_id, v_entity, 'customer_payment', 'PMT-'), p_date, iv.currency, p_amount, 'gift_card', 'posted',
          acct_system_register(p_tenant_id, v_entity, 'undeposited_funds'), g.code, NULL)
  RETURNING id INTO v_rid;
  v_je := acct_post_entry(p_tenant_id, v_entity, p_date, jsonb_build_array(
            jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'gift_card_liability'), 'debit', p_amount, 'customer_id', iv.customer_id::text, 'description', 'Gift card ' || g.code),
            jsonb_build_object('account_id', acct_role_account(p_tenant_id, v_entity, 'accounts_receivable'), 'credit', p_amount, 'customer_id', iv.customer_id::text, 'description', 'Gift card ' || g.code)),
          'customer_receipt', v_rid::text, g.code, 'Gift card redemption', 'gc-redeem:' || v_rid, NULL, NULL, NULL, false, false, 'acct_ar_receipts', v_rid);
  UPDATE acct_ar_receipts SET posted_journal_id = v_je, deposit_id = NULL WHERE id = v_rid;
  INSERT INTO acct_ar_receipt_applications(tenant_id, receipt_id, invoice_id, applied_amount) VALUES (p_tenant_id, v_rid, iv.id, p_amount);
  UPDATE acct_ar_invoices SET amount_paid = amount_paid + p_amount WHERE id = iv.id;
  PERFORM acct_invoice_refresh_status(iv.id);
  UPDATE acct_gift_cards SET balance = balance - p_amount, status = CASE WHEN balance - p_amount = 0 THEN 'redeemed' ELSE status END, updated_at = now() WHERE id = g.id;
  INSERT INTO acct_gift_card_transactions(tenant_id, gift_card_id, txn_type, amount, balance_after, reference, posted_journal_id)
  VALUES (p_tenant_id, g.id, 'redeem', -p_amount, g.balance - p_amount, iv.invoice_number, v_je);
  RETURN v_rid;
END $$;

-- @seq 287
CREATE FUNCTION public.acct_report_snapshots_lock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Published report snapshots cannot be changed or deleted; publish a new one instead';
END $$;

-- @seq 288
CREATE FUNCTION public.acct_retained_earnings_statement(p_tenant uuid, p_from date, p_to date, p_entity uuid DEFAULT NULL::uuid) RETURNS TABLE(sort_order integer, line text, amount numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
DECLARE v_begin numeric; v_ni numeric; v_draw numeric; v_contrib numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant);
  -- beginning RE = RE account + every P&L residual before the period
  SELECT coalesce(sum(s.cr - s.dr),0) INTO v_begin FROM acct__ledger_sums(p_tenant, p_entity, NULL, p_from - 1, false) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id
   WHERE a.account_type IN ('revenue','expense') OR a.detail_type = 'retained_earnings';
  SELECT coalesce(sum(s.cr - s.dr),0) INTO v_ni FROM acct__ledger_sums(p_tenant, p_entity, p_from, p_to, true) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id WHERE a.account_type IN ('revenue','expense');
  SELECT coalesce(sum(s.dr - s.cr),0) INTO v_draw FROM acct__ledger_sums(p_tenant, p_entity, p_from, p_to, true) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id WHERE a.detail_type IN ('owner_draw','distributions','dividends');
  SELECT coalesce(sum(s.cr - s.dr),0) INTO v_contrib FROM acct__ledger_sums(p_tenant, p_entity, p_from, p_to, true) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id WHERE a.detail_type = 'owner_contributions';
  RETURN QUERY VALUES
    (10, 'Retained earnings, beginning of period', v_begin),
    (20, 'Net income', v_ni),
    (30, 'Owner draws / distributions', -v_draw),
    (40, 'Retained earnings, end of period', v_begin + v_ni - v_draw),
    (50, 'Owner contributions (memo, held in contributed capital)', v_contrib);
END $$;

-- @seq 289
CREATE FUNCTION public.acct_retry_processor_events(p_max_attempts integer DEFAULT 8) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE e record; n int := 0;
BEGIN
  FOR e IN SELECT id FROM acct_processor_events WHERE status IN ('failed','received') AND attempts < p_max_attempts ORDER BY received_at LIMIT 500 LOOP
    PERFORM acct_process_processor_event(e.id); n := n + 1;
  END LOOP;
  RETURN n;
END $$;

-- @seq 290
CREATE FUNCTION public.acct_reverse_channel_settlement(p_settlement_id uuid, p_date date, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s acct_channel_settlements%ROWTYPE; v uuid;
BEGIN
  SELECT * INTO s FROM acct_channel_settlements WHERE id = p_settlement_id FOR UPDATE;
  PERFORM acct_assert_access(s.tenant_id);
  IF s.status <> 'posted' THEN RAISE EXCEPTION 'Only posted settlements can be reversed'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required'; END IF;
  v := acct_reverse_journal(s.journal_entry_id, p_date, 'Settlement reversed: ' || p_reason);
  UPDATE acct_channel_settlements SET status = 'reversed', reversal_journal_id = v, updated_at = now() WHERE id = s.id;
  RETURN v;
END $$;

-- @seq 291
CREATE FUNCTION public.acct_reverse_journal(p_journal_id uuid, p_reversal_date date, p_memo text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE o acct_journal_entries%ROWTYPE; v_lines jsonb; v_new uuid;
BEGIN
  SELECT * INTO o FROM acct_journal_entries WHERE id = p_journal_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Journal not found'; END IF;
  PERFORM acct_assert_access(o.tenant_id);
  IF o.status <> 'posted' THEN RAISE EXCEPTION 'Only posted journals can be reversed (status is %)', o.status; END IF;
  IF o.reversal_of_id IS NOT NULL THEN RAISE EXCEPTION 'This entry is itself a reversal'; END IF;
  SELECT jsonb_agg(jsonb_build_object('account_id', account_id, 'description', 'Reversal: ' || coalesce(description,''),
           'debit', credit, 'credit', debit, 'transaction_currency', transaction_currency,
           'transaction_debit', transaction_credit, 'transaction_credit', transaction_debit, 'exchange_rate', exchange_rate,
           'customer_id', customer_id, 'vendor_id', vendor_id, 'employee_id', employee_id, 'project_id', project_id,
           'department_id', department_id, 'location_id', location_id, 'tax_code_id', tax_code_id, 'item_id', item_id,
           'dimensions', dimensions) ORDER BY line_no)
    INTO v_lines FROM acct_journal_lines WHERE journal_entry_id = p_journal_id;
  v_new := acct_post_entry(o.tenant_id, o.entity_id, coalesce(p_reversal_date, o.entry_date), v_lines, o.source, o.id::text,
                           'REV-' || o.entry_no, coalesce(p_memo, 'Reversal of #' || o.entry_no), 'reverse:' || o.id, o.book_id,
                           NULL, o.currency, o.is_adjusting, false, o.source_doc_type, o.source_doc_id);
  UPDATE acct_journal_entries SET reversal_of_id = p_journal_id WHERE id = v_new;
  UPDATE acct_journal_entries SET status = 'reversed', reversed_by_id = v_new WHERE id = p_journal_id;
  RETURN v_new;
END $$;

-- @seq 292
CREATE FUNCTION public.acct_role_account(p_tenant_id uuid, p_entity_id uuid, p_role text, p_required boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid;
BEGIN
  SELECT account_id INTO v FROM acct_account_roles WHERE tenant_id=p_tenant_id AND entity_id=p_entity_id AND role=p_role;
  IF v IS NULL AND p_required THEN
    RAISE EXCEPTION 'No account is assigned to the "%" role for this company. Assign one in Chart of Accounts > Account roles.', p_role;
  END IF;
  RETURN v;
END $$;

-- @seq 293
CREATE FUNCTION public.acct_round(p_amount numeric, p_currency text DEFAULT 'USD'::text) RETURNS numeric
    LANGUAGE sql STABLE
    AS $$
  SELECT round(coalesce(p_amount,0),
               coalesce((SELECT minor_units FROM acct_currencies WHERE code = upper(p_currency) LIMIT 1), 2));
$$;

-- @seq 294
CREATE FUNCTION public.acct_run_auto_reversals(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE a record; v uuid; n int := 0;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR a IN SELECT ar.*, je.status AS je_status, je.entry_no FROM acct_auto_reversals ar JOIN acct_journal_entries je ON je.id = ar.journal_entry_id
            WHERE ar.tenant_id = p_tenant_id AND ar.status = 'scheduled' AND ar.reverse_on <= p_as_of ORDER BY ar.reverse_on LOOP
    IF a.je_status <> 'posted' THEN
      UPDATE acct_auto_reversals SET status = CASE WHEN a.je_status = 'reversed' THEN 'cancelled' ELSE status END,
             error = CASE WHEN a.je_status = 'reversed' THEN 'Already reversed manually' ELSE 'Entry is not posted yet' END WHERE id = a.id;
      CONTINUE;
    END IF;
    BEGIN
      v := acct_reverse_journal(a.journal_entry_id, a.reverse_on, 'Auto-reversal of #' || a.entry_no);
      UPDATE acct_auto_reversals SET status = 'reversed', reversal_journal_id = v, error = NULL WHERE id = a.id;
      n := n + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE acct_auto_reversals SET status = 'failed', error = SQLERRM WHERE id = a.id;
    END;
  END LOOP;
  RETURN n;
END $$;

-- @seq 295
CREATE FUNCTION public.acct_run_depreciation(p_tenant_id uuid, p_through date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid; v_book uuid; ab record; v_month date; v_end date; v_amt numeric; v_total numeric; v_acc numeric; v_taken int;
        v_first boolean; v_run uuid; v_lines jsonb := '[]'::jsonb; v_je uuid; v_period uuid; v_count int := 0; v_sum numeric := 0;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  v_entity := acct_default_entity(p_tenant_id);
  v_book := acct_primary_book(p_tenant_id, v_entity);
  v_end := (date_trunc('month', p_through) + interval '1 month - 1 day')::date;
  IF v_end <> p_through THEN v_end := (date_trunc('month', p_through) - interval '1 day')::date; END IF;   -- only whole months
  v_period := acct_period_for(v_book, v_end, true);
  INSERT INTO acct_asset_depreciation_runs(tenant_id, book_id, period_id, run_date, status, created_by)
  VALUES (p_tenant_id, v_book, v_period, v_end, 'draft', auth.uid()) RETURNING id INTO v_run;
  FOR ab IN SELECT b.*, a.name, a.original_cost, a.residual_value, a.id AS fa_id, c.accumulated_depreciation_account_id acc_acct,
                   c.depreciation_expense_account_id exp_acct
              FROM acct_asset_books b JOIN acct_fixed_assets a ON a.id = b.asset_id
              JOIN acct_asset_classes c ON c.id = a.asset_class_id
             WHERE a.tenant_id = p_tenant_id AND b.book_id = v_book AND a.status = 'in_service'
               AND b.depreciation_start_date <= v_end FOR UPDATE OF b LOOP
    v_acc := ab.accumulated_depreciation; v_total := 0;
    v_month := CASE WHEN ab.last_depreciation_date IS NULL
                    THEN date_trunc('month', ab.depreciation_start_date)::date + CASE WHEN ab.convention = 'next_month' THEN interval '1 month' ELSE interval '0' END
                    ELSE (ab.last_depreciation_date + 1) END;
    v_taken := CASE WHEN ab.last_depreciation_date IS NULL THEN 0
                    ELSE (extract(year FROM age(ab.last_depreciation_date + 1, date_trunc('month', ab.depreciation_start_date)::date)) * 12
                        + extract(month FROM age(ab.last_depreciation_date + 1, date_trunc('month', ab.depreciation_start_date)::date)))::int
                         - CASE WHEN ab.convention = 'next_month' THEN 1 ELSE 0 END END;
    WHILE (v_month + interval '1 month - 1 day')::date <= v_end LOOP
      v_first := ab.last_depreciation_date IS NULL AND v_total = 0 AND v_taken = 0;
      v_amt := acct__depreciation_month(ab.depreciation_method, ab.convention, ab.in_service_cost, coalesce(ab.residual_value,0),
                                        ab.useful_life_months, v_acc, v_taken, v_first);
      EXIT WHEN v_amt <= 0;
      v_acc := v_acc + v_amt; v_total := v_total + v_amt; v_taken := v_taken + 1;
      v_month := (v_month + interval '1 month')::date;
    END LOOP;
    IF v_total > 0 THEN
      INSERT INTO acct_asset_depreciation_lines(run_id, asset_book_id, depreciation_amount, accumulated_after, nbv_after)
      VALUES (v_run, ab.id, v_total, v_acc, ab.in_service_cost - v_acc);
      v_lines := v_lines || jsonb_build_array(
        jsonb_build_object('account_id', ab.exp_acct, 'debit', v_total, 'description', 'Depreciation ' || ab.name),
        jsonb_build_object('account_id', ab.acc_acct, 'credit', v_total, 'description', 'Depreciation ' || ab.name));
      UPDATE acct_asset_books SET accumulated_depreciation = v_acc, net_book_value = in_service_cost - v_acc, last_depreciation_date = (v_month - 1) WHERE id = ab.id;
      UPDATE acct_fixed_assets SET accumulated_depreciation = v_acc, updated_at = now(),
             status = CASE WHEN v_acc >= original_cost - coalesce(residual_value,0) THEN 'fully_depreciated' ELSE status END WHERE id = ab.fa_id;
      v_count := v_count + 1; v_sum := v_sum + v_total;
    END IF;
  END LOOP;
  IF v_count = 0 THEN
    DELETE FROM acct_asset_depreciation_runs WHERE id = v_run;
    RETURN jsonb_build_object('assets', 0, 'amount', 0, 'through', v_end);
  END IF;
  v_je := acct_post_entry(p_tenant_id, v_entity, v_end, v_lines, 'fixed_asset', v_run::text, 'DEP ' || to_char(v_end,'YYYY-MM'),
                          'Depreciation through ' || v_end, 'dep:' || v_run, v_book, NULL, NULL, true, false, 'acct_asset_depreciation_runs', v_run);
  UPDATE acct_asset_depreciation_runs SET status = 'posted', journal_id = v_je, posted_at = now() WHERE id = v_run;
  RETURN jsonb_build_object('run_id', v_run, 'journal_id', v_je, 'assets', v_count, 'amount', v_sum, 'through', v_end);
END $$;

-- @seq 296
CREATE FUNCTION public.acct_run_recognition(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE l record; v_je uuid; n int := 0; v_sum numeric := 0; v_dr uuid; v_cr uuid; v_amt numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR l IN SELECT rl.*, s.kind, s.name, s.balance_account_id, s.pl_account_id, s.entity_id, s.vendor_id, s.customer_id
             FROM acct_recognition_lines rl JOIN acct_recognition_schedules s ON s.id = rl.schedule_id
            WHERE rl.tenant_id = p_tenant_id AND rl.status = 'pending' AND rl.recognize_on <= p_as_of AND s.status = 'active'
            ORDER BY rl.recognize_on, s.created_at, rl.line_no FOR UPDATE OF rl LOOP
    v_amt := abs(l.amount);
    -- expense kinds: Dr expense / Cr balance (prepaid consumed, or accrual booked); revenue kinds: Dr balance / Cr revenue
    IF l.kind IN ('prepaid_expense','accrued_expense') THEN v_dr := l.pl_account_id; v_cr := l.balance_account_id;
    ELSE v_dr := l.balance_account_id; v_cr := l.pl_account_id; END IF;
    IF l.amount < 0 THEN SELECT v_cr, v_dr INTO v_dr, v_cr; END IF;   -- reversal line flips
    v_je := acct_post_entry(p_tenant_id, l.entity_id, l.recognize_on, jsonb_build_array(
              jsonb_build_object('account_id', v_dr, 'debit', v_amt, 'description', l.name || CASE WHEN l.amount < 0 THEN ' (reversal)' ELSE '' END,
                                 'vendor_id', l.vendor_id, 'customer_id', l.customer_id),
              jsonb_build_object('account_id', v_cr, 'credit', v_amt, 'description', l.name || CASE WHEN l.amount < 0 THEN ' (reversal)' ELSE '' END,
                                 'vendor_id', l.vendor_id, 'customer_id', l.customer_id)),
            CASE WHEN l.kind LIKE 'accrued%' THEN 'allocation' ELSE 'revenue_recognition' END, l.schedule_id::text, NULL,
            l.name || ' ' || l.line_no, 'recog:' || l.id, NULL, NULL, NULL, true, false, 'acct_recognition_schedules', l.schedule_id);
    UPDATE acct_recognition_lines SET status = 'posted', journal_entry_id = v_je, posted_at = now() WHERE id = l.id;
    n := n + 1; v_sum := v_sum + l.amount;
  END LOOP;
  UPDATE acct_recognition_schedules s SET status = 'completed'
   WHERE s.tenant_id = p_tenant_id AND s.status = 'active' AND NOT EXISTS (SELECT 1 FROM acct_recognition_lines WHERE schedule_id = s.id AND status = 'pending');
  RETURN jsonb_build_object('posted', n, 'net_amount', v_sum, 'as_of', p_as_of);
END $$;

-- @seq 297
CREATE FUNCTION public.acct_run_recurring_bills(p_as_of date DEFAULT CURRENT_DATE, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_recurring_bills%ROWTYPE; v_bill uuid; l jsonb; n int := 0; v_step interval; v_due date; v_round int; v_guard int := 0;
BEGIN
 LOOP   -- catch up every missed occurrence, not just one
  v_round := 0; v_guard := v_guard + 1;
  EXIT WHEN v_guard > 400;
  FOR t IN SELECT * FROM acct_recurring_bills WHERE is_active AND next_run_date <= p_as_of AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
            AND (end_date IS NULL OR next_run_date <= end_date) AND coalesce(occurrences_remaining, 1) > 0 FOR UPDATE SKIP LOCKED LOOP
    IF p_tenant_id IS NOT NULL THEN PERFORM acct_assert_access(t.tenant_id); END IF;
    v_step := CASE t.frequency WHEN 'weekly' THEN interval '7 days' WHEN 'biweekly' THEN interval '14 days' WHEN 'monthly' THEN interval '1 month'
                               WHEN 'quarterly' THEN interval '3 months' ELSE interval '1 year' END * t.interval_count;
    INSERT INTO acct_ap_bills(tenant_id, entity_id, vendor_id, bill_number, bill_date, due_date, currency, status, source, memo, terms_id, recurring_bill_id)
    VALUES (t.tenant_id, t.entity_id, t.vendor_id, NULL, t.next_run_date, NULL, 'USD', 'draft', 'recurring', t.memo, t.terms_id, t.id)
    RETURNING id, due_date INTO v_bill, v_due;
    FOR l IN SELECT value FROM jsonb_array_elements(t.lines) LOOP
      INSERT INTO acct_ap_bill_lines(bill_id, line_no, description, quantity, unit_cost, expense_account_id, item_id, billable, billable_customer_id, dimensions, tenant_id)
      VALUES (v_bill, NULL, coalesce(l->>'description', t.name), coalesce((l->>'quantity')::numeric, 1), coalesce((l->>'unit_cost')::numeric, 0),
              nullif(l->>'expense_account_id','')::uuid, nullif(l->>'item_id','')::uuid, coalesce((l->>'billable')::boolean, false),
              nullif(l->>'billable_customer_id','')::uuid, coalesce(l->'dimensions','{}'::jsonb), t.tenant_id);
    END LOOP;
    IF t.auto_post THEN
      PERFORM acct_post_bill(v_bill, true);
      IF t.auto_pay_bank_account_id IS NOT NULL THEN
        PERFORM acct_schedule_bill_payment(v_bill, t.auto_pay_bank_account_id, greatest(t.next_run_date, v_due - t.pay_days_before_due), coalesce(t.auto_pay_method, 'ach'));
      END IF;
    END IF;
    UPDATE acct_recurring_bills SET next_run_date = (next_run_date + v_step)::date, last_bill_id = v_bill,
           occurrences_remaining = occurrences_remaining - 1, updated_at = now() WHERE id = t.id;
    n := n + 1; v_round := v_round + 1;
  END LOOP;
  EXIT WHEN v_round = 0;
 END LOOP;
  RETURN n;
END $$;

-- @seq 298
CREATE FUNCTION public.acct_run_recurring_invoices(p_as_of date DEFAULT CURRENT_DATE, p_tenant_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_recurring_invoices%ROWTYPE; v_inv uuid; l record; j jsonb; n int := 0; v_step interval; v_cnt int; v_round int; v_guard int := 0;
BEGIN
 LOOP
  v_round := 0; v_guard := v_guard + 1; EXIT WHEN v_guard > 400;
  FOR t IN SELECT * FROM acct_recurring_invoices WHERE status = 'active' AND next_run_date <= p_as_of AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
            AND (coalesce(ends_on, end_date) IS NULL OR next_run_date <= coalesce(ends_on, end_date))
            AND (occurrences_limit IS NULL OR occurrences_done < occurrences_limit) FOR UPDATE SKIP LOCKED LOOP
    IF p_tenant_id IS NOT NULL THEN PERFORM acct_assert_access(t.tenant_id); END IF;
    v_step := CASE t.frequency WHEN 'weekly' THEN interval '7 days' WHEN 'biweekly' THEN interval '14 days' WHEN 'monthly' THEN interval '1 month'
                               WHEN 'quarterly' THEN interval '3 months' WHEN 'annually' THEN interval '1 year' WHEN 'yearly' THEN interval '1 year' ELSE interval '1 month' END * t.interval_count;
    INSERT INTO acct_ar_invoices(tenant_id, entity_id, customer_id, invoice_number, invoice_date, due_date, currency, status, recurring_invoice_id,
                                 tax_jurisdiction_id)
    VALUES (t.tenant_id, coalesce(t.entity_id, acct_default_entity(t.tenant_id)), t.customer_id, NULL, t.next_run_date, NULL, t.currency, 'draft', t.id,
            nullif(t.metadata->>'tax_jurisdiction_id','')::uuid)
    RETURNING id INTO v_inv;
    v_cnt := 0;
    FOR l IN SELECT * FROM acct_recurring_invoice_lines WHERE recurring_invoice_id = t.id ORDER BY line_number LOOP
      INSERT INTO acct_ar_invoice_lines(invoice_id, line_no, description, quantity, unit_price, revenue_account_id, dimensions, tenant_id)
      VALUES (v_inv, NULL, l.description, l.quantity, l.unit_price, NULL, '{}'::jsonb, t.tenant_id);
      v_cnt := v_cnt + 1;
    END LOOP;
    IF v_cnt = 0 THEN
      FOR j IN SELECT value FROM jsonb_array_elements(t.lines) LOOP
        INSERT INTO acct_ar_invoice_lines(invoice_id, line_no, description, quantity, unit_price, item_id, revenue_account_id, dimensions, tenant_id)
        VALUES (v_inv, NULL, coalesce(j->>'description', t.name), coalesce((j->>'quantity')::numeric,1), coalesce((j->>'unit_price')::numeric, (j->>'rate')::numeric, 0),
                nullif(j->>'item_id','')::uuid, nullif(j->>'revenue_account_id','')::uuid, '{}'::jsonb, t.tenant_id);
      END LOOP;
    END IF;
    PERFORM acct_post_invoice(v_inv);
    UPDATE acct_recurring_invoices SET next_run_date = (next_run_date + v_step)::date, next_run_on = (next_run_date + v_step)::date, last_invoice_id = v_inv,
           last_run_at = now(), last_run_on = t.next_run_date, run_count = run_count + 1, occurrences_done = occurrences_done + 1, updated_at = now()
     WHERE id = t.id;
    n := n + 1; v_round := v_round + 1;
  END LOOP;
  EXIT WHEN v_round = 0;
 END LOOP;
  RETURN n;
END $$;

-- @seq 299
CREATE FUNCTION public.acct_run_review(p_tenant_id uuid, p_from date, p_to date, p_params jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_entity uuid; s acct_settings%ROWTYPE; v_run uuid; v_large numeric; v_rcpt numeric; v_stale int; v_undep int;
        v_dims text[]; v_checks text[]; v_total int; v_new int; v_udf uuid; v_ar uuid; v_ap uuid; v_unc_i uuid; v_unc_e uuid;
        v_year int := extract(year FROM p_to)::int; v_summary jsonb;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_to < p_from THEN RAISE EXCEPTION 'Review period ends before it starts'; END IF;
  v_entity := acct_default_entity(p_tenant_id);
  s := acct__settings(p_tenant_id, v_entity);
  v_large := coalesce((p_params->>'large_txn_threshold')::numeric, s.large_txn_threshold);
  v_rcpt  := coalesce((p_params->>'receipt_required_over')::numeric, s.receipt_required_over);
  v_stale := coalesce((p_params->>'stale_days')::int, 60);
  v_undep := coalesce((p_params->>'undeposited_days')::int, 14);
  v_checks := CASE WHEN p_params ? 'checks' THEN ARRAY(SELECT jsonb_array_elements_text(p_params->'checks')) END;
  v_ar := acct_role_account(p_tenant_id, v_entity, 'accounts_receivable', false);
  v_ap := acct_role_account(p_tenant_id, v_entity, 'accounts_payable', false);
  v_unc_i := acct_role_account(p_tenant_id, v_entity, 'uncategorized_income', false);
  v_unc_e := acct_role_account(p_tenant_id, v_entity, 'uncategorized_expense', false);
  v_udf := acct_system_register(p_tenant_id, v_entity, 'undeposited_funds');
  -- dimensions the company actually uses on P&L lines, unless the run names them
  v_dims := CASE WHEN p_params ? 'required_dimensions' THEN ARRAY(SELECT jsonb_array_elements_text(p_params->'required_dimensions'))
                 ELSE ARRAY(SELECT DISTINCT k FROM acct_journal_lines l JOIN acct_chart_of_accounts a ON a.id = l.account_id,
                                   jsonb_object_keys(CASE WHEN jsonb_typeof(l.dimensions) = 'object' THEN l.dimensions ELSE '{}'::jsonb END) k
                             WHERE l.tenant_id = p_tenant_id AND a.account_type IN ('revenue','expense')
                               AND l.created_at > now() - interval '400 days') END;

  INSERT INTO acct_review_runs(tenant_id, entity_id, period_from, period_to, params, run_by)
  VALUES (p_tenant_id, v_entity, p_from, p_to, p_params, auth.uid()) RETURNING id INTO v_run;

  CREATE TEMP TABLE IF NOT EXISTS _acct_findings(check_code text, severity text, title text, detail text, source_type text, source_id uuid,
     journal_entry_id uuid, account_id uuid, amount numeric, txn_date date, fp text) ON COMMIT DROP;
  DELETE FROM _acct_findings;

  -- posted lines in the period (helper CTE repeated per check for clarity)
  -- 1. postings to a parent (header) account
  INSERT INTO _acct_findings
  SELECT 'parent_account_posting','warning', 'Posted to header account ' || a.code || ' ' || a.name,
         'Header accounts have sub-accounts; post to a sub-account so reports roll up correctly.', 'acct_journal_entries', je.id, je.id, a.id,
         abs(l.debit - l.credit), je.entry_date, 'parent:' || l.id
    FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id JOIN acct_chart_of_accounts a ON a.id = l.account_id
   WHERE l.tenant_id = p_tenant_id AND je.status = 'posted' AND je.entry_date BETWEEN p_from AND p_to
     AND EXISTS (SELECT 1 FROM acct_chart_of_accounts c WHERE c.parent_account_id = a.id AND c.is_active);

  -- 2. large transactions
  INSERT INTO _acct_findings
  SELECT 'large_transaction','info', 'Large ' || je.source || ' entry #' || je.entry_no || ' (' || to_char(je.total_debit,'FM999,999,990.00') || ')',
         coalesce(je.memo, je.reference), 'acct_journal_entries', je.id, je.id, NULL, je.total_debit, je.entry_date, 'large:' || je.id
    FROM acct_journal_entries je
   WHERE je.tenant_id = p_tenant_id AND je.status = 'posted' AND je.entry_date BETWEEN p_from AND p_to
     AND NOT je.is_closing AND je.reversal_of_id IS NULL AND je.total_debit >= v_large
     AND je.source IN ('manual','bank','expense','vendor_bill','import','integration','allocation');

  -- 3. P&L lines missing a dimension the company uses (class, location, department...)
  IF array_length(v_dims,1) > 0 THEN
    INSERT INTO _acct_findings
    SELECT 'missing_dimension','warning', 'Missing ' || array_to_string(ARRAY(SELECT d FROM unnest(v_dims) d WHERE NOT (coalesce(l.dimensions,'{}'::jsonb) ? d)
                                   AND NOT (d = 'location' AND l.location_id IS NOT NULL) AND NOT (d = 'department' AND l.department_id IS NOT NULL)), ', ')
           || ' on ' || a.code || ' ' || a.name, coalesce(l.description, je.memo), 'acct_journal_entries', je.id, je.id, a.id,
           abs(l.debit - l.credit), je.entry_date, 'dim:' || l.id
      FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id JOIN acct_chart_of_accounts a ON a.id = l.account_id
     WHERE l.tenant_id = p_tenant_id AND je.status = 'posted' AND je.entry_date BETWEEN p_from AND p_to AND NOT je.is_closing
       AND a.account_type IN ('revenue','expense') AND je.source NOT IN ('inventory','fixed_asset','revenue_recognition','payroll')
       AND EXISTS (SELECT 1 FROM unnest(v_dims) d WHERE NOT (coalesce(l.dimensions,'{}'::jsonb) ? d)
                     AND NOT (d = 'location' AND l.location_id IS NOT NULL) AND NOT (d = 'department' AND l.department_id IS NOT NULL));
  END IF;

  -- 4. income without a customer (manual and bank entries only; documents always carry one)
  INSERT INTO _acct_findings
  SELECT 'missing_customer','warning', 'Income on ' || a.code || ' ' || a.name || ' has no customer', coalesce(l.description, je.memo),
         'acct_journal_entries', je.id, je.id, a.id, l.credit - l.debit, je.entry_date, 'nocust:' || l.id
    FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id JOIN acct_chart_of_accounts a ON a.id = l.account_id
   WHERE l.tenant_id = p_tenant_id AND je.status = 'posted' AND je.entry_date BETWEEN p_from AND p_to
     AND a.account_type = 'revenue' AND je.source IN ('manual','bank') AND l.customer_id IS NULL AND l.credit > 0;

  -- 5. sales tax with no jurisdiction (cannot be filed)
  INSERT INTO _acct_findings
  SELECT 'tax_no_jurisdiction','error', 'Sales tax ' || to_char(tt.tax_amount,'FM999,990.00') || ' has no jurisdiction',
         'Tax collected on ' || tt.source_doc_type || ' cannot be assigned to a return.', tt.source_doc_type, tt.source_doc_id, tt.journal_entry_id, NULL,
         tt.tax_amount, tt.tax_date, 'taxjur:' || tt.id
    FROM acct_tax_transactions tt
   WHERE tt.tenant_id = p_tenant_id AND tt.tax_date BETWEEN p_from AND p_to AND tt.jurisdiction_id IS NULL AND tt.tax_amount <> 0;
  INSERT INTO _acct_findings
  SELECT 'tax_no_jurisdiction','error', 'Invoice ' || i.invoice_number || ' charged tax without a jurisdiction', NULL, 'acct_ar_invoices', i.id,
         i.posted_journal_id, NULL, i.tax_total, i.invoice_date, 'invjur:' || i.id
    FROM acct_ar_invoices i
   WHERE i.tenant_id = p_tenant_id AND i.invoice_date BETWEEN p_from AND p_to AND i.posted_journal_id IS NOT NULL AND i.status <> 'void'
     AND i.tax_total <> 0 AND i.tax_jurisdiction_id IS NULL;

  -- 6. the same kind of item taxed at different rates in the same place (outside holidays/exemptions)
  INSERT INTO _acct_findings
  SELECT 'tax_inconsistent','warning', 'Category ' || coalesce(tt.tax_category,'(none)') || ' taxed at ' || count(DISTINCT tt.rate) || ' different rates in ' || coalesce(j.name, '?'),
         'Rates used: ' || string_agg(DISTINCT round(tt.rate * 100, 3)::text || '%', ', '), NULL, NULL, NULL, NULL, sum(tt.tax_amount), max(tt.tax_date),
         'taxmix:' || coalesce(tt.jurisdiction_id::text,'') || ':' || coalesce(tt.tax_category,'') || ':' || p_from || ':' || p_to
    FROM acct_tax_transactions tt LEFT JOIN acct_tax_jurisdictions j ON j.id = tt.jurisdiction_id
   WHERE tt.tenant_id = p_tenant_id AND tt.tax_date BETWEEN p_from AND p_to AND tt.direction = 'output'
     AND coalesce(tt.reason,'') !~* '(holiday|exempt|resale|reversal|cancel|refund)' AND tt.gross_amount > 0
   GROUP BY tt.jurisdiction_id, tt.tax_category, j.name HAVING count(DISTINCT tt.rate) > 1;

  -- 7. expenses over the receipt threshold with nothing attached
  INSERT INTO _acct_findings
  SELECT 'missing_attachment','warning', 'No receipt: bill ' || coalesce(b.bill_number,'') || ' ' || coalesce(v.display_name, v.legal_name), NULL,
         'acct_ap_bills', b.id, b.posted_journal_id, NULL, b.total, b.bill_date, 'att:' || b.id
    FROM acct_ap_bills b JOIN acct_vendors v ON v.id = b.vendor_id
   WHERE b.tenant_id = p_tenant_id AND b.bill_date BETWEEN p_from AND p_to AND b.posted_journal_id IS NOT NULL AND b.status <> 'void'
     AND b.total >= v_rcpt AND b.inbox_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM acct_attachments at WHERE at.tenant_id = p_tenant_id AND at.entity_type = 'acct_ap_bills' AND at.entity_id = b.id::text);
  INSERT INTO _acct_findings
  SELECT 'missing_attachment','warning', 'No receipt: ' || replace(sp.txn_kind,'_',' ') || ' ' ||
         coalesce(sp.payee_name, (SELECT coalesce(v.display_name, v.legal_name) FROM acct_vendors v WHERE v.id = sp.payee_vendor_id), ''), sp.memo,
         'acct_spend_transactions', sp.id, sp.posted_journal_id, NULL, sp.total, sp.payment_date, 'att:' || sp.id
    FROM acct_spend_transactions sp
   WHERE sp.tenant_id = p_tenant_id AND sp.payment_date BETWEEN p_from AND p_to AND sp.status = 'posted' AND sp.txn_kind <> 'cc_credit'
     AND sp.total >= v_rcpt AND sp.inbox_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM acct_attachments at WHERE at.tenant_id = p_tenant_id AND at.entity_type = 'acct_spend_transactions' AND at.entity_id = sp.id::text)
     AND NOT EXISTS (SELECT 1 FROM acct_receipt_extractions re WHERE re.matched_bank_transaction_id = sp.bank_transaction_id AND sp.bank_transaction_id IS NOT NULL);
  INSERT INTO _acct_findings
  SELECT 'missing_attachment','warning', 'No receipt: bank line ' || coalesce(bt.payee, bt.description), NULL,
         'acct_bank_transactions', bt.id, bt.posted_journal_id, bt.category_account_id, -bt.amount, bt.transaction_date, 'att:' || bt.id
    FROM acct_bank_transactions bt
   WHERE bt.tenant_id = p_tenant_id AND bt.transaction_date BETWEEN p_from AND p_to AND bt.review_status = 'posted'
     AND bt.amount <= -v_rcpt AND coalesce(bt.txn_type,'expense') IN ('expense','check') AND bt.receipt_attachment_id IS NULL
     AND NOT EXISTS (SELECT 1 FROM acct_receipt_extractions re WHERE re.matched_bank_transaction_id = bt.id)
     AND NOT EXISTS (SELECT 1 FROM acct_attachments at WHERE at.tenant_id = p_tenant_id AND at.entity_type = 'acct_bank_transactions' AND at.entity_id = bt.id::text);

  -- 8. added automatically by a bank rule (spot-check)
  INSERT INTO _acct_findings
  SELECT 'added_by_rule','info', 'Added by rule "' || r.name || '": ' || coalesce(bt.payee, bt.description), NULL,
         'acct_bank_transactions', bt.id, bt.posted_journal_id, bt.category_account_id, abs(bt.amount), bt.transaction_date, 'rule:' || bt.id
    FROM acct_bank_transactions bt JOIN acct_bank_rules r ON r.id = bt.suggested_rule_id
   WHERE bt.tenant_id = p_tenant_id AND bt.transaction_date BETWEEN p_from AND p_to AND bt.review_status = 'posted' AND r.auto_confirm;

  -- 9. money left in uncategorized / suspense accounts
  INSERT INTO _acct_findings
  SELECT 'uncategorized','warning', 'Uncategorized: ' || coalesce(l.description, je.memo, '(no description)'), a.code || ' ' || a.name,
         'acct_journal_entries', je.id, je.id, a.id, abs(l.debit - l.credit), je.entry_date, 'unc:' || l.id
    FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id JOIN acct_chart_of_accounts a ON a.id = l.account_id
   WHERE l.tenant_id = p_tenant_id AND je.status = 'posted' AND je.entry_date BETWEEN p_from AND p_to
     AND (l.account_id IN (v_unc_i, v_unc_e) OR a.name ~* '(suspense|ask my accountant|uncategori[sz]ed)');

  -- 10. balances on the wrong side at period end
  INSERT INTO _acct_findings
  SELECT 'negative_balance', CASE WHEN a.subtype IN ('bank','cash') THEN 'warning' ELSE 'info' END,
         CASE WHEN a.subtype IN ('bank','cash') THEN 'Negative cash balance: ' ELSE 'Balance on the unusual side: ' END || a.code || ' ' || a.name,
         'Balance ' || to_char(bal,'FM999,999,990.00') || ' as of ' || p_to, 'acct_chart_of_accounts', a.id, NULL, a.id, bal, p_to,
         'neg:' || a.id || ':' || p_to
    FROM (SELECT a.id, sum(CASE WHEN a.normal_balance = 'debit' THEN l.debit - l.credit ELSE l.credit - l.debit END) bal
            FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id JOIN acct_chart_of_accounts a ON a.id = l.account_id
           WHERE l.tenant_id = p_tenant_id AND je.status IN ('posted','reversed') AND je.entry_date <= p_to
             AND a.account_type IN ('asset','liability') AND a.subtype IN ('bank','cash','accounts_receivable','accounts_payable','inventory','other_current_liability')
           GROUP BY a.id) x JOIN acct_chart_of_accounts a ON a.id = x.id
   WHERE x.bal < -0.005;
  INSERT INTO _acct_findings
  SELECT 'negative_inventory','error', 'Negative stock: ' || v.item_name || ' (' || v.quantity || ')', 'Sales exceeded recorded receipts; enter the missing purchase or count.',
         'acct_items', v.item_id, NULL, NULL, v.value, p_to, 'negqty:' || v.item_id
    FROM acct_inventory_valuation(p_tenant_id, p_to) v WHERE v.quantity < 0;

  -- 11. coded differently from this payee's history (>= 3 prior, >= 80% to another account)
  INSERT INTO _acct_findings
  SELECT 'possible_miscoding','warning', coalesce(bt.payee, bt.description) || ' coded to ' || a.code || ' ' || a.name || ', usually ' || h.code || ' ' || h.name,
         h.n || ' of ' || h.total || ' earlier transactions went to ' || h.code, 'acct_bank_transactions', bt.id, bt.posted_journal_id, bt.category_account_id,
         abs(bt.amount), bt.transaction_date, 'miscode:' || bt.id
    FROM acct_bank_transactions bt JOIN acct_chart_of_accounts a ON a.id = bt.category_account_id
    CROSS JOIN LATERAL (
      SELECT x.category_account_id, c.code, c.name, count(*) n, sum(count(*)) OVER () total
        FROM acct_bank_transactions x JOIN acct_chart_of_accounts c ON c.id = x.category_account_id
       WHERE x.tenant_id = p_tenant_id AND x.id <> bt.id AND x.review_status = 'posted' AND x.normalized_descriptor = bt.normalized_descriptor
         AND sign(x.amount) = sign(bt.amount)
       GROUP BY x.category_account_id, c.code, c.name ORDER BY count(*) DESC LIMIT 1) h
   WHERE bt.tenant_id = p_tenant_id AND bt.transaction_date BETWEEN p_from AND p_to AND bt.review_status = 'posted'
     AND bt.normalized_descriptor IS NOT NULL AND h.category_account_id <> bt.category_account_id AND h.n >= 3 AND h.n::numeric / h.total >= 0.8;

  -- 12. duplicates
  INSERT INTO _acct_findings
  SELECT 'possible_duplicate','warning', 'Possible duplicate bill: ' || coalesce(v.display_name, v.legal_name) || ' ' || to_char(b.total,'FM999,999,990.00'),
         'Also bill ' || coalesce(b2.bill_number,'(no number)') || ' on ' || b2.bill_date, 'acct_ap_bills', b.id, b.posted_journal_id, NULL, b.total, b.bill_date,
         'dupbill:' || least(b.id::text, b2.id::text) || ':' || greatest(b.id::text, b2.id::text)
    FROM acct_ap_bills b JOIN acct_ap_bills b2 ON b2.tenant_id = b.tenant_id AND b2.vendor_id = b.vendor_id AND b2.id > b.id
         AND b2.total = b.total AND abs(b2.bill_date - b.bill_date) <= 7 AND b2.status <> 'void'
    JOIN acct_vendors v ON v.id = b.vendor_id
   WHERE b.tenant_id = p_tenant_id AND b.status <> 'void' AND greatest(b.bill_date, b2.bill_date) BETWEEN p_from AND p_to;
  INSERT INTO _acct_findings
  SELECT 'possible_duplicate','warning', 'Possible duplicate expense: ' || coalesce(sp.payee_name,'') || ' ' || to_char(sp.total,'FM999,999,990.00'),
         'Same payee, amount and date as another expense', 'acct_spend_transactions', sp.id, sp.posted_journal_id, NULL, sp.total, sp.payment_date,
         'dupspend:' || least(sp.id::text, s2.id::text) || ':' || greatest(sp.id::text, s2.id::text)
    FROM acct_spend_transactions sp JOIN acct_spend_transactions s2 ON s2.tenant_id = sp.tenant_id AND s2.id > sp.id AND s2.status = 'posted'
         AND s2.txn_kind = sp.txn_kind AND s2.total = sp.total AND s2.payment_date = sp.payment_date
         AND lower(coalesce(s2.payee_name,'')) = lower(coalesce(sp.payee_name,''))
   WHERE sp.tenant_id = p_tenant_id AND sp.status = 'posted' AND sp.payment_date BETWEEN p_from AND p_to;
  INSERT INTO _acct_findings
  SELECT 'possible_duplicate','warning', 'Possible duplicate journal #' || je.entry_no || ' and #' || j2.entry_no, je.memo, 'acct_journal_entries', je.id, je.id, NULL,
         je.total_debit, je.entry_date, 'dupje:' || je.id || ':' || j2.id
    FROM acct_journal_entries je JOIN acct_journal_entries j2 ON j2.tenant_id = je.tenant_id AND j2.id <> je.id AND j2.entry_no > je.entry_no
         AND j2.status = 'posted' AND j2.source = 'manual' AND j2.entry_date = je.entry_date AND j2.total_debit = je.total_debit
         AND coalesce(j2.memo,'') = coalesce(je.memo,'')
   WHERE je.tenant_id = p_tenant_id AND je.status = 'posted' AND je.source = 'manual' AND je.entry_date BETWEEN p_from AND p_to;

  -- 13. bank-register items in the books that never cleared the bank
  INSERT INTO _acct_findings
  SELECT 'stale_uncleared','warning', 'Uncleared for ' || (p_to - je.entry_date) || ' days: ' || coalesce(l.description, je.memo, je.reference, ''),
         ba.name, 'acct_journal_entries', je.id, je.id, l.account_id, l.debit - l.credit, je.entry_date, 'stale:' || l.id
    FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id
    JOIN acct_bank_accounts ba ON ba.gl_account_id = l.account_id AND ba.tenant_id = p_tenant_id
   WHERE l.tenant_id = p_tenant_id AND je.status = 'posted' AND coalesce(l.cleared_status,'uncleared') = 'uncleared'
     AND je.entry_date <= p_to - v_stale AND coalesce(ba.account_kind,'') NOT IN ('undeposited_funds','payment_processor');
  INSERT INTO _acct_findings
  SELECT 'stale_undeposited','warning', 'Payment not deposited after ' || (p_to - r.receipt_date) || ' days: ' || coalesce(r.receipt_number,''),
         r.payment_method || ' ' || coalesce(r.reference,''), 'acct_ar_receipts', r.id, r.posted_journal_id, NULL, r.amount, r.receipt_date, 'undep:' || r.id
    FROM acct_ar_receipts r
   WHERE r.tenant_id = p_tenant_id AND r.deposit_account_id = v_udf AND r.deposit_id IS NULL AND r.voided_at IS NULL
     AND r.posted_journal_id IS NOT NULL AND r.receipt_date <= p_to - v_undep;

  -- 14. bank/card accounts not reconciled through the period end
  INSERT INTO _acct_findings
  SELECT 'not_reconciled','warning', 'Not reconciled through ' || p_to || ': ' || ba.name,
         'Last reconciled ' || coalesce((SELECT max(as_of_date)::text FROM acct_reconciliations r WHERE r.bank_account_id = ba.id AND r.status = 'reconciled'), 'never'),
         'acct_bank_accounts', ba.id, NULL, ba.gl_account_id, NULL, p_to, 'recon:' || ba.id || ':' || p_to
    FROM acct_bank_accounts ba
   WHERE ba.tenant_id = p_tenant_id AND ba.is_active AND coalesce(ba.account_kind,'') NOT IN ('undeposited_funds','payment_processor')
     AND NOT EXISTS (SELECT 1 FROM acct_reconciliations r WHERE r.bank_account_id = ba.id AND r.status = 'reconciled' AND r.as_of_date >= p_to)
     AND EXISTS (SELECT 1 FROM acct_journal_lines l WHERE l.account_id = ba.gl_account_id);

  -- 15. sub-ledgers that do not agree with the general ledger
  INSERT INTO _acct_findings
  SELECT 'subledger_tieout','error', x.label || ' does not agree with the general ledger',
         'Sub-ledger ' || to_char(x.sub,'FM999,999,990.00') || ' vs GL ' || to_char(x.gl,'FM999,999,990.00'), NULL, NULL, NULL, x.acct, x.sub - x.gl, current_date,
         'tie:' || x.code || ':' || current_date
    FROM (
      SELECT 'ar' code, 'Open invoices (A/R)' label, v_ar acct,
             (SELECT coalesce(sum(open_balance),0) FROM acct_ar_invoices WHERE tenant_id = p_tenant_id AND posted_journal_id IS NOT NULL AND status <> 'void') sub,
             (SELECT coalesce(sum(debit - credit),0) FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id
               WHERE l.account_id = v_ar AND je.status IN ('posted','reversed')
                 -- shop-order A/R is tracked per order in acct_order_postings, not as invoices
                 AND coalesce(je.source_doc_type,'') <> 'erp_orders') gl
      UNION ALL
      SELECT 'ap', 'Open bills (A/P)', v_ap,
             (SELECT coalesce(sum(open_balance),0) FROM acct_ap_bills WHERE tenant_id = p_tenant_id AND posted_journal_id IS NOT NULL AND status <> 'void'),
             (SELECT coalesce(sum(credit - debit),0) FROM acct_journal_lines l JOIN acct_journal_entries je ON je.id = l.journal_entry_id
               WHERE l.account_id = v_ap AND je.status IN ('posted','reversed'))
      UNION ALL
      SELECT 'inv:' || t.account_code, 'Inventory ' || t.account_code, NULL, t.items_value, t.gl_balance FROM acct_inventory_tieout(p_tenant_id, p_to) t
      UNION ALL
      SELECT 'rec:' || t.account_code, 'Schedules ' || t.account_name, NULL, t.schedules_remaining, t.gl_balance FROM acct_recognition_tieout(p_tenant_id, p_to) t
    ) x
   WHERE abs(x.sub - x.gl) > 0.005;
  INSERT INTO _acct_findings
  SELECT 'balance_sheet_out_of_balance','error', 'Balance sheet is out of balance by ' || b.amount, NULL, NULL, NULL, NULL, NULL, b.amount, p_to, 'bs:' || p_to
    FROM acct_balance_sheet(p_tenant_id, p_to) b WHERE b.section = 'Out of Balance' AND abs(b.amount) > 0.005;

  -- 16. unfinished work dated in the period
  INSERT INTO _acct_findings
  SELECT 'draft_document','info', 'Draft ' || x.kind || ' ' || coalesce(x.num,''), NULL, x.tbl, x.id, NULL, NULL, x.amt, x.d, 'draft:' || x.id
    FROM (SELECT 'invoice' kind, invoice_number num, 'acct_ar_invoices' tbl, id, total amt, invoice_date d FROM acct_ar_invoices
           WHERE tenant_id = p_tenant_id AND status = 'draft' AND invoice_date BETWEEN p_from AND p_to
          UNION ALL SELECT 'bill', bill_number, 'acct_ap_bills', id, total, bill_date FROM acct_ap_bills
           WHERE tenant_id = p_tenant_id AND status IN ('draft','pending_approval') AND bill_date BETWEEN p_from AND p_to
          UNION ALL SELECT 'expense', payee_name, 'acct_spend_transactions', id, total, payment_date FROM acct_spend_transactions
           WHERE tenant_id = p_tenant_id AND status = 'draft' AND payment_date BETWEEN p_from AND p_to
          UNION ALL SELECT 'journal', '#' || entry_no, 'acct_journal_entries', id, total_debit, entry_date FROM acct_journal_entries
           WHERE tenant_id = p_tenant_id AND status IN ('draft','approved') AND entry_date BETWEEN p_from AND p_to) x;

  -- 17. 1099 vendors without a W-9 / TIN
  INSERT INTO _acct_findings
  SELECT 'missing_w9', CASE WHEN m.must_file THEN 'error' ELSE 'warning' END, 'No W-9 on file: ' || m.vendor_name,
         'Paid ' || to_char(m.amount,'FM999,999,990.00') || ' on ' || m.form || ' box ' || m.box || ' in ' || v_year, 'acct_vendors', m.vendor_id, NULL, NULL,
         m.amount, p_to, 'w9:' || m.vendor_id || ':' || v_year
    FROM acct_1099_summary(p_tenant_id, v_year) m WHERE NOT (m.tin_on_file AND m.w9_on_file) AND m.amount > 0;

  -- 18. shop orders that failed to post
  INSERT INTO _acct_findings
  SELECT 'order_sync_error','error', 'Shop order ' || coalesce(o.order_number, op.order_id::text) || ' did not post', op.last_error,
         'erp_orders', op.order_id, NULL, NULL, o.total, o.order_date::date, 'ordererr:' || op.order_id || ':' || md5(op.last_error)
    FROM acct_order_postings op LEFT JOIN erp_orders o ON o.id = op.order_id
   WHERE op.tenant_id = p_tenant_id AND op.last_error IS NOT NULL;

  -- 19. bank feed backlog
  INSERT INTO _acct_findings
  SELECT 'bank_feed_backlog','info', count(*) || ' bank lines waiting more than 30 days in ' || ba.name, NULL, 'acct_bank_accounts', ba.id, NULL, ba.gl_account_id,
         sum(abs(bt.amount)), min(bt.transaction_date), 'backlog:' || ba.id || ':' || p_to
    FROM acct_bank_transactions bt JOIN acct_bank_accounts ba ON ba.id = bt.bank_account_id
   WHERE bt.tenant_id = p_tenant_id AND bt.review_status IN ('for_review','categorized') AND bt.transaction_date <= p_to - 30
   GROUP BY ba.id, ba.name, ba.gl_account_id;

  -- 20. customer payments sitting unapplied
  INSERT INTO _acct_findings
  SELECT 'unapplied_payment','info', 'Unapplied payment ' || coalesce(r.receipt_number,'') || ' ' || to_char(r.unapplied_amount,'FM999,990.00'), NULL,
         'acct_ar_receipts', r.id, r.posted_journal_id, NULL, r.unapplied_amount, r.receipt_date, 'unapplied:' || r.id
    FROM acct_ar_receipts r
   WHERE r.tenant_id = p_tenant_id AND r.unapplied_amount > 0 AND r.voided_at IS NULL AND r.receipt_date <= p_to;

  -- keep only requested checks; drop ignored ones
  IF v_checks IS NOT NULL THEN DELETE FROM _acct_findings WHERE check_code <> ALL (v_checks); END IF;
  DELETE FROM _acct_findings f USING acct_review_ignore_rules ir
   WHERE ir.tenant_id = p_tenant_id AND ir.check_code = f.check_code
     AND (ir.account_id IS NULL OR ir.account_id = f.account_id) AND (ir.source_id IS NULL OR ir.source_id = f.source_id)
     AND (ir.title_contains IS NULL OR strpos(lower(f.title), lower(ir.title_contains)) > 0);

  SELECT count(*) INTO v_total FROM _acct_findings;
  SELECT count(*) INTO v_new FROM _acct_findings f WHERE NOT EXISTS (SELECT 1 FROM acct_review_findings x WHERE x.tenant_id = p_tenant_id AND x.fingerprint = f.fp);
  INSERT INTO acct_review_findings(tenant_id, first_run_id, last_run_id, check_code, severity, title, detail, source_type, source_id, journal_entry_id,
                                   account_id, amount, txn_date, fingerprint)
  SELECT DISTINCT ON (fp) p_tenant_id, v_run, v_run, check_code, severity, left(title, 300), detail, source_type, source_id, journal_entry_id, account_id, amount, txn_date, fp
    FROM _acct_findings ORDER BY fp
  ON CONFLICT (tenant_id, fingerprint) DO UPDATE SET last_run_id = EXCLUDED.last_run_id, amount = EXCLUDED.amount, detail = EXCLUDED.detail,
     title = EXCLUDED.title, severity = EXCLUDED.severity, updated_at = now(),
     -- a resolved finding that shows up again is reopened; ignored stays ignored
     status = CASE WHEN acct_review_findings.status = 'resolved' THEN 'open' ELSE acct_review_findings.status END;
  -- findings from earlier runs over the same window that are no longer detected are resolved automatically
  UPDATE acct_review_findings f SET status = 'resolved', resolution_note = coalesce(resolution_note, 'No longer detected'), resolved_at = now(), updated_at = now()
   WHERE f.tenant_id = p_tenant_id AND f.status IN ('open','in_progress') AND f.last_run_id <> v_run
     AND f.txn_date BETWEEN p_from AND p_to AND (v_checks IS NULL OR f.check_code = ANY (v_checks))
     AND NOT EXISTS (SELECT 1 FROM _acct_findings x WHERE x.fp = f.fingerprint);

  SELECT coalesce(jsonb_object_agg(check_code, n), '{}'::jsonb) INTO v_summary
    FROM (SELECT check_code, count(*) n FROM _acct_findings GROUP BY 1) z;
  UPDATE acct_review_runs SET finding_count = v_total, new_count = v_new, summary = v_summary WHERE id = v_run;
  RETURN jsonb_build_object('run_id', v_run, 'findings', v_total, 'new', v_new, 'by_check', v_summary,
     'errors', (SELECT count(*) FROM _acct_findings WHERE severity = 'error'));
END $$;

-- @seq 300
CREATE FUNCTION public.acct_run_scheduled_payments(p_as_of date DEFAULT CURRENT_DATE) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s acct_scheduled_payments%ROWTYPE; n int := 0; r record;
BEGIN
  FOR s IN SELECT * FROM acct_scheduled_payments WHERE status = 'scheduled' AND scheduled_date <= p_as_of ORDER BY scheduled_date FOR UPDATE SKIP LOCKED LOOP
    BEGIN
      SELECT * INTO r FROM acct_pay_bills(s.bank_account_id, s.scheduled_date, jsonb_build_array(jsonb_build_object('bill_id', s.bill_id, 'amount', s.amount)),
                                          s.method, NULL, s.method = 'check', 'Scheduled payment', 'sched:' || s.id);
      UPDATE acct_scheduled_payments SET status = 'paid', ap_payment_id = r.payment_id, updated_at = now() WHERE id = s.id;
      UPDATE acct_ap_payments SET scheduled_payment_id = s.id WHERE id = r.payment_id;
      n := n + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE acct_scheduled_payments SET status = 'failed', failure_reason = SQLERRM, updated_at = now() WHERE id = s.id;
    END;
  END LOOP;
  RETURN n;
END $$;

-- @seq 301
CREATE FUNCTION public.acct_sales_tax_liability(p_tenant_id uuid, p_entity_id uuid, p_start date, p_end date) RETURNS TABLE(jurisdiction_id uuid, jurisdiction text, gross_sales numeric, taxable_sales numeric, exempt_sales numeric, tax_collected numeric, tax_filed numeric, tax_open numeric)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT t.jurisdiction_id, j.name,
         sum(t.gross_amount), sum(t.taxable_amount), sum(t.exempt_amount), sum(t.tax_amount),
         sum(t.tax_amount) FILTER (WHERE t.filing_id IS NOT NULL),
         sum(t.tax_amount) FILTER (WHERE t.filing_id IS NULL)
    FROM acct_tax_transactions t JOIN acct_tax_jurisdictions j ON j.id = t.jurisdiction_id
   WHERE acct_can_access(p_tenant_id) AND t.tenant_id = p_tenant_id AND t.entity_id = p_entity_id
     AND t.direction = 'sale' AND t.tax_date BETWEEN p_start AND p_end
   GROUP BY t.jurisdiction_id, j.name ORDER BY j.name;
$$;

-- @seq 302
CREATE FUNCTION public.acct_schedule_auto_reversal(p_journal_id uuid, p_reverse_on date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE j acct_journal_entries%ROWTYPE; v uuid; v_on date;
BEGIN
  SELECT * INTO j FROM acct_journal_entries WHERE id = p_journal_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Journal entry not found'; END IF;
  PERFORM acct_assert_access(j.tenant_id);
  IF j.status NOT IN ('draft','approved','posted') THEN RAISE EXCEPTION 'Only draft or posted entries can be scheduled to reverse'; END IF;
  v_on := coalesce(p_reverse_on, (SELECT end_date + 1 FROM acct_periods WHERE id = j.period_id));
  IF v_on <= j.entry_date THEN RAISE EXCEPTION 'Reversal date must be after the entry date'; END IF;
  INSERT INTO acct_auto_reversals(tenant_id, journal_entry_id, reverse_on) VALUES (j.tenant_id, j.id, v_on)
  ON CONFLICT (journal_entry_id) DO UPDATE SET reverse_on = EXCLUDED.reverse_on, status = 'scheduled', error = NULL
  RETURNING id INTO v;
  RETURN v;
END $$;

-- @seq 303
CREATE FUNCTION public.acct_schedule_bill_payment(p_bill_id uuid, p_bank_account_id uuid, p_date date, p_method text DEFAULT 'ach'::text, p_amount numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_ap_bills%ROWTYPE; v acct_vendors%ROWTYPE; v_id uuid; v_sched numeric;
BEGIN
  SELECT * INTO b FROM acct_ap_bills WHERE id = p_bill_id;
  PERFORM acct_assert_access(b.tenant_id);
  IF b.status NOT IN ('open','partially_paid','approved','pending_approval') THEN RAISE EXCEPTION 'Bill % is %', b.bill_number, b.status; END IF;
  SELECT * INTO v FROM acct_vendors WHERE id = b.vendor_id;
  IF p_method = 'ach' AND (v.ach_routing_number IS NULL OR v.ach_account_vault_id IS NULL) THEN
    RAISE EXCEPTION 'Vendor % has no ACH bank details on file', coalesce(v.display_name, v.legal_name); END IF;
  SELECT coalesce(sum(amount),0) INTO v_sched FROM acct_scheduled_payments WHERE bill_id = b.id AND status IN ('scheduled','processing');
  IF coalesce(p_amount, b.open_balance - v_sched) + v_sched > b.open_balance THEN RAISE EXCEPTION 'Scheduled payments would exceed the open balance'; END IF;
  PERFORM acct_bank_gl(p_bank_account_id);
  INSERT INTO acct_scheduled_payments(tenant_id, entity_id, bill_id, vendor_id, bank_account_id, method, amount, scheduled_date, created_by)
  VALUES (b.tenant_id, b.entity_id, b.id, b.vendor_id, p_bank_account_id, p_method, coalesce(p_amount, b.open_balance - v_sched), p_date, auth.uid())
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;

-- @seq 304
CREATE FUNCTION public.acct_seed_default_coa(p_tenant_id uuid, p_entity_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE n int := 0; r record; v_id uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  FOR r IN SELECT * FROM (VALUES
   -- code, name, type, subtype, detail, sched C line, control, reconcilable, role
   ('1000','Checking','asset','bank','checking','BS',false,true,NULL),
   ('1050','Savings','asset','bank','savings','BS',false,true,NULL),
   ('1090','Petty Cash','asset','cash','cash_on_hand','BS',false,true,NULL),
   ('1100','Undeposited Funds','asset','other_current_asset','undeposited_funds','BS',false,false,'undeposited_funds'),
   ('1150','Payment Processor Clearing (Stripe)','asset','other_current_asset','processor_clearing','BS',false,true,'processor_clearing'),
   ('1160','Disputed Funds Held','asset','other_current_asset','dispute_holding','BS',false,false,'dispute_holding'),
   ('1200','Accounts Receivable','asset','accounts_receivable','accounts_receivable','BS',true,false,'accounts_receivable'),
   ('1300','Inventory Asset','asset','inventory','inventory','BS',false,false,'inventory_asset'),
   ('1400','Prepaid Expenses','asset','other_current_asset','prepaid','BS',false,false,NULL),
   ('1450','Vendor Prepayments','asset','other_current_asset','vendor_prepayments','BS',false,false,'vendor_prepayments'),
   ('1500','Furniture and Equipment','asset','fixed_asset','equipment','BS',false,false,NULL),
   ('1590','Accumulated Depreciation','contra_asset','accumulated_depreciation','accumulated_depreciation','BS',false,false,NULL),
   ('2000','Accounts Payable','liability','accounts_payable','accounts_payable','BS',true,false,'accounts_payable'),
   ('2100','Business Credit Card','liability','credit_card','credit_card','BS',false,true,NULL),
   ('2200','Sales Tax Payable','liability','other_current_liability','sales_tax_payable','BS',false,false,'sales_tax_payable'),
   ('2250','Payroll Liabilities','liability','other_current_liability','payroll_liabilities','BS',false,false,'payroll_liabilities'),
   ('2260','Tips Payable','liability','other_current_liability','tips','BS',false,false,'tips_payable'),
   ('2300','Gift Card Liability','liability','other_current_liability','gift_cards','BS',false,false,'gift_card_liability'),
   ('2350','Customer Deposits','liability','other_current_liability','customer_deposits','BS',false,false,'customer_deposits'),
   ('2360','Unapplied Customer Payments','liability','other_current_liability','unapplied_cash','BS',false,false,'unapplied_cash'),
   ('2400','Line of Credit','liability','line_of_credit','line_of_credit','BS',false,true,NULL),
   ('2700','Notes Payable','liability','long_term_liability','notes_payable','BS',false,false,NULL),
   ('3000','Opening Balance Equity','equity','equity','opening_balance_equity','BS',false,false,'opening_balance_equity'),
   ('3100','Owner''s Draw','contra_equity','equity','owner_draw','BS',false,false,'owner_draw'),
   ('3200','Owner''s Contributions','equity','equity','owner_contributions','BS',false,false,NULL),
   ('3900','Retained Earnings','equity','equity','retained_earnings','BS',false,false,'retained_earnings'),
   ('4000','Sales','revenue','income','sales_of_product','1',false,false,'default_income'),
   ('4050','Service Income','revenue','income','service','1',false,false,NULL),
   ('4100','Shipping Income','revenue','income','shipping','1',false,false,'shipping_income'),
   ('4800','Sales Returns and Allowances','revenue','income','returns','2',false,false,'sales_returns'),
   ('4850','Discounts Given','revenue','income','discounts','2',false,false,'discounts_given'),
   ('4900','Uncategorized Income','revenue','income','uncategorized','6',false,false,'uncategorized_income'),
   ('4950','Interest Earned','revenue','other_income','interest','6',false,false,'interest_income'),
   ('5000','Cost of Goods Sold','expense','cogs','supplies_materials_cogs','4',false,false,'cogs'),
   ('6000','Advertising and Marketing','expense','expense','advertising','8',false,false,NULL),
   ('6050','Car and Truck','expense','expense','auto','9',false,false,NULL),
   ('6080','Merchant and Processor Fees','expense','expense','merchant_fees','10',false,false,'processor_fees'),
   ('6100','Contract Labor','expense','expense','contractors','11',false,false,NULL),
   ('6150','Depreciation','expense','expense','depreciation','13',false,false,NULL),
   ('6200','Insurance','expense','expense','insurance','15',false,false,NULL),
   ('6250','Interest Expense','expense','expense','interest','16b',false,false,'interest_expense'),
   ('6300','Legal and Professional','expense','expense','legal_professional','17',false,false,NULL),
   ('6350','Office Expenses','expense','expense','office','18',false,false,NULL),
   ('6400','Rent','expense','expense','rent','20b',false,false,NULL),
   ('6450','Repairs and Maintenance','expense','expense','repairs','21',false,false,NULL),
   ('6500','Supplies','expense','expense','supplies','22',false,false,'default_expense'),
   ('6550','Taxes and Licenses','expense','expense','taxes_licenses','23',false,false,NULL),
   ('6600','Travel','expense','expense','travel','24a',false,false,NULL),
   ('6650','Meals','expense','expense','meals','24b',false,false,NULL),
   ('6700','Utilities','expense','expense','utilities','25',false,false,NULL),
   ('6750','Wages','expense','expense','wages','26',false,false,'wages_expense'),
   ('6800','Bank Service Charges','expense','expense','bank_charges','27a',false,false,'bank_service_charges'),
   ('6850','Chargeback Losses','expense','expense','chargebacks','27a',false,false,'chargeback_loss'),
   ('6900','Uncategorized Expense','expense','expense','uncategorized','27a',false,false,'uncategorized_expense'),
   ('6990','Rounding and FX Gain/Loss','expense','other_expense','fx','27a',false,false,'rounding')
  ) AS t(code,name,typ,sub,detail,line,ctrl,recon,role) LOOP
    SELECT id INTO v_id FROM acct_chart_of_accounts WHERE tenant_id = p_tenant_id AND code = r.code;
    IF v_id IS NULL THEN
      INSERT INTO acct_chart_of_accounts(tenant_id, entity_id, code, name, account_type, normal_balance, subtype, detail_type,
             is_control_account, is_reconcilable, is_system, tax_line_id, metadata, is_bank_feed)
      VALUES (p_tenant_id, p_entity_id, r.code, r.name, r.typ,
              CASE WHEN r.typ IN ('asset','expense','contra_equity') OR r.role IN ('sales_returns','discounts_given') THEN 'debit' ELSE 'credit' END,
              r.sub, r.detail, r.ctrl, r.recon, r.role IS NOT NULL,
              (SELECT id FROM acct_tax_lines WHERE tenant_id IS NULL AND form = CASE WHEN r.line IN ('BS') THEN 'Balance sheet' ELSE 'Schedule C' END AND line = r.line LIMIT 1),
              '{}'::jsonb, r.sub IN ('bank','credit_card','line_of_credit'))
      RETURNING id INTO v_id;
      n := n + 1;
    END IF;
    IF r.role IS NOT NULL THEN
      INSERT INTO acct_account_roles(tenant_id, entity_id, role, account_id) VALUES (p_tenant_id, p_entity_id, r.role, v_id)
      ON CONFLICT (tenant_id, entity_id, role) DO NOTHING;
    END IF;
  END LOOP;
  -- the contra-equity owner's draw normally carries a debit balance
  UPDATE acct_chart_of_accounts SET normal_balance = 'debit' WHERE tenant_id = p_tenant_id AND code = '3100';
  RETURN n;
END $$;

-- @seq 305
CREATE FUNCTION public.acct_seed_tax_mississippi(p_tenant_id uuid, p_entity_id uuid, p_register boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_us uuid; v_ms uuid; v_tup uuid; v_jxn uuid; v_liab uuid; v_c uuid; y int;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  v_liab := acct_role_account(p_tenant_id, p_entity_id, 'sales_tax_payable');
  INSERT INTO acct_tax_jurisdictions(tenant_id, code, name, country_code, level) VALUES (p_tenant_id,'US','United States','US','country')
    ON CONFLICT (tenant_id, code) DO UPDATE SET level = 'country' RETURNING id INTO v_us;
  INSERT INTO acct_tax_jurisdictions(tenant_id, code, name, country_code, state_code, level, parent_id, authority_name, filing_frequency)
    VALUES (p_tenant_id,'US-MS','Mississippi','US','MS','state',v_us,'Mississippi Department of Revenue','monthly')
    ON CONFLICT (tenant_id, code) DO UPDATE SET parent_id = v_us, level = 'state' RETURNING id INTO v_ms;
  INSERT INTO acct_tax_jurisdictions(tenant_id, code, name, country_code, state_code, locality, level, parent_id, authority_name)
    VALUES (p_tenant_id,'US-MS-TUPELO','Tupelo','US','MS','Tupelo','city',v_ms,'Mississippi Department of Revenue')
    ON CONFLICT (tenant_id, code) DO UPDATE SET parent_id = v_ms RETURNING id INTO v_tup;
  INSERT INTO acct_tax_jurisdictions(tenant_id, code, name, country_code, state_code, locality, level, parent_id, authority_name)
    VALUES (p_tenant_id,'US-MS-JACKSON','Jackson','US','MS','Jackson','city',v_ms,'Mississippi Department of Revenue')
    ON CONFLICT (tenant_id, code) DO UPDATE SET parent_id = v_ms RETURNING id INTO v_jxn;
  -- Corinth: state rate only (no city levy) -> use the US-MS jurisdiction directly

  IF NOT EXISTS (SELECT 1 FROM acct_tax_codes WHERE tenant_id = p_tenant_id AND code = 'MS-STATE') THEN
    INSERT INTO acct_tax_codes(tenant_id, jurisdiction_id, code, name, tax_type, rate, recoverable_percent, payable_account_id, effective_from, is_compound, is_active)
    VALUES (p_tenant_id, v_ms, 'MS-STATE', 'Mississippi sales tax 7%', 'sales', 0.07, 0, v_liab, '2000-01-01', false, true),
           (p_tenant_id, v_tup, 'MS-TUPELO', 'Tupelo local 0.25%', 'sales', 0.0025, 0, v_liab, '2000-01-01', false, true),
           (p_tenant_id, v_jxn, 'MS-JACKSON', 'Jackson infrastructure 1%', 'sales', 0.01, 0, v_liab, '2000-01-01', false, true);
  END IF;

  IF NOT EXISTS (SELECT 1 FROM acct_tax_taxability_rules WHERE tenant_id = p_tenant_id AND jurisdiction_id = v_ms) THEN
    INSERT INTO acct_tax_taxability_rules(tenant_id, jurisdiction_id, tax_category, treatment, rate_override, max_unit_price,
           effective_from, effective_to, priority, name, legal_reference)
    VALUES
     (p_tenant_id, v_ms, 'grocery', 'reduced', 0.05, NULL, '2025-07-01', NULL, 100, 'MS groceries reduced rate 5%', 'Miss. Code 27-65-17; DOR sales tax rates'),
     (p_tenant_id, v_ms, 'services_nontaxable', 'exempt', NULL, NULL, '2000-01-01', NULL, 100, 'Non-taxable service', NULL),
     (p_tenant_id, v_ms, 'gift_card', 'exempt', NULL, NULL, '2000-01-01', NULL, 100, 'Stored value is not a retail sale', NULL),
     (p_tenant_id, v_ms, 'exempt', 'exempt', NULL, NULL, '2000-01-01', NULL, 100, 'Exempt by law', NULL);
    -- sales-tax holiday: per item, unit price strictly below $100
    FOREACH y IN ARRAY ARRAY[2026] LOOP
      INSERT INTO acct_tax_taxability_rules(tenant_id, jurisdiction_id, tax_category, treatment, max_unit_price, effective_from, effective_to, priority, name, legal_reference)
      SELECT p_tenant_id, v_ms, c, 'exempt', 100, make_date(y,7,10), make_date(y,7,12), 500,
             'MS Sales Tax Holiday ' || y || ' (' || c || ' under $100)', 'MS DOR 2026 Sales Tax Holiday guide'
        FROM unnest(ARRAY['clothing','footwear','school_supplies']) c;
    END LOOP;
  END IF;

  IF p_register AND NOT EXISTS (SELECT 1 FROM acct_tax_nexus WHERE entity_id = p_entity_id AND jurisdiction_id = v_ms) THEN
    INSERT INTO acct_tax_nexus(tenant_id, entity_id, jurisdiction_id, nexus_type, collect_tax, effective_from, filing_frequency)
    VALUES (p_tenant_id, p_entity_id, v_ms, 'physical', true, '2000-01-01', 'monthly');
  END IF;
  RETURN v_ms;
END $_$;

-- @seq 306
CREATE FUNCTION public.acct_seed_tax_us_state(p_tenant_id uuid, p_entity_id uuid, p_state text, p_register boolean DEFAULT false, p_nexus_type text DEFAULT 'economic'::text, p_effective_from date DEFAULT CURRENT_DATE, p_registration_number text DEFAULT NULL::text, p_filing_frequency text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s tax_us_states%ROWTYPE; v_us uuid; v_st uuid; v_liab uuid;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  SELECT * INTO s FROM tax_us_states WHERE state_code = upper(p_state);
  IF NOT FOUND THEN RAISE EXCEPTION 'Unknown US state code %', p_state; END IF;
  IF upper(p_state) = 'MS' THEN RETURN acct_seed_tax_mississippi(p_tenant_id, p_entity_id, p_register); END IF;
  v_liab := acct_role_account(p_tenant_id, p_entity_id, 'sales_tax_payable');
  INSERT INTO acct_tax_jurisdictions(tenant_id, code, name, country_code, level) VALUES (p_tenant_id,'US','United States','US','country')
    ON CONFLICT (tenant_id, code) DO UPDATE SET level = 'country' RETURNING id INTO v_us;
  INSERT INTO acct_tax_jurisdictions(tenant_id, code, name, country_code, state_code, level, parent_id, filing_frequency, registration_number, metadata)
    VALUES (p_tenant_id, 'US-' || s.state_code, s.name, 'US', s.state_code, 'state', v_us, p_filing_frequency, p_registration_number,
            jsonb_build_object('sst_status', s.sst_status, 'rate_source', s.rate_source_url))
    ON CONFLICT (tenant_id, code) DO UPDATE SET parent_id = v_us, level = 'state',
      filing_frequency = coalesce(EXCLUDED.filing_frequency, acct_tax_jurisdictions.filing_frequency),
      registration_number = coalesce(EXCLUDED.registration_number, acct_tax_jurisdictions.registration_number)
    RETURNING id INTO v_st;
  IF s.has_state_sales_tax AND NOT EXISTS (SELECT 1 FROM acct_tax_codes WHERE tenant_id = p_tenant_id AND code = s.state_code || '-STATE') THEN
    INSERT INTO acct_tax_codes(tenant_id, jurisdiction_id, code, name, tax_type, rate, recoverable_percent, payable_account_id, effective_from, is_compound, is_active)
    VALUES (p_tenant_id, v_st, s.state_code || '-STATE', s.name || ' state sales tax ' || rtrim(rtrim(to_char(s.state_rate*100,'FM990.000'),'0'),'.') || '%',
            'sales', s.state_rate, 0, v_liab, s.rate_as_of, false, true);
  END IF;
  IF p_register AND NOT EXISTS (SELECT 1 FROM acct_tax_nexus WHERE entity_id = p_entity_id AND jurisdiction_id = v_st AND effective_from = p_effective_from) THEN
    INSERT INTO acct_tax_nexus(tenant_id, entity_id, jurisdiction_id, nexus_type, collect_tax, registration_number, registered_on, effective_from,
                               filing_frequency, economic_sales_threshold, economic_txn_threshold)
    VALUES (p_tenant_id, p_entity_id, v_st, p_nexus_type, true, p_registration_number, CASE WHEN p_registration_number IS NOT NULL THEN p_effective_from END,
            p_effective_from, p_filing_frequency, s.econ_sales_threshold, s.econ_txn_threshold);
    UPDATE tax_nexus_alerts SET status = 'resolved', resolution = 'registered', last_checked_at = now()
     WHERE tenant_id = p_tenant_id AND entity_id = p_entity_id AND state_code = s.state_code;
  END IF;
  RETURN v_st;
END $$;

-- @seq 307
CREATE FUNCTION public.acct_send_invoice(p_invoice_id uuid, p_reminder boolean DEFAULT false, p_message text DEFAULT NULL::text, p_pay_url_base text DEFAULT NULL::text, p_pdf_path text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE iv acct_ar_invoices%ROWTYPE; v_to text[]; v_name text; v_mail uuid; v_subject text; v_base text; v_url text;
BEGIN
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
  PERFORM acct_assert_access(iv.tenant_id);
  IF iv.status = 'void' THEN RAISE EXCEPTION 'Invoice is void'; END IF;
  IF iv.posted_journal_id IS NULL THEN PERFORM acct_post_invoice(iv.id); SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id; END IF;
  IF p_reminder AND iv.sent_at IS NULL THEN RAISE EXCEPTION 'Send the invoice before sending a reminder'; END IF;
  IF p_reminder AND iv.open_balance <= 0 THEN RAISE EXCEPTION 'Invoice % is already paid', iv.invoice_number; END IF;
  SELECT coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)),''), c.company_name, c.email) INTO v_name FROM crm_customers c WHERE c.id = iv.customer_id;
  v_to := array_remove(ARRAY[coalesce(iv.customer_email, (SELECT email FROM crm_customers WHERE id = iv.customer_id))], NULL);
  IF cardinality(v_to) = 0 THEN RAISE EXCEPTION 'Customer has no email address'; END IF;
  v_base := coalesce(p_pay_url_base, nullif(current_setting('app.public_base_url', true), ''));
  v_url := CASE WHEN v_base IS NOT NULL AND iv.public_token IS NOT NULL THEN rtrim(v_base, '/') || '/pay/' || iv.public_token END;
  v_subject := CASE WHEN p_reminder THEN 'Reminder: invoice ' ELSE coalesce(iv.email_subject || ' ', 'Invoice ') END || iv.invoice_number
               || ' - ' || to_char(iv.open_balance, 'FM999,999,990.00') || ' ' || iv.currency || ' due ' || to_char(iv.due_date, 'Mon DD, YYYY');
  v_mail := email_enqueue(iv.tenant_id, 'invoice:' || iv.id || ':' || CASE WHEN p_reminder THEN 'r' || (iv.reminder_count + 1) ELSE 's' || (iv.resent_count + 1) END,
              app__default_from(iv.tenant_id), v_to || coalesce(iv.cc_emails, '{}'::text[]), v_subject,
              '<p>Hello ' || coalesce(v_name, '') || ',</p><p>' || coalesce(p_message, iv.message_to_customer, iv.email_body,
                 'Invoice ' || iv.invoice_number || ' for ' || to_char(iv.total, 'FM999,999,990.00') || ' is due ' || to_char(iv.due_date, 'Mon DD, YYYY') || '.')
              || '</p>' || coalesce('<p><a href="' || v_url || '">View and pay</a></p>', ''),
              NULL, 'transactional', 'acct_ar_invoices', iv.id,
              CASE WHEN p_pdf_path IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('path', p_pdf_path, 'filename', iv.invoice_number || '.pdf')) END,
              NULL, iv.customer_id);
  IF p_reminder THEN
    UPDATE acct_ar_invoices SET reminder_count = reminder_count + 1, last_reminder_at = now() WHERE id = iv.id;
  ELSE
    UPDATE acct_ar_invoices SET sent_at = coalesce(sent_at, now()), resent_count = CASE WHEN sent_at IS NULL THEN resent_count ELSE resent_count + 1 END,
           status = CASE WHEN status IN ('draft','open') THEN 'sent' ELSE status END WHERE id = iv.id;
  END IF;
  RETURN v_mail;
END $$;

-- @seq 308
CREATE FUNCTION public.acct_send_statement(p_statement_id uuid, p_reminder boolean DEFAULT false, p_message text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s acct_customer_statements%ROWTYPE; v_email text; v_name text; v_mail uuid; v_subject text;
BEGIN
  SELECT * INTO s FROM acct_customer_statements WHERE id = p_statement_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Statement not found'; END IF;
  PERFORM acct_assert_access(s.tenant_id);
  IF s.status = 'void' THEN RAISE EXCEPTION 'Statement is void'; END IF;
  IF p_reminder AND s.sent_at IS NULL THEN RAISE EXCEPTION 'Send the statement before sending a reminder'; END IF;
  SELECT c.email, coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)),''), c.email) INTO v_email, v_name FROM crm_customers c WHERE c.id = s.customer_id;
  IF v_email IS NULL THEN RAISE EXCEPTION 'Customer has no email address'; END IF;
  v_subject := CASE WHEN p_reminder THEN 'Reminder: statement ' ELSE 'Statement ' END || s.statement_number
               || ' - balance ' || to_char(s.closing_balance, 'FM999,999,990.00');
  v_mail := email_enqueue(s.tenant_id, 'statement:' || s.id || ':' || CASE WHEN p_reminder THEN 'r' || (s.reminder_count + 1) ELSE 'send' END,
              app__default_from(s.tenant_id), ARRAY[v_email], v_subject,
              '<p>Hello ' || coalesce(v_name,'') || ',</p><p>' || coalesce(p_message, 'Your statement for ' || to_char(s.period_start,'Mon DD, YYYY') || ' to '
                || to_char(s.period_end,'Mon DD, YYYY') || ' shows a balance of ' || to_char(s.closing_balance,'FM999,999,990.00') || '.') || '</p>'
                || coalesce('<p><a href="' || s.document_url || '">View statement (PDF)</a></p>', ''),
              NULL, 'transactional', 'acct_customer_statements', s.id,
              CASE WHEN s.document_url IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('path', s.document_url, 'filename', s.statement_number || '.pdf')) END,
              NULL, s.customer_id);
  IF p_reminder THEN
    UPDATE acct_customer_statements SET reminder_count = reminder_count + 1, last_reminder_at = now(), email_outbox_id = v_mail, updated_at = now() WHERE id = s.id;
  ELSE
    UPDATE acct_customer_statements SET status = 'sent', sent_at = now(), email_outbox_id = v_mail, updated_at = now() WHERE id = s.id;
  END IF;
  RETURN v_mail;
END $$;

-- @seq 309
CREATE FUNCTION public.acct_send_statement_batch(p_batch_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_statement_batches%ROWTYPE; s record; n int := 0;
BEGIN
  SELECT * INTO b FROM acct_statement_batches WHERE id = p_batch_id FOR UPDATE;
  PERFORM acct_assert_access(b.tenant_id);
  IF b.status = 'draft' THEN RAISE EXCEPTION 'Generate the batch before sending'; END IF;
  FOR s IN SELECT st.id FROM acct_customer_statements st JOIN crm_customers c ON c.id = st.customer_id
            WHERE st.batch_id = b.id AND st.status = 'generated' AND c.email IS NOT NULL LOOP
    PERFORM acct_send_statement(s.id); n := n + 1;
  END LOOP;
  UPDATE acct_statement_batches SET status = 'sent', sent_at = now() WHERE id = b.id;
  RETURN n;
END $$;

-- @seq 310
CREATE FUNCTION public.acct_set_opening_balance(p_bank_account_id uuid, p_amount numeric, p_as_of date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_bank_accounts%ROWTYPE; v_obe uuid; v_liab boolean; v_je uuid;
BEGIN
  SELECT * INTO b FROM acct_bank_accounts WHERE id = p_bank_account_id;
  PERFORM acct_assert_access(b.tenant_id);
  v_obe := acct_role_account(b.tenant_id, b.entity_id, 'opening_balance_equity');
  v_liab := b.account_kind IN ('credit_card','line_of_credit','loan');
  -- for liabilities p_amount = amount owed
  v_je := acct_post_entry(b.tenant_id, b.entity_id, p_as_of, jsonb_build_array(
            jsonb_build_object('account_id', b.gl_account_id, 'debit', CASE WHEN v_liab THEN -p_amount ELSE p_amount END, 'description', 'Opening balance'),
            jsonb_build_object('account_id', v_obe, 'credit', CASE WHEN v_liab THEN -p_amount ELSE p_amount END, 'description', 'Opening balance ' || b.name)),
          'opening_balance', b.id::text, 'OPEN-' || b.name, 'Opening balance', 'opening:' || b.id, NULL, NULL, NULL, false, false, 'acct_bank_accounts', b.id);
  UPDATE acct_bank_accounts SET opening_balance = p_amount, opening_balance_date = p_as_of WHERE id = b.id;
  -- the opening line is history, not something to reconcile
  UPDATE acct_journal_lines SET cleared_status = 'reconciled', cleared_at = now() WHERE journal_entry_id = v_je AND account_id = b.gl_account_id;
  RETURN v_je;
END $$;

-- @seq 311
CREATE FUNCTION public.acct_set_period_status(p_period_id uuid, p_status text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p acct_periods%ROWTYPE; n int;
BEGIN
  SELECT * INTO p FROM acct_periods WHERE id = p_period_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Period not found'; END IF;
  PERFORM acct_assert_access(p.tenant_id);
  IF p_status NOT IN ('open','soft_closed','closed','locked') THEN RAISE EXCEPTION 'Invalid period status %', p_status; END IF;
  IF p.status = 'locked' THEN RAISE EXCEPTION 'Locked periods cannot be reopened'; END IF;
  IF p_status IN ('closed','locked') THEN
    SELECT count(*) INTO n FROM acct_journal_entries WHERE period_id = p.id AND status IN ('draft','approved');
    IF n > 0 THEN RAISE EXCEPTION 'Period % has % unposted journal entries', p.name, n; END IF;
    IF EXISTS (SELECT 1 FROM acct_periods WHERE book_id = p.book_id AND end_date < p.start_date AND status IN ('open','soft_closed')) THEN
      RAISE EXCEPTION 'Close earlier periods first';
    END IF;
  END IF;
  IF p_status = 'open' AND EXISTS (SELECT 1 FROM acct_periods WHERE book_id = p.book_id AND start_date > p.end_date AND status = 'locked') THEN
    RAISE EXCEPTION 'A later period is locked; this period cannot be reopened';
  END IF;
  UPDATE acct_periods SET status = p_status,
         closed_at = CASE WHEN p_status IN ('closed','locked') THEN now() END,
         closed_by = CASE WHEN p_status IN ('closed','locked') THEN auth.uid() END
   WHERE id = p.id;
END $$;

-- @seq 312
CREATE FUNCTION public.acct_set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;

-- @seq 313
CREATE FUNCTION public.acct_setup_channel(p_tenant_id uuid, p_channel text, p_payout_bank_account_id uuid DEFAULT NULL::uuid, p_entity_id uuid DEFAULT NULL::uuid, p_reserve boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
DECLARE v_e uuid := coalesce(p_entity_id, acct_default_entity(p_tenant_id)); v_ch text := lower(btrim(p_channel));
        v_gl uuid; v_reg uuid; v_id uuid; v_res uuid; v_fee uuid; v_ad uuid;
BEGIN
  PERFORM platform__assert_tenant_admin(p_tenant_id);
  IF v_ch IS NULL OR v_ch !~ '^[a-z0-9_]+$' THEN RAISE EXCEPTION 'Channel code must be lowercase letters, digits or underscore (etsy, amazon, tiktok_shop...)'; END IF;
  IF p_payout_bank_account_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM acct_bank_accounts WHERE id = p_payout_bank_account_id AND tenant_id = p_tenant_id) THEN
    RAISE EXCEPTION 'Payout account is not a register of this company';
  END IF;
  SELECT id INTO v_id FROM acct_channel_accounts WHERE tenant_id = p_tenant_id AND entity_id = v_e AND channel = v_ch;
  IF v_id IS NOT NULL THEN
    UPDATE acct_channel_accounts SET payout_bank_account_id = coalesce(p_payout_bank_account_id, payout_bank_account_id), is_active = true, updated_at = now()
     WHERE id = v_id;
    RETURN v_id;
  END IF;
  v_gl := acct__ensure_account(p_tenant_id, v_e, 'CLR-' || upper(v_ch), initcap(replace(v_ch,'_',' ')) || ' Clearing', 'asset', 'debit',
                               'other_current_asset', 'processor_clearing', NULL, 'operating');
  INSERT INTO acct_bank_accounts(tenant_id, entity_id, name, account_type, currency, gl_account_id, account_kind, is_active, metadata)
  VALUES (p_tenant_id, v_e, initcap(replace(v_ch,'_',' ')) || ' Clearing', 'payment_processor', 'USD', v_gl, 'payment_processor', true,
          jsonb_build_object('channel', v_ch))
  RETURNING id INTO v_reg;
  v_fee := acct_role_account(p_tenant_id, v_e, 'processor_fees', false);
  SELECT id INTO v_ad FROM acct_chart_of_accounts WHERE tenant_id = p_tenant_id AND entity_id = v_e AND code = '6000' AND account_type = 'expense';
  IF p_reserve THEN
    v_res := acct__ensure_account(p_tenant_id, v_e, 'RSV-' || upper(v_ch), initcap(replace(v_ch,'_',' ')) || ' Reserve', 'asset', 'debit',
                                  'other_current_asset', 'processor_reserve', NULL, 'operating');
  END IF;
  INSERT INTO acct_channel_accounts(tenant_id, entity_id, channel, clearing_register_id, payout_bank_account_id, fee_account_id, advertising_account_id, reserve_account_id)
  VALUES (p_tenant_id, v_e, v_ch, v_reg, p_payout_bank_account_id, v_fee, v_ad, v_res)
  RETURNING id INTO v_id;
  RETURN v_id;
END $_$;

-- @seq 314
CREATE FUNCTION public.acct_signoff_close_task(p_task_id uuid, p_approve boolean DEFAULT true, p_note text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_close_tasks%ROWTYPE;
BEGIN
  SELECT * INTO t FROM acct_close_tasks WHERE id = p_task_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Task not found'; END IF;
  PERFORM acct_assert_access(t.tenant_id);
  IF t.status <> 'ready_for_review' THEN RAISE EXCEPTION 'Task is not waiting for review (status %)', t.status; END IF;
  IF auth.uid() IS NOT NULL AND t.completed_by = auth.uid() THEN RAISE EXCEPTION 'The preparer cannot sign off their own task'; END IF;
  IF t.reviewer_id IS NOT NULL AND auth.uid() IS NOT NULL AND auth.uid() <> t.reviewer_id THEN RAISE EXCEPTION 'Only the assigned reviewer can sign off'; END IF;
  UPDATE acct_close_tasks SET status = CASE WHEN p_approve THEN 'done' ELSE 'in_progress' END,
         signed_off_by = CASE WHEN p_approve THEN auth.uid() END, signed_off_at = CASE WHEN p_approve THEN now() END, updated_at = now()
   WHERE id = t.id;
  IF p_note IS NOT NULL OR NOT p_approve THEN
    INSERT INTO acct_close_task_comments(tenant_id, task_id, author_id, body)
    VALUES (t.tenant_id, t.id, auth.uid(), coalesce(p_note, 'Sent back for changes'));
  END IF;
  RETURN CASE WHEN p_approve THEN 'done' ELSE 'in_progress' END;
END $$;

-- @seq 319
CREATE FUNCTION public.acct_start_reconciliation(p_bank_account_id uuid, p_statement_end_date date, p_statement_ending_balance numeric, p_service_charge numeric DEFAULT 0, p_service_charge_date date DEFAULT NULL::date, p_service_charge_account_id uuid DEFAULT NULL::uuid, p_interest_earned numeric DEFAULT 0, p_interest_date date DEFAULT NULL::date, p_interest_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_bank_accounts%ROWTYPE; v_id uuid; v_begin numeric; v_je uuid; v_acct uuid; v_liab boolean;
BEGIN
  SELECT * INTO b FROM acct_bank_accounts WHERE id = p_bank_account_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Register not found'; END IF;
  PERFORM acct_assert_access(b.tenant_id);
  IF EXISTS (SELECT 1 FROM acct_reconciliations WHERE bank_account_id = b.id AND status IN ('open','in_progress','reopened')) THEN
    RAISE EXCEPTION 'A reconciliation is already in progress for %; finish or delete it first', b.name; END IF;
  IF EXISTS (SELECT 1 FROM acct_reconciliations WHERE bank_account_id = b.id AND status = 'reconciled' AND as_of_date >= p_statement_end_date) THEN
    RAISE EXCEPTION 'Statement date must be after the last reconciled statement'; END IF;
  v_liab := b.account_kind IN ('credit_card','line_of_credit','loan');
  -- beginning balance = last reconciled ending balance, else the sum of lines already marked reconciled (e.g. opening balance)
  SELECT statement_balance INTO v_begin FROM acct_reconciliations WHERE bank_account_id = b.id AND status = 'reconciled' ORDER BY as_of_date DESC LIMIT 1;
  IF v_begin IS NULL THEN
    SELECT CASE WHEN v_liab THEN -1 ELSE 1 END * coalesce(sum(debit - credit),0) INTO v_begin
      FROM acct_journal_lines WHERE account_id = b.gl_account_id AND cleared_status = 'reconciled';
  END IF;
  INSERT INTO acct_reconciliations(tenant_id, entity_id, bank_account_id, as_of_date, statement_balance, gl_balance, beginning_balance, status, prepared_by,
         service_charge_amount, service_charge_date, interest_earned_amount, interest_earned_date)
  VALUES (b.tenant_id, b.entity_id, b.id, p_statement_end_date, p_statement_ending_balance, 0, v_begin, 'in_progress', auth.uid(),
          coalesce(p_service_charge,0), coalesce(p_service_charge_date, p_statement_end_date), coalesce(p_interest_earned,0), coalesce(p_interest_date, p_statement_end_date))
  RETURNING id INTO v_id;

  IF coalesce(p_service_charge,0) > 0 THEN
    v_acct := coalesce(p_service_charge_account_id, acct_role_account(b.tenant_id, b.entity_id, 'bank_service_charges'));
    v_je := acct_post_entry(b.tenant_id, b.entity_id, coalesce(p_service_charge_date, p_statement_end_date), jsonb_build_array(
              jsonb_build_object('account_id', v_acct, 'debit', p_service_charge, 'description', 'Service charge'),
              jsonb_build_object('account_id', b.gl_account_id, 'credit', p_service_charge, 'description', 'Service charge')),
            'bank', v_id::text, 'SVC', 'Bank service charge (reconciliation)', 'recsvc:' || v_id, NULL, NULL, NULL, false, false, 'acct_reconciliations', v_id);
    UPDATE acct_journal_lines SET cleared_status = 'cleared', reconciliation_id = v_id, cleared_at = now() WHERE journal_entry_id = v_je AND account_id = b.gl_account_id;
    UPDATE acct_reconciliations SET service_charge_account_id = v_acct, service_charge_journal_id = v_je WHERE id = v_id;
  END IF;
  IF coalesce(p_interest_earned,0) > 0 THEN
    v_acct := coalesce(p_interest_account_id, acct_role_account(b.tenant_id, b.entity_id, CASE WHEN v_liab THEN 'interest_expense' ELSE 'interest_income' END));
    -- assets: interest earned increases the balance; cards/LOC: "interest" is a finance charge that increases the amount owed
    v_je := acct_post_entry(b.tenant_id, b.entity_id, coalesce(p_interest_date, p_statement_end_date), jsonb_build_array(
              jsonb_build_object('account_id', b.gl_account_id, 'debit', CASE WHEN v_liab THEN 0 ELSE p_interest_earned END,
                                 'credit', CASE WHEN v_liab THEN p_interest_earned ELSE 0 END, 'description', 'Interest'),
              jsonb_build_object('account_id', v_acct, 'debit', CASE WHEN v_liab THEN p_interest_earned ELSE 0 END,
                                 'credit', CASE WHEN v_liab THEN 0 ELSE p_interest_earned END, 'description', 'Interest')),
            'bank', v_id::text, 'INT', 'Interest (reconciliation)', 'recint:' || v_id, NULL, NULL, NULL, false, false, 'acct_reconciliations', v_id);
    UPDATE acct_journal_lines SET cleared_status = 'cleared', reconciliation_id = v_id, cleared_at = now() WHERE journal_entry_id = v_je AND account_id = b.gl_account_id;
    UPDATE acct_reconciliations SET interest_account_id = v_acct, interest_journal_id = v_je WHERE id = v_id;
  END IF;
  -- anything already cleared by the bank feed up to the statement date is pre-ticked
  UPDATE acct_journal_lines l SET reconciliation_id = v_id
    FROM acct_journal_entries e
   WHERE e.id = l.journal_entry_id AND l.account_id = b.gl_account_id AND l.cleared_status = 'cleared'
     AND l.reconciliation_id IS NULL AND e.posting_date <= p_statement_end_date;
  RETURN v_id;
END $$;

-- @seq 320
CREATE FUNCTION public.acct_submit_bill(p_bill_id uuid, p_stage text DEFAULT 'bill'::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE b acct_ap_bills%ROWTYPE; w acct_workflows%ROWTYPE; v_appr uuid; i int := 0;
BEGIN
  SELECT * INTO b FROM acct_ap_bills WHERE id = p_bill_id FOR UPDATE;
  PERFORM acct_assert_access(b.tenant_id);
  SELECT * INTO w FROM acct_workflows
   WHERE tenant_id = b.tenant_id AND is_active AND entity_type = CASE p_stage WHEN 'bill' THEN 'bill' ELSE 'bill_payment' END
     AND coalesce(threshold_amount, 0) <= b.total
     AND (NOT rules ? 'vendor_ids' OR rules->'vendor_ids' ? b.vendor_id::text)
   ORDER BY threshold_amount DESC NULLS LAST LIMIT 1;
  DELETE FROM acct_ap_approvals WHERE bill_id = b.id AND stage = p_stage AND status = 'pending';
  IF w.id IS NULL THEN
    IF p_stage = 'bill' THEN UPDATE acct_ap_bills SET approval_status = 'not_required', status = CASE WHEN status='draft' THEN 'approved' ELSE status END WHERE id = b.id;
    ELSE UPDATE acct_ap_bills SET payment_approval_status = 'not_required' WHERE id = b.id; END IF;
    RETURN 'not_required';
  END IF;
  FOR v_appr IN SELECT (jsonb_array_elements_text(w.rules->'approvers'))::uuid LOOP
    i := i + 1;
    INSERT INTO acct_ap_approvals(tenant_id, bill_id, approver_id, sequence_no, status, stage) VALUES (b.tenant_id, b.id, v_appr, i, 'pending', p_stage);
  END LOOP;
  IF i = 0 THEN RAISE EXCEPTION 'Approval workflow % has no approvers', w.name; END IF;
  IF p_stage = 'bill' THEN UPDATE acct_ap_bills SET approval_status = 'pending', status = 'pending_approval' WHERE id = b.id;
  ELSE UPDATE acct_ap_bills SET payment_approval_status = 'pending' WHERE id = b.id; END IF;
  RETURN 'pending';
END $$;

-- @seq 321
CREATE FUNCTION public.acct_suggest_coding(p_bank_txn_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_bank_transactions%ROWTYPE; d text; a record; h record; v_total int; v record; v_sign int;
BEGIN
  SELECT * INTO t FROM acct_bank_transactions WHERE id = p_bank_txn_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Bank transaction not found'; END IF;
  PERFORM acct_assert_access(t.tenant_id);
  d := coalesce(t.normalized_descriptor, acct_normalize_descriptor(coalesce(t.payee, t.description)));
  v_sign := sign(t.amount);
  IF d IS NULL THEN RETURN jsonb_build_object('confidence', NULL, 'source', 'none'); END IF;

  -- 1. alias
  SELECT va.*, coalesce(va.account_id, ve.default_expense_account_id) AS acct INTO a
    FROM acct_vendor_aliases va LEFT JOIN acct_vendors ve ON ve.id = va.vendor_id
   WHERE va.tenant_id = t.tenant_id
     AND CASE va.match_type WHEN 'equals' THEN d = lower(va.alias) WHEN 'starts_with' THEN d LIKE lower(va.alias) || '%'
              ELSE strpos(d, lower(va.alias)) > 0 END
   ORDER BY length(va.alias) DESC LIMIT 1;
  IF FOUND AND a.acct IS NOT NULL THEN
    RETURN jsonb_build_object('account_id', a.acct, 'vendor_id', a.vendor_id, 'customer_id', a.customer_id,
      'confidence', CASE WHEN a.account_id IS NOT NULL THEN 'high' ELSE 'medium' END, 'source', 'alias', 'alias', a.alias);
  END IF;

  -- 2. exact history (posted lines, same direction)
  SELECT count(*) INTO v_total FROM acct_bank_transactions x
   WHERE x.tenant_id = t.tenant_id AND x.id <> t.id AND x.review_status = 'posted' AND x.normalized_descriptor = d
     AND sign(x.amount) = v_sign AND x.category_account_id IS NOT NULL;
  IF v_total > 0 THEN
    SELECT x.category_account_id AS acct, count(*) AS n, max(x.payee_vendor_id::text)::uuid AS vendor_id, max(x.payee_customer_id::text)::uuid AS customer_id
      INTO h FROM acct_bank_transactions x
     WHERE x.tenant_id = t.tenant_id AND x.id <> t.id AND x.review_status = 'posted' AND x.normalized_descriptor = d
       AND sign(x.amount) = v_sign AND x.category_account_id IS NOT NULL
     GROUP BY x.category_account_id ORDER BY count(*) DESC, max(x.transaction_date) DESC LIMIT 1;
    RETURN jsonb_build_object('account_id', h.acct, 'vendor_id', h.vendor_id, 'customer_id', h.customer_id,
      'confidence', CASE WHEN h.n >= 3 AND h.n::numeric / v_total >= 0.8 THEN 'high'
                         WHEN h.n::numeric / v_total >= 0.6 THEN 'medium' ELSE 'low' END,
      'source', 'history', 'times_used', h.n, 'of', v_total);
  END IF;

  -- 3. similar descriptors
  SELECT x.category_account_id AS acct, count(*) AS n, max(similarity(x.normalized_descriptor, d)) AS sim,
         max(x.payee_vendor_id::text)::uuid AS vendor_id
    INTO h FROM acct_bank_transactions x
   WHERE x.tenant_id = t.tenant_id AND x.id <> t.id AND x.review_status = 'posted' AND x.category_account_id IS NOT NULL
     AND sign(x.amount) = v_sign AND x.normalized_descriptor % d
   GROUP BY x.category_account_id ORDER BY max(similarity(x.normalized_descriptor, d)) DESC, count(*) DESC LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('account_id', h.acct, 'vendor_id', h.vendor_id,
      'confidence', CASE WHEN h.sim >= 0.6 THEN 'medium' ELSE 'low' END, 'source', 'similar', 'similarity', round(h.sim::numeric, 2));
  END IF;

  -- 4. vendor name
  SELECT ve.id, ve.default_expense_account_id AS acct, similarity(lower(coalesce(ve.display_name, ve.legal_name)), d) AS sim INTO v
    FROM acct_vendors ve
   WHERE ve.tenant_id = t.tenant_id AND ve.is_active AND (lower(coalesce(ve.display_name, ve.legal_name)) % d
          OR strpos(d, lower(coalesce(ve.display_name, ve.legal_name))) > 0)
   ORDER BY 3 DESC LIMIT 1;
  IF FOUND THEN
    RETURN jsonb_build_object('account_id', v.acct, 'vendor_id', v.id,
      'confidence', CASE WHEN v.acct IS NOT NULL AND v.sim >= 0.5 THEN 'medium' ELSE 'low' END, 'source', 'vendor_name', 'similarity', round(v.sim::numeric, 2));
  END IF;
  RETURN jsonb_build_object('confidence', NULL, 'source', 'none');
END $$;

-- @seq 322
CREATE FUNCTION public.acct_sync_erp_order(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_t uuid;
BEGIN
  SELECT tenant_id INTO v_t FROM erp_orders WHERE id = p_order_id;
  PERFORM acct_assert_access(v_t);
  RETURN acct__sync_erp_order(p_order_id);
END $$;

-- @seq 323
CREATE FUNCTION public.acct_sync_pending_orders(p_tenant_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r record; ok int := 0; bad int := 0;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' AND current_user NOT IN ('postgres','supabase_admin','service_role') THEN
    IF p_tenant_id IS NULL THEN RAISE EXCEPTION 'service_role only' USING ERRCODE = '42501'; END IF;
    PERFORM acct_assert_access(p_tenant_id);
  END IF;
  FOR r IN SELECT o.id, o.tenant_id, o.crm_customer_id FROM erp_orders o LEFT JOIN acct_order_postings p ON p.order_id = o.id
            WHERE (p_tenant_id IS NULL OR o.tenant_id = p_tenant_id) AND acct_default_entity(o.tenant_id) IS NOT NULL
              AND (p.order_id IS NULL OR p.last_error IS NOT NULL OR p.last_status IS DISTINCT FROM lower(coalesce(o.status,''))
                   OR (p.sale_journal_id IS NULL AND acct__order_is_fulfilled(o.status)))
              AND NOT EXISTS (SELECT 1 FROM acct_legacy_map m WHERE m.tenant_id = o.tenant_id AND m.legacy_table = 'erp_orders' AND m.legacy_id = o.id::text)
            LIMIT 5000 LOOP
    BEGIN
      PERFORM acct__sync_erp_order(r.id); ok := ok + 1;
    EXCEPTION WHEN OTHERS THEN
      bad := bad + 1;
      INSERT INTO acct_order_postings(order_id, tenant_id, entity_id, party, last_error)
      VALUES (r.id, r.tenant_id, acct_default_entity(r.tenant_id), coalesce(r.crm_customer_id::text, 'order:' || r.id), SQLERRM)
      ON CONFLICT (order_id) DO UPDATE SET last_error = EXCLUDED.last_error, updated_at = now();
    END;
  END LOOP;
  RETURN jsonb_build_object('synced', ok, 'failed', bad);
END $$;

-- @seq 324
CREATE FUNCTION public.acct_system_register(p_tenant_id uuid, p_entity_id uuid, p_kind text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid; v_gl uuid; v_role text; v_name text; v_kind text;
BEGIN
  v_role := CASE p_kind WHEN 'undeposited_funds' THEN 'undeposited_funds' WHEN 'stripe' THEN 'processor_clearing' ELSE NULL END;
  IF v_role IS NULL THEN RAISE EXCEPTION 'Unknown system register %', p_kind; END IF;
  v_gl := acct_role_account(p_tenant_id, p_entity_id, v_role);
  SELECT id INTO v FROM acct_bank_accounts WHERE gl_account_id = v_gl;
  IF v IS NOT NULL THEN RETURN v; END IF;
  v_name := CASE p_kind WHEN 'stripe' THEN 'Stripe Balance' ELSE 'Undeposited Funds' END;
  v_kind := CASE p_kind WHEN 'stripe' THEN 'payment_processor' ELSE 'undeposited_funds' END;
  INSERT INTO acct_bank_accounts(tenant_id, entity_id, name, account_type, account_kind, currency, gl_account_id, provider)
  VALUES (p_tenant_id, p_entity_id, v_name, v_kind, v_kind, 'USD', v_gl, CASE WHEN p_kind = 'stripe' THEN 'stripe' END)
  RETURNING id INTO v;
  RETURN v;
END $$;

-- @seq 326
CREATE FUNCTION public.acct_time_entry_unlink_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  IF NEW.invoiced_line_id IS NULL AND OLD.invoiced_line_id IS NOT NULL AND NEW.status = 'invoiced' THEN
    NEW.status := 'approved'; NEW.invoice_id := NULL;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END $$;

-- @seq 327
CREATE FUNCTION public.acct_transfer_funds(p_from_account_id uuid, p_to_account_id uuid, p_date date, p_amount numeric, p_memo text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f acct_bank_accounts%ROWTYPE; t acct_bank_accounts%ROWTYPE; v_id uuid := gen_random_uuid(); v_je uuid;
BEGIN
  SELECT * INTO f FROM acct_bank_accounts WHERE id = p_from_account_id;
  SELECT * INTO t FROM acct_bank_accounts WHERE id = p_to_account_id;
  IF f.id IS NULL OR t.id IS NULL THEN RAISE EXCEPTION 'Both accounts are required'; END IF;
  IF f.tenant_id <> t.tenant_id OR f.entity_id <> t.entity_id THEN RAISE EXCEPTION 'Transfers must stay within one company'; END IF;
  PERFORM acct_assert_access(f.tenant_id);
  IF f.id = t.id THEN RAISE EXCEPTION 'Pick two different accounts'; END IF;
  IF coalesce(p_amount,0) <= 0 THEN RAISE EXCEPTION 'Transfer amount must be positive'; END IF;
  v_je := acct_post_entry(f.tenant_id, f.entity_id, p_date, jsonb_build_array(
            jsonb_build_object('account_id', acct_bank_gl(t.id), 'debit', p_amount, 'description', coalesce(p_memo, 'Transfer from ' || f.name)),
            jsonb_build_object('account_id', acct_bank_gl(f.id), 'credit', p_amount, 'description', coalesce(p_memo, 'Transfer to ' || t.name))),
          'transfer', v_id::text, NULL, coalesce(p_memo, 'Transfer ' || f.name || ' to ' || t.name), 'transfer:' || v_id,
          NULL, NULL, f.currency, false, false, 'acct_bank_transfers', v_id);
  INSERT INTO acct_bank_transfers(id, tenant_id, entity_id, from_account_id, to_account_id, transfer_date, amount, memo, journal_entry_id)
  VALUES (v_id, f.tenant_id, f.entity_id, f.id, t.id, p_date, p_amount, p_memo, v_je);
  RETURN v_id;
END $$;

-- @seq 328
CREATE FUNCTION public.acct_trial_balance(p_tenant uuid, p_as_of date DEFAULT CURRENT_DATE, p_entity uuid DEFAULT NULL::uuid) RETURNS TABLE(account_id uuid, code text, name text, account_type text, debit numeric, credit numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
#variable_conflict use_column
BEGIN
  PERFORM acct_assert_access(p_tenant);
  RETURN QUERY
  SELECT a.id, a.code, a.name, a.account_type,
         greatest(s.dr - s.cr, 0)::numeric, greatest(s.cr - s.dr, 0)::numeric
    FROM acct__ledger_sums(p_tenant, p_entity, NULL, p_as_of, false) s
    JOIN acct_chart_of_accounts a ON a.id = s.account_id
   WHERE s.dr <> s.cr
   ORDER BY a.code;
END $$;

-- @seq 329
CREATE FUNCTION public.acct_unbilled_time(p_tenant_id uuid, p_through date DEFAULT CURRENT_DATE) RETURNS TABLE(customer_id uuid, customer_name text, entries bigint, hours numeric, amount numeric, oldest date)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  SELECT te.customer_id, coalesce(nullif(btrim(concat_ws(' ', c.first_name, c.last_name)),''), c.email)::text, count(*), sum(te.hours),
         round(sum(te.hours * coalesce(te.rate, it.sales_price, 0)), 2), min(te.work_date)
    FROM acct_time_entries te JOIN crm_customers c ON c.id = te.customer_id LEFT JOIN acct_items it ON it.id = te.item_id
   WHERE te.tenant_id = p_tenant_id AND te.billable AND te.invoiced_line_id IS NULL AND te.status IN ('open','approved') AND te.work_date <= p_through
   GROUP BY 1, 2 ORDER BY 6;
END $$;

-- @seq 330
CREATE FUNCTION public.acct_undo_bank_transaction(p_bank_txn_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t acct_bank_transactions%ROWTYPE;
BEGIN
  SELECT * INTO t FROM acct_bank_transactions WHERE id = p_bank_txn_id FOR UPDATE;
  PERFORM acct_assert_access(t.tenant_id);
  IF EXISTS (SELECT 1 FROM acct_journal_lines WHERE id = t.matched_journal_line_id AND cleared_status = 'reconciled') THEN
    RAISE EXCEPTION 'This transaction is reconciled; undo the reconciliation first'; END IF;
  IF t.review_status = 'posted' THEN
    UPDATE acct_journal_lines SET cleared_status = 'uncleared', cleared_at = NULL WHERE id = t.matched_journal_line_id;
    PERFORM acct_reverse_journal(t.posted_journal_id, t.transaction_date, 'Undo bank feed add');
  ELSIF t.review_status = 'matched' THEN
    UPDATE acct_journal_lines SET cleared_status = 'uncleared', cleared_at = NULL WHERE id = t.matched_journal_line_id;
  END IF;
  UPDATE acct_bank_transactions SET review_status = 'for_review', match_status = 'unmatched', posted_journal_id = NULL,
         matched_journal_line_id = NULL WHERE id = t.id;
END $$;

-- @seq 331
CREATE FUNCTION public.acct_undo_reconciliation(p_reconciliation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_reconciliations%ROWTYPE;
BEGIN
  SELECT * INTO r FROM acct_reconciliations WHERE id = p_reconciliation_id FOR UPDATE;
  PERFORM acct_assert_access(r.tenant_id);
  IF EXISTS (SELECT 1 FROM acct_reconciliations WHERE bank_account_id = r.bank_account_id AND as_of_date > r.as_of_date AND status = 'reconciled') THEN
    RAISE EXCEPTION 'Only the most recent reconciliation can be undone'; END IF;
  UPDATE acct_journal_lines SET cleared_status = 'cleared' WHERE reconciliation_id = r.id;
  UPDATE acct_reconciliations SET status = 'reopened', completed_at = NULL WHERE id = r.id;
END $$;

-- @seq 332
CREATE FUNCTION public.acct_update_finding(p_finding_id uuid, p_status text DEFAULT NULL::text, p_assignee uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_ignore_future boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE f acct_review_findings%ROWTYPE;
BEGIN
  SELECT * INTO f FROM acct_review_findings WHERE id = p_finding_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Finding not found'; END IF;
  PERFORM acct_assert_access(f.tenant_id);
  IF p_status IS NOT NULL AND p_status NOT IN ('open','in_progress','resolved','ignored') THEN RAISE EXCEPTION 'Invalid status %', p_status; END IF;
  IF p_status = 'ignored' AND coalesce(p_note,'') = '' THEN RAISE EXCEPTION 'Say why this finding is being ignored'; END IF;
  UPDATE acct_review_findings SET status = coalesce(p_status, status), assignee_id = coalesce(p_assignee, assignee_id),
         resolution_note = coalesce(p_note, resolution_note),
         resolved_by = CASE WHEN p_status IN ('resolved','ignored') THEN auth.uid() ELSE resolved_by END,
         resolved_at = CASE WHEN p_status IN ('resolved','ignored') THEN now() ELSE resolved_at END, updated_at = now()
   WHERE id = f.id;
  IF p_note IS NOT NULL THEN
    INSERT INTO acct_review_comments(tenant_id, finding_id, author_id, body) VALUES (f.tenant_id, f.id, auth.uid(), p_note);
  END IF;
  IF p_ignore_future THEN
    INSERT INTO acct_review_ignore_rules(tenant_id, check_code, account_id, source_id, reason, created_by)
    VALUES (f.tenant_id, f.check_code, f.account_id, f.source_id, coalesce(p_note, 'Ignored from finding'), auth.uid());
  END IF;
END $$;

-- @seq 333
CREATE FUNCTION public.acct_valid_routing(p text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
  SELECT p ~ '^[0-9]{9}$' AND (
    3*(substr(p,1,1)::int + substr(p,4,1)::int + substr(p,7,1)::int) +
    7*(substr(p,2,1)::int + substr(p,5,1)::int + substr(p,8,1)::int) +
      (substr(p,3,1)::int + substr(p,6,1)::int + substr(p,9,1)::int)) % 10 = 0;
$_$;

-- @seq 334
CREATE FUNCTION public.acct_validate_journal_entry(p_journal_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
DECLARE v_debit numeric(24,6); v_credit numeric(24,6); v_count integer; v_status acct_posting_status;
BEGIN
    SELECT status INTO v_status FROM acct_journal_entries WHERE id=p_journal_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Journal entry % not found', p_journal_id; END IF;
    IF v_status <> 'draft' AND v_status <> 'approved' THEN RAISE EXCEPTION 'Journal entry % cannot be posted from status %', p_journal_id, v_status; END IF;
    SELECT COUNT(*), COALESCE(SUM(debit),0), COALESCE(SUM(credit),0) INTO v_count,v_debit,v_credit FROM acct_journal_lines WHERE journal_entry_id=p_journal_id;
    IF v_count < 2 THEN RAISE EXCEPTION 'A journal entry requires at least two lines'; END IF;
    IF v_debit <= 0 OR v_credit <= 0 OR v_debit <> v_credit THEN RAISE EXCEPTION 'Journal % is not balanced: debit %, credit %', p_journal_id,v_debit,v_credit; END IF;
    UPDATE acct_journal_entries SET total_debit=v_debit,total_credit=v_credit,status='posted',posted_by=auth.uid(),posted_at=now() WHERE id=p_journal_id;
END; $$;

-- @seq 335
CREATE FUNCTION public.acct_vendor_before_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
  NEW.entity_id := coalesce(NEW.entity_id, acct_default_entity(NEW.tenant_id));
  NEW.ap_account_id := coalesce(NEW.ap_account_id, acct_role_account(NEW.tenant_id, NEW.entity_id, 'accounts_payable'));
  IF NEW.vendor_number IS NULL OR NEW.vendor_number = '' THEN NEW.vendor_number := acct_next_number(NEW.tenant_id, NEW.entity_id, 'vendor', 'V-'); END IF;
  NEW.display_name := coalesce(NEW.display_name, NEW.company_name, NEW.legal_name);
  NEW.metadata := coalesce(NEW.metadata, '{}'::jsonb);
  IF (TG_OP = 'INSERT' OR NEW.ap_account_id IS DISTINCT FROM OLD.ap_account_id)
     AND NOT EXISTS (SELECT 1 FROM acct_chart_of_accounts WHERE id = NEW.ap_account_id AND account_type = 'liability' AND is_control_account) THEN
    RAISE EXCEPTION 'Vendor A/P account must be an Accounts Payable control account'; END IF;
  IF NEW.ach_routing_number IS NOT NULL AND NOT acct_valid_routing(NEW.ach_routing_number) THEN
    RAISE EXCEPTION 'Routing number % fails the ABA checksum', NEW.ach_routing_number; END IF;
  IF NEW.ach_account_last4 IS NOT NULL AND NEW.ach_account_last4 !~ '^[0-9]{4}$' THEN RAISE EXCEPTION 'Store only the last 4 digits of the ACH account'; END IF;
  IF NEW.tin_last4 IS NOT NULL AND NEW.tin_last4 !~ '^[0-9]{4}$' THEN RAISE EXCEPTION 'Store only the last 4 digits of the TIN'; END IF;
  IF NEW.vendor_kind = 'contractor' THEN
    NEW.is_1099_vendor := true; NEW.tax_form_type := coalesce(NEW.tax_form_type, '1099-NEC'); NEW.default_1099_box := coalesce(NEW.default_1099_box, 'NEC-1');
  ELSIF NEW.vendor_kind = 'landlord' AND NEW.is_1099_vendor THEN NEW.default_1099_box := coalesce(NEW.default_1099_box, 'MISC-1'); NEW.tax_form_type := coalesce(NEW.tax_form_type, '1099-MISC');
  ELSIF NEW.vendor_kind = 'attorney' THEN NEW.is_1099_vendor := true; NEW.default_1099_box := coalesce(NEW.default_1099_box, 'NEC-1'); NEW.tax_form_type := coalesce(NEW.tax_form_type, '1099-NEC');
  ELSIF NEW.is_1099_vendor THEN NEW.default_1099_box := coalesce(NEW.default_1099_box, 'NEC-1'); NEW.tax_form_type := coalesce(NEW.tax_form_type, '1099-NEC');
  END IF;
  RETURN NEW;
END $_$;

-- @seq 336
CREATE FUNCTION public.acct_vendor_credit_inventory_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE l record; it acct_items%ROWTYPE;
BEGIN
  IF OLD.posted_journal_id IS NULL AND NEW.posted_journal_id IS NOT NULL THEN
    FOR l IN SELECT * FROM acct_ap_vendor_credit_lines WHERE credit_id = NEW.id AND item_id IS NOT NULL LOOP
      SELECT * INTO it FROM acct_items WHERE id = l.item_id;
      CONTINUE WHEN it.item_type <> 'inventory' OR l.account_id <> it.inventory_asset_account_id;
      PERFORM acct__inv_vendor_return(NEW.tenant_id, NEW.entity_id, l.item_id, l.quantity, l.amount, NEW.credit_date,
                                      'acct_ap_vendor_credits', NEW.id, l.id, NEW.credit_number);
    END LOOP;
  END IF;
  RETURN NULL;
END $$;

-- @seq 337
CREATE FUNCTION public.acct_void_bill_payment(p_payment_id uuid, p_reason text DEFAULT NULL::text, p_void_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p acct_ap_payments%ROWTYPE; a record; v_rev uuid;
BEGIN
  SELECT * INTO p FROM acct_ap_payments WHERE id = p_payment_id FOR UPDATE;
  PERFORM acct_assert_access(p.tenant_id);
  IF p.status = 'void' THEN RAISE EXCEPTION 'Payment already void'; END IF;
  IF EXISTS (SELECT 1 FROM acct_journal_lines WHERE journal_entry_id = p.posted_journal_id AND cleared_status = 'reconciled') THEN
    RAISE EXCEPTION 'Payment is reconciled; undo the reconciliation first'; END IF;
  v_rev := acct_reverse_journal(p.posted_journal_id, coalesce(p_void_date, p.payment_date), 'Void bill payment ' || p.payment_number || coalesce(': ' || p_reason, ''));
  FOR a IN SELECT * FROM acct_ap_payment_applications WHERE payment_id = p.id LOOP
    UPDATE acct_ap_bills SET amount_paid = amount_paid - a.applied_amount WHERE id = a.bill_id;
    PERFORM acct_bill_refresh_status(a.bill_id);
  END LOOP;
  UPDATE acct_ap_payments SET status = 'void', voided_at = now(), memo = concat_ws(' | ', memo, 'VOID: ' || coalesce(p_reason,'')) WHERE id = p.id;
  RETURN v_rev;
END $$;

-- @seq 338
CREATE FUNCTION public.acct_void_credit_memo(p_memo_id uuid, p_reason text, p_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE m acct_ar_credit_memos%ROWTYPE; a record; v_rev uuid;
BEGIN
  SELECT * INTO m FROM acct_ar_credit_memos WHERE id = p_memo_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Credit memo not found'; END IF;
  PERFORM acct_assert_access(m.tenant_id);
  IF m.status = 'void' THEN RETURN NULL; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required to void'; END IF;
  FOR a IN SELECT * FROM acct_credit_memo_applications WHERE credit_memo_id = m.id AND reversed_at IS NULL LOOP
    UPDATE acct_ar_invoices SET amount_credited = amount_credited - a.amount WHERE id = a.invoice_id;
    PERFORM acct_invoice_refresh_status(a.invoice_id);
    UPDATE acct_credit_memo_applications SET reversed_at = now() WHERE id = a.id;
  END LOOP;
  IF m.posted_journal_id IS NOT NULL THEN
    v_rev := acct_reverse_journal(m.posted_journal_id, coalesce(p_date, current_date), 'Void credit memo ' || m.memo_number || ': ' || p_reason);
    INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
                                      tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason, journal_entry_id)
    SELECT tenant_id, entity_id, coalesce(p_date, current_date), direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
           tax_category, -gross_amount, -taxable_amount, -exempt_amount, rate, -tax_amount, 'Void ' || m.memo_number, v_rev
      FROM acct_tax_transactions WHERE source_doc_type = 'acct_ar_credit_memos' AND source_doc_id = m.id AND journal_entry_id = m.posted_journal_id;
  END IF;
  UPDATE acct_ar_credit_memos SET status = 'void', applied_amount = 0, voided_at = now(), void_reason = p_reason, updated_at = now() WHERE id = m.id;
  RETURN v_rev;
END $$;

-- @seq 339
CREATE FUNCTION public.acct_void_deposit(p_deposit_id uuid, p_reason text, p_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE d acct_bank_deposits%ROWTYPE; v_rev uuid;
BEGIN
  SELECT * INTO d FROM acct_bank_deposits WHERE id = p_deposit_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Deposit not found'; END IF;
  PERFORM acct_assert_access(d.tenant_id);
  IF d.status = 'void' THEN RETURN NULL; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required to void'; END IF;
  IF d.bank_transaction_id IS NOT NULL THEN RAISE EXCEPTION 'Deposit is matched to a bank transaction; undo the match first'; END IF;
  IF EXISTS (SELECT 1 FROM acct_reconciliation_items ri JOIN acct_journal_lines jl ON jl.id = ri.journal_line_id
              WHERE jl.journal_entry_id = d.posted_journal_id) THEN
    RAISE EXCEPTION 'Deposit is in a finished reconciliation; undo the reconciliation first';
  END IF;
  IF d.posted_journal_id IS NOT NULL THEN
    v_rev := acct_reverse_journal(d.posted_journal_id, coalesce(p_date, current_date), 'Void deposit ' || d.deposit_number || ': ' || p_reason);
  END IF;
  UPDATE acct_ar_invoices i SET status = 'paid' FROM acct_ar_receipt_applications a JOIN acct_ar_receipts r ON r.id = a.receipt_id
   WHERE r.deposit_id = d.id AND i.id = a.invoice_id AND i.status = 'deposited';
  UPDATE acct_ar_receipts SET deposit_id = NULL WHERE deposit_id = d.id;
  UPDATE acct_bank_deposits SET status = 'void', memo = concat_ws(' | ', memo, 'Void: ' || p_reason), updated_at = now() WHERE id = d.id;
  RETURN v_rev;
END $$;

-- @seq 340
CREATE FUNCTION public.acct_void_document(p_doc_type text, p_doc_id uuid, p_reason text, p_void_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_t uuid; v_je uuid; v_rev uuid; v_date date; v_status text;
BEGIN
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required to void'; END IF;
  IF p_doc_type = 'bill' THEN
    SELECT tenant_id, posted_journal_id, bill_date, status INTO v_t, v_je, v_date, v_status FROM acct_ap_bills WHERE id = p_doc_id FOR UPDATE;
    PERFORM acct_assert_access(v_t);
    IF EXISTS (SELECT 1 FROM acct_ap_payment_applications a JOIN acct_ap_payments p ON p.id = a.payment_id WHERE a.bill_id = p_doc_id AND p.status <> 'void')
       OR EXISTS (SELECT 1 FROM acct_ap_vendor_credit_applications WHERE bill_id = p_doc_id) THEN
      RAISE EXCEPTION 'Bill has payments or credits applied; void those first'; END IF;
    UPDATE acct_scheduled_payments SET status = 'cancelled' WHERE bill_id = p_doc_id AND status = 'scheduled';
    IF v_je IS NOT NULL THEN v_rev := acct_reverse_journal(v_je, coalesce(p_void_date, v_date), 'Void: ' || p_reason); END IF;
    UPDATE acct_ap_bills SET status = 'void', voided_at = now(), void_reason = p_reason WHERE id = p_doc_id;
  ELSIF p_doc_type = 'spend' THEN
    SELECT tenant_id, posted_journal_id, payment_date INTO v_t, v_je, v_date FROM acct_spend_transactions WHERE id = p_doc_id FOR UPDATE;
    PERFORM acct_assert_access(v_t);
    IF EXISTS (SELECT 1 FROM acct_journal_lines WHERE journal_entry_id = v_je AND cleared_status = 'reconciled') THEN
      RAISE EXCEPTION 'Transaction is reconciled; undo the reconciliation first'; END IF;
    UPDATE acct_bank_transactions SET review_status = 'for_review', match_status = 'unmatched', matched_journal_line_id = NULL, posted_journal_id = NULL
     WHERE posted_journal_id = v_je;
    IF v_je IS NOT NULL THEN v_rev := acct_reverse_journal(v_je, coalesce(p_void_date, v_date), 'Void: ' || p_reason); END IF;
    UPDATE acct_spend_transactions SET status = 'void', voided_at = now(), memo = concat_ws(' | ', memo, 'VOID: ' || p_reason) WHERE id = p_doc_id;
  ELSIF p_doc_type = 'vendor_credit' THEN
    SELECT tenant_id, posted_journal_id, credit_date INTO v_t, v_je, v_date FROM acct_ap_vendor_credits WHERE id = p_doc_id FOR UPDATE;
    PERFORM acct_assert_access(v_t);
    IF EXISTS (SELECT 1 FROM acct_ap_vendor_credit_applications WHERE credit_id = p_doc_id) THEN RAISE EXCEPTION 'Credit has been applied to bills'; END IF;
    IF v_je IS NOT NULL THEN v_rev := acct_reverse_journal(v_je, coalesce(p_void_date, v_date), 'Void: ' || p_reason); END IF;
    UPDATE acct_ap_vendor_credits SET status = 'void' WHERE id = p_doc_id;
  ELSIF p_doc_type = 'bill_payment' THEN
    RETURN acct_void_bill_payment(p_doc_id, p_reason, p_void_date);
  ELSE
    RAISE EXCEPTION 'Unknown document type % (bill, spend, vendor_credit, bill_payment)', p_doc_type;
  END IF;
  RETURN v_rev;
END $$;

-- @seq 341
CREATE FUNCTION public.acct_void_invoice(p_invoice_id uuid, p_reason text, p_void_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE iv acct_ar_invoices%ROWTYPE; v_rev uuid;
BEGIN
  SELECT * INTO iv FROM acct_ar_invoices WHERE id = p_invoice_id FOR UPDATE;
  PERFORM acct_assert_access(iv.tenant_id);
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required to void'; END IF;
  IF EXISTS (SELECT 1 FROM acct_ar_receipt_applications a JOIN acct_ar_receipts r ON r.id = a.receipt_id WHERE a.invoice_id = iv.id AND r.status <> 'void') THEN
    RAISE EXCEPTION 'Invoice has payments; void or unapply the payments first'; END IF;
  IF iv.posted_journal_id IS NOT NULL THEN
    v_rev := acct_reverse_journal(iv.posted_journal_id, coalesce(p_void_date, iv.invoice_date), 'Void invoice ' || iv.invoice_number || ': ' || p_reason);
    -- tax subledger: negative mirror rows so filings net to zero
    INSERT INTO acct_tax_transactions(tenant_id, entity_id, tax_date, direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
                                      rule_id, tax_category, gross_amount, taxable_amount, exempt_amount, rate, tax_amount, reason, journal_entry_id)
    SELECT tenant_id, entity_id, coalesce(p_void_date, iv.invoice_date), direction, source_doc_type, source_doc_id, source_line_ref, jurisdiction_id, tax_code_id,
           rule_id, tax_category, -gross_amount, -taxable_amount, -exempt_amount, rate, -tax_amount, 'Void: ' || p_reason, v_rev
      FROM acct_tax_transactions WHERE source_doc_type = 'acct_ar_invoices' AND source_doc_id = iv.id AND journal_entry_id = iv.posted_journal_id;
  END IF;
  UPDATE acct_ar_invoices SET status = 'void', voided_at = now(), voided_by = auth.uid(), void_reason = p_reason WHERE id = iv.id;
  RETURN v_rev;
END $$;

-- @seq 342
CREATE FUNCTION public.acct_void_receipt(p_receipt_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r acct_ar_receipts%ROWTYPE; a record; v_rev uuid; je record;
BEGIN
  SELECT * INTO r FROM acct_ar_receipts WHERE id = p_receipt_id FOR UPDATE;
  PERFORM acct_assert_access(r.tenant_id);
  IF r.status = 'void' THEN RAISE EXCEPTION 'Already void'; END IF;
  IF r.deposit_id IS NOT NULL THEN RAISE EXCEPTION 'Payment is in bank deposit; remove it from the deposit first'; END IF;
  FOR je IN SELECT id FROM acct_journal_entries WHERE source_doc_type = 'acct_ar_receipts' AND source_doc_id = r.id AND status = 'posted' LOOP
    v_rev := acct_reverse_journal(je.id, r.receipt_date, 'Void payment ' || r.receipt_number || ': ' || coalesce(p_reason,''));
  END LOOP;
  FOR a IN SELECT * FROM acct_ar_receipt_applications WHERE receipt_id = r.id LOOP
    IF a.as_deposit THEN UPDATE acct_ar_invoices SET deposit_paid = deposit_paid - a.applied_amount WHERE id = a.invoice_id;
    ELSE UPDATE acct_ar_invoices SET amount_paid = amount_paid - a.applied_amount WHERE id = a.invoice_id; PERFORM acct_invoice_refresh_status(a.invoice_id); END IF;
  END LOOP;
  UPDATE acct_ar_receipts SET status = 'void', voided_at = now(), memo = concat_ws(' | ', memo, 'VOID: ' || coalesce(p_reason,'')) WHERE id = r.id;
  RETURN v_rev;
END $$;

-- @seq 343
CREATE FUNCTION public.acct_void_transfer(p_transfer_id uuid, p_reason text, p_date date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE x acct_bank_transfers%ROWTYPE; v uuid;
BEGIN
  SELECT * INTO x FROM acct_bank_transfers WHERE id = p_transfer_id FOR UPDATE;
  PERFORM acct_assert_access(x.tenant_id);
  IF x.status = 'void' THEN RAISE EXCEPTION 'Transfer is already void'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required to void'; END IF;
  v := acct_reverse_journal(x.journal_entry_id, coalesce(p_date, x.transfer_date), 'Transfer void: ' || p_reason);
  UPDATE acct_bank_transfers SET status = 'void', void_journal_id = v WHERE id = x.id;
  RETURN v;
END $$;

-- @seq 525
CREATE FUNCTION public.post_journal(p_tenant_id uuid, p_entry_date date, p_lines jsonb, p_memo text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text, p_source_id text DEFAULT NULL::text, p_currency text DEFAULT 'USD'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_journal_id  uuid;
  v_total_debit numeric(18,4) := 0;
  v_total_credit numeric(18,4) := 0;
  v_line jsonb;
  v_account_id uuid;
  v_debit numeric(18,4);
  v_credit numeric(18,4);
begin
  if p_lines is null or jsonb_array_length(p_lines) = 0 then
    raise exception 'No journal lines provided';
  end if;
  for v_line in select jsonb_array_elements(p_lines) loop
    v_total_debit  := v_total_debit  + coalesce((v_line->>'debit')::numeric, 0);
    v_total_credit := v_total_credit + coalesce((v_line->>'credit')::numeric, 0);
  end loop;
  if v_total_debit <> v_total_credit then
    raise exception 'Journal not balanced: debits %, credits %', v_total_debit, v_total_credit;
  end if;
  insert into journal_entries (tenant_id, entry_date, memo, reference, source, source_id, currency, posted, created_by)
  values (p_tenant_id, p_entry_date, p_memo, p_reference, p_source, p_source_id, p_currency, true, auth.uid())
  returning id into v_journal_id;
  for v_line in select jsonb_array_elements(p_lines) loop
    v_account_id := (v_line->>'account_id')::uuid;
    v_debit  := coalesce((v_line->>'debit')::numeric, 0);
    v_credit := coalesce((v_line->>'credit')::numeric, 0);
    insert into journal_lines (
      journal_id, tenant_id, account_id,
      customer_id, invoice_id, payment_id, order_id, product_id, inventory_item_id,
      tax_id, description, debit, credit, fc_currency
    ) values (
      v_journal_id, p_tenant_id, v_account_id,
      nullif(v_line->>'customer_id','')::text,
      nullif(v_line->>'invoice_id','')::text,
      nullif(v_line->>'payment_id','')::text,
      nullif(v_line->>'order_id','')::text,
      nullif(v_line->>'product_id','')::text,
      nullif(v_line->>'inventory_item_id','')::text,
      nullif(v_line->>'tax_id','')::uuid,
      v_line->>'description',
      v_debit, v_credit,
      p_currency
    );
  end loop;
  return v_journal_id;
end;
$$;

-- @seq 533
CREATE FUNCTION public.rpc_get_balance_sheet(p_tenant_id uuid, p_as_of_date date) RETURNS TABLE(section text, account_code text, account_name text, account_type text, debit numeric, credit numeric, balance numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    CASE coa.account_type
      WHEN 'asset' THEN 'Assets'
      WHEN 'liability' THEN 'Liabilities'
      WHEN 'equity' THEN 'Equity'
      WHEN 'contra_asset' THEN 'Assets'
      WHEN 'contra_liability' THEN 'Liabilities'
      WHEN 'contra_equity' THEN 'Equity'
      ELSE 'Other'
    END AS section,
    coa.code AS account_code,
    coa.name AS account_name,
    coa.account_type::text AS account_type,
    COALESCE(SUM(jl.debit), 0)::numeric AS debit,
    COALESCE(SUM(jl.credit), 0)::numeric AS credit,
    CASE
      WHEN coa.account_type IN ('asset','contra_liability','contra_equity') THEN
        COALESCE(SUM(jl.debit) - SUM(jl.credit), 0)::numeric
      WHEN coa.account_type IN ('liability','equity','contra_asset') THEN
        COALESCE(SUM(jl.credit) - SUM(jl.debit), 0)::numeric
      ELSE
        COALESCE(SUM(jl.debit) - SUM(jl.credit), 0)::numeric
    END AS balance
  FROM public.acct_journal_lines jl
  JOIN public.acct_journal_entries je ON je.id = jl.journal_entry_id
  JOIN public.acct_chart_of_accounts coa ON coa.id = jl.account_id
  WHERE jl.tenant_id = p_tenant_id
    AND je.tenant_id = p_tenant_id
    AND je.status = 'posted'
    AND je.entry_date <= p_as_of_date
    AND coa.account_type IN ('asset','liability','equity','contra_asset','contra_liability','contra_equity')
  GROUP BY coa.code, coa.name, coa.account_type
  ORDER BY
    CASE coa.account_type WHEN 'asset' THEN 1 WHEN 'liability' THEN 2 WHEN 'equity' THEN 3 ELSE 9 END,
    coa.code;

  RETURN QUERY
  SELECT
    'TOTAL'::text AS section,
    ''::text AS account_code,
    CASE
      WHEN coa.account_type = 'asset' THEN 'Total Assets'
      WHEN coa.account_type = 'liability' THEN 'Total Liabilities'
      WHEN coa.account_type = 'equity' THEN 'Total Equity'
      ELSE 'Other'
    END AS account_name,
    coa.account_type::text AS account_type,
    0::numeric AS debit,
    0::numeric AS credit,
    CASE
      WHEN coa.account_type IN ('asset','contra_liability','contra_equity') THEN
        COALESCE(SUM(jl.debit) - SUM(jl.credit), 0)::numeric
      WHEN coa.account_type IN ('liability','equity','contra_asset') THEN
        COALESCE(SUM(jl.credit) - SUM(jl.debit), 0)::numeric
      ELSE 0::numeric
    END AS balance
  FROM public.acct_journal_lines jl
  JOIN public.acct_journal_entries je ON je.id = jl.journal_entry_id
  JOIN public.acct_chart_of_accounts coa ON coa.id = jl.account_id
  WHERE jl.tenant_id = p_tenant_id
    AND je.tenant_id = p_tenant_id
    AND je.status = 'posted'
    AND je.entry_date <= p_as_of_date
    AND coa.account_type IN ('asset','liability','equity','contra_asset','contra_liability','contra_equity')
  GROUP BY coa.account_type
  ORDER BY
    CASE coa.account_type WHEN 'asset' THEN 1 WHEN 'liability' THEN 2 WHEN 'equity' THEN 3 ELSE 9 END;
END;
$$;

-- @seq 534
CREATE FUNCTION public.rpc_get_general_ledger(p_tenant_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(entry_no bigint, entry_date date, posting_date date, source text, memo text, reference text, line_no integer, account_code text, account_name text, account_type text, line_description text, debit numeric, credit numeric, running_balance numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  WITH ordered_lines AS (
    SELECT
      je.entry_no,
      je.entry_date,
      je.posting_date,
      je.source::text AS source,
      je.memo,
      je.reference,
      jl.line_no,
      coa.code AS account_code,
      coa.name AS account_name,
      coa.account_type::text AS account_type,
      jl.description AS line_description,
      jl.debit,
      jl.credit,
      SUM(CASE
             WHEN coa.account_type IN ('asset','expense') THEN jl.debit - jl.credit
             WHEN coa.account_type IN ('liability','equity','revenue') THEN jl.credit - jl.debit
             ELSE jl.debit - jl.credit
           END)
        OVER (PARTITION BY coa.id ORDER BY je.entry_date, je.entry_no, jl.line_no) AS running_balance
    FROM public.acct_journal_lines jl
    JOIN public.acct_journal_entries je ON je.id = jl.journal_entry_id
    JOIN public.acct_chart_of_accounts coa ON coa.id = jl.account_id
    WHERE jl.tenant_id = p_tenant_id
      AND je.tenant_id = p_tenant_id
      AND je.status = 'posted'
      AND je.entry_date BETWEEN p_start_date AND p_end_date
  )
  SELECT
    ol.entry_no,
    ol.entry_date,
    ol.posting_date,
    ol.source,
    ol.memo,
    ol.reference,
    ol.line_no,
    ol.account_code,
    ol.account_name,
    ol.account_type,
    ol.line_description,
    ol.debit,
    ol.credit,
    ol.running_balance
  FROM ordered_lines ol
  ORDER BY ol.account_code, ol.entry_date, ol.entry_no, ol.line_no;
END;
$$;

-- @seq 535
CREATE FUNCTION public.rpc_get_profit_and_loss(p_tenant_id uuid, p_start_date date, p_end_date date) RETURNS TABLE(account_code text, account_name text, account_type text, debit numeric, credit numeric, net_amount numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    coa.code AS account_code,
    coa.name AS account_name,
    coa.account_type::text AS account_type,
    COALESCE(SUM(jl.debit), 0)::numeric AS debit,
    COALESCE(SUM(jl.credit), 0)::numeric AS credit,
    CASE
      WHEN coa.account_type = 'revenue' THEN
        COALESCE(SUM(jl.credit) - SUM(jl.debit), 0)::numeric
      WHEN coa.account_type = 'expense' THEN
        COALESCE(SUM(jl.debit) - SUM(jl.credit), 0)::numeric
      ELSE
        0::numeric
    END AS net_amount
  FROM public.acct_journal_lines jl
  JOIN public.acct_journal_entries je ON je.id = jl.journal_entry_id
  JOIN public.acct_chart_of_accounts coa ON coa.id = jl.account_id
  WHERE jl.tenant_id = p_tenant_id
    AND je.tenant_id = p_tenant_id
    AND je.status = 'posted'
    AND je.entry_date BETWEEN p_start_date AND p_end_date
    AND coa.account_type IN ('revenue', 'expense')
  GROUP BY coa.code, coa.name, coa.account_type
  ORDER BY coa.account_type, coa.code;

  RETURN QUERY
  SELECT
    'TOTAL'::text AS account_code,
    'Net Income'::text AS account_name,
    'total'::text AS account_type,
    0::numeric AS debit,
    0::numeric AS credit,
    (
      COALESCE((SELECT SUM(jl.credit) - SUM(jl.debit) FROM public.acct_journal_lines jl
                 JOIN public.acct_journal_entries je ON je.id = jl.journal_entry_id
                 JOIN public.acct_chart_of_accounts coa ON coa.id = jl.account_id
                 WHERE jl.tenant_id = p_tenant_id AND je.status = 'posted'
                   AND je.entry_date BETWEEN p_start_date AND p_end_date
                   AND coa.account_type = 'revenue'), 0)
      -
      COALESCE((SELECT SUM(jl.debit) - SUM(jl.credit) FROM public.acct_journal_lines jl
                 JOIN public.acct_journal_entries je ON je.id = jl.journal_entry_id
                 JOIN public.acct_chart_of_accounts coa ON coa.id = jl.account_id
                 WHERE jl.tenant_id = p_tenant_id AND je.status = 'posted'
                   AND je.entry_date BETWEEN p_start_date AND p_end_date
                   AND coa.account_type = 'expense'), 0)
    )::numeric AS net_amount;
END;
$$;

-- @seq 536
CREATE FUNCTION public.rpc_get_trial_balance(p_tenant_id uuid, p_end_date date) RETURNS TABLE(account_code text, account_name text, account_type text, total_debit numeric, total_credit numeric, balance numeric)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    coa.code AS account_code,
    coa.name AS account_name,
    coa.account_type::text AS account_type,
    COALESCE(SUM(jl.debit), 0)::numeric AS total_debit,
    COALESCE(SUM(jl.credit), 0)::numeric AS total_credit,
    CASE
      WHEN coa.account_type IN ('asset','expense') THEN
        COALESCE(SUM(jl.debit) - SUM(jl.credit), 0)::numeric
      WHEN coa.account_type IN ('liability','equity','revenue') THEN
        COALESCE(SUM(jl.credit) - SUM(jl.debit), 0)::numeric
      ELSE
        COALESCE(SUM(jl.debit) - SUM(jl.credit), 0)::numeric
    END AS balance
  FROM public.acct_journal_lines jl
  JOIN public.acct_journal_entries je ON je.id = jl.journal_entry_id
  JOIN public.acct_chart_of_accounts coa ON coa.id = jl.account_id
  WHERE jl.tenant_id = p_tenant_id
    AND je.tenant_id = p_tenant_id
    AND je.status = 'posted'
    AND je.entry_date <= p_end_date
  GROUP BY coa.code, coa.name, coa.account_type
  ORDER BY coa.code;

  RETURN QUERY
  SELECT
    'TOTAL'::text AS account_code,
    'Totals (debits must equal credits)'::text AS account_name,
    'total'::text AS account_type,
    COALESCE(SUM(jl.debit), 0)::numeric AS total_debit,
    COALESCE(SUM(jl.credit), 0)::numeric AS total_credit,
    0::numeric AS balance
  FROM public.acct_journal_lines jl
  JOIN public.acct_journal_entries je ON je.id = jl.journal_entry_id
  WHERE jl.tenant_id = p_tenant_id
    AND je.tenant_id = p_tenant_id
    AND je.status = 'posted'
    AND je.entry_date <= p_end_date;
END;
$$;

